# ---------------- Doctor → patient credentials helpers ----------------
# These back the "auto-generate a login when a doctor adds a patient" flow.
# Keep them at module scope so any new endpoint can call them.

# Cryptographically random temporary password. Uses `secrets` (stdlib) and a
# 62-char unambiguous alphabet (no I/l/1/O/0) so the string is usable when
# dictated over the phone.
_TEMP_PASSWORD_LENGTH = 10
_TEMP_PASSWORD_ALPHABET = "".join(
    c for c in (string.ascii_letters + string.digits) if c not in "Il1O0"
)


def _generate_temp_password() -> str:
    """10-char random password. Cryptographically secure via `secrets`."""
    return "".join(secrets.choice(_TEMP_PASSWORD_ALPHABET) for _ in range(_TEMP_PASSWORD_LENGTH))


_USERNAME_CLEAN_RE = re.compile(r"[^a-z0-9._-]+")


def _slugify_username(name: str) -> str:
    """Turn a patient's display name into a usable username slug.

    Lowercases, replaces runs of disallowed chars with a single dot, trims
    leading/trailing dots/dashes. Returns '' if the name has nothing usable.
    """
    if not name:
        return ""
    s = name.strip().lower()
    s = _USERNAME_CLEAN_RE.sub(".", s)
    s = s.strip("._-")
    # Cap to a sane length; the caller will append an id suffix.
    return s[:32]


def _derive_unique_username(db: Session, name: str, fallback_id: int) -> str:
    """Build a unique username. Tries {slug}.{id}, then adds random suffixes
    on collision. Raises ValueError if even the salted form collides 5x in a row
    (extremely unlikely; surface instead of looping forever).
    """
    slug = _slugify_username(name) or f"patient.{fallback_id}"
    candidate = f"{slug}.{fallback_id}"
    for attempt in range(5):
        existing = db.query(models.User).filter(models.User.username == candidate).first()
        if not existing:
            return candidate
        # Collision — append a 4-char random suffix and retry.
        suffix = secrets.token_hex(2)
        candidate = f"{slug}.{fallback_id}_{suffix}"
    raise ValueError(f"Could not derive a unique username for '{name}' after 5 attempts")


def _doctor_specialization(db: Session, doctor_user_id: int) -> Optional[str]:
    """Return the doctor's profile.specialization, or None if the profile
    doesn't exist yet. Used to set the `department` snapshot on a new
    PatientDoctorLink."""
    profile = (
        db.query(models.DoctorProfile)
        .filter(models.DoctorProfile.user_id == doctor_user_id)
        .first()
    )
    return profile.specialization if profile else None


def _make_synthetic_email(username: str) -> str:
    """Auto-generated patients get an email under our own subdomain. They can
    still log in with the username — this just gives the doctor something
    readable to put in the credentials modal."""
    return f"{username}@patients.system.local"


def _get_or_create_patient_link(
    db: Session, patient_id: int, doctor_user_id: int, department: Optional[str] = None
) -> models.PatientDoctorLink:
    """Idempotent link creator. Returns the existing link if a (patient, doctor)
    row already exists; otherwise creates one with `department` set (which
    the caller should already have snapshotted from DoctorProfile.specialization)."""
    existing = (
        db.query(models.PatientDoctorLink)
        .filter(
            models.PatientDoctorLink.patient_id == patient_id,
            models.PatientDoctorLink.doctor_user_id == doctor_user_id,
        )
        .first()
    )
    if existing:
        return existing
    if department is None:
        department = _doctor_specialization(db, doctor_user_id)
    link = models.PatientDoctorLink(
        patient_id=patient_id,
        doctor_user_id=doctor_user_id,
        department=department,
    )
    db.add(link)
    db.flush()  # ensure id is populated
    return link


def _doctor_names_for_link(db: Session, doctor_ids: list[int]) -> dict[int, str]:
    """One roundtrip → {doctor_user_id: full_name or username} for the given ids."""
    if not doctor_ids:
        return {}
    rows = db.query(models.User.id, models.User.full_name, models.User.username).filter(
        models.User.id.in_(doctor_ids)
    ).all()
    return {r.id: (r.full_name or r.username) for r in rows}


def _serialize_patient_links(
    db: Session, patient_id: int, doctor_ids: Optional[list[int]] = None
) -> list[schemas.PatientDoctorLinkOut]:
    """Read all links for a patient and attach doctor_name. If `doctor_ids` is
    provided, skip the lookup (used when the caller already has the names)."""
    links = (
        db.query(models.PatientDoctorLink)
        .filter(models.PatientDoctorLink.patient_id == patient_id)
        .all()
    )
    if not links:
        return []
    ids = list({l.doctor_user_id for l in links})
    names = _doctor_names_for_link(db, ids)
    return [
        schemas.PatientDoctorLinkOut(
            id=l.id,
            patient_id=l.patient_id,
            doctor_user_id=l.doctor_user_id,
            doctor_name=names.get(l.doctor_user_id),
            department=l.department,
            created_at=l.created_at,
        )
        for l in links
    ]


def _attach_patient_links(
    db: Session, patients: list[models.Patient]
) -> list[schemas.PatientOut]:
    """Convert a list of Patient ORM rows to PatientOut with `linked_doctors`
    populated. Issues AT MOST one extra query for the links and one for the
    doctor names."""
    if not patients:
        return []
    patient_ids = [p.id for p in patients]
    link_rows = (
        db.query(models.PatientDoctorLink)
        .filter(models.PatientDoctorLink.patient_id.in_(patient_ids))
        .all()
    )
    doctor_ids = list({l.doctor_user_id for l in link_rows})
    names = _doctor_names_for_link(db, doctor_ids)

    by_patient: dict[int, list[schemas.PatientDoctorLinkOut]] = {pid: [] for pid in patient_ids}
    for l in link_rows:
        by_patient[l.patient_id].append(
            schemas.PatientDoctorLinkOut(
                id=l.id,
                patient_id=l.patient_id,
                doctor_user_id=l.doctor_user_id,
                doctor_name=names.get(l.doctor_user_id),
                department=l.department,
                created_at=l.created_at,
            )
        )

    out = []
    for p in patients:
        out.append(
            schemas.PatientOut(
                id=p.id,
                name=p.name,
                age=p.age,
                gender=p.gender,
                contact=p.contact,
                created_at=p.created_at,
                onboarded_by_doctor_id=getattr(p, "onboarded_by_doctor_id", None),
                linked_doctors=by_patient.get(p.id, []),
            )
        )
    return out


def _attach_user_links(
    db: Session, user: models.User
) -> schemas.UserOut:
    """Convert a User ORM row to UserOut with `linked_doctors` populated for
    patient-role users."""
    linked = []
    if user.role == "patient" and user.patient_id:
        linked = _serialize_patient_links(db, user.patient_id)
    return schemas.UserOut(
        id=user.id,
        username=user.username,
        email=user.email,
        full_name=user.full_name,
        role=user.role,
        patient_id=user.patient_id,
        created_by_doctor_id=user.created_by_doctor_id,
        linked_doctors=linked,
        profile_picture=user.profile_picture,
        created_at=user.created_at,
    )


def _doctor_has_patient_link(
    db: Session, doctor_user_id: int, patient_id: int
) -> bool:
    """True if there exists a PatientDoctorLink for this (patient, doctor) pair."""
    return (
        db.query(models.PatientDoctorLink)
        .filter(
            models.PatientDoctorLink.doctor_user_id == doctor_user_id,
            models.PatientDoctorLink.patient_id == patient_id,
        )
        .first()
        is not None
    )


def _record_care_event(
    db: Session,
    patient_id: int,
    kind: str,
    target_kind: str,
    *,
    actor_user_id: Optional[int] = None,
    doctor_user_id: Optional[int] = None,
    hospital_id: Optional[int] = None,
    note: Optional[str] = None,
) -> models.PatientCareEvent:
    """Append one care-network history row (doctors + hospitals)."""
    ev = models.PatientCareEvent(
        patient_id=patient_id,
        actor_user_id=actor_user_id,
        kind=kind,
        target_kind=target_kind,
        doctor_user_id=doctor_user_id,
        hospital_id=hospital_id,
        note=note,
    )
    db.add(ev)
    return ev


def _patient_name(db: Session, patient_id: int) -> str:
    p = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    return p.name if p else f"Patient #{patient_id}"


def _user_display_name(db: Session, user_id: int) -> str:
    u = db.query(models.User).filter(models.User.id == user_id).first()
    return (u.full_name or u.username) if u else "Unknown"


