# ---- 2026-08-24: AI Doctor v2 startup hook -------------------------------
# Optional one-shot backfill of the RAG corpus on startup. Off by default
# (RAG_BACKFILL_ON_START=false). Flip to "true" for one boot to seed
# every patient's medical history + reports into Qdrant, then back to
# "false" so subsequent boots don't re-index.
@app.on_event("startup")
async def _rag_backfill_on_start():
    if not getattr(config, "RAG_BACKFILL_ON_START", False):
        return
    try:
        import rag_client
        if not rag_client.is_available():
            logger.warning("RAG backfill requested but RAG is unavailable; skipping.")
            return
        with SessionLocal() as db:
            patient_ids = [pid for (pid,) in db.query(models.Patient.id).all()]
        logger.info("RAG backfill starting for %s patients", len(patient_ids))
        for pid in patient_ids:
            _ai_doctor_index_patient_corpus(pid)
        logger.info("RAG backfill complete.")
    except Exception as exc:
        logger.warning("RAG backfill failed: %s", exc)

