# ---------------- Auth (Signup / Login) ----------------

@app.post("/signup", response_model=schemas.UserOut)
def signup(user: schemas.UserCreate, db: Session = Depends(get_db)):
    existing_username = db.query(models.User).filter(models.User.username == user.username).first()
    if existing_username:
        raise HTTPException(status_code=400, detail="Username already taken")

    existing_email = db.query(models.User).filter(models.User.email == user.email).first()
    if existing_email:
        raise HTTPException(status_code=400, detail="An account with this email already exists. Please log in instead.")

    # Block public signup of admin accounts — only the admin panel can create admins
    if user.role == "admin":
        raise HTTPException(status_code=403, detail="Admin accounts cannot be created through public signup.")

    # linked_doctor_id only applies to patient-role signups. For other roles
    # we silently ignore it so a stray input never blocks signup.
    linked_doctor_id: Optional[int] = None
    if user.linked_doctor_id is not None:
        if user.role != "patient":
            raise HTTPException(
                status_code=400,
                detail="linked_doctor_id can only be used when signing up as a patient.",
            )
        doctor = (
            db.query(models.User)
            .filter(models.User.id == user.linked_doctor_id, models.User.role == "doctor")
            .first()
        )
        if not doctor:
            raise HTTPException(status_code=400, detail="Selected doctor does not exist.")
        linked_doctor_id = doctor.id

    new_user = models.User(
        username=user.username,
        email=user.email,
        full_name=user.full_name,
        hashed_password=auth.hash_password(user.password),
        role=user.role,
        patient_id=user.patient_id,
    )
    db.add(new_user)
    db.commit()
    db.refresh(new_user)

    # Hospital-role users get their own Hospital + HospitalProfile auto-created
    # at signup so they don't have to fill out a "create your hospital" form
    # later. Name defaults to "<full_name>'s Hospital"; address/phone are
    # placeholders the admin can edit from their dashboard via
    # PATCH /hospitals/mine. If they already have a profile (rare race or
    # re-activation), we leave it alone.
    if new_user.role == "hospital":
        existing_profile = (
            db.query(models.HospitalProfile)
            .filter(models.HospitalProfile.user_id == new_user.id)
            .first()
        )
        if existing_profile is None or existing_profile.hospital_id is None:
            display = (new_user.full_name or new_user.username or "New").strip()
            hospital_name = f"{display}'s Hospital"
            # Guard against name collisions (e.g. two admins signing up with
            # the same display name) — append a short id suffix if needed.
            base_name = hospital_name
            for _ in range(5):
                clash = (
                    db.query(models.Hospital)
                    .filter(models.Hospital.name == hospital_name)
                    .first()
                )
                if clash is None:
                    break
                hospital_name = f"{base_name} #{secrets.token_hex(2)}"
            h = models.Hospital(
                name=hospital_name,
                address=None,
                phone=None,
                created_by_user_id=new_user.id,
            )
            db.add(h)
            db.flush()  # populate h.id
            if existing_profile is None:
                db.add(models.HospitalProfile(
                    user_id=new_user.id,
                    hospital_id=h.id,
                    display_name=new_user.full_name,
                ))
            else:
                existing_profile.hospital_id = h.id
                existing_profile.display_name = new_user.full_name
            db.commit()
            db.refresh(new_user)

    # Auto-claim the default "General Ward" (ward_id=1) for this hospital,
    # if it hasn't been claimed yet. This ensures the hospital admit request
    # flow works out-of-the-box without requiring the admin to manually claim
    # the ward first.
    ward = db.query(models.Ward).filter(models.Ward.id == 1).first()
    if ward is not None and ward.hospital_id is None:
        ward.hospital_id = h.id
        db.commit()
        db.refresh(ward)

    # If the patient picked a doctor at signup, stamp the link immediately so
    # the doctor's dashboard shows the new patient on first login. We do this
    # AFTER the commit because the User row needs an id, and the Patient row
    # for patient-role signups is created lazily by _auto_link_patient when
    # they first hit /patient/profile. Until then, the link has patient_id=NULL
    # — the /patients/mine endpoint falls back to User.created_by_doctor_id
    # to bridge that gap.
    if linked_doctor_id and new_user.role == "patient":
        new_user.created_by_doctor_id = linked_doctor_id
        if new_user.patient_id is not None:
            _get_or_create_patient_link(db, new_user.patient_id, linked_doctor_id)
        db.commit()
        db.refresh(new_user)

    return _attach_user_links(db, new_user)


@app.post("/login", response_model=schemas.Token)
def login(form_data: OAuth2PasswordRequestForm = Depends(), db: Session = Depends(get_db)):
    user = db.query(models.User).filter(models.User.username == form_data.username).first()
    if not user or not auth.verify_password(form_data.password, user.hashed_password):
        raise HTTPException(status_code=401, detail="Incorrect username or password")

    access_token = auth.create_access_token(data={"sub": user.username})
    return {"access_token": access_token, "token_type": "bearer"}


@app.get("/me", response_model=schemas.UserOut)
def get_me(current_user: models.User = Depends(auth.get_current_user), db: Session = Depends(get_db)):
    return _attach_user_links(db, current_user)


@app.get("/me/dashboard-stats")
def my_dashboard_stats(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Aggregated dashboard tile counts.

    One endpoint serves both roles so the client doesn't render a
    different layout for each — the JSON stays the same, the values
    vary.

    Shape::

        {
            "registered_patients": int,
            "appointments_upcoming": int,
            "prescriptions_signed": int,
            "triage_time_minutes": int,
        }

    For ``patient`` accounts:
      * ``registered_patients`` is the count of medical records on
        their own account (since "registered" reflects how much of
        their own record exists).
      * ``prescriptions_signed`` counts Prescriptions on their account.
      * ``triage_time_minutes`` is the avg gap (min) between
        successive records over the last 30 days.

    For ``doctor`` accounts:
      * ``registered_patients`` is the size of their linked-patient
        roster via PatientDoctorLink (and legacy onboarded fallback).
      * ``prescriptions_signed`` counts Prescriptions on their roster.
      * ``triage_time_minutes`` is the rolling average gap over the
        last 30 days across their roster's record creations.

    Defensive (2026-08-28): the whole computation is wrapped in a
    try/except so a single bad row (NULL created_at, schema drift, an
    unrelated SQL error) returns a zero-filled payload instead of a
    500 Internal Server Error — the dashboard tiles should never break
    the page.
    """
    zeros = {
        "registered_patients": 0,
        "appointments_upcoming": 0,
        "prescriptions_signed": 0,
        "triage_time_minutes": 0,
    }

    try:
        role = current_user.role

        if role == "patient":
            pid = current_user.patient_id
            if not pid:
                return zeros

            records_count = (
                db.query(models.MedicalRecord)
                .filter(models.MedicalRecord.patient_id == pid)
                .count()
            )

            from datetime import datetime, timedelta
            now = datetime.utcnow()
            upcoming_count = (
                db.query(models.Appointment)
                .filter(
                    models.Appointment.patient_id == pid,
                    models.Appointment.scheduled_at >= now,
                )
                .count()
            )
            rx_count = (
                db.query(models.Prescription)
                .filter(models.Prescription.patient_id == pid)
                .count()
            )

            recent_records = (
                db.query(models.MedicalRecord)
                .filter(
                    models.MedicalRecord.patient_id == pid,
                    models.MedicalRecord.created_at >= now - timedelta(days=30),
                    models.MedicalRecord.created_at.isnot(None),
                )
                .order_by(models.MedicalRecord.created_at.asc())
                .all()
            )
            if len(recent_records) < 2:
                avg_triage = 0
            else:
                deltas = []
                for i in range(1, len(recent_records)):
                    a, b = recent_records[i].created_at, recent_records[i-1].created_at
                    if a is None or b is None:
                        continue
                    d = (a - b).total_seconds() / 60.0
                    if d < 0:
                        continue  # out-of-order timestamps shouldn't crash us
                    deltas.append(d)
                avg_triage = int(sum(deltas) / len(deltas)) if deltas else 0

            return {
                "registered_patients": records_count,
                "appointments_upcoming": upcoming_count,
                "prescriptions_signed": rx_count,
                "triage_time_minutes": avg_triage,
            }

        if role == "doctor":
            linked_ids = [
                pid for (pid,) in db.query(models.PatientDoctorLink.patient_id)
                .filter(models.PatientDoctorLink.doctor_user_id == current_user.id)
                .all()
            ]
            onboarded = [
                p.id for p in db.query(models.Patient)
                .filter(models.Patient.onboarded_by_doctor_id == current_user.id)
                .all()
            ]
            all_ids = sorted(set(linked_ids + onboarded))
            from datetime import datetime, timedelta
            now = datetime.utcnow()
            upcoming = (
                db.query(models.Appointment)
                .filter(
                    models.Appointment.scheduled_at >= now,
                    sa_or_(
                        models.Appointment.doctor_user_id == current_user.id,
                        models.Appointment.patient_id.in_(all_ids or [0]),
                    ),
                )
                .count()
            )
            rx_signed = (
                db.query(models.Prescription)
                .filter(models.Prescription.patient_id.in_(all_ids or [0]))
                .count()
            )
            all_records = (
                db.query(models.MedicalRecord.created_at)
                .filter(
                    models.MedicalRecord.patient_id.in_(all_ids or [0]),
                    models.MedicalRecord.created_at >= now - timedelta(days=30),
                    models.MedicalRecord.created_at.isnot(None),
                )
                .order_by(models.MedicalRecord.created_at.asc())
                .all()
            )
            if len(all_records) < 2:
                avg_triage = 0
            else:
                deltas = []
                # Skip NULL timestamps (created_at is nullable on the model)
                times = [r[0] for r in all_records if r[0] is not None]
                for i in range(1, len(times)):
                    d = (times[i] - times[i-1]).total_seconds() / 60.0
                    if d < 0:
                        continue
                    deltas.append(d)
                avg_triage = int(sum(deltas) / len(deltas)) if deltas else 0
            return {
                "registered_patients": len(all_ids),
                "appointments_upcoming": upcoming,
                "prescriptions_signed": rx_signed,
                "triage_time_minutes": avg_triage,
            }

        # nurse / hospital / shopkeeper — generic zeros; dashboard tiles
        # are mostly doctor / patient oriented.
        return zeros

    except Exception as e:
        # Never crash the dashboard tiles — log and return zeros.
        try:
            import logging
            logging.getLogger("uvicorn.error").exception(
                "/me/dashboard-stats crashed for user %s (role=%s): %s",
                getattr(current_user, "id", None),
                getattr(current_user, "role", None),
                e,
            )
        except Exception:
            pass
        return zeros


# ============================================================================
# Patient Dashboard — live intelligence + analytics
# Aggregates the authenticated patient's own appointments, records,
# prescriptions and admissions into the four dashboard metrics
# (Today / Active / Average wait / Compliance). Patient identity always
# comes from the auth token — never from a caller-supplied id.
# ============================================================================
@app.get("/patient/dashboard/summary")
def patient_dashboard_summary(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    pid = current_user.patient_id
    now = datetime.utcnow()
    today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    def _doc_name(doc_user_id):
        if not doc_user_id:
            return None
        u = db.query(models.User).filter(models.User.id == doc_user_id).first()
        return (u.full_name or u.username) if u else None

    # ---------- Appointments (own) ----------
    appts = (
        db.query(models.Appointment)
        .filter(models.Appointment.patient_id == pid)
        .order_by(models.Appointment.scheduled_at.asc())
        .all()
    )
    appts = [a for a in appts if a.scheduled_at is not None]

    # ---------- Today aggregation ----------
    todays_appts = [a for a in appts if today_start <= a.scheduled_at < today_start + timedelta(days=1)]
    records_today = (
        db.query(models.MedicalRecord.id)
        .filter(models.MedicalRecord.patient_id == pid, models.MedicalRecord.created_at >= today_start)
        .count()
    )
    rx_today = (
        db.query(models.Prescription.id)
        .filter(models.Prescription.patient_id == pid, models.Prescription.created_at >= today_start)
        .count()
    )

    # Hourly activity profile for today (appointments by hour + record events)
    hourly = [0] * 24
    for a in todays_appts:
        hourly[a.scheduled_at.hour] += 1
    for base, col in ((models.MedicalRecord, models.MedicalRecord.created_at), (models.Prescription, models.Prescription.created_at)):
        rows = db.query(col).filter(base.patient_id == pid, col >= today_start, col.isnot(None)).all()
        for (ts,) in rows:
            hourly[ts.hour] += 1

    today_count = len(todays_appts)
    today_completed = sum(1 for a in todays_appts if a.status == "completed")
    today_cancelled = sum(1 for a in todays_appts if a.status == "cancelled")
    today_upcoming = sum(1 for a in todays_appts if a.status in ("scheduled", "confirmed") and a.scheduled_at >= now)

    # ---------- Active items ----------
    active_items = []
    for a in appts:
        if a.status in ("scheduled", "confirmed") and a.scheduled_at >= now:
            active_items.append({
                "kind": "appointment",
                "title": f"Appointment with Dr. {_doc_name(a.doctor_user_id) or 'doctor'}",
                "subtitle": f"{a.department or 'Consultation'} · {a.scheduled_at.strftime('%b %d, %I:%M %p')}",
                "status": a.status,
                "status_label": "Confirmed" if a.status == "confirmed" else "Scheduled",
                "start_time": a.scheduled_at.isoformat(),
                "last_update": (a.updated_at or a.created_at).isoformat() if (a.updated_at or a.created_at) else None,
                "next_step": "Attend your appointment on time.",
                "appointment_id": a.id,
            })
    admission = (
        db.query(models.Admission)
        .filter(models.Admission.patient_id == pid, models.Admission.discharged_at.is_(None))
        .order_by(models.Admission.admitted_at.desc())
        .first()
    )
    if admission is not None:
        active_items.append({
            "kind": "admission",
            "title": "Active hospital admission",
            "subtitle": f"Admitted {admission.admitted_at.strftime('%b %d, %Y')}",
            "status": "active",
            "status_label": "Active",
            "start_time": admission.admitted_at.isoformat(),
            "last_update": (admission.notes or "")[:120] or None,
            "next_step": "Follow your care team's instructions.",
        })
    pending_records = (
        db.query(models.MedicalRecord.id)
        .filter(models.MedicalRecord.patient_id == pid, models.MedicalRecord.diagnosis.is_(None))
        .count()
    )
    if pending_records:
        active_items.append({
            "kind": "record",
            "title": "Pending analysis record",
            "subtitle": f"{pending_records} record(s) awaiting review",
            "status": "pending",
            "status_label": "Pending",
            "start_time": None,
            "last_update": None,
            "next_step": "Ask your doctor about the result at your next visit.",
        })

    # ---------- Average wait (real: schedule → completion gap) ----------
    wait_history = []
    for a in appts:
        if a.status == "completed" and a.scheduled_at:
            end = a.updated_at or a.created_at or a.scheduled_at
            mins = max(0.0, (end - a.scheduled_at).total_seconds() / 60.0)
            if mins <= 60 * 24:
                wait_history.append({
                    "label": a.scheduled_at.strftime("%b %d"),
                    "minutes": round(mins, 1),
                    "appointment_id": a.id,
                })
    wait_available = len(wait_history) > 0
    avg_wait = round(sum(w["minutes"] for w in wait_history) / len(wait_history), 1) if wait_history else None
    wait_history = wait_history[-14:]
    wait_trend = "flat"
    if len(wait_history) >= 4:
        mid = len(wait_history) // 2
        first = sum(x["minutes"] for x in wait_history[:mid]) / max(len(wait_history[:mid]), 1)
        second = sum(x["minutes"] for x in wait_history) / len(wait_history)
        if second < first - 1:
            wait_trend = "down"
        elif second > first + 1:
            wait_trend = "up"
    estimated_minutes = avg_wait
    next_appt = next((a for a in appts if a.status in ("scheduled", "confirmed") and a.scheduled_at >= now), None)

    # ---------- Compliance (verified data only) ----------
    attended = sum(1 for a in appts if a.status == "completed")
    missed = sum(1 for a in appts if a.status == "no_show")
    cancelled = sum(1 for a in appts if a.status == "cancelled")
    upcoming = sum(1 for a in appts if a.status in ("scheduled", "confirmed") and a.scheduled_at >= now)
    considered = attended + missed
    compliance_available = considered > 0
    compliance_pct = round((attended / considered) * 100) if considered else None

    weekly = []
    if appts:
        week_map = {}
        for a in appts:
            if a.status in ("completed", "no_show") and a.scheduled_at:
                wk = a.scheduled_at.isocalendar()[:2]
                entry = week_map.setdefault(wk, {"attended": 0, "missed": 0})
                entry["attended" if a.status == "completed" else "missed"] += 1
        for key in sorted(week_map.keys())[-8:]:
            e = week_map[key]
            weekly.append({"label": f"W{key[1]}", "attended": e["attended"], "missed": e["missed"]})

    # ---------- Insights (deterministic, data-only) ----------
    insights = []
    if today_upcoming > 0:
        insights.append(f"You have {today_upcoming} appointment(s) still ahead today — keep an eye on the time.")
    elif today_count > 0 and today_completed > 0:
        insights.append("Your appointment activity for today is complete. Well done staying on track.")
    if next_appt is not None:
        delta_h = (next_appt.scheduled_at - now).total_seconds() / 3600.0
        if delta_h <= 24:
            when = "in a few hours" if delta_h <= 6 else "tomorrow"
            insights.append(f"Next appointment is {when} — {next_appt.scheduled_at.strftime('%b %d, %I:%M %p')}.")
    if compliance_available:
        if compliance_pct >= 80:
            insights.append(f"Your appointment adherence is strong ({compliance_pct}% attended).")
        elif missed > 0:
            insights.append(f"You missed {missed} appointment(s) — reschedule instead of skipping to keep your care on track.")
    if not appts and admission is None and records_today == 0 and rx_today == 0:
        insights.append("No activity yet — book an appointment or add a health record to get started.")

    return {
        "today": {
            "total": today_count + records_today + rx_today,
            "appointments": today_count,
            "completed": today_completed,
            "upcoming": today_upcoming,
            "cancelled": today_cancelled,
            "record_events": records_today + rx_today,
            "hourly": hourly,
        },
        "active": {"count": len(active_items), "items": active_items},
        "wait": {
            "available": wait_available,
            "average_minutes": avg_wait,
            "estimated_minutes": estimated_minutes,
            "upcoming_at": next_appt.scheduled_at.isoformat() if next_appt else None,
            "trend": wait_trend,
            "history": wait_history,
        },
        "compliance": {
            "available": compliance_available,
            "percentage": compliance_pct,
            "attended": attended,
            "missed": missed,
            "cancelled": cancelled,
            "upcoming": upcoming,
            "weekly": weekly,
            "basis": ["appointment attendance (completed vs no-show)"],
        },
        "insights": insights[:3],
        "generated_at": now.isoformat(),
    }


# ============================================================================
# Doctor Dashboard — live intelligence + analytics
# Aggregates the authenticated doctor's own appointments and roster into
# the four dashboard metrics (Today / Active / Average wait / Compliance).
# Doctor identity always comes from the auth token — never from a
# caller-supplied id. Values are computed from real rows only; no
# simulated wait times or invented percentages.
# ============================================================================
@app.get("/doctor/dashboard/summary")
def doctor_dashboard_summary(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required.")
    now = datetime.utcnow()
    today_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    def _patient_name(pid):
        if not pid:
            return None
        p = db.query(models.Patient).filter(models.Patient.id == pid).first()
        return p.name if p else None

    # Roster: linked + legacy onboarded patients (same scope as
    # /me/dashboard-stats so the tiles stay consistent).
    linked_ids = [
        pid for (pid,) in db.query(models.PatientDoctorLink.patient_id)
        .filter(models.PatientDoctorLink.doctor_user_id == current_user.id)
        .all()
    ]
    onboarded_ids = [
        p.id for p in db.query(models.Patient)
        .filter(models.Patient.onboarded_by_doctor_id == current_user.id)
        .all()
    ]
    roster = sorted(set(linked_ids + onboarded_ids))

    # ---------- Appointments (own + roster-legacy) ----------
    q = (
        db.query(models.Appointment)
        .filter(
            sa_or_(
                models.Appointment.doctor_user_id == current_user.id,
                models.Appointment.patient_id.in_(roster or [0]),
            )
        )
        .order_by(models.Appointment.scheduled_at.asc())
        .all()
    )
    appts = [a for a in q if a.scheduled_at is not None]

    # ---------- Today aggregation ----------
    todays_appts = [a for a in appts if today_start <= a.scheduled_at < today_start + timedelta(days=1)]
    today_completed = sum(1 for a in todays_appts if a.status == "completed")
    today_cancelled = sum(1 for a in todays_appts if a.status == "cancelled")
    today_upcoming = sum(1 for a in todays_appts if a.status in ("scheduled", "confirmed") and a.scheduled_at >= now)
    today_pending = sum(1 for a in todays_appts if a.status in ("scheduled", "confirmed") and a.scheduled_at < now)
    patients_seen = len({a.patient_id for a in todays_appts if a.patient_id})

    hourly = [0] * 24
    for a in todays_appts:
        hourly[a.scheduled_at.hour] += 1

    # ---------- Active workload ----------
    active_items = []
    for a in appts:
        if a.status in ("scheduled", "confirmed") and a.scheduled_at >= now:
            active_items.append({
                "kind": "appointment",
                "title": _patient_name(a.patient_id) or f"Patient #{a.patient_id}",
                "subtitle": f"{a.department or 'Consultation'} · {a.scheduled_at.strftime('%b %d, %I:%M %p')}"
                             + (f" · Room {a.room_number}" if a.room_number else ""),
                "status": a.status,
                "status_label": "Confirmed" if a.status == "confirmed" else "Scheduled",
                "priority": a.priority or "normal",
                "start_time": a.scheduled_at.isoformat(),
                "last_update": (a.updated_at or a.created_at).isoformat() if (a.updated_at or a.created_at) else None,
                "next_step": "Attend the consultation at the scheduled time.",
                "appointment_id": a.id,
            })
            if len(active_items) >= 20:
                break
    active_items.sort(key=lambda it: it["start_time"] or "")

    # ---------- Average wait (real: schedule → completion gap) ----------
    wait_history = []
    for a in appts:
        if a.status == "completed" and a.scheduled_at:
            end = a.updated_at or a.created_at or a.scheduled_at
            mins = max(0.0, (end - a.scheduled_at).total_seconds() / 60.0)
            if mins <= 60 * 24:
                wait_history.append({
                    "label": a.scheduled_at.strftime("%b %d"),
                    "minutes": round(mins, 1),
                    "appointment_id": a.id,
                })
    wait_history = wait_history[-14:]
    wait_available = len(wait_history) > 0
    avg_wait = round(sum(w["minutes"] for w in wait_history) / len(wait_history), 1) if wait_history else None
    wait_trend = "flat"
    if len(wait_history) >= 4:
        mid = len(wait_history) // 2
        first = sum(x["minutes"] for x in wait_history[:mid]) / max(len(wait_history[:mid]), 1)
        second = sum(x["minutes"] for x in wait_history) / len(wait_history)
        if second < first - 1:
            wait_trend = "down"
        elif second > first + 1:
            wait_trend = "up"
    next_appt = next((a for a in appts if a.status in ("scheduled", "confirmed") and a.scheduled_at >= now), None)

    # ---------- Compliance (appointment completion, verified data only) ----------
    attended = sum(1 for a in appts if a.status == "completed")
    missed = sum(1 for a in appts if a.status == "no_show")
    cancelled = sum(1 for a in appts if a.status == "cancelled")
    upcoming = sum(1 for a in appts if a.status in ("scheduled", "confirmed") and a.scheduled_at >= now)
    considered = attended + missed
    compliance_available = considered > 0
    compliance_pct = round((attended / considered) * 100) if considered else None

    weekly = []
    if appts:
        week_map = {}
        for a in appts:
            if a.status in ("completed", "no_show") and a.scheduled_at:
                wk = a.scheduled_at.isocalendar()[:2]
                entry = week_map.setdefault(wk, {"attended": 0, "missed": 0})
                entry["attended" if a.status == "completed" else "missed"] += 1
        for key in sorted(week_map.keys())[-8:]:
            e = week_map[key]
            weekly.append({"label": f"W{key[1]}", "attended": e["attended"], "missed": e["missed"]})

    # ---------- Insights (deterministic, data-only) ----------
    insights = []
    if today_upcoming > 0:
        insights.append(f"{today_upcoming} appointment(s) still ahead today.")
    if today_completed > 0:
        insights.append(f"You completed {today_completed} consultation(s) today.")
    if patients_seen > 0:
        insights.append(f"{patients_seen} different patient(s) seen today.")
    if wait_available:
        if wait_trend == "down":
            insights.append(f"Average wait is improving ({avg_wait} min over {len(wait_history)} completed visit(s)).")
        else:
            insights.append(f"Average wait is {avg_wait} min across your last {len(wait_history)} completed visit(s).")
    elif appts:
        insights.append("Wait analytics will appear once you complete consultations — it is measured from scheduled time to completion.")
    if compliance_available:
        if compliance_pct >= 85:
            insights.append(f"Appointment completion is strong ({compliance_pct}% of {considered} tracked visit(s)).")
        elif missed > 0:
            insights.append(f"{missed} appointment(s) ended as no-show — completion counts only attended vs no-show visits.")
    if not appts:
        insights.append("No appointments yet — new bookings will appear here automatically.")

    return {
        "today": {
            "total": len(todays_appts),
            "appointments": len(todays_appts),
            "completed": today_completed,
            "upcoming": today_upcoming,
            "pending": today_pending,
            "cancelled": today_cancelled,
            "patients_seen": patients_seen,
            "hourly": hourly,
        },
        "active": {
            "count": len(active_items),
            "today_handled": today_completed,
            "waiting": sum(1 for a in todays_appts if a.status in ("scheduled", "confirmed") and a.scheduled_at >= now),
            "items": active_items,
        },
        "wait": {
            "available": wait_available,
            "average_minutes": avg_wait,
            "estimated_minutes": avg_wait,
            "next_at": next_appt.scheduled_at.isoformat() if next_appt else None,
            "trend": wait_trend,
            "history": wait_history,
        },
        "compliance": {
            "available": compliance_available,
            "percentage": compliance_pct,
            "attended": attended,
            "missed": missed,
            "cancelled": cancelled,
            "upcoming": upcoming,
            "weekly": weekly,
            "basis": ["appointment completion (completed vs no-show)"],
        },
        "insights": insights[:3],
        "generated_at": now.isoformat(),
    }


@app.patch("/me", response_model=schemas.UserOut)
def update_me(
    update: schemas.UserUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    if update.full_name is not None:
        current_user.full_name = update.full_name
    if update.profile_picture is not None:
        current_user.profile_picture = update.profile_picture
    db.commit()
    db.refresh(current_user)
    return current_user


@app.post("/change-password")
def change_password(
    payload: schemas.PasswordChange,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    if not auth.verify_password(payload.current_password, current_user.hashed_password):
        raise HTTPException(status_code=401, detail="Current password is incorrect")

    current_user.hashed_password = auth.hash_password(payload.new_password)
    db.commit()
    return {"message": "Password updated successfully"}


# ---------------- Profile picture ----------------

ALLOWED_AVATAR_MIMES = {"image/jpeg", "image/png", "image/webp"}
ALLOWED_AVATAR_EXTS = {".jpg", ".jpeg", ".png", ".webp"}
AVATAR_MAX_BYTES = 2 * 1024 * 1024  # 2 MB

# 1x1 transparent PNG, returned when a user has no profile picture so the
# frontend <img> never gets a 404 + broken-image icon.
_TRANSPARENT_PNG_BYTES = bytes.fromhex(
    "89504e470d0a1a0a0000000d49484452000000010000000108060000001f15c4"
    "890000000d49444154789c6300010000000500010d0a2db40000000049454e44ae"
    "426082"
)


def _avatar_ext(filename: str) -> str:
    """Pick a safe extension for an uploaded avatar. Defaults to .jpg."""
    if not filename:
        return ".jpg"
    _, ext = os.path.splitext(filename.lower())
    return ext if ext in ALLOWED_AVATAR_EXTS else ".jpg"


def _transparent_png_response():
    from fastapi import Response
    return Response(
        content=_TRANSPARENT_PNG_BYTES,
        media_type="image/png",
        headers={"Cache-Control": "private, max-age=300"},
    )


@app.post("/me/avatar")
async def upload_my_avatar(
    file: UploadFile = File(...),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Upload (or replace) the logged-in user's profile picture."""
    mime = (file.content_type or "").lower()
    if mime not in ALLOWED_AVATAR_MIMES:
        raise HTTPException(
            status_code=400,
            detail=f"Unsupported image type '{mime}'. Allowed: jpeg, png, webp.",
        )

    content = await file.read()
    if len(content) > AVATAR_MAX_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"Image too large. Max {AVATAR_MAX_BYTES // (1024 * 1024)} MB.",
        )

    avatar_dir = os.path.join(UPLOAD_DIR, "avatars")
    os.makedirs(avatar_dir, exist_ok=True)

    ext = _avatar_ext(file.filename or "")

    # Delete the previous avatar file (if any) so we don't leak storage.
    if current_user.profile_picture:
        old_path = os.path.join(UPLOAD_DIR, current_user.profile_picture)
        try:
            if os.path.exists(old_path):
                os.remove(old_path)
        except OSError:
            pass  # best-effort cleanup

    disk_path = os.path.join(avatar_dir, f"{current_user.id}{ext}")
    with open(disk_path, "wb") as f:
        f.write(content)

    current_user.profile_picture = f"avatars/{current_user.id}{ext}"
    db.commit()
    db.refresh(current_user)

    return {
        "profile_picture": current_user.profile_picture,
        "url": f"/me/avatar/{current_user.id}",
    }


@app.get("/me/avatar/{user_id}")
def get_avatar(
    user_id: int,
    db: Session = Depends(get_db),
):
    """Serve a user's profile picture. Returns a 1x1 transparent PNG if missing."""
    user = db.query(models.User).filter(models.User.id == user_id).first()
    if not user or not user.profile_picture:
        return _transparent_png_response()

    disk_path = os.path.join(UPLOAD_DIR, user.profile_picture)
    if not os.path.exists(disk_path):
        return _transparent_png_response()

    ext = os.path.splitext(disk_path)[1].lower()
    media_type = {
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
        ".png": "image/png",
        ".webp": "image/webp",
    }.get(ext, "application/octet-stream")

    return FileResponse(
        disk_path,
        media_type=media_type,
        headers={"Cache-Control": "private, max-age=300"},
    )


# ---------------- Disease Prediction ----------------

@app.post("/predict-disease")
def predict_disease(
    request: schemas.PredictionRequest,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    # Validate & normalize input before touching the model. Short/empty
    # inputs get a clear message instead of a confusing model response.
    symptoms = (request.symptoms or "").strip()
    if not symptoms:
        raise HTTPException(status_code=400, detail="Please describe your symptoms so they can be analyzed.")

    try:
        result = gemini_client.predict_disease(
            symptoms=symptoms,
            age=request.age,
            gender=request.gender,
            history=request.history
        )
    except Exception as exc:
        # predict_disease is designed not to raise, but keep a last-resort
        # guard so an unexpected model layer error never surfaces a 500.
        logger.warning("predict_disease endpoint error: %s", exc)
        result = {
            "patient_summary": "The symptom analysis service is temporarily unavailable. Please try again in a moment.",
            "conditions": [],
            "severity": {"level": "moderate", "score": 0, "explanation": "Service temporarily unavailable.", "urgency": "Try again shortly."},
            "red_flags": [],
            "recommended_tests": [],
            "self_care": [],
            "when_to_see_doctor": [],
            "questions_for_doctor": [],
            "see_doctor": False,
            "doctor_urgency": "",
            "ai_confidence": {"score": 0, "explanation": "Service error"},
            "doctor_verification_required": True,
            "clinical_disclaimer": "This is AI-assisted analysis for informational purposes only. Always consult a qualified healthcare professional for diagnosis and treatment.",
            "service_unavailable": True,
        }

    # If a patient_id was given, automatically save this as a medical record
    if request.patient_id and not result.get("service_unavailable"):
        patient = db.query(models.Patient).filter(models.Patient.id == request.patient_id).first()
        if not patient:
            raise HTTPException(status_code=404, detail="Patient not found")

        record = models.MedicalRecord(
            patient_id=request.patient_id,
            symptoms=symptoms,
            diagnosis=json.dumps(result),
            notes="Auto-generated by AI prediction"
        )
        db.add(record)
        db.commit()

    # Auto-save to AI report history (patient logged in or patient_id provided)
    _hook_save_ai_report(
        db,
        patient_id=current_user.patient_id or request.patient_id,
        feature_type="symptom_checker",
        report_type="Symptom Checker Report",
        title=f"Symptom analysis — {symptoms[:60]}",
        generated_result=json.dumps(result),
        findings=result.get("patient_summary") or "",
        recommendations=json.dumps(result.get("self_care") or []),
        input_summary=json.dumps({"symptoms": symptoms, "age": request.age, "gender": request.gender}),
        ai_model="gemini",
        source_entity_type="analysis",
    )

    return Response(content=json.dumps(result), media_type="application/json")




# ---------------- Symptom Image Analysis ----------------

@app.post("/symptom-image-analyze")
async def symptom_image_analyze(
    file: UploadFile = File(...),
    symptoms: str = Form(""),
    age: int = Form(None),
    gender: str = Form(None),
    history: str = Form(None),
    patient_id: int = Form(None),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    """Analyze a body-part image along with symptom text to provide
    a comprehensive symptom assessment. The pipeline:
    
    1. Validate & preprocess the uploaded image
    2. Use vision model to identify body part and visible signs
    3. Combine with user-provided symptom text
    4. Generate comprehensive analysis with conditions, severity, next steps
    
    Returns a structured result with:
    - body_part_detected: identified body region
    - visible_signs: what the AI sees in the image
    - conditions: list of possible conditions
    - severity: low/medium/high/critical
    - confidence: 0-1
    - recommendations: actionable next steps
    - medications: specific medication suggestions
    - pipeline_stages: each stage of the analysis
    """
    # 1. Read and validate the image
    file_bytes = await file.read()
    mime_type = file.content_type or "image/jpeg"
    
    if len(file_bytes) < 100:
        raise HTTPException(status_code=400, detail="Image too small or empty")
    
    if not mime_type.startswith("image/"):
        raise HTTPException(status_code=400, detail="File must be an image")
    
    import base64
    img_b64 = base64.b64encode(file_bytes).decode("utf-8")
    
    pipeline_stages = []
    pipeline_stages.append({"stage": "Image Validation", "status": "complete", "detail": f"Valid {mime_type} image, {len(file_bytes)} bytes"})
    
    # 2. Image preprocessing (basic validation)
    pipeline_stages.append({"stage": "Image Preprocessing", "status": "complete", "detail": "Image decoded and ready for analysis"})
    
    # 3. Use Nemotron Omni for body-part identification and visible sign detection
    vision_prompt = f"""You are a medical image analysis AI. Analyze this body-part image carefully.

First, identify:
1. What body part is shown in the image
2. What visible signs, abnormalities, or conditions you can observe
3. Any measurements, colors, textures, or patterns that are notable

Then, provide a brief description of what you see.

Patient-reported symptoms: {symptoms or 'None provided'}
Patient age: {age or 'Unknown'}
Patient gender: {gender or 'Unknown'}
Medical history: {history or 'None provided'}

Return your analysis as JSON:
{{
  "body_part": "identified body part",
  "body_region": "anatomical region",
  "visible_signs": ["list of visible signs/abnormalities"],
  "skin_observations": "description of skin condition if visible",
  "swelling": "any swelling noted",
  "color_changes": "any color changes",
  "texture": "skin texture observations",
  "wounds_or_lesions": "any wounds, cuts, rashes, or lesions",
  "overall_impression": "brief overall impression of what you observe"
}}

Be specific and clinical in your observations. Do NOT diagnose - just describe what you see."""

    pipeline_stages.append({"stage": "Body-Part Identification", "status": "in_progress", "detail": "Analyzing image..."})
    
    # Call vision model
    vision_result = gemini_client._omni_analyze(img_b64, mime_type, vision_prompt)
    
    pipeline_stages[-1] = {"stage": "Body-Part Identification", "status": "complete", "detail": "Body part identified"}
    pipeline_stages.append({"stage": "Medical Vision Analysis", "status": "complete", "detail": "Visible signs detected"})
    
    # Parse vision result
    import json as _json
    vision_data = {}
    try:
        vision_data = _json.loads(vision_result)
    except:
        vision_data = {
            "body_part": "Unknown",
            "visible_signs": [vision_result[:200]],
            "overall_impression": vision_result[:300]
        }
    
    # 4. Combine vision analysis with symptom text for comprehensive diagnosis
    pipeline_stages.append({"stage": "Symptom + Visual Analysis Integration", "status": "in_progress", "detail": "Combining visual and text data..."})
    
    combined_prompt = f"""You are an expert medical AI assistant. You have been given:

1. IMAGE ANALYSIS from a body-part photo:
{vision_result}

2. PATIENT-REPORTED SYMPTOMS:
{symptoms or 'No symptoms described'}

3. PATIENT INFORMATION:
- Age: {age or 'Unknown'}
- Gender: {gender or 'Unknown'}  
- Medical History: {history or 'None provided'}

Based on BOTH the visual analysis AND the reported symptoms, provide a comprehensive assessment:

Return ONLY valid JSON in this format:
{{
  "possible_conditions": [
    {{
      "name": "Condition name",
      "likelihood": "high/medium/low",
      "description": "Brief explanation of why this condition is considered",
      "matching_symptoms": ["symptoms that match this condition"],
      "matching_visual_signs": ["visual signs from the image that support this"]
    }}
  ],
  "severity": "low/medium/high/critical",
  "severity_explanation": "Why this severity level was assigned",
  "confidence": 0.85,
  "confidence_explanation": "Factors affecting confidence level",
  "visible_analysis": {{
    "body_part": "{vision_data.get('body_part', 'Unknown')}",
    "key_findings": ["key findings from image analysis"],
    "abnormalities_detected": true_or_false
  }},
  "differential_diagnosis": [
    {{
      "condition": "condition name",
      "probability": "percentage like 45%",
      "reasoning": "why this is considered"
    }}
  ],
  "medications": [
    {{
      "name": "Generic drug name",
      "dosage": "500mg",
      "frequency": "twice daily",
      "duration": "7 days",
      "purpose": "what it treats",
      "instructions": "take with food"
    }}
  ],
  "recommended_tests": [
    {{
      "name": "Test name",
      "purpose": "why this test is recommended",
      "urgency": "routine/urgent"
    }}
  ],
  "lifestyle_recommendations": ["specific lifestyle advice"],
  "warning_signs": ["symptoms that would indicate need for emergency care"],
  "next_steps": ["clear actionable next steps for the patient"],
  "when_to_see_doctor": "specific guidance on when to seek in-person care",
  "follow_up_timeline": "when to reassess if symptoms don't improve"
}}

IMPORTANT: Always suggest SPECIFIC medications with dosages. Be thorough and detailed. The patient needs actionable guidance."""

    # Call LLM for comprehensive analysis
    try:
        analysis_text = gemini_client._nemotron_chat(combined_prompt)
        analysis_data = _json.loads(gemini_client._clean_json_text(analysis_text))
    except Exception as e:
        analysis_data = {
            "possible_conditions": [],
            "severity": "medium",
            "confidence": 0.5,
            "medications": [],
            "next_steps": ["Please consult a healthcare provider for proper evaluation"]
        }
    
    pipeline_stages[-1] = {"stage": "Symptom + Visual Analysis Integration", "status": "complete", "detail": "Analysis complete"}
    pipeline_stages.append({"stage": "AI Medical Assessment", "status": "complete", "detail": f"Found {len(analysis_data.get('possible_conditions', []))} possible conditions"})
    pipeline_stages.append({"stage": "Severity & Risk Assessment", "status": "complete", "detail": f"Severity: {analysis_data.get('severity', 'medium')}"})
    pipeline_stages.append({"stage": "Recommendation Generation", "status": "complete", "detail": f"Generated {len(analysis_data.get('medications', []))} medication suggestions"})
    
    # Combine all results
    result = {
        "body_part": vision_data.get("body_part", "Unknown"),
        "visible_signs": vision_data.get("visible_signs", []),
        "visible_analysis": vision_data,
        "symptoms_text": symptoms,
        "conditions": [c.get("name", "") for c in analysis_data.get("possible_conditions", [])],
        "possible_conditions": analysis_data.get("possible_conditions", []),
        "severity": analysis_data.get("severity", "medium"),
        "severity_explanation": analysis_data.get("severity_explanation", ""),
        "confidence": analysis_data.get("confidence", 0.5),
        "confidence_explanation": analysis_data.get("confidence_explanation", ""),
        "differential_diagnosis": analysis_data.get("differential_diagnosis", []),
        "medications": analysis_data.get("medications", []),
        "recommended_tests": analysis_data.get("recommended_tests", []),
        "lifestyle_recommendations": analysis_data.get("lifestyle_recommendations", []),
        "warning_signs": analysis_data.get("warning_signs", []),
        "next_steps": analysis_data.get("next_steps", []),
        "when_to_see_doctor": analysis_data.get("when_to_see_doctor", ""),
        "follow_up_timeline": analysis_data.get("follow_up_timeline", ""),
        "recommendation": analysis_data.get("next_steps", ["Consult a doctor"])[0] if analysis_data.get("next_steps") else "Consult a doctor",
        "risk_level": analysis_data.get("severity", "medium"),
        "pipeline_stages": pipeline_stages
    }
    
    # Save to patient record if patient_id provided
    if patient_id:
        patient = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
        if patient:
            record = models.MedicalRecord(
                patient_id=patient_id,
                symptoms=f"[Image Analysis] {symptoms}",
                diagnosis=json.dumps(result),
                notes="Auto-generated by Symptom Image Analysis AI"
            )
            db.add(record)
            db.commit()
    
    return result


