# ---------------- Diet & Fitness Plan ----------------

def calculate_bmi(weight_kg: float, height_cm: float) -> tuple[float, str]:
    """Calculates BMI and its category. Done in plain Python for accuracy - not by Gemini."""
    height_m = height_cm / 100
    bmi = round(weight_kg / (height_m ** 2), 1)

    if bmi < 18.5:
        category = "underweight"
    elif bmi < 25:
        category = "normal"
    elif bmi < 30:
        category = "overweight"
    else:
        category = "obese"

    return bmi, category


@app.post("/diet-plan", response_model=schemas.DietPlanOut)
def diet_plan(
    request: schemas.DietPlanRequest,
    current_user: models.User = Depends(auth.get_current_user)
):
    bmi, bmi_category = calculate_bmi(request.weight_kg, request.height_cm)

    ai_result = gemini_client.get_diet_fitness_plan(
        age=request.age,
        gender=request.gender,
        bmi=bmi,
        bmi_category=bmi_category,
        conditions=request.conditions,
        fitness_goal=request.fitness_goal
    )

    return {
        "bmi": bmi,
        "bmi_category": bmi_category,
        "diet_recommendations": ai_result.get("diet_recommendations", []),
        "fitness_recommendations": ai_result.get("fitness_recommendations", []),
        "calorie_target": ai_result.get("calorie_target", "unavailable"),
        "precautions": ai_result.get("precautions", "")
    }


# ---------------- Prescription Digitization ----------------

@app.post("/digitize-prescription", response_model=schemas.PrescriptionDigitizeOut)
async def digitize_prescription(
    file: UploadFile = File(...),
    patient_id: Optional[int] = Form(None),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    image_bytes = await file.read()
    mime_type = file.content_type or "image/jpeg"

    result = gemini_client.digitize_prescription(image_bytes, mime_type)

    # If a patient_id was given, save each extracted medicine as a prescription record
    if patient_id:
        patient = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
        if not patient:
            raise HTTPException(status_code=404, detail="Patient not found")

        for med in result.get("medicines", []):
            new_prescription = models.Prescription(
                patient_id=patient_id,
                medicine_name=med.get("name", "unknown"),
                dosage=med.get("dosage"),
                instructions=f"Frequency: {med.get('frequency', '-')}, Duration: {med.get('duration', '-')}"
            )
            db.add(new_prescription)
        db.commit()

    return result


# ---------------- Notification preferences ----------------

def _get_or_create_prefs(db: Session, user_id: int) -> models.NotificationPreference:
    """Lazy-create a default row so first-time callers always get a usable object."""
    prefs = db.query(models.NotificationPreference).filter(
        models.NotificationPreference.user_id == user_id
    ).first()
    if prefs:
        return prefs
    prefs = models.NotificationPreference(user_id=user_id)
    db.add(prefs)
    db.commit()
    db.refresh(prefs)
    return prefs


@app.get("/notifications/preferences", response_model=schemas.NotificationPrefsOut)
def get_notification_prefs(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Returns the current user's notification preferences. Creates a row with
    defaults on first call so the frontend never has to special-case 404."""
    return _get_or_create_prefs(db, current_user.id)


@app.put("/notifications/preferences", response_model=schemas.NotificationPrefsOut)
def update_notification_prefs(
    payload: schemas.NotificationPrefsUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Partial-update friendly: only the fields the client sends are touched."""
    prefs = _get_or_create_prefs(db, current_user.id)
    data = payload.model_dump(exclude_unset=True)
    # Guard the lead-time field so we never store nonsensical values.
    if "reminder_lead_minutes" in data:
        lead = data["reminder_lead_minutes"]
        if lead is None or lead < 0 or lead > 24 * 60:
            raise HTTPException(status_code=400, detail="reminder_lead_minutes must be between 0 and 1440.")
    for field, value in data.items():
        setattr(prefs, field, value)
    db.commit()
    db.refresh(prefs)
    return prefs


@app.post("/notifications/test-browser")
def test_browser_notification(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Endpoint the frontend calls after the user enables browser notifications.
    Verifies the preference is on, returns a payload the frontend uses to fire
    a real ``new Notification(...)`` via the browser Notification API."""
    prefs = _get_or_create_prefs(db, current_user.id)
    return {
        "ok": True,
        "browser_enabled": prefs.browser_enabled,
        "title": "Medical Intelligence System",
        "body": "Notifications are working. You'll be reminded before scheduled medicines.",
    }


def _chat_last_read_at(
    db: Session,
    patient_id: int,
    doctor_user_id: int,
    sender: "models.User",
) -> "Optional[datetime]":
    """Return the timestamp the SENDER (the notif recipient's other side)
    last marked this thread as read. We track per-side cursors on each
    message (ChatMessage.doctor_last_read_at / patient_last_read_at) rather
    than per-thread, so the "recipient is caught up" check is: max of the
    side's column across the whole thread.

    The pair's sides: the patient (patient_last_read_at) and the provider
    participant stored in the legacy doctor_user_id column — a doctor, an
    assigned nurse, or a hospital admin (doctor_last_read_at).
    - Sender == provider side  -> recipient is the patient -> patient col.
    - Any other sender         -> recipient is the provider user -> doctor col.
    Returns None when the recipient hasn't ever read the thread."""
    col = (
        models.ChatMessage.patient_last_read_at
        if sender.id == doctor_user_id
        else models.ChatMessage.doctor_last_read_at
    )
    row = (
        db.query(col)
        .filter(
            models.ChatMessage.patient_id == patient_id,
            models.ChatMessage.doctor_user_id == doctor_user_id,
        )
        .order_by(col.desc())
        .first()
    )
    return row[0] if row and row[0] else None


# ---- Notification event helpers (the bell feed) ----
# Persistent log of every notification the system produces for a user.
# Honors the user's per-feature opt-out flags on NotificationPreference.

# Map: NotificationPreference flag -> notification kind value. Single source
# of truth so a typo here can't desync the toggle from the fired events.
# Hospital/nurse/discharge events all bucket under notif_admission_events so
# we don't need a column migration per kind.
_KIND_TO_FLAG = {
    "patient_added":   "notif_patient_added",
    "doctor_linked":   "notif_doctor_linked",
    "chat_message":    "notif_chat_message",
    "admit_pending_placement":             "notif_admission_events",
    "admit_placed":                        "notif_admission_events",
    "nurse_assigned":                      "notif_admission_events",
    "discharge_appeal_filed":              "notif_admission_events",
    "discharge_appeal_hospital_approved":  "notif_admission_events",
    "discharge_appeal_doctor_approved":    "notif_admission_events",
    "discharge_complete":                  "notif_admission_events",
    # Nurse → doctor: medication / treatment / note updates. Buckets under
    # notif_admission_events so the doctor sees them in the bell feed and on
    # the patient dashboard without needing a new opt-out column.
    "nurse_medication_added":     "notif_admission_events",
    "nurse_medication_stopped":   "notif_admission_events",
    "nurse_treatment_added":      "notif_admission_events",
    "nurse_treatment_completed":  "notif_admission_events",
    "nurse_report_sent":          "notif_admission_events",
    "nurse_note_added":           "notif_admission_events",
    # 2026-08: doctor's withdraw of a pending hospital-admit request.
    "admit_cancelled":            "notif_admission_events",
    # 2026-08: nurse handed a patient to another nurse (same hospital).
    "nurse_transferred_away":     "notif_admission_events",
    # 2026-08: nurse is asking the hospital admin to pick a new nurse.
    "patient_needs_new_nurse":    "notif_admission_events",
    # 2026-08: nurse pushed an AI-aggregated summary report (medications +
    # treatments + prior notes + Gemini brief) to the doctor.
    "nurse_ai_report":            "notif_admission_events",
    # 2026-09 care-task assignment workflow (nurse My Assignments).
    "task_assigned":              "notif_admission_events",
    "task_escalated":             "notif_admission_events",
    "task_followup_due":          "notif_admission_events",
    "task_overdue":               "notif_admission_events",
    # Patient <-> doctor care-network requests/decisions (bell feed).
    "doctor_link_request":        "notif_doctor_linked",
    "doctor_link_accepted":       "notif_doctor_linked",
    "doctor_link_rejected":       "notif_doctor_linked",
}


# ===========================================================================
# SYSTEM ACTIVITY ENGINE helpers
# ===========================================================================

_ACTIVITY_PATIENT_CACHE: dict = {}


def _patient_display_name(db: Session, patient_id: Optional[int]) -> str:
    """Return the Patient.name for a patients.id, or 'Patient #<id>'."""
    if not patient_id:
        return ""
    cached = _ACTIVITY_PATIENT_CACHE.get(patient_id)
    if cached:
        return cached
    row = db.query(models.Patient.name).filter(models.Patient.id == patient_id).first()
    name = (row[0] if row and row[0] else f"Patient #{patient_id}")
    if len(_ACTIVITY_PATIENT_CACHE) < 2000:
        _ACTIVITY_PATIENT_CACHE[patient_id] = name
    return name


def _user_display_name(db: Session, user_id: Optional[int]) -> str:
    """Return a User's full name/username for an id."""
    if not user_id:
        return ""
    row = db.query(models.User).filter(models.User.id == user_id).first()
    if not row:
        return ""
    return row.full_name or row.username or ""


def _record_activity(
    db: Session,
    *,
    actor_user_id: Optional[int],
    actor_role: Optional[str],
    event_type: str,
    entity_type: Optional[str] = None,
    entity_id: Optional[int] = None,
    detail: str,
    patient_id: Optional[int] = None,
    hospital_id: Optional[int] = None,
    nurse_user_id: Optional[int] = None,
) -> models.SystemActivity:
    """Append one row to the shared system-activity feed. The detail string
    must stay free of private medical content (names only where they are
    already authorized for the receiving dashboard)."""
    row = models.SystemActivity(
        actor_user_id=actor_user_id,
        actor_role=actor_role,
        event_type=event_type[:60],
        entity_type=entity_type,
        entity_id=entity_id,
        detail=(detail or "")[:300],
        patient_id=patient_id,
        hospital_id=hospital_id,
        nurse_user_id=nurse_user_id,
        created_at=datetime.utcnow(),
    )
    db.add(row)
    try:
        db.commit()
    except Exception:
        db.rollback()
        # The feed is best-effort — never let a logging failure break the
        # real operation that triggered it.
        return None
    db.refresh(row)
    return row


