@app.get("/doctor/profile", response_model=schemas.DoctorProfileOut)
def get_doctor_profile(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Only doctor accounts can access this endpoint")
    profile = db.query(models.DoctorProfile).filter(models.DoctorProfile.user_id == current_user.id).first()
    if not profile:
        raise HTTPException(status_code=404, detail="Doctor profile not set up yet")
    return profile


@app.put("/doctor/profile", response_model=schemas.DoctorProfileOut)
def upsert_doctor_profile(
    payload: schemas.DoctorProfileCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Only doctor accounts can access this endpoint")

    profile = db.query(models.DoctorProfile).filter(models.DoctorProfile.user_id == current_user.id).first()
    if not profile:
        profile = models.DoctorProfile(user_id=current_user.id)
        db.add(profile)

    # Apply only the fields the client sent (partial-update friendly)
    for field, value in payload.model_dump(exclude_unset=True).items():
        setattr(profile, field, value)

    db.commit()
    db.refresh(profile)
    return profile


# ---------------- Doctor extended profile ----------------
# Child-table CRUD for the rich doctor profile: career history, education,
# practice addresses, contact details. Each table is a 1-doctor → many-rows
# relation (mirrors the MedicalHistoryEntry / PatientReport pattern).

def _ensure_doctor(current_user: models.User) -> None:
    """Shared guard: every write endpoint on doctor child tables requires role=doctor."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Only doctor accounts can access this endpoint")


