@app.post("/doctor/contacts", response_model=schemas.ContactOut, status_code=201)
def add_contact(
    payload: schemas.ContactCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    _ensure_doctor(current_user)
    if payload.kind not in schemas.ALLOWED_CONTACT_KINDS:
        raise HTTPException(
            status_code=422,
            detail=f"kind must be one of: {sorted(schemas.ALLOWED_CONTACT_KINDS)}",
        )
    if payload.is_primary:
        # Only one primary contact per kind per doctor.
        db.query(models.DoctorContact).filter(
            models.DoctorContact.user_id == current_user.id,
            models.DoctorContact.kind == payload.kind,
            models.DoctorContact.is_primary == True,  # noqa: E712
        ).update({models.DoctorContact.is_primary: False})
    row = models.DoctorContact(user_id=current_user.id, **payload.model_dump())
    db.add(row)
    db.commit()
    db.refresh(row)
    return row


