# ---------- Doctor invite codes ----------
# ---------------- Doctor directory + Patient link endpoints ----------------
# Replaces the old invite-code system. Patients now pick a doctor from a
# dropdown (populated by GET /doctors) at signup time, and can add/remove
# doctors later from their own dashboard via POST/DELETE below.

@app.get("/doctors", response_model=list[schemas.DoctorListItem])
def list_doctors(
    db: Session = Depends(get_db),
    current_user: Optional[models.User] = Depends(auth.get_optional_user),
):
    """List all doctor accounts. Used by the patient-side signup dropdown
    AND the patient's "Add another doctor" modal. Includes the doctor's
    specialization so patients can pick by department.

    Public (no auth required) so the signup-time doctor picker works for
    a brand-new patient who hasn't logged in yet. The list only exposes
    non-sensitive fields (name, username, specialization, clinic) — no
    email, no phone, no patient roster.
    """
    rows = (
        db.query(models.User)
        .outerjoin(models.DoctorProfile, models.DoctorProfile.user_id == models.User.id)
        .filter(models.User.role == "doctor")
        .order_by(models.User.full_name.asc().nullslast(), models.User.username.asc())
        .all()
    )
    out: list[schemas.DoctorListItem] = []
    for u in rows:
        profile = (
            db.query(models.DoctorProfile)
            .filter(models.DoctorProfile.user_id == u.id)
            .first()
        )
        out.append(
            schemas.DoctorListItem(
                id=u.id,
                username=u.username,
                full_name=u.full_name,
                specialization=profile.specialization if profile else None,
                clinic_name=profile.clinic_name if profile else None,
            )
        )
    return out


@app.get("/doctors/directory", response_model=list[schemas.DoctorDirectoryItem])
def doctors_directory(
    q: Optional[str] = None,
    department: Optional[str] = None,
    state: Optional[str] = None,
    min_experience: Optional[int] = None,
    hospital: Optional[str] = None,
    skip: int = 0,
    limit: Optional[int] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Doctor directory — rich records for the patient-side discovery page.

    Requires authentication (any logged-in user). Returns every doctor on the
    platform joined with their profile, primary practice address, and
    primary contact so the front-end can render a discovery card without
    further round-trips.

    Filters (all optional, AND-combined):
      q               free-text search across full_name, hospital_name,
                      hospital_address, specialization, city, state
      department      exact match on DoctorProfile.specialization
                      (case-insensitive)
      state           exact match on DoctorAddress.state (case-insensitive)
      min_experience  DoctorProfile.experience_years >= value
      hospital        partial match on hospital_name (case-insensitive)
      skip/limit      server-side pagination window

    For patient-role callers each item also carries `is_linked` so the UI
    can render Link / Unlink states without a second round-trip.
    """
    rows = (
        db.query(models.User)
        .outerjoin(models.DoctorProfile, models.DoctorProfile.user_id == models.User.id)
        .filter(models.User.role == "doctor")
        .order_by(models.User.full_name.asc().nullslast(), models.User.username.asc())
        .all()
    )

    # Pre-fetch primary addresses + primary contacts in two queries so we
    # don't hit N+1 when iterating doctors.
    user_ids = [u.id for u in rows]
    primary_addresses: dict[int, models.DoctorAddress] = {}
    primary_contacts: dict[int, models.DoctorContact] = {}
    if user_ids:
        for a in (
            db.query(models.DoctorAddress)
            .filter(models.DoctorAddress.user_id.in_(user_ids))
            .filter(models.DoctorAddress.is_primary == True)  # noqa: E712
            .all()
        ):
            # If multiple primary rows exist for one user, keep the first.
            primary_addresses.setdefault(a.user_id, a)
        for c in (
            db.query(models.DoctorContact)
            .filter(models.DoctorContact.user_id.in_(user_ids))
            .filter(models.DoctorContact.is_primary == True)  # noqa: E712
            .all()
        ):
            primary_contacts.setdefault(c.user_id, c)

    # Normalise filter inputs.
    q_norm = (q or "").strip().lower()
    dept_norm = (department or "").strip().lower()
    state_norm = (state or "").strip().lower()
    hosp_norm = (hospital or "").strip().lower()
    min_exp = int(min_experience) if min_experience is not None else None

    # Patient viewers: preload the doctors they already have links to so
    # each item can carry is_linked without a per-doctor query.
    linked_ids: set[int] = set()
    if current_user and current_user.role == "patient" and current_user.patient_id:
        link_rows = (
            db.query(models.PatientDoctorLink.doctor_user_id)
            .filter(models.PatientDoctorLink.patient_id == current_user.patient_id)
            .all()
        )
        linked_ids = {r[0] for r in link_rows}

    out: list[schemas.DoctorDirectoryItem] = []
    for u in rows:
        profile = (
            db.query(models.DoctorProfile)
            .filter(models.DoctorProfile.user_id == u.id)
            .first()
        )
        addr = primary_addresses.get(u.id)
        contact = primary_contacts.get(u.id)

        # Hospital name = profile.clinic_name OR (primary address).label OR
        # a derived "{line1}, {city}" if we have any address bits.
        hospital_name = (
            (profile.clinic_name if profile else None)
            or (addr.label if addr else None)
            or None
        )

        # Formatted full address.
        hospital_address = None
        if addr:
            bits = [b for b in (addr.line1, addr.line2) if b]
            if addr.city:
                bits.append(addr.city)
            if addr.state:
                bits.append(addr.state)
            if addr.pincode:
                bits.append(addr.pincode)
            if bits:
                hospital_address = ", ".join(bits)

        # Filters applied in Python here (we already pulled the rows).
        if dept_norm:
            spec = (profile.specialization if profile else None) or ""
            if dept_norm != spec.lower():
                continue
        if state_norm:
            addr_state = (addr.state if addr else None) or ""
            if state_norm != addr_state.lower():
                continue
        if min_exp is not None:
            years = profile.experience_years if profile else None
            if years is None or years < min_exp:
                continue
        if hosp_norm and hospital_name:
            if hosp_norm not in hospital_name.lower():
                continue

        item = schemas.DoctorDirectoryItem(
            id=u.id,
            full_name=u.full_name,
            specialization=profile.specialization if profile else None,
            experience_years=profile.experience_years if profile else None,
            hospital_name=hospital_name,
            hospital_address=hospital_address,
            city=addr.city if addr else None,
            state=addr.state if addr else None,
            contact_value=contact.value if contact else None,
            contact_kind=contact.kind if contact else None,
            is_linked=u.id in linked_ids,
        )

        # Free-text q matches against the flattened record.
        if q_norm:
            hay = " ".join(
                str(x) for x in (
                    item.full_name, item.specialization, item.hospital_name,
                    item.hospital_address, item.city, item.state,
                ) if x
            ).lower()
            if q_norm not in hay:
                continue

        out.append(item)

    # Server-side pagination (optional). The per-doctor fetch happens for the
    # whole filtered set, then we slice out the requested window.
    if skip or limit is not None:
        end = None if limit is None else skip + limit
        return out[skip:end]
    return out


@app.get("/doctors/{doctor_user_id}/public-profile", response_model=schemas.DoctorPublicProfile)
def doctor_public_profile(
    doctor_user_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Patient-visible profile for one doctor (Manage → Doctors detail view).
    Only public professional fields the doctor configured are returned —
    never credentials, internal data, or patient rosters."""
    u = (
        db.query(models.User)
        .filter(models.User.id == doctor_user_id, models.User.role == "doctor")
        .first()
    )
    if not u:
        raise HTTPException(status_code=404, detail="Doctor not found")
    profile = (
        db.query(models.DoctorProfile)
        .filter(models.DoctorProfile.user_id == u.id)
        .first()
    )
    addr = (
        db.query(models.DoctorAddress)
        .filter(
            models.DoctorAddress.user_id == u.id,
            models.DoctorAddress.is_primary == True,  # noqa: E712
        )
        .first()
    )
    contact = (
        db.query(models.DoctorContact)
        .filter(
            models.DoctorContact.user_id == u.id,
            models.DoctorContact.is_primary == True,  # noqa: E712
        )
        .first()
    )
    clinic_address = None
    if addr:
        bits = [b for b in (addr.line1, addr.line2) if b]
        if addr.city:
            bits.append(addr.city)
        if addr.state:
            bits.append(addr.state)
        if addr.pincode:
            bits.append(addr.pincode)
        if bits:
            clinic_address = ", ".join(bits)

    is_linked = False
    if current_user and current_user.role == "patient" and current_user.patient_id:
        is_linked = _doctor_has_patient_link(db, u.id, current_user.patient_id)

    return schemas.DoctorPublicProfile(
        id=u.id,
        full_name=u.full_name,
        profile_picture=u.profile_picture,
        username=u.username,
        specialization=profile.specialization if profile else None,
        qualifications=profile.qualifications if profile else None,
        experience_years=profile.experience_years if profile else None,
        clinic_name=profile.clinic_name if profile else None,
        clinic_address=clinic_address or (profile.clinic_address if profile else None),
        consultation_fee=profile.consultation_fee if profile else None,
        bio=profile.bio if profile else None,
        languages=profile.languages if profile else None,
        available_hours=profile.available_hours if profile else None,
        city=addr.city if addr else None,
        state=addr.state if addr else None,
        contact_value=contact.value if contact else None,
        contact_kind=contact.kind if contact else None,
        is_linked=is_linked,
        created_at=u.created_at,
    )


@app.post("/patients/{patient_id}/doctors", response_model=schemas.PatientDoctorLinkOut)
def add_doctor_link(
    patient_id: int,
    payload: schemas.PatientDoctorLinkCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Link a doctor to a patient.

    - The patient can call this on their own record to add a doctor (for a
      different department / advice reason).
    - A doctor who already owns a link to this patient can also add another
      doctor (e.g. they want a colleague in).

    Idempotent: re-linking the same (patient, doctor) pair returns the
    existing row rather than erroring.
    """
    _ensure_patient_or_doctor(current_user, patient_id, db)

    doctor = (
        db.query(models.User)
        .filter(models.User.id == payload.doctor_user_id, models.User.role == "doctor")
        .first()
    )
    if not doctor:
        raise HTTPException(status_code=400, detail="Selected doctor does not exist.")

    department = payload.department or _doctor_specialization(db, doctor.id)
    link = _get_or_create_patient_link(db, patient_id, doctor.id, department)
    _record_care_event(
        db,
        patient_id,
        "doctor_link",
        "doctor",
        actor_user_id=current_user.id,
        doctor_user_id=doctor.id,
    )
    db.commit()
    db.refresh(link)

    # Notify the doctor that a patient has linked to them. Honors the doctor's
    # per-feature opt-out (notif_doctor_linked).
    patient = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    patient_name = patient.name if patient else f"Patient #{patient_id}"
    actor_name = current_user.full_name or current_user.username
    _enqueue_notification(
        db,
        recipient_user_id=doctor.id,
        kind="doctor_linked",
        title=f"{patient_name} linked to you",
        detail=f"{actor_name} added you as their doctor.",
        link="dashboard.html",
    )
    db.commit()

    return schemas.PatientDoctorLinkOut(
        id=link.id,
        patient_id=link.patient_id,
        doctor_user_id=link.doctor_user_id,
        doctor_name=doctor.full_name or doctor.username,
        department=link.department,
        created_at=link.created_at,
    )


@app.get("/patients/mine/linked-doctors")
def get_my_linked_doctors(
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Return the list of doctors linked to the authenticated patient."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required")
    links = (
        db.query(models.PatientDoctorLink)
        .filter(models.PatientDoctorLink.patient_id == current_user.patient_id)
        .all()
    )
    doctor_ids = [link.doctor_user_id for link in links]
    profiles_by_uid: dict[int, models.DoctorProfile] = {}
    users_by_id: dict[int, models.User] = {}
    if doctor_ids:
        for p in (
            db.query(models.DoctorProfile)
            .filter(models.DoctorProfile.user_id.in_(doctor_ids))
            .all()
        ):
            profiles_by_uid[p.user_id] = p
        for u in db.query(models.User).filter(models.User.id.in_(doctor_ids)).all():
            users_by_id[u.id] = u
    result = []
    for link in links:
        u = users_by_id.get(link.doctor_user_id)
        profile = profiles_by_uid.get(link.doctor_user_id)
        result.append({
            "link_id": link.id,
            "user_id": link.doctor_user_id,
            "name": (u.full_name or u.username) if u else "Unknown",
            "department": link.department or (profile.specialization if profile else "") or "",
            "specialization": (profile.specialization if profile else "") or "",
            "qualifications": (profile.qualifications if profile else None),
            "experience_years": (profile.experience_years if profile else None),
            "clinic_name": (profile.clinic_name if profile else None),
            "profile_picture": (u.profile_picture if u else None),
            "created_at": link.created_at.isoformat() if link.created_at else None,
        })
    return result


@app.post("/patients/mine/linked-doctors")
def link_my_doctor(
    payload: Optional[schemas.PatientDoctorLinkCreate] = None,
    doctor_user_id: Optional[int] = None,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Patient-initiated link request to a doctor.

    Accepts the doctor as JSON body ({"doctor_user_id": N}) — the format the
    patient Doctors page sends — with the legacy ?doctor_user_id= query form
    kept as a fallback for older callers.

    The link does NOT become active immediately: a pending PatientDoctorRequest
    is created and the doctor is notified. The doctor accepts or rejects from
    their My Patients page; only acceptance creates the PatientDoctorLink.
    """
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required")
    target = payload.doctor_user_id if payload else doctor_user_id
    if not target:
        raise HTTPException(status_code=422, detail="doctor_user_id is required")
    department = (payload.department if payload else None) or _doctor_specialization(db, target)
    # Validate the target is a doctor
    doctor = db.query(models.User).filter(
        models.User.id == target, models.User.role == "doctor"
    ).first()
    if not doctor:
        raise HTTPException(status_code=404, detail="Doctor not found")
    # Already actively linked?
    existing = db.query(models.PatientDoctorLink).filter(
        models.PatientDoctorLink.patient_id == current_user.patient_id,
        models.PatientDoctorLink.doctor_user_id == target,
    ).first()
    if existing:
        raise HTTPException(status_code=409, detail="Already linked")
    # Already requested but not answered yet?
    pending = db.query(models.PatientDoctorRequest).filter(
        models.PatientDoctorRequest.patient_id == current_user.patient_id,
        models.PatientDoctorRequest.doctor_user_id == target,
    ).first()
    if pending:
        raise HTTPException(status_code=409, detail="Request already sent")
    req = models.PatientDoctorRequest(
        patient_id=current_user.patient_id,
        doctor_user_id=target,
    )
    db.add(req)
    _record_care_event(
        db,
        current_user.patient_id,
        "doctor_request",
        "doctor",
        actor_user_id=current_user.id,
        doctor_user_id=target,
        note=department,
    )
    db.commit()
    db.refresh(req)
    patient_name = _patient_name(db, current_user.patient_id)
    doctor_name = doctor.full_name or doctor.username
    _enqueue_notification(
        db,
        recipient_user_id=target,
        kind="doctor_link_request",
        title=f"{patient_name} wants to link with you",
        detail=f"{patient_name} sent you a doctor-link request. Approve it from My Patients to start sharing records.",
        link="patients-list.html",
    )
    db.commit()
    return {"status": "requested", "request_id": req.id, "doctor_user_id": target}


@app.delete("/patients/mine/linked-doctors/{doctor_user_id}", status_code=204)
def unlink_my_doctor(
    doctor_user_id: int,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Unlink a doctor from the authenticated patient."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required")
    link = db.query(models.PatientDoctorLink).filter(
        models.PatientDoctorLink.patient_id == current_user.patient_id,
        models.PatientDoctorLink.doctor_user_id == doctor_user_id,
    ).first()
    if not link:
        raise HTTPException(status_code=404, detail="Link not found")
    _record_care_event(
        db,
        current_user.patient_id,
        "doctor_unlink",
        "doctor",
        actor_user_id=current_user.id,
        doctor_user_id=doctor_user_id,
    )
    db.delete(link)
    db.commit()
    return None


# ============================================================
# Patient → Doctor link requests (approval workflow)
# ============================================================
# Patient clicks Link on the Doctors page → a pending PatientDoctorRequest
# row + a notification to the doctor. The doctor accepts/rejects from their
# My Patients page; only acceptance creates the active PatientDoctorLink.

def _doctor_pending_request_rows(db: Session, doctor_user_id: int) -> list:
    """Pending PatientDoctorRequest rows aimed at this doctor, newest first."""
    return (
        db.query(models.PatientDoctorRequest)
        .filter(models.PatientDoctorRequest.doctor_user_id == doctor_user_id)
        .order_by(models.PatientDoctorRequest.created_at.desc())
        .all()
    )


@app.get("/patients/mine/doctor-requests")
def get_my_doctor_requests(
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Pending doctor-link requests sent by the authenticated patient."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required")
    rows = (
        db.query(models.PatientDoctorRequest)
        .filter(models.PatientDoctorRequest.patient_id == current_user.patient_id)
        .order_by(models.PatientDoctorRequest.created_at.desc())
        .all()
    )
    out = []
    for r in rows:
        u = db.query(models.User).filter(models.User.id == r.doctor_user_id).first()
        prof = (
            db.query(models.DoctorProfile)
            .filter(models.DoctorProfile.user_id == r.doctor_user_id)
            .first()
        )
        out.append({
            "request_id": r.id,
            "patient_id": r.patient_id,
            "doctor_user_id": r.doctor_user_id,
            "doctor_name": (u.full_name or u.username) if u else "Unknown",
            "doctor_specialization": (prof.specialization if prof else None),
            "created_at": r.created_at.isoformat() if r.created_at else None,
        })
    return out


@app.delete("/patients/mine/doctor-requests/{doctor_user_id}", status_code=204)
def cancel_my_doctor_request(
    doctor_user_id: int,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Cancel a pending doctor-link request the patient sent."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required")
    row = (
        db.query(models.PatientDoctorRequest)
        .filter(
            models.PatientDoctorRequest.patient_id == current_user.patient_id,
            models.PatientDoctorRequest.doctor_user_id == doctor_user_id,
        )
        .first()
    )
    if not row:
        raise HTTPException(status_code=404, detail="Request not found")
    _record_care_event(
        db,
        current_user.patient_id,
        "doctor_request_cancelled",
        "doctor",
        actor_user_id=current_user.id,
        doctor_user_id=doctor_user_id,
    )
    db.delete(row)
    db.commit()
    doctor_name = _user_display_name(db, doctor_user_id)
    _enqueue_notification(
        db,
        recipient_user_id=doctor_user_id,
        kind="doctor_link_cancelled",
        title=f"{_patient_name(db, current_user.patient_id)} withdrew their link request",
        detail=f"The request from {doctor_name}'s patient was cancelled by the patient.",
        link="patients-list.html",
    )
    db.commit()
    return None


@app.get("/doctors/mine/link-requests")
def get_my_link_requests(
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Pending patient link requests waiting on the authenticated doctor."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required")
    rows = _doctor_pending_request_rows(db, current_user.id)
    out = []
    for r in rows:
        out.append({
            "request_id": r.id,
            "patient_id": r.patient_id,
            "patient_name": _patient_name(db, r.patient_id),
            "created_at": r.created_at.isoformat() if r.created_at else None,
        })
    return out


@app.post("/doctors/mine/link-requests/{request_id}/accept")
def accept_link_request(
    request_id: int,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Doctor accepts a patient's link request → active PatientDoctorLink."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required")
    row = (
        db.query(models.PatientDoctorRequest)
        .filter(models.PatientDoctorRequest.id == request_id)
        .first()
    )
    if not row:
        raise HTTPException(status_code=404, detail="Request not found")
    if row.doctor_user_id != current_user.id:
        raise HTTPException(status_code=403, detail="This request is for another doctor")
    patient_id = row.patient_id
    # Idempotent link creation (returns existing row if a link somehow
    # already exists — e.g. the doctor added the patient meanwhile).
    _get_or_create_patient_link(db, patient_id, current_user.id)
    patient_name = _patient_name(db, patient_id)
    _record_care_event(
        db,
        patient_id,
        "doctor_request_accepted",
        "doctor",
        actor_user_id=current_user.id,
        doctor_user_id=current_user.id,
        note=patient_name,
    )
    db.delete(row)
    db.commit()
    doctor_name = current_user.full_name or current_user.username
    _enqueue_notification(
        db,
        recipient_user_id=_patient_user_id(db, patient_id),
        kind="doctor_link_accepted",
        title=f"Dr. {doctor_name} accepted your request",
        detail=f"You are now linked with Dr. {doctor_name}. They can see your records.",
        link="patient-doctors.html",
    )
    db.commit()
    return {"status": "accepted", "patient_id": patient_id}


@app.post("/doctors/mine/link-requests/{request_id}/reject")
def reject_link_request(
    request_id: int,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Doctor rejects a patient's link request."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required")
    row = (
        db.query(models.PatientDoctorRequest)
        .filter(models.PatientDoctorRequest.id == request_id)
        .first()
    )
    if not row:
        raise HTTPException(status_code=404, detail="Request not found")
    if row.doctor_user_id != current_user.id:
        raise HTTPException(status_code=403, detail="This request is for another doctor")
    patient_id = row.patient_id
    _record_care_event(
        db,
        patient_id,
        "doctor_request_rejected",
        "doctor",
        actor_user_id=current_user.id,
        doctor_user_id=current_user.id,
    )
    db.delete(row)
    db.commit()
    doctor_name = current_user.full_name or current_user.username
    _enqueue_notification(
        db,
        recipient_user_id=_patient_user_id(db, patient_id),
        kind="doctor_link_rejected",
        title=f"Dr. {doctor_name} declined your request",
        detail="Your doctor-link request was not accepted. You can pick another doctor from the Doctors page.",
        link="patient-doctors.html",
    )
    db.commit()
    return {"status": "rejected"}


def _patient_user_id(db: Session, patient_id: int) -> Optional[int]:
    u = (
        db.query(models.User)
        .filter(models.User.role == "patient", models.User.patient_id == patient_id)
        .first()
    )
    return u.id if u else None


# ============================================================
# Patient ↔ Hospital linking (Manage → Hospitals)
# ============================================================
# A patient can browse the hospital directory and link hospitals they
# receive care at. Links live in patient_hospital_links — one row per
# (patient, hospital). Unlinking flips status to "unlinked" (soft) so the
# relationship history stays auditable; re-linking reactivates the row.

def _patient_active_hospital_rows(db: Session, patient_id: int):
    """[(link, hospital)] for the patient's currently active links."""
    links = (
        db.query(models.PatientHospitalLink)
        .filter(
            models.PatientHospitalLink.patient_id == patient_id,
            models.PatientHospitalLink.status == "linked",
        )
        .order_by(models.PatientHospitalLink.linked_at.desc())
        .all()
    )
    if not links:
        return []
    ids = [l.hospital_id for l in links]
    hospitals = {
        h.id: h
        for h in db.query(models.Hospital)
        .filter(models.Hospital.id.in_(ids))
        .all()
    }
    return [(l, hospitals.get(l.hospital_id)) for l in links]


def _serialize_patient_hospital_link(link, hospital) -> dict:
    return {
        "link_id": link.id,
        "patient_id": link.patient_id,
        "hospital_id": link.hospital_id,
        "hospital_name": hospital.name if hospital else "Unknown",
        "address": hospital.address if hospital else None,
        "phone": hospital.phone if hospital else None,
        "status": link.status,
        "linked_at": link.linked_at.isoformat() if link.linked_at else None,
        "unlinked_at": link.unlinked_at.isoformat() if link.unlinked_at else None,
        "created_at": link.created_at.isoformat() if link.created_at else None,
    }


@app.get("/patients/mine/linked-hospitals")
def get_my_linked_hospitals(
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Return the hospitals the authenticated patient is linked to."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required")
    return [
        _serialize_patient_hospital_link(link, hospital)
        for link, hospital in _patient_active_hospital_rows(db, current_user.patient_id)
    ]


@app.post("/patients/mine/linked-hospitals", response_model=schemas.PatientHospitalLinkOut)
def link_my_hospital(
    payload: schemas.PatientHospitalLinkCreate,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Link a hospital to the authenticated patient. Re-linking after an
    unlink reactivates the same row (no duplicates)."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required")
    hospital = db.query(models.Hospital).filter(
        models.Hospital.id == payload.hospital_id
    ).first()
    if not hospital:
        raise HTTPException(status_code=404, detail="Hospital not found")
    link = (
        db.query(models.PatientHospitalLink)
        .filter(
            models.PatientHospitalLink.patient_id == current_user.patient_id,
            models.PatientHospitalLink.hospital_id == payload.hospital_id,
        )
        .first()
    )
    now = datetime.utcnow()
    if link is None:
        link = models.PatientHospitalLink(
            patient_id=current_user.patient_id,
            hospital_id=payload.hospital_id,
            status="linked",
            linked_at=now,
        )
        db.add(link)
    else:
        if link.status == "linked":
            raise HTTPException(status_code=409, detail="Already linked")
        link.status = "linked"
        link.linked_at = now
        link.unlinked_at = None
    _record_care_event(
        db,
        current_user.patient_id,
        "hospital_link",
        "hospital",
        actor_user_id=current_user.id,
        hospital_id=hospital.id,
    )
    db.commit()
    db.refresh(link)

    # Notify the hospital's admins that a patient linked to them.
    admins = (
        db.query(models.HospitalProfile.user_id)
        .filter(models.HospitalProfile.hospital_id == hospital.id)
        .all()
    )
    me = current_user.full_name or current_user.username
    for (admin_user_id,) in admins:
        _enqueue_notification(
            db,
            recipient_user_id=admin_user_id,
            kind="hospital_linked",
            title="Patient linked to your hospital",
            detail=f"{me} linked to {hospital.name}.",
            link="hospital-dashboard.html",
        )
    db.commit()
    db.refresh(link)
    return schemas.PatientHospitalLinkOut(
        link_id=link.id,
        patient_id=link.patient_id,
        hospital_id=link.hospital_id,
        hospital_name=hospital.name,
        address=hospital.address,
        phone=hospital.phone,
        status=link.status,
        linked_at=link.linked_at,
        unlinked_at=link.unlinked_at,
        created_at=link.created_at,
    )


@app.delete("/patients/mine/linked-hospitals/{hospital_id}", status_code=204)
def unlink_my_hospital(
    hospital_id: int,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Soft-unlink a hospital from the authenticated patient. The row is
    kept with status='unlinked' + unlinked_at so history is preserved."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required")
    link = (
        db.query(models.PatientHospitalLink)
        .filter(
            models.PatientHospitalLink.patient_id == current_user.patient_id,
            models.PatientHospitalLink.hospital_id == hospital_id,
            models.PatientHospitalLink.status == "linked",
        )
        .first()
    )
    if not link:
        raise HTTPException(status_code=404, detail="Link not found")
    _record_care_event(
        db,
        current_user.patient_id,
        "hospital_unlink",
        "hospital",
        actor_user_id=current_user.id,
        hospital_id=hospital_id,
    )
    link.status = "unlinked"
    link.unlinked_at = datetime.utcnow()
    db.commit()
    return None


@app.delete("/patients/{patient_id}/doctors/{link_id}", status_code=204)
def remove_doctor_link(
    patient_id: int,
    link_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Unlink a doctor from a patient. Allowed by the patient themselves
    OR by any doctor who already has a link to this patient (they can
    remove a co-caring doctor they don't want on the case anymore)."""
    _ensure_patient_or_doctor(current_user, patient_id, db)
    link = (
        db.query(models.PatientDoctorLink)
        .filter(
            models.PatientDoctorLink.id == link_id,
            models.PatientDoctorLink.patient_id == patient_id,
        )
        .first()
    )
    if not link:
        raise HTTPException(status_code=404, detail="Link not found")
    _record_care_event(
        db,
        patient_id,
        "doctor_unlink",
        "doctor",
        actor_user_id=current_user.id,
        doctor_user_id=link.doctor_user_id,
    )
    db.delete(link)
    db.commit()
    return None


# ============================================================
# Patient care-network history (Doctors + Hospitals timelines)
# ============================================================

def _serialize_care_events(db: Session, patient_id: int, kind: Optional[str] = None) -> list[dict]:
    """Care-network history for a patient. When nothing has been recorded
    yet, synthesizes the current state (active links + hospital unlinks that
    predate the audit table) so the timeline is never empty for a patient
    who already has relationships."""
    rows = (
        db.query(models.PatientCareEvent)
        .filter(models.PatientCareEvent.patient_id == patient_id)
        .order_by(models.PatientCareEvent.created_at.desc())
        .all()
    )

    synthetic = []
    if not rows:
        # Active doctor links as "linked" events.
        doc_links = (
            db.query(models.PatientDoctorLink)
            .filter(models.PatientDoctorLink.patient_id == patient_id)
            .all()
        )
        for i, l in enumerate(doc_links):
            synthetic.append({
                "id": -1 - i,
                "patient_id": patient_id,
                "kind": "doctor_link",
                "target_kind": "doctor",
                "doctor_user_id": l.doctor_user_id,
                "hospital_id": None,
                "note": l.department,
                "created_at": l.created_at,
            })
        # Hospital links (linked + unlinked rows both tell part of the story).
        hosp_links = (
            db.query(models.PatientHospitalLink)
            .filter(models.PatientHospitalLink.patient_id == patient_id)
            .all()
        )
        for i, hl in enumerate(hosp_links):
            if hl.status == "linked":
                synthetic.append({
                    "id": -100 - i,
                    "patient_id": patient_id,
                    "kind": "hospital_link",
                    "target_kind": "hospital",
                    "hospital_id": hl.hospital_id,
                    "created_at": hl.linked_at or hl.created_at,
                })
            elif hl.unlinked_at is not None:
                synthetic.append({
                    "id": -200 - i,
                    "patient_id": patient_id,
                    "kind": "hospital_unlink",
                    "target_kind": "hospital",
                    "hospital_id": hl.hospital_id,
                    "created_at": hl.unlinked_at,
                })

    # Gather display names for targets.
    events = synthetic + [
        {
            "id": e.id,
            "patient_id": e.patient_id,
            "kind": e.kind,
            "target_kind": e.target_kind,
            "doctor_user_id": e.doctor_user_id,
            "hospital_id": e.hospital_id,
            "note": e.note,
            "created_at": e.created_at,
        }
        for e in rows
    ]
    if not events:
        return []

    doctor_ids = [e["doctor_user_id"] for e in events if e.get("doctor_user_id")]
    hospital_ids = [e["hospital_id"] for e in events if e.get("hospital_id")]
    names: dict[int, str] = {}
    if doctor_ids:
        for r in db.query(models.User).filter(models.User.id.in_(set(doctor_ids))).all():
            names[("d", r.id)] = (r.full_name or r.username)
    if hospital_ids:
        for r in db.query(models.Hospital).filter(models.Hospital.id.in_(set(hospital_ids))).all():
            names[("h", r.id)] = r.name

    out = []
    for e in events:
        if kind and e["target_kind"] != kind:
            continue
        out.append({
            "id": e["id"],
            "patient_id": e["patient_id"],
            "kind": e["kind"],
            "target_kind": e["target_kind"],
            "doctor_user_id": e.get("doctor_user_id"),
            "doctor_name": names.get(("d", e.get("doctor_user_id"))) if e.get("doctor_user_id") else None,
            "hospital_id": e.get("hospital_id"),
            "hospital_name": names.get(("h", e.get("hospital_id"))) if e.get("hospital_id") else None,
            "note": e.get("note"),
            "created_at": e.get("created_at").isoformat() if e.get("created_at") else None,
        })
    return out


@app.get("/patients/mine/care-events")
def get_my_care_events(
    kind: Optional[str] = None,  # "doctor" | "hospital"
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Relationship timeline for the authenticated patient (linked/unlinked
    dates for doctors and hospitals)."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required")
    return _serialize_care_events(db, current_user.patient_id, kind)


# ---------------- Patient Profile (personal info + habits) ----------------

def _ensure_patient_access(current_user: models.User, patient_id: int, db: Session) -> models.Patient:
    """Helper: validate the patient exists and the caller is allowed to access it.

    Doctors must be linked to the patient (via PatientDoctorLink) — a doctor
    who has no link returns 404 so we don't leak existence. Patients can
    only access their own record.
    """
    patient = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    if not patient:
        raise HTTPException(status_code=404, detail="Patient not found")

    if current_user.role == "doctor":
        if not _doctor_has_patient_link(db, current_user.id, patient_id):
            raise HTTPException(status_code=404, detail="Patient not found")
        return patient

    # Non-doctor (patient / nurse) must be linked to this patient record
    if current_user.patient_id != patient_id:
        raise HTTPException(status_code=403, detail="You can only access your own patient record")
    return patient


# Alias for the same helper — used at the new guarded endpoints below so
# call sites read consistently. The behavior is identical to
# _ensure_patient_access (doctor = any patient, otherwise owner-only).
def _ensure_patient_or_doctor(current_user: models.User, patient_id: int, db: Session) -> models.Patient:
    return _ensure_patient_access(current_user, patient_id, db)


# ============================================================
# Hospital: Wards / Beds / Admissions
# ============================================================
# Wards are physical rooms/sections with a per-day billing rate. Beds
# belong to exactly one ward. An Admission pins a Patient to a Bed with
# admit/discharge timestamps; ``BedTransfer`` is an audit log of moves.
#
# Access model:
# - Any authed user can READ /wards and /admissions (the beds page is for
#   any clinical staff). Patients can see their own admissions.
# - Doctor-only writes: ward CRUD, bed CRUD, admit, discharge, transfer.
# - Notes edit is further restricted to the doctor who created the
#   admission (matches the user's "only the admitting doctor can edit
#   notes" decision).

def _doctor_only(current_user: models.User) -> None:
    """Raise 403 unless caller is a doctor. Mirrors the inline role check
    pattern used by /patients (line 1355) so a non-doctor hitting any of
    these endpoints gets the same error shape."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required.")


def _ensure_hospital_admin(db: Session, current_user: models.User) -> models.HospitalProfile:
    """Return the caller's HospitalProfile or 403. The caller must be a
    user with role='hospital' who has already created/joined a hospital.
    If they have a profile but no hospital_id, the routes that need a
    hospital will return 404 with a "create a hospital first" message."""
    if current_user.role != "hospital":
        raise HTTPException(status_code=403, detail="Hospital admin access required.")
    profile = (
        db.query(models.HospitalProfile)
        .filter(models.HospitalProfile.user_id == current_user.id)
        .first()
    )
    if profile is None or profile.hospital_id is None:
        raise HTTPException(
            status_code=404,
            detail="You haven't created or joined a hospital yet. Visit the hospital dashboard to set one up.",
        )
    return profile


def _ensure_nurse(current_user: models.User) -> models.User:
    """Raise 403 unless caller is a nurse. Returns the User for chaining."""
    if current_user.role != "nurse":
        raise HTTPException(status_code=403, detail="Nurse access required.")
    return current_user


def _admission_belongs_to_hospital(
    db: Session, current_user: models.User, admission_id: int
) -> Optional[models.Admission]:
    """If the admission's hospital_id matches the caller's hospital, return
    the admission row. Otherwise raise 403. Caller must have already passed
    _ensure_hospital_admin."""
    profile = _ensure_hospital_admin(db, current_user)
    adm = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    if adm is None:
        raise HTTPException(status_code=404, detail="Admission not found.")
    if adm.hospital_id != profile.hospital_id:
        raise HTTPException(
            status_code=403,
            detail="This admission does not belong to your hospital.",
        )
    return adm


def _nurse_for_patient(
    db: Session, current_user: models.User, patient_id: int
) -> models.NurseAssignment:
    """Return the active NurseAssignment for (patient, current_user) or 403.
    Use for nurse-only writes (e.g. filing a discharge appeal)."""
    if current_user.role != "nurse":
        raise HTTPException(status_code=403, detail="Nurse access required.")
    a = (
        db.query(models.NurseAssignment)
        .filter(
            models.NurseAssignment.patient_id == patient_id,
            models.NurseAssignment.nurse_user_id == current_user.id,
            models.NurseAssignment.is_active == True,  # noqa: E712
        )
        .first()
    )
    if a is None:
        raise HTTPException(
            status_code=403,
            detail="You are not currently assigned to this patient.",
        )
    return a


def _admission_to_out(db: Session, a: models.Admission) -> schemas.AdmissionOut:
    """Helper: SQLAlchemy Admission row → AdmissionOut, joined with patient
    / bed / ward names + computed flags. Centralized so every endpoint
    returns the same shape (no surprise field differences between
    GET /admissions/{id} and POST /admissions)."""
    patient = db.query(models.Patient).filter(models.Patient.id == a.patient_id).first()
    bed = db.query(models.Bed).filter(models.Bed.id == a.bed_id).first()
    ward = db.query(models.Ward).filter(models.Ward.id == a.ward_id_at_admit).first()
    admitted_by_user = db.query(models.User).filter(models.User.id == a.admitted_by).first()
    transfer_count = (
        db.query(models.BedTransfer)
        .filter(models.BedTransfer.admission_id == a.id)
        .count()
    )
    hospital = None
    hospital_name = None
    if getattr(a, "hospital_id", None) is not None:
        hospital = (
            db.query(models.Hospital)
            .filter(models.Hospital.id == a.hospital_id)
            .first()
        )
        if hospital:
            hospital_name = hospital.name
    nurse_name = None
    nurse_uid = None
    active_assignment = (
        db.query(models.NurseAssignment)
        .filter(
            models.NurseAssignment.patient_id == a.patient_id,
            models.NurseAssignment.is_active == True,  # noqa: E712
        )
        .first()
    )
    if active_assignment is not None:
        nurse_uid = active_assignment.nurse_user_id
        nurse_user = (
            db.query(models.User)
            .filter(models.User.id == nurse_uid)
            .first()
        )
        if nurse_user:
            nurse_name = nurse_user.full_name or nurse_user.username
    return schemas.AdmissionOut(
        id=a.id,
        patient_id=a.patient_id,
        patient_name=patient.name if patient else None,
        bed_id=a.bed_id,
        bed_number=bed.bed_number if bed else None,
        ward_id=a.ward_id_at_admit,
        ward_name=ward.name if ward else None,
        admitted_by=a.admitted_by,
        admitted_by_name=(
            (admitted_by_user.full_name or admitted_by_user.username)
            if admitted_by_user else None
        ),
        admitted_at=a.admitted_at,
        discharged_at=a.discharged_at,
        discharged_by=a.discharged_by,
        discharge_reason=a.discharge_reason,
        notes=a.notes,
        is_active=a.discharged_at is None,
        transfer_count=transfer_count,
        hospital_id=getattr(a, "hospital_id", None),
        hospital_name=hospital_name,
        assigned_nurse_user_id=nurse_uid,
        assigned_nurse_name=nurse_name,
    )


def _bed_to_out(db: Session, b: models.Bed) -> schemas.BedOut:
    """Helper: SQLAlchemy Bed row → BedOut with computed occupancy."""
    active = (
        db.query(models.Admission)
        .filter(
            models.Admission.bed_id == b.id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    return schemas.BedOut(
        id=b.id,
        ward_id=b.ward_id,
        bed_number=b.bed_number,
        bed_type=b.bed_type,
        notes=b.notes,
        created_at=b.created_at,
        is_occupied=active is not None,
        current_admission_id=active.id if active else None,
    )


def _ward_to_out(db: Session, w: models.Ward) -> schemas.WardOut:
    """Helper: SQLAlchemy Ward row → WardOut with bed_count + occupied_count."""
    beds = db.query(models.Bed).filter(models.Bed.ward_id == w.id).all()
    bed_count = len(beds)
    occupied = 0
    for b in beds:
        active = (
            db.query(models.Admission)
            .filter(
                models.Admission.bed_id == b.id,
                models.Admission.discharged_at.is_(None),
            )
            .first()
        )
        if active is not None:
            occupied += 1
    hospital_name = None
    if getattr(w, "hospital_id", None) is not None:
        h = (
            db.query(models.Hospital)
            .filter(models.Hospital.id == w.hospital_id)
            .first()
        )
        if h:
            hospital_name = h.name
    return schemas.WardOut(
        id=w.id,
        name=w.name,
        ward_type=w.ward_type,
        daily_rate=w.daily_rate,
        total_beds=w.total_beds,
        notes=w.notes,
        created_at=w.created_at,
        bed_count=bed_count,
        hospital_id=getattr(w, "hospital_id", None),
        hospital_name=hospital_name,
        occupied_count=occupied,
    )


# ---------- Wards ----------

@app.get("/wards", response_model=list[schemas.WardOut])
def list_wards(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """All wards. Public to any authed user (beds page is clinical staff)."""
    wards = db.query(models.Ward).order_by(models.Ward.id).all()
    return [_ward_to_out(db, w) for w in wards]


@app.post("/wards", response_model=schemas.WardOut)
def create_ward(
    payload: schemas.WardCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    # Doctors can create wards (legacy behavior). Hospital admins can too;
    # their new ward is auto-claimed for their hospital.
    if current_user.role not in ("doctor", "hospital"):
        raise HTTPException(status_code=403, detail="Doctor or hospital admin access required.")
    # Unique-by-name: surface a clean 400 instead of an IntegrityError.
    clash = db.query(models.Ward).filter(models.Ward.name == payload.name).first()
    if clash is not None:
        raise HTTPException(status_code=400, detail=f"A ward named '{payload.name}' already exists.")
    hospital_id = None
    if current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        hospital_id = profile.hospital_id
    ward = models.Ward(
        name=payload.name,
        ward_type=payload.ward_type or "general",
        daily_rate=payload.daily_rate if payload.daily_rate is not None else 500.0,
        total_beds=payload.total_beds if payload.total_beds is not None else 10,
        notes=payload.notes,
        hospital_id=hospital_id,
    )
    db.add(ward)
    db.commit()
    db.refresh(ward)
    return _ward_to_out(db, ward)


@app.get("/wards/{ward_id}", response_model=schemas.WardOut)
def get_ward(
    ward_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    ward = db.query(models.Ward).filter(models.Ward.id == ward_id).first()
    if not ward:
        raise HTTPException(status_code=404, detail="Ward not found")
    return _ward_to_out(db, ward)


@app.put("/wards/{ward_id}", response_model=schemas.WardOut)
def update_ward(
    ward_id: int,
    payload: schemas.WardUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    # Both doctors and hospital admins can edit wards. Hospital admins
    # may only edit wards that belong to their hospital.
    if current_user.role not in ("doctor", "hospital"):
        raise HTTPException(status_code=403, detail="Doctor or hospital admin access required.")
    ward = db.query(models.Ward).filter(models.Ward.id == ward_id).first()
    if not ward:
        raise HTTPException(status_code=404, detail="Ward not found")
    if current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        if ward.hospital_id != profile.hospital_id:
            raise HTTPException(
                status_code=403,
                detail="That ward belongs to a different hospital.",
            )
    # Apply only the fields the caller actually sent (avoid overwriting with None).
    data = payload.model_dump(exclude_unset=True)
    if "name" in data:
        clash = (
            db.query(models.Ward)
            .filter(models.Ward.name == data["name"], models.Ward.id != ward_id)
            .first()
        )
        if clash:
            raise HTTPException(status_code=400, detail=f"A ward named '{data['name']}' already exists.")
    for k, v in data.items():
        setattr(ward, k, v)
    db.commit()
    db.refresh(ward)
    return _ward_to_out(db, ward)


@app.delete("/wards/{ward_id}", status_code=204)
def delete_ward(
    ward_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    # Both doctors and hospital admins can delete wards (hospital admins
    # only their own). Bed deletion cascades via Ward.beds.
    if current_user.role not in ("doctor", "hospital"):
        raise HTTPException(status_code=403, detail="Doctor or hospital admin access required.")
    ward = db.query(models.Ward).filter(models.Ward.id == ward_id).first()
    if not ward:
        raise HTTPException(status_code=404, detail="Ward not found")
    if current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        if ward.hospital_id != profile.hospital_id:
            raise HTTPException(
                status_code=403,
                detail="That ward belongs to a different hospital.",
            )
    # Block deletion while any active admission is in this ward — losing
    # an active admission would orphan a patient.
    active = (
        db.query(models.Admission)
        .filter(
            models.Admission.ward_id_at_admit == ward_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if active is not None:
        raise HTTPException(
            status_code=409,
            detail="Cannot delete a ward with active admissions. Discharge first.",
        )
    db.delete(ward)  # cascade="all, delete-orphan" on Ward.beds drops the beds
    db.commit()
    return None


# ---------- Beds ----------

@app.get("/wards/{ward_id}/beds", response_model=list[schemas.BedOut])
def list_ward_beds(
    ward_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    if not db.query(models.Ward).filter(models.Ward.id == ward_id).first():
        raise HTTPException(status_code=404, detail="Ward not found")
    beds = (
        db.query(models.Bed)
        .filter(models.Bed.ward_id == ward_id)
        .order_by(models.Bed.bed_number)
        .all()
    )
    return [_bed_to_out(db, b) for b in beds]


@app.post("/wards/{ward_id}/beds", response_model=list[schemas.BedOut])
def add_ward_beds(
    ward_id: int,
    payload: schemas.BedBulkCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    # Both doctors and hospital admins can add beds. For hospital admins
    # the ward must belong to their hospital.
    if current_user.role not in ("doctor", "hospital"):
        raise HTTPException(status_code=403, detail="Doctor or hospital admin access required.")
    ward = db.query(models.Ward).filter(models.Ward.id == ward_id).first()
    if ward is None:
        raise HTTPException(status_code=404, detail="Ward not found")
    if current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        if ward.hospital_id != profile.hospital_id:
            raise HTTPException(
                status_code=403,
                detail="That ward belongs to a different hospital.",
            )
    if not ward:
        raise HTTPException(status_code=404, detail="Ward not found")
    if not payload.beds:
        # No-op if the caller sent an empty array — a typo-proof convenience.
        return []
    created: list[models.Bed] = []
    for spec in payload.beds:
        bed = models.Bed(
            ward_id=ward.id,
            bed_number=spec.bed_number,
            bed_type=spec.bed_type,
            notes=spec.notes,
        )
        db.add(bed)
        created.append(bed)
    try:
        db.commit()
    except Exception as exc:
        db.rollback()
        # SQLite raises IntegrityError on duplicate (ward_id, bed_number);
        # re-raise as a clean 400 instead of letting the framework return 500.
        raise HTTPException(status_code=400, detail=f"Duplicate bed number: {exc}")
    for b in created:
        db.refresh(b)
    return [_bed_to_out(db, b) for b in created]


@app.delete("/beds/{bed_id}", status_code=204)
def delete_bed(
    bed_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    # Both doctors and hospital admins can delete beds (hospital admins
    # only beds that belong to their hospital via the ward).
    if current_user.role not in ("doctor", "hospital"):
        raise HTTPException(status_code=403, detail="Doctor or hospital admin access required.")
    bed = db.query(models.Bed).filter(models.Bed.id == bed_id).first()
    if not bed:
        raise HTTPException(status_code=404, detail="Bed not found")
    if current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        ward = db.query(models.Ward).filter(models.Ward.id == bed.ward_id).first()
        if ward is None or ward.hospital_id != profile.hospital_id:
            raise HTTPException(
                status_code=403,
                detail="That bed belongs to a different hospital.",
            )
    # Block while the bed is currently occupied.
    active = (
        db.query(models.Admission)
        .filter(
            models.Admission.bed_id == bed_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if active is not None:
        raise HTTPException(
            status_code=409,
            detail="Cannot delete a bed with an active admission.",
        )
    db.delete(bed)
    db.commit()
    return None


# ---------- Admissions ----------

@app.get("/admissions", response_model=schemas.AdmissionListOut)
def list_admissions(
    status: str = "active",
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List admissions filtered by status. ``status`` accepts:
    - ``active``     (default) — discharged_at IS NULL
    - ``discharged`` — discharged_at IS NOT NULL
    - ``all``        — no filter
    Newest first by ``admitted_at``.

    Scope by role:
    - doctor  → only admissions where admitted_by == current_user.id
                (so a doctor sees "their" admitted patients, not every
                patient in the system).
    - hospital admin → only admissions at the admin's hospital.
    - nurse   → only admissions for patients currently assigned to them.
    - patient → only their own admissions.
    """
    q = db.query(models.Admission)
    if status == "active":
        q = q.filter(models.Admission.discharged_at.is_(None))
    elif status == "discharged":
        q = q.filter(models.Admission.discharged_at.is_not(None))
    elif status == "all":
        pass
    else:
        raise HTTPException(
            status_code=400,
            detail="status must be one of: active, discharged, all",
        )

    role = getattr(current_user, "role", None)
    if role == "doctor":
        q = q.filter(models.Admission.admitted_by == current_user.id)
    elif role == "hospital":
        profile = (
            db.query(models.HospitalProfile)
            .filter(models.HospitalProfile.user_id == current_user.id)
            .first()
        )
        if profile is None or profile.hospital_id is None:
            return schemas.AdmissionListOut(items=[], total_count=0)
        q = q.filter(models.Admission.hospital_id == profile.hospital_id)
    elif role == "nurse":
        assigned_patient_ids = [
            row.patient_id
            for row in db.query(models.NurseAssignment)
            .filter(
                models.NurseAssignment.nurse_user_id == current_user.id,
                models.NurseAssignment.is_active == True,  # noqa: E712
            )
            .all()
        ]
        if not assigned_patient_ids:
            return schemas.AdmissionListOut(items=[], total_count=0)
        q = q.filter(models.Admission.patient_id.in_(assigned_patient_ids))
    elif role == "patient":
        # Find this user's patient row (if any) and scope to that.
        pat = (
            db.query(models.Patient)
            .filter(models.Patient.user_id == current_user.id)
            .first()
        )
        if pat is None:
            return schemas.AdmissionListOut(items=[], total_count=0)
        q = q.filter(models.Admission.patient_id == pat.id)
    # shopkeeper / unknown roles: empty list (admissions are clinical data).
    if role not in ("doctor", "hospital", "nurse", "patient"):
        return schemas.AdmissionListOut(items=[], total_count=0)

    rows = q.order_by(models.Admission.admitted_at.desc()).all()
    return schemas.AdmissionListOut(
        items=[_admission_to_out(db, a) for a in rows],
        total_count=len(rows),
    )


@app.post("/admissions", response_model=schemas.AdmissionOut)
def create_admission(
    payload: schemas.AdmissionCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Admit a patient to a bed. Doctor-only. Rejects 404/409/400 cleanly."""
    _doctor_only(current_user)
    # The patient must exist.
    if not db.query(models.Patient).filter(models.Patient.id == payload.patient_id).first():
        raise HTTPException(status_code=404, detail="Patient not found")
    # The bed must exist.
    bed = db.query(models.Bed).filter(models.Bed.id == payload.bed_id).first()
    if not bed:
        raise HTTPException(status_code=404, detail="Bed not found")
    # The bed must not already be occupied by an active admission.
    clash = (
        db.query(models.Admission)
        .filter(
            models.Admission.bed_id == payload.bed_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if clash is not None:
        raise HTTPException(
            status_code=409,
            detail="That bed is already occupied. Pick a free bed.",
        )
    # Reject if the patient already has an active admission somewhere else —
    # keeps the model clean ("one admission per patient at a time"). The
    # existing active admission must be discharged first.
    already = (
        db.query(models.Admission)
        .filter(
            models.Admission.patient_id == payload.patient_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if already is not None:
        raise HTTPException(
            status_code=409,
            detail="Patient already has an active admission. Discharge first.",
        )

    admission = models.Admission(
        patient_id=payload.patient_id,
        bed_id=bed.id,
        admitted_by=current_user.id,
        admitted_at=datetime.utcnow(),
        ward_id_at_admit=bed.ward_id,
        notes=payload.notes,
    )
    db.add(admission)
    db.commit()
    db.refresh(admission)
    return _admission_to_out(db, admission)


@app.get("/admissions/{admission_id}", response_model=schemas.AdmissionOut)
def get_admission(
    admission_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """One admission's details. Patients can see only their own; doctors
    can see all (matches the "any doctor can manage" decision)."""
    a = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    if not a:
        raise HTTPException(status_code=404, detail="Admission not found")
    # If the caller is a patient, they can only see their own admission.
    if current_user.role != "doctor" and current_user.patient_id != a.patient_id:
        raise HTTPException(status_code=403, detail="Forbidden")
    return _admission_to_out(db, a)


# ---------- 2026-08-23: Emergency admit ----------
# A red-button shortcut accessible from both the doctor and patient
# dashboards. Skips the doctor↔hospital admission-request dance: the
# caller picks a hospital; the server auto-assigns the first free bed
# in any ward of that hospital AND the first nurse whose account is
# active and who has no current patient assignment. The flow is the
# same for doctors (who can fill in new-patient demographics) and
# patients (who are always admitting themselves).
#
# NOTE on "logged in": we don't track session presence yet, so we
# approximate "logged in" by "account is active (User.is_active) and
# not currently in a NurseAssignment". A future session-presence
# column would refine this without changing the route shape.


def _pick_free_bed_in_hospital(db: Session, hospital_id: int):
    """Return the first Bed (id, ward) in `hospital_id` whose bed has no
    active admission, in ward-id order so legacy wards fill first."""
    rows = (
        db.query(models.Bed, models.Ward)
        .join(models.Ward, models.Ward.id == models.Bed.ward_id)
        .filter(models.Ward.hospital_id == hospital_id)
        .order_by(models.Ward.id.asc(), models.Bed.id.asc())
        .all()
    )
    for bed, ward in rows:
        clash = (
            db.query(models.Admission)
            .filter(
                models.Admission.bed_id == bed.id,
                models.Admission.discharged_at.is_(None),
            )
            .first()
        )
        if clash is None:
            return bed, ward
    return None, None


def _pick_vacant_nurse(db: Session):
    """Return the first User with role='nurse' that currently has no
    active NurseAssignment. Returns None if every nurse is busy. We pick
    the user with the lowest id for determinism so the UI preview
    matches the actual server pick.

    NOTE: User has no `is_active` column yet — when we add session
    presence we'll filter on that here."""
    nurses = (
        db.query(models.User)
        .filter(models.User.role == "nurse")
        .order_by(models.User.id.asc())
        .all()
    )
    busy_ids = {
        na.nurse_user_id
        for na in db.query(models.NurseAssignment)
        .filter(models.NurseAssignment.is_active == True)  # noqa: E712
        .all()
    }
    for n in nurses:
        if n.id not in busy_ids:
            return n
    return None


def _emergency_count_free_beds(db: Session, hospital_id: int) -> tuple[int, int]:
    """Returns (free_count, total_count) for the given hospital."""
    total = (
        db.query(models.Bed)
        .join(models.Ward, models.Ward.id == models.Bed.ward_id)
        .filter(models.Ward.hospital_id == hospital_id)
        .count()
    )
    occupied_bed_ids = {
        a.bed_id
        for a in db.query(models.Admission)
        .filter(models.Admission.discharged_at.is_(None))
        .all()
    }
    all_beds = (
        db.query(models.Bed.id)
        .join(models.Ward, models.Ward.id == models.Bed.ward_id)
        .filter(models.Ward.hospital_id == hospital_id)
        .all()
    )
    free = sum(1 for (bid,) in all_beds if bid not in occupied_bed_ids)
    return free, total


def _emergency_count_available_nurses(db: Session) -> tuple[int, int]:
    nurses = (
        db.query(models.User)
        .filter(models.User.role == "nurse")
        .all()
    )
    busy_ids = {
        na.nurse_user_id
        for na in db.query(models.NurseAssignment)
        .filter(models.NurseAssignment.is_active == True)  # noqa: E712
        .all()
    }
    total = len(nurses)
    avail = sum(1 for n in nurses if n.id not in busy_ids)
    return avail, total


@app.get("/emergency/preview/{hospital_id}", response_model=schemas.EmergencyPreviewOut)
def emergency_preview(
    hospital_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """What the server WOULD auto-assign right now: shows the picked bed
    + nurse so the UI can preview "Your admission will be in ICU-A bed
    G-03 with Nurse X" before the caller confirms."""
    if current_user.role not in {"doctor", "patient"}:
        raise HTTPException(status_code=403, detail="Doctor or patient access required.")
    h = db.query(models.Hospital).filter(models.Hospital.id == hospital_id).first()
    if not h:
        raise HTTPException(status_code=404, detail="Hospital not found.")
    free, total = _emergency_count_free_beds(db, hospital_id)
    avail_n, total_n = _emergency_count_available_nurses(db)
    bed, ward = _pick_free_bed_in_hospital(db, hospital_id)
    nurse = _pick_vacant_nurse(db)
    return schemas.EmergencyPreviewOut(
        hospital_id=h.id,
        hospital_name=h.name,
        free_beds=free,
        total_beds=total,
        available_nurses=avail_n,
        total_nurses=total_n,
        picked_bed_id=bed.id if bed else None,
        picked_bed_number=bed.bed_number if bed else None,
        picked_ward_id=ward.id if ward else None,
        picked_ward_name=ward.name if ward else None,
        picked_nurse_user_id=nurse.id if nurse else None,
        picked_nurse_name=(nurse.full_name or nurse.username) if nurse else None,
    )


@app.post("/emergency/admit", response_model=schemas.EmergencyAdmitOut)
def emergency_admit(
    payload: schemas.EmergencyAdmitIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """One-shot emergency admission. Doctor or patient. Picks first free
    bed in the named hospital and first vacant nurse. Mirrors the
    same rules as /admissions (one active admission per patient, bed
    must be free) but bypasses the request/accept handshake so the
    caller can act in seconds. Demographics supplied when creating a
    brand-new patient row (doctor-initiated emergency)."""
    if current_user.role not in {"doctor", "patient"}:
        raise HTTPException(status_code=403, detail="Doctor or patient access required.")

    h = db.query(models.Hospital).filter(models.Hospital.id == payload.hospital_id).first()
    if not h:
        raise HTTPException(status_code=404, detail="Hospital not found.")

    patient_created = False
    patient_id = payload.patient_id
    if current_user.role == "patient":
        # Patients always admit themselves. Ignore any patient_id they
        # sent and pin it to their own record — otherwise they could
        # create admissions for other patients.
        if not current_user.patient_id:
            raise HTTPException(
                status_code=404,
                detail="Your account is not linked to a patient record yet.",
            )
        patient_id = current_user.patient_id
    elif not patient_id:
        # Doctor caller — no existing patient picked. Create one on the fly.
        if not payload.name or not (payload.name or "").strip():
            raise HTTPException(
                status_code=400,
                detail=(
                    "Patient name is required for a new-patient emergency "
                    "(or supply patient_id of an existing patient)."
                ),
            )
        new_p = models.Patient(
            name=payload.name.strip(),
            age=payload.age,
            gender=payload.gender,
            contact=payload.contact,
            onboarded_by_doctor_id=current_user.id,
        )
        db.add(new_p)
        db.flush()
        patient_id = new_p.id
        patient_created = True

    # Validate the patient exists (covers patient_id path too).
    p = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    if not p:
        raise HTTPException(status_code=404, detail="Patient not found.")

    # One active admission per patient.
    existing = (
        db.query(models.Admission)
        .filter(
            models.Admission.patient_id == patient_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if existing is not None:
        raise HTTPException(
            status_code=409,
            detail="Patient already has an active admission. Discharge first.",
        )

    bed, ward = _pick_free_bed_in_hospital(db, payload.hospital_id)
    if not bed:
        raise HTTPException(
            status_code=409,
            detail="No free beds in that hospital right now. Try another hospital.",
        )

    nurse = _pick_vacant_nurse(db)

    admission = models.Admission(
        patient_id=patient_id,
        bed_id=bed.id,
        admitted_by=current_user.id,
        admitted_at=datetime.utcnow(),
        ward_id_at_admit=ward.id,
        notes=(payload.reason or None),
        hospital_id=payload.hospital_id,
    )
    db.add(admission)
    db.flush()  # need admission.id before NurseAssignment (FK is patient_id, so OK to add later)

    na_out: Optional[schemas.NurseAssignmentOut] = None
    if nurse is not None:
        # Clear any prior active assignments for this patient (mirrors
        # /admissions/{id}/nurse semantics — emergency doesn't allow
        # an "additional" nurse on top of an existing one).
        from sqlalchemy import text as _sa_text
        db.execute(
            _sa_text(
                "DELETE FROM nurse_assignments "
                "WHERE patient_id = :pid AND is_active = 1"
            ),
            {"pid": patient_id},
        )
        db.flush()
        na = models.NurseAssignment(
            patient_id=patient_id,
            nurse_user_id=nurse.id,
            assigned_by_user_id=current_user.id,
            assigned_at=datetime.utcnow(),
            is_active=True,
            notes=f"Auto-assigned via Emergency admit ({payload.reason or 'no reason given'})",
        )
        db.add(na)
        db.flush()
        na_out = _na_to_out(db, na)

    # Notifications: nurse + admitting doctor + (if applicable) hospital admin.
    if nurse is not None:
        _enqueue_notification(
            db,
            recipient_user_id=nurse.id,
            kind="emergency_admit",
            title=f"EMERGENCY: {p.name}",
            detail=(
                f"You've been auto-assigned to {p.name} (Bed {bed.bed_number}, "
                f"Ward {ward.name}, {h.name})."
            ),
            link="nurse-dashboard.html",
        )
    # All hospital admins of this hospital (best-effort: any user with
    # role='hospital' whose hospital_profiles.hospital_id == this one).
    admin_ids = [
        r[0]
        for r in db.query(models.HospitalProfile.user_id)
        .filter(models.HospitalProfile.hospital_id == h.id)
        .all()
    ]
    for admin_uid in admin_ids:
        _enqueue_notification(
            db,
            recipient_user_id=admin_uid,
            kind="emergency_admit",
            title=f"Emergency admission at {h.name}",
            detail=(
                f"{p.name} admitted to Bed {bed.bed_number} ({ward.name}). "
                f"Nurse: {nurse.full_name if nurse and nurse.full_name else (nurse.username if nurse else 'unassigned')}."
            ),
            link="hospital-admit-queue.html",
        )
    # Notify the admitting user if they're a doctor (so the doctor's own
    # dashboard reflects the new admission they just filed).
    if current_user.role == "doctor":
        _enqueue_notification(
            db,
            recipient_user_id=current_user.id,
            kind="emergency_admit",
            title=f"Emergency admit filed: {p.name}",
            detail=(
                f"Bed {bed.bed_number} ({ward.name}) at {h.name}. "
                f"Nurse: {nurse.full_name if nurse and nurse.full_name else (nurse.username if nurse else 'unassigned')}."
            ),
            link="dashboard.html",
        )

    db.commit()
    db.refresh(admission)
    return schemas.EmergencyAdmitOut(
        admission=_admission_to_out(db, admission),
        nurse_assignment=na_out,
        hospital_id=h.id,
        hospital_name=h.name,
        patient_created=patient_created,
    )


@app.put("/admissions/{admission_id}/discharge", response_model=schemas.AdmissionOut)
def discharge_admission(
    admission_id: int,
    payload: schemas.AdmissionDischargeIn = schemas.AdmissionDischargeIn(),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    _doctor_only(current_user)
    a = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    if not a:
        raise HTTPException(status_code=404, detail="Admission not found")
    if a.discharged_at is not None:
        raise HTTPException(status_code=409, detail="Admission is already discharged.")
    a.discharged_at = datetime.utcnow()
    a.discharged_by = current_user.id
    a.discharge_reason = payload.reason
    db.commit()
    db.refresh(a)
    return _admission_to_out(db, a)


@app.post("/admissions/{admission_id}/transfer", response_model=schemas.AdmissionOut)
def transfer_admission(
    admission_id: int,
    payload: schemas.AdmissionTransferIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Move an admission to a different bed. Records a BedTransfer row
    for audit and updates Admission.bed_id."""
    _doctor_only(current_user)
    a = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    if not a:
        raise HTTPException(status_code=404, detail="Admission not found")
    if a.discharged_at is not None:
        raise HTTPException(status_code=409, detail="Cannot transfer a discharged admission.")
    if payload.to_bed_id == a.bed_id:
        raise HTTPException(status_code=400, detail="Transfer target is the same as the current bed.")
    new_bed = db.query(models.Bed).filter(models.Bed.id == payload.to_bed_id).first()
    if not new_bed:
        raise HTTPException(status_code=404, detail="Target bed not found")
    # Block transfer onto an occupied bed.
    clash = (
        db.query(models.Admission)
        .filter(
            models.Admission.bed_id == payload.to_bed_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if clash is not None:
        raise HTTPException(status_code=409, detail="Target bed is already occupied.")
    transfer = models.BedTransfer(
        admission_id=a.id,
        from_bed_id=a.bed_id,
        to_bed_id=new_bed.id,
        transferred_by=current_user.id,
        reason=payload.reason,
    )
    db.add(transfer)
    a.bed_id = new_bed.id
    # We deliberately do NOT update ward_id_at_admit — that anchors billing
    # to the ward the patient was first admitted to. Mid-stay transfers
    # don't change the per-day rate.
    db.commit()
    db.refresh(a)
    return _admission_to_out(db, a)


@app.put("/admissions/{admission_id}/notes", response_model=schemas.AdmissionOut)
def update_admission_notes(
    admission_id: int,
    payload: schemas.AdmissionNotesIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Update the free-text notes on an admission. Restricted to the
    doctor who created the admission (matches the "only the admitting
    doctor can edit notes" decision). Other doctors get 403, not 401."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required.")
    a = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    if not a:
        raise HTTPException(status_code=404, detail="Admission not found")
    if a.admitted_by != current_user.id:
        raise HTTPException(
            status_code=403,
            detail="Only the admitting doctor can edit these notes.",
        )
    if a.discharged_at is not None:
        raise HTTPException(status_code=409, detail="Cannot edit notes on a discharged admission.")
    a.notes = payload.notes
    db.commit()
    db.refresh(a)
    return _admission_to_out(db, a)


@app.get("/admissions/{admission_id}/charges", response_model=schemas.AdmissionChargesOut)
def admission_charges(
    admission_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Compute charges: days × ward's daily_rate at admission time.
    Days are inclusive of the admit day (so a same-day admission is 1 day).
    For an active admission we charge up to NOW."""
    a = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    if not a:
        raise HTTPException(status_code=404, detail="Admission not found")
    ward = db.query(models.Ward).filter(models.Ward.id == a.ward_id_at_admit).first()
    daily_rate = ward.daily_rate if ward else 0.0
    end = a.discharged_at or datetime.utcnow()
    # days = ceil((end - admitted_at) / 1 day), min 1
    delta = end - a.admitted_at
    days = max(1, (delta.days + (1 if delta.seconds > 0 else 0)))
    return schemas.AdmissionChargesOut(
        admission_id=a.id,
        admitted_at=a.admitted_at,
        discharged_at=a.discharged_at,
        is_active=a.discharged_at is None,
        days=days,
        daily_rate=daily_rate,
        total_charges=days * daily_rate,
    )


# ---------- Admission requests (patient → doctor accept/reject) ----------
# A patient files a request for a specific bed; a doctor reviews the queue
# and accepts (which creates the actual Admission row) or rejects (which
# records the decision and frees the patient to request again later).
#
# The status flow is documented on the AdmissionRequest model. We also
# support /cancel for patients who change their mind.

def _admreq_to_out(db: Session, r: models.AdmissionRequest) -> schemas.AdmissionRequestOut:
    """Build the Out shape with the joins the frontend renders (patient name,
    bed number, ward name, decided-by name). Single helper so list and
    detail responses stay in sync."""
    patient = db.query(models.Patient).filter(models.Patient.id == r.patient_id).first()
    bed = db.query(models.Bed).filter(models.Bed.id == r.bed_id).first()
    ward = db.query(models.Ward).filter(models.Ward.id == bed.ward_id).first() if bed else None
    decided_by = (
        db.query(models.User).filter(models.User.id == r.decided_by_user_id).first()
        if r.decided_by_user_id else None
    )
    return schemas.AdmissionRequestOut(
        id=r.id,
        patient_id=r.patient_id,
        patient_name=patient.name if patient else None,
        bed_id=r.bed_id,
        bed_number=bed.bed_number if bed else None,
        ward_id=bed.ward_id if bed else None,
        ward_name=ward.name if ward else None,
        requested_by_user_id=r.requested_by_user_id,
        requested_at=r.requested_at,
        status=r.status,
        decided_by_user_id=r.decided_by_user_id,
        decided_by_name=(decided_by.full_name or decided_by.username) if decided_by else None,
        decided_at=r.decided_at,
        decision_reason=r.decision_reason,
        request_reason=r.request_reason,
        admission_id=r.admission_id,
    )


@app.post("/admission-requests", response_model=schemas.AdmissionRequestOut, status_code=201)
def create_admission_request(
    payload: schemas.AdmissionRequestCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Patient files a request for a specific bed. The request lands in the
    doctor's pending queue — no Admission row is created yet."""
    if current_user.role != "patient":
        raise HTTPException(status_code=403, detail="Only patient accounts can file admission requests.")
    if current_user.patient_id != payload.patient_id:
        raise HTTPException(
            status_code=403,
            detail="You can only file a request for your own patient record.",
        )
    if not db.query(models.Patient).filter(models.Patient.id == payload.patient_id).first():
        raise HTTPException(status_code=404, detail="Patient not found")
    bed = db.query(models.Bed).filter(models.Bed.id == payload.bed_id).first()
    if not bed:
        raise HTTPException(status_code=404, detail="Bed not found")
    # Block if the patient already has a pending request for this same bed.
    dup = (
        db.query(models.AdmissionRequest)
        .filter(
            models.AdmissionRequest.patient_id == payload.patient_id,
            models.AdmissionRequest.bed_id == payload.bed_id,
            models.AdmissionRequest.status == "pending",
        )
        .first()
    )
    if dup is not None:
        raise HTTPException(
            status_code=409,
            detail="You already have a pending request for this bed.",
        )
    # Block if the patient already has an active admission.
    active = (
        db.query(models.Admission)
        .filter(
            models.Admission.patient_id == payload.patient_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if active is not None:
        raise HTTPException(
            status_code=409,
            detail="You already have an active admission. Discharge first.",
        )
    req = models.AdmissionRequest(
        patient_id=payload.patient_id,
        bed_id=payload.bed_id,
        requested_by_user_id=current_user.id,
        requested_at=datetime.utcnow(),
        status="pending",
        request_reason=payload.request_reason,
    )
    db.add(req)
    db.commit()
    db.refresh(req)
    return _admreq_to_out(db, req)


@app.get("/admission-requests", response_model=schemas.AdmissionRequestListOut)
def list_admission_requests(
    status: str = "pending",
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List admission requests.

    - Doctors: see all requests (default: pending only).
    - Patients: see only their own (any status).

    Status filter accepts: pending | accepted | rejected | cancelled | all.
    """
    if status not in schemas.ADMISSION_REQUEST_STATUSES and status != "all":
        raise HTTPException(
            status_code=400,
            detail=f"status must be one of: pending, accepted, rejected, cancelled, all",
        )
    q = db.query(models.AdmissionRequest)
    if current_user.role == "patient":
        q = q.filter(models.AdmissionRequest.requested_by_user_id == current_user.id)
    elif current_user.role != "doctor":
        # Hospital / nurse / shopkeeper: nothing to see.
        return schemas.AdmissionRequestListOut(items=[], total_count=0)
    if status != "all":
        q = q.filter(models.AdmissionRequest.status == status)
    rows = q.order_by(models.AdmissionRequest.requested_at.desc()).all()
    return schemas.AdmissionRequestListOut(
        items=[_admreq_to_out(db, r) for r in rows],
        total_count=len(rows),
    )


@app.post("/admission-requests/{request_id}/accept", response_model=schemas.AdmissionOut)
def accept_admission_request(
    request_id: int,
    payload: schemas.AdmissionRequestDecision,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Doctor accepts a pending request → creates the Admission row.

    We re-validate the bed is still free (the patient might have moved on
    since the request was filed) and the patient doesn't already have an
    active admission (race-condition guard)."""
    _doctor_only(current_user)
    req = (
        db.query(models.AdmissionRequest)
        .filter(models.AdmissionRequest.id == request_id)
        .first()
    )
    if not req:
        raise HTTPException(status_code=404, detail="Request not found")
    if req.status != "pending":
        raise HTTPException(
            status_code=409,
            detail=f"Request is already {req.status}; cannot accept.",
        )
    bed = db.query(models.Bed).filter(models.Bed.id == req.bed_id).first()
    if not bed:
        raise HTTPException(status_code=404, detail="Bed not found")
    clash = (
        db.query(models.Admission)
        .filter(
            models.Admission.bed_id == req.bed_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if clash is not None:
        raise HTTPException(
            status_code=409,
            detail="That bed is no longer free. Reject the request and ask the patient to pick another bed.",
        )
    already = (
        db.query(models.Admission)
        .filter(
            models.Admission.patient_id == req.patient_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if already is not None:
        raise HTTPException(
            status_code=409,
            detail="Patient already has an active admission. Reject this request.",
        )
    admission = models.Admission(
        patient_id=req.patient_id,
        bed_id=bed.id,
        admitted_by=current_user.id,
        admitted_at=datetime.utcnow(),
        ward_id_at_admit=bed.ward_id,
        notes=req.request_reason,  # carry the patient's reason as the initial note
    )
    db.add(admission)
    db.flush()  # need admission.id
    req.status = "accepted"
    req.decided_by_user_id = current_user.id
    req.decided_at = datetime.utcnow()
    req.decision_reason = payload.reason
    req.admission_id = admission.id
    db.commit()
    db.refresh(admission)
    return _admission_to_out(db, admission)


@app.post("/admission-requests/{request_id}/reject", response_model=schemas.AdmissionRequestOut)
def reject_admission_request(
    request_id: int,
    payload: schemas.AdmissionRequestDecision,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Doctor rejects a pending request. Terminal — patient must file a new
    one to try again."""
    _doctor_only(current_user)
    req = (
        db.query(models.AdmissionRequest)
        .filter(models.AdmissionRequest.id == request_id)
        .first()
    )
    if not req:
        raise HTTPException(status_code=404, detail="Request not found")
    if req.status != "pending":
        raise HTTPException(
            status_code=409,
            detail=f"Request is already {req.status}; cannot reject.",
        )
    req.status = "rejected"
    req.decided_by_user_id = current_user.id
    req.decided_at = datetime.utcnow()
    req.decision_reason = payload.reason
    db.commit()
    db.refresh(req)
    return _admreq_to_out(db, req)


@app.post("/admission-requests/{request_id}/cancel", response_model=schemas.AdmissionRequestOut)
def cancel_admission_request(
    request_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Patient cancels their own pending request. Terminal."""
    if current_user.role != "patient":
        raise HTTPException(status_code=403, detail="Only the requester can cancel a request.")
    req = (
        db.query(models.AdmissionRequest)
        .filter(models.AdmissionRequest.id == request_id)
        .first()
    )
    if not req:
        raise HTTPException(status_code=404, detail="Request not found")
    if req.requested_by_user_id != current_user.id:
        raise HTTPException(status_code=403, detail="You can only cancel your own request.")
    if req.status != "pending":
        raise HTTPException(
            status_code=409,
            detail=f"Request is already {req.status}; cannot cancel.",
        )
    req.status = "cancelled"
    req.decided_at = datetime.utcnow()
    db.commit()
    db.refresh(req)
    return _admreq_to_out(db, req)


# ---------- Admit existing patient (convenience endpoint) ----------
# Mirrors POST /admissions but routes via /patients/{id}/admit so the
# frontend can call it directly from the patient-details card without
# needing to know the doctor's own user id.

@app.post("/patients/{patient_id}/admit", response_model=schemas.AdmissionOut)
def admit_existing_patient(
    patient_id: int,
    payload: schemas.AdmissionCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    _doctor_only(current_user)
    # The patient_id in the path MUST match the body (defense in depth —
    # so a UI bug that sends the wrong id doesn't silently admit the wrong
    # patient).
    if payload.patient_id != patient_id:
        raise HTTPException(
            status_code=400,
            detail="Path patient_id and body patient_id must match.",
        )
    return create_admission(payload=payload, db=db, current_user=current_user)


@app.get("/patient/profile", response_model=schemas.PatientProfileOut)
def get_my_patient_profile(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    if current_user.role != "patient":
        raise HTTPException(status_code=403, detail="Only patient accounts can use this endpoint")

    # Auto-link: a freshly signed-up patient doesn't yet have a Patient row.
    # Create one on first read so the form opens populated-empty instead of
    # crashing with "not linked to a patient record".
    if not current_user.patient_id:
        _auto_link_patient(db, current_user)

    profile = db.query(models.PatientProfile).filter(models.PatientProfile.patient_id == current_user.patient_id).first()
    if not profile:
        # Return an empty shell so the frontend form has something to bind to.
        # Pydantic v2 needs every field — populate safe defaults for the
        # required ones and leave everything else None.
        return schemas.PatientProfileOut(
            id=0,
            patient_id=current_user.patient_id,
            updated_at=datetime.utcnow(),
        )
    return profile


def _auto_link_patient(db: Session, current_user: models.User) -> None:
    """Create a Patient row for a patient-role user and link it via users.patient_id.

    Used the first time a freshly signed-up patient opens their profile page
    or hits Save. The Patient row's `name` is required (non-nullable) so we
    fall back to full_name -> username. Other fields stay null until the
    patient fills the form and hits Save.

    If the user signed up via the doctor dropdown (User.created_by_doctor_id
    is set), we also create a PatientDoctorLink so the row shows up on that
    doctor's /patients/mine view. The legacy onboarded_by_doctor_id column is
    set as a back-compat cache; new code must read the link table.
    """
    full_name = (current_user.full_name or "").strip() or current_user.username
    new_patient = models.Patient(
        name=full_name,
        age=None,
        gender=None,
        contact=None,
    )
    db.add(new_patient)
    db.flush()  # populates new_patient.id without committing
    # Now link the new Patient row to this User via the FK column.
    current_user.patient_id = new_patient.id

    # Carry the doctor ownership from the User row into the M:N link table.
    if current_user.created_by_doctor_id is not None:
        new_patient.onboarded_by_doctor_id = current_user.created_by_doctor_id  # back-compat cache
        _get_or_create_patient_link(
            db,
            new_patient.id,
            current_user.created_by_doctor_id,
            _doctor_specialization(db, current_user.created_by_doctor_id),
        )

    db.commit()
    db.refresh(current_user)
    db.refresh(new_patient)


@app.put("/patient/profile", response_model=schemas.PatientProfileOut)
def upsert_my_patient_profile(
    payload: schemas.PatientProfileCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    if current_user.role != "patient":
        raise HTTPException(status_code=403, detail="Only patient accounts can use this endpoint")

    # Auto-link on first Save — same helper as GET so the two paths agree.
    if not current_user.patient_id:
        _auto_link_patient(db, current_user)

    profile = db.query(models.PatientProfile).filter(models.PatientProfile.patient_id == current_user.patient_id).first()
    if not profile:
        profile = models.PatientProfile(patient_id=current_user.patient_id)
        db.add(profile)

    for field, value in payload.model_dump(exclude_unset=True).items():
        setattr(profile, field, value)

    db.commit()
    db.refresh(profile)
    return profile


