@app.get("/opd/visits", response_model=list[schemas.OPDVisitOut])
def list_opd_visits(
    hospital_id: Optional[int] = None,
    patient_id: Optional[int] = None,
    doctor_id: Optional[int] = None,
    status: Optional[str] = None,
    skip: int = 0, limit: int = 100,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    q = db.query(models.OPDVisit)
    if hospital_id:
        q = q.filter(models.OPDVisit.hospital_id == hospital_id)
    if patient_id:
        q = q.filter(models.OPDVisit.patient_id == patient_id)
    if doctor_id:
        q = q.filter(models.OPDVisit.doctor_user_id == doctor_id)
    if status:
        q = q.filter(models.OPDVisit.status == status)
    visits = q.order_by(models.OPDVisit.created_at.desc()).offset(skip).limit(limit).all()
    result = []
    for v in visits:
        patient = db.query(models.Patient).filter(models.Patient.id == v.patient_id).first()
        doctor = db.query(models.User).filter(models.User.id == v.doctor_user_id).first()
        out = schemas.OPDVisitOut.model_validate(v)
        out.patient_name = patient.name if patient else None
        out.doctor_name = doctor.full_name or doctor.username if doctor else None
        result.append(out)
    return result


@app.post("/opd/visits", response_model=schemas.OPDVisitOut)
def create_opd_visit(
    visit_in: schemas.OPDVisitCreate,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    # Generate visit number
    today = datetime.utcnow().strftime("%Y%m%d")
    count = db.query(models.OPDVisit).filter(
        models.OPDVisit.hospital_id == visit_in.hospital_id,
        models.OPDVisit.created_at >= datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0),
    ).count() + 1
    visit_number = f"OPD-{today}-{count:04d}"

    visit = models.OPDVisit(
        hospital_id=visit_in.hospital_id,
        patient_id=visit_in.patient_id,
        doctor_user_id=visit_in.doctor_user_id,
        visit_number=visit_number,
        department=visit_in.department,
        chief_complaint=visit_in.chief_complaint,
        symptoms=visit_in.symptoms,
        diagnosis=visit_in.diagnosis,
        treatment_given=visit_in.treatment_given,
        prescriptions=visit_in.prescriptions,
        advice=visit_in.advice,
        follow_up_date=visit_in.follow_up_date,
        consultation_fee=visit_in.consultation_fee,
        fee_paid=visit_in.fee_paid,
        payment_method=visit_in.payment_method,
        notes=visit_in.notes,
        created_by_user_id=current_user.id,
    )
    db.add(visit)
    db.commit()
    db.refresh(visit)
    return visit


@app.put("/opd/visits/{visit_id}", response_model=schemas.OPDVisitOut)
def update_opd_visit(
    visit_id: int,
    visit_in: schemas.OPDVisitUpdate,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    visit = db.query(models.OPDVisit).filter(models.OPDVisit.id == visit_id).first()
    if not visit:
        raise HTTPException(status_code=404, detail="OPD visit not found")
    for k, v in visit_in.model_dump(exclude_unset=True).items():
        setattr(visit, k, v)
    db.commit()
    db.refresh(visit)
    return visit


