@app.put("/insurance/claims/{claim_id}", response_model=schemas.InsuranceClaimOut)
def update_insurance_claim(
    claim_id: int,
    update_in: schemas.InsuranceClaimUpdate,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    claim = db.query(models.InsuranceClaim).filter(models.InsuranceClaim.id == claim_id).first()
    if not claim:
        raise HTTPException(status_code=404, detail="Claim not found")
    for k, v in update_in.model_dump(exclude_unset=True).items():
        setattr(claim, k, v)
    if update_in.status in ("approved", "rejected", "partially_approved", "paid"):
        claim.decided_at = datetime.utcnow()
    if update_in.status == "submitted":
        claim.submitted_at = datetime.utcnow()
    db.commit()
    db.refresh(claim)
    return claim


