@app.post("/pharmacy/invoices", response_model=schemas.HospitalInvoiceOut)
def create_pharmacy_invoice(
    inv_in: schemas.HospitalInvoiceCreate,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    today = datetime.utcnow().strftime("%Y%m%d")
    count = db.query(models.HospitalInvoice).filter(
        models.HospitalInvoice.hospital_id == inv_in.hospital_id,
        models.HospitalInvoice.created_at >= datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0),
    ).count() + 1
    invoice_number = f"INV-{today}-{count:04d}"

    inv = models.HospitalInvoice(
        hospital_id=inv_in.hospital_id,
        patient_id=inv_in.patient_id,
        admission_id=inv_in.admission_id,
        opd_visit_id=inv_in.opd_visit_id,
        invoice_number=invoice_number,
        discount=inv_in.discount,
        payment_method=inv_in.payment_method,
        notes=inv_in.notes,
        issued_by=current_user.id,
    )
    db.add(inv)
    db.flush()

    subtotal = 0.0
    for item_data in inv_in.items:
        qty = item_data.get("quantity", 0)
        unit_price = item_data.get("unit_price", 0)
        line_total = qty * unit_price
        subtotal += line_total
        item = models.HospitalInvoiceItem(
            invoice_id=inv.id,
            stock_id=item_data.get("stock_id"),
            medicine_name=item_data.get("medicine_name", ""),
            quantity=qty,
            unit_price=unit_price,
            mrp=item_data.get("mrp"),
            line_total=line_total,
        )
        db.add(item)
        # Decrement stock
        if item_data.get("stock_id"):
            stock_row = db.query(models.HospitalPharmacyStock).filter(
                models.HospitalPharmacyStock.id == item_data["stock_id"]
            ).first()
            if stock_row:
                stock_row.quantity = max(0, stock_row.quantity - qty)

    inv.subtotal = subtotal
    inv.total = subtotal - inv.discount
    db.commit()
    db.refresh(inv)
    items = db.query(models.HospitalInvoiceItem).filter(models.HospitalInvoiceItem.invoice_id == inv.id).all()
    patient = db.query(models.Patient).filter(models.Patient.id == inv.patient_id).first()
    out = schemas.HospitalInvoiceOut.model_validate(inv)
    out.patient_name = patient.name if patient else None
    out.items = [schemas.HospitalInvoiceItemOut.model_validate(i) for i in items]
    return out


