@app.post("/purchase/orders", response_model=schemas.PurchaseOrderOut)
def create_purchase_order(
    po_in: schemas.PurchaseOrderCreate,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    today = datetime.utcnow().strftime("%Y%m%d")
    count = db.query(models.PurchaseOrder).filter(
        models.PurchaseOrder.hospital_id == po_in.hospital_id,
        models.PurchaseOrder.created_at >= datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0),
    ).count() + 1
    order_number = f"PO-{today}-{count:04d}"

    po = models.PurchaseOrder(
        hospital_id=po_in.hospital_id,
        order_number=order_number,
        supplier_name=po_in.supplier_name,
        supplier_contact=po_in.supplier_contact,
        discount=po_in.discount,
        tax=po_in.tax,
        payment_method=po_in.payment_method,
        expected_date=po_in.expected_date,
        notes=po_in.notes,
        created_by=current_user.id,
    )
    db.add(po)
    db.flush()

    total = 0.0
    for item_data in po_in.items:
        qty = item_data.get("quantity", 0)
        price = item_data.get("purchase_price", 0)
        line_total = qty * price
        total += line_total
        item = models.PurchaseOrderItem(
            order_id=po.id,
            medicine_name=item_data.get("medicine_name", ""),
            generic_name=item_data.get("generic_name"),
            batch_no=item_data.get("batch_no"),
            manufacturer=item_data.get("manufacturer"),
            quantity_ordered=qty,
            unit=item_data.get("unit"),
            purchase_price=price,
            mrp=item_data.get("mrp"),
            expiry_date=item_data.get("expiry_date"),
            line_total=line_total,
        )
        db.add(item)

    po.total_amount = total
    po.grand_total = total - po.discount + po.tax
    db.commit()
    db.refresh(po)
    items = db.query(models.PurchaseOrderItem).filter(models.PurchaseOrderItem.order_id == po.id).all()
    out = schemas.PurchaseOrderOut.model_validate(po)
    out.items = [schemas.PurchaseOrderItemOut.model_validate(i) for i in items]
    return out


@app.put("/purchase/orders/{po_id}", response_model=schemas.PurchaseOrderOut)
def update_purchase_order(
    po_id: int,
    update_in: schemas.PurchaseOrderUpdate,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    po = db.query(models.PurchaseOrder).filter(models.PurchaseOrder.id == po_id).first()
    if not po:
        raise HTTPException(status_code=404, detail="Purchase order not found")
    for k, v in update_in.model_dump(exclude_unset=True).items():
        setattr(po, k, v)
    db.commit()
    db.refresh(po)
    items = db.query(models.PurchaseOrderItem).filter(models.PurchaseOrderItem.order_id == po.id).all()
    out = schemas.PurchaseOrderOut.model_validate(po)
    out.items = [schemas.PurchaseOrderItemOut.model_validate(i) for i in items]
    return out


@app.post("/purchase/orders/{po_id}/receive", response_model=schemas.PurchaseOrderOut)
def receive_purchase_order(
    po_id: int,
    receive_in: schemas.PurchaseOrderReceive,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    po = db.query(models.PurchaseOrder).filter(models.PurchaseOrder.id == po_id).first()
    if not po:
        raise HTTPException(status_code=404, detail="Purchase order not found")

    all_received = True
    for ri in receive_in.items:
        item = db.query(models.PurchaseOrderItem).filter(models.PurchaseOrderItem.id == ri.item_id).first()
        if item and item.order_id == po_id:
            item.quantity_received = ri.quantity_received
            if item.quantity_received < item.quantity_ordered:
                all_received = False
            # Auto-add to pharmacy stock
            if receive_in.auto_add_to_stock:
                existing = db.query(models.HospitalPharmacyStock).filter(
                    models.HospitalPharmacyStock.hospital_id == po.hospital_id,
                    models.HospitalPharmacyStock.medicine_name == item.medicine_name,
                    models.HospitalPharmacyStock.batch_no == (item.batch_no or ""),
                ).first()
                if existing:
                    existing.quantity += ri.quantity_received
                else:
                    stock = models.HospitalPharmacyStock(
                        hospital_id=po.hospital_id,
                        medicine_name=item.medicine_name,
                        generic_name=item.generic_name,
                        batch_no=item.batch_no or "",
                        manufacturer=item.manufacturer,
                        quantity=ri.quantity_received,
                        unit=item.unit,
                        purchase_price=item.purchase_price,
                        mrp=item.mrp,
                        expiry_date=item.expiry_date,
                    )
                    db.add(stock)

    po.order_status = "received" if all_received else "partial_received"
    po.received_date = date.today()
    db.commit()
    db.refresh(po)
    items = db.query(models.PurchaseOrderItem).filter(models.PurchaseOrderItem.order_id == po.id).all()
    out = schemas.PurchaseOrderOut.model_validate(po)
    out.items = [schemas.PurchaseOrderItemOut.model_validate(i) for i in items]
    return out


# ---------------- Patient Reports (uploaded files) ----------------

ALLOWED_REPORT_CATEGORIES = {"lab", "imaging", "discharge", "prescription", "other"}


@app.get("/patients/{patient_id}/reports", response_model=list[schemas.PatientReportOut])
def list_patient_reports(
    patient_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    _ensure_patient_access(current_user, patient_id, db)
    return (
        db.query(models.PatientReport)
        .filter(models.PatientReport.patient_id == patient_id)
        .order_by(models.PatientReport.uploaded_at.desc())
        .all()
    )


@app.post("/patients/{patient_id}/reports", response_model=schemas.PatientReportOut)
async def upload_patient_report(
    patient_id: int,
    file: UploadFile = File(...),
    title: str = Form(...),
    category: str = Form("other"),
    notes: Optional[str] = Form(None),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    _ensure_patient_access(current_user, patient_id, db)

    if category not in ALLOWED_REPORT_CATEGORIES:
        raise HTTPException(status_code=400, detail=f"Invalid category. Must be one of: {sorted(ALLOWED_REPORT_CATEGORIES)}")

    # Read & size-check the file (cap at MAX_UPLOAD_BYTES so we don't OOM the server)
    content = await file.read()
    if len(content) > MAX_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail=f"File too large. Max {MAX_UPLOAD_BYTES // (1024*1024)} MB.")

    # Store with a unique prefix to avoid collisions; preserve original name for downloads
    safe_original = os.path.basename(file.filename or "report")
    stored_name = f"{uuid.uuid4().hex}_{safe_original}"
    stored_path = os.path.join(UPLOAD_DIR, stored_name)

    with open(stored_path, "wb") as f:
        f.write(content)

    report = models.PatientReport(
        patient_id=patient_id,
        title=title,
        category=category,
        file_name=safe_original,
        stored_path=stored_path,
        mime_type=file.content_type,
        file_size=len(content),
        uploaded_by_user_id=current_user.id,
        notes=notes,
    )
    db.add(report)
    db.commit()
    db.refresh(report)
    return report


@app.get("/patients/{patient_id}/reports/{report_id}/download")
def download_patient_report(
    patient_id: int,
    report_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    _ensure_patient_access(current_user, patient_id, db)

    report = (
        db.query(models.PatientReport)
        .filter(models.PatientReport.id == report_id, models.PatientReport.patient_id == patient_id)
        .first()
    )
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")
    if not os.path.exists(report.stored_path):
        raise HTTPException(status_code=410, detail="Report file is missing on disk")

    return FileResponse(
        path=report.stored_path,
        media_type=report.mime_type or "application/octet-stream",
        filename=report.file_name,
    )


@app.delete("/patients/{patient_id}/reports/{report_id}")
def delete_patient_report(
    patient_id: int,
    report_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user)
):
    _ensure_patient_access(current_user, patient_id, db)

    report = (
        db.query(models.PatientReport)
        .filter(models.PatientReport.id == report_id, models.PatientReport.patient_id == patient_id)
        .first()
    )
    if not report:
        raise HTTPException(status_code=404, detail="Report not found")

    # Remove the file from disk if it's still there, then the DB row
    if report.stored_path and os.path.exists(report.stored_path):
        try:
            os.remove(report.stored_path)
        except OSError:
            pass  # don't fail the request if the file is already gone

    db.delete(report)
    db.commit()
    return {"message": "Report deleted", "id": report_id}


# ============================================================================
# Doctor <-> Patient chat
# ============================================================================
#
# A "thread" is the (patient_id, doctor_user_id) pair. Both parties can read
# and send in the thread. Authorization is enforced by _ensure_chat_access:
#   * the patient themself (current_user.patient_id == patient_id), OR
#   * a doctor linked to this patient via PatientDoctorLink.
#
# Live-ish delivery is via 3s polling on the frontend (matches the existing
# notifications-bell pattern); we deliberately don't add WebSockets to keep
# the surface area small.

# Mime types we'll accept for chat attachments. Images and videos are
# permitted by category (any subtype); documents are gated to a fixed set of
# office formats so the doctor isn't receiving arbitrary executables.
_CHAT_DOCUMENT_MIMES = {
    "application/pdf",
    "application/msword",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "application/vnd.ms-powerpoint",
    "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    "text/plain",
    "text/csv",
}
CHAT_MAX_UPLOAD_BYTES = 25 * 1024 * 1024  # 25 MB — slightly higher than reports


def _chat_attachment_kind(mime: Optional[str]) -> str:
    """Bucket the mime type into a UI-friendly kind."""
    if not mime:
        return "other"
    m = mime.lower()
    if m.startswith("image/"):
        return "image"
    if m.startswith("video/"):
        return "video"
    if m.startswith("audio/"):
        return "audio"  # voice messages + audio attachments
    if m in _CHAT_DOCUMENT_MIMES:
        return "document"
    return "other"


def _chat_attachment_allowed(mime: Optional[str]) -> bool:
    if not mime:
        return False
    m = mime.lower()
    if m.startswith("image/") or m.startswith("video/") or m.startswith("audio/"):
        return True
    return m in _CHAT_DOCUMENT_MIMES


# ---------------------------------------------------------------------------
# Care-team helpers. "Care team" = the people the backend has actually
# linked to a patient:
#   * doctors   -> PatientDoctorLink rows (or the admitting doctor of a
#                  current admission),
#   * nurses    -> active NurseAssignment rows,
#   * hospitals -> hospital admins (HospitalProfile) of the hospital the
#                  patient is admitted to / registered at.
# Threads stay keyed on the (patient_id, provider_user_id) pair exactly as
# before — we only broaden WHICH provider users can anchor a channel and who
# may read/write it. No new message storage is introduced.
# ---------------------------------------------------------------------------
def _current_admission_for_patient(db: Session, patient_id: int) -> Optional[models.Admission]:
    return (
        db.query(models.Admission)
        .filter(
            models.Admission.patient_id == patient_id,
            models.Admission.discharged_at.is_(None),
        )
        .order_by(models.Admission.admitted_at.desc())
        .first()
    )


def _patient_care_doctors(db: Session, patient_id: int) -> set[int]:
    """Doctor user ids currently on a patient's care team."""
    ids = {
        r
        for (r,) in db.query(models.PatientDoctorLink.doctor_user_id)
        .filter(models.PatientDoctorLink.patient_id == patient_id)
        .all()
    }
    adm = _current_admission_for_patient(db, patient_id)
    if adm is not None and adm.admitted_by:
        ids.add(adm.admitted_by)
    return ids


def _patient_care_nurses(db: Session, patient_id: int) -> set[int]:
    """Nurse user ids with an ACTIVE assignment to the patient."""
    return {
        r
        for (r,) in db.query(models.NurseAssignment.nurse_user_id)
        .filter(
            models.NurseAssignment.patient_id == patient_id,
            models.NurseAssignment.is_active == True,  # noqa: E712
        )
        .all()
    }


def _hospitals_for_patient(db: Session, patient_id: int) -> set[int]:
    """Hospital ids the patient belongs to: via a current admission OR via a
    HospitalRegistrationLink (role='patient') on their user account."""
    ids: set[int] = set()
    adm = _current_admission_for_patient(db, patient_id)
    if adm is not None and adm.hospital_id:
        ids.add(adm.hospital_id)
    patient_user_id = db.query(models.User.id).filter(
        models.User.patient_id == patient_id, models.User.role == "patient"
    ).first()
    if patient_user_id is not None:
        regs = (
            db.query(models.HospitalRegistrationLink.hospital_id)
            .filter(
                models.HospitalRegistrationLink.user_id == patient_user_id[0],
                models.HospitalRegistrationLink.role == "patient",
            )
            .all()
        )
        ids.update(r for (r,) in regs)
    return ids


def _hospital_profile_for_admin(db: Session, user_id: int) -> Optional[models.HospitalProfile]:
    """The HospitalProfile row linking a hospital-role user to their hospital."""
    return (
        db.query(models.HospitalProfile)
        .filter(models.HospitalProfile.user_id == user_id)
        .first()
    )


def _hospital_admin_users(db: Session, hospital_id: int) -> set[int]:
    """Hospital-role admin user ids for a hospital (via HospitalProfile)."""
    return {
        r
        for (r,) in db.query(models.HospitalProfile.user_id)
        .filter(models.HospitalProfile.hospital_id == hospital_id)
        .all()
    }


def _hospital_name_for_user(db: Session, user_id: int) -> Optional[str]:
    """Hospital display name for a hospital-role user, or None."""
    hp = _hospital_profile_for_admin(db, user_id)
    if hp is None or hp.hospital_id is None:
        return None
    hosp = db.query(models.Hospital).filter(models.Hospital.id == hp.hospital_id).first()
    return hosp.name if hosp else None


def _patient_hospital_admins(db: Session, patient_id: int) -> set[int]:
    """Hospital-role admin user ids across every hospital the patient belongs to."""
    out: set[int] = set()
    for hid in _hospitals_for_patient(db, patient_id):
        out.update(_hospital_admin_users(db, hid))
    return out


def _provider_member_kind(db: Session, user_id: int, patient_id: int) -> Optional[str]:
    """If `user_id` is a live provider member of `patient_id`'s care team,
    return 'doctor' | 'nurse' | 'hospital'; else None."""
    user = db.query(models.User).filter(models.User.id == user_id).first()
    if not user:
        return None
    if user.role == "doctor" and user_id in _patient_care_doctors(db, patient_id):
        return "doctor"
    if user.role == "nurse" and user_id in _patient_care_nurses(db, patient_id):
        return "nurse"
    if user.role == "hospital" and user_id in _patient_hospital_admins(db, patient_id):
        return "hospital"
    return None


def _chat_can_access_pair(
    db: Session, current_user: models.User, patient_id: int, other_user_id: int
) -> bool:
    """Relationship check for the (patient, provider) channel.

    A caller may read/write a channel anchored on patient `patient_id` with
    provider user `other_user_id` only when the backend actually links them:
      * the patient themself (with a live provider member on the other side),
      * the provider user themself (live member of that patient),
      * a doctor on the patient's care team (their care channels),
      * an assigned nurse (channels with the patient's doctors/hospital),
      * a hospital admin of the patient's hospital (their care channels).
    Every branch traces to PatientDoctorLink / NurseAssignment /
    HospitalProfile / Admission rows — unrelated users never pass.
    """
    if current_user.role == "patient":
        return current_user.patient_id == patient_id and (
            _provider_member_kind(db, other_user_id, patient_id) is not None
        )
    if current_user.id == other_user_id:
        # The provider side of the pair must genuinely be on this patient's
        # care team (a patient account can never be a provider member).
        return _provider_member_kind(db, current_user.id, patient_id) is not None
    if current_user.role == "doctor":
        # A caring doctor may join the patient's channels with their assigned
        # nurse / hospital admin for coordination — but NOT the private
        # patient<->another-doctor channel (that pair is only patient + that
        # doctor themselves, handled by the id==other_user_id branch above).
        kind = _provider_member_kind(db, other_user_id, patient_id)
        return (
            current_user.id in _patient_care_doctors(db, patient_id)
            and kind in ("nurse", "hospital")
        )
    if current_user.role == "nurse":
        # An assigned nurse talks with the patient's doctors / hospital — not
        # through another nurse's private channel.
        if current_user.id not in _patient_care_nurses(db, patient_id):
            return False
        return _provider_member_kind(db, other_user_id, patient_id) in ("doctor", "hospital")
    if current_user.role == "hospital":
        return current_user.id in _patient_hospital_admins(db, patient_id) and (
            _provider_member_kind(db, other_user_id, patient_id) is not None
        )
    return False


def _ensure_chat_access(
    current_user: models.User, patient_id: int, doctor_user_id: int, db: Session
) -> None:
    """Caller must have a live care-team relationship with the thread.

    Raises 404 (not 403) when the caller has no relationship with the thread
    so we don't leak whether the (patient, provider) pair exists.
    """
    # Verify the patient exists.
    patient = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    if not patient:
        raise HTTPException(status_code=404, detail="Chat thread not found")
    if not _chat_can_access_pair(db, current_user, patient_id, doctor_user_id):
        raise HTTPException(status_code=404, detail="Chat thread not found")


def _chat_thread_pair(db: Session, current_user: models.User):
    """Returns a list of (patient_id, provider_user_id) thread tuples the
    caller is allowed to see. Every pair traces to a live care-team
    relationship, so unrelated users never appear:

      * patients  -> one channel per linked doctor, per ACTIVE assigned
                     nurse, and per hospital admin of their hospital,
      * doctors   -> one channel per linked patient (with themselves) plus
                     that patient's assigned nurses / hospital admins,
      * nurses    -> one channel per active assignment with themselves (the
                     patient), with the patient's doctors, and with the
                     patient's hospital admins,
      * hospitals -> the patients of their hospital (admitted or registered)
                     with themselves, with the admitting doctor, and with
                     assigned nurses.
    """
    def _dedup(pairs):
        seen = set()
        out = []
        for p in pairs:
            if p not in seen:
                seen.add(p)
                out.append(p)
        return out

    if current_user.role == "patient" and current_user.patient_id:
        pid = current_user.patient_id
        pairs = [(pid, d) for d in sorted(_patient_care_doctors(db, pid))]
        pairs += [(pid, n) for n in sorted(_patient_care_nurses(db, pid))]
        pairs += [(pid, h) for h in sorted(_patient_hospital_admins(db, pid))]
        return _dedup(pairs)

    if current_user.role == "doctor":
        patient_ids = [
            pid
            for (pid,) in db.query(models.PatientDoctorLink.patient_id)
            .filter(models.PatientDoctorLink.doctor_user_id == current_user.id)
            .all()
        ]
        pairs = []
        for pid in patient_ids:
            pairs.append((pid, current_user.id))
            pairs += [(pid, n) for n in sorted(_patient_care_nurses(db, pid))]
            pairs += [(pid, h) for h in sorted(_patient_hospital_admins(db, pid))]
        return _dedup(pairs)

    if current_user.role == "nurse":
        rows = (
            db.query(models.NurseAssignment)
            .filter(
                models.NurseAssignment.nurse_user_id == current_user.id,
                models.NurseAssignment.is_active == True,  # noqa: E712
            )
            .all()
        )
        pairs = []
        for na in rows:
            pid = na.patient_id
            pairs.append((pid, current_user.id))
            # Admitting doctor (kept from the original behaviour) + any
            # linked doctor + hospital admins for this patient.
            adm = _current_admission_for_patient(db, pid)
            admitting = adm.admitted_by if (adm is not None and adm.admitted_by) else None
            if admitting:
                pairs.append((pid, admitting))
            for d in sorted(_patient_care_doctors(db, pid)):
                if d != admitting:
                    pairs.append((pid, d))
            pairs += [(pid, h) for h in sorted(_patient_hospital_admins(db, pid))]
        return _dedup(pairs)

    if current_user.role == "hospital":
        hp = _hospital_profile_for_admin(db, current_user.id)
        if hp is None or hp.hospital_id is None:
            return []
        hid = hp.hospital_id
        # Patients: currently admitted to this hospital + patients registered
        # under this hospital's registration links.
        patient_ids = {
            r
            for (r,) in db.query(models.Admission.patient_id)
            .filter(
                models.Admission.hospital_id == hid,
                models.Admission.discharged_at.is_(None),
            )
            .all()
        }
        reg_patient_user_ids = [
            r
            for (r,) in db.query(models.HospitalRegistrationLink.user_id)
            .filter(
                models.HospitalRegistrationLink.hospital_id == hid,
                models.HospitalRegistrationLink.role == "patient",
            )
            .all()
        ]
        if reg_patient_user_ids:
            for (r,) in db.query(models.User.patient_id).filter(
                models.User.id.in_(reg_patient_user_ids),
                models.User.patient_id.isnot(None),
            ).all():
                if r:
                    patient_ids.add(r)
        pairs = []
        for pid in sorted(patient_ids):
            pairs.append((pid, current_user.id))
            # Every caring doctor (linked or admitting) + assigned nurses so
            # the hospital sees the full care team for their patients.
            pairs += [(pid, d) for d in sorted(_patient_care_doctors(db, pid))]
            pairs += [(pid, n) for n in sorted(_patient_care_nurses(db, pid))]
        return _dedup(pairs)
    return []


def _chat_user_name(user: Optional[models.User]) -> str:
    if not user:
        return "Unknown"
    return user.full_name or user.username or "Unknown"


def _chat_patient_user_id(db: Session, patient_id: int) -> Optional[int]:
    """The user account id of the patient row (threads are anchored on the
    patient_id of the patients table; the patient account holds a patient_id)."""
    row = (
        db.query(models.User.id)
        .filter(models.User.patient_id == patient_id, models.User.role == "patient")
        .first()
    )
    return row[0] if row else None


def _chat_parse_hidden_ids(msg: models.ChatMessage) -> set[int]:
    if not msg.hidden_from_user_ids:
        return set()
    try:
        return {int(x) for x in json.loads(msg.hidden_from_user_ids)}
    except Exception:
        return set()


def _chat_is_hidden_from(msg: models.ChatMessage, viewer_user_id: int) -> bool:
    return viewer_user_id in _chat_parse_hidden_ids(msg)


def _get_or_create_chat_pref(
    db: Session, user_id: int, patient_id: int, doctor_user_id: int
) -> models.ChatConversationPref:
    """Return the per-(user, thread) pref row, creating it on the fly."""
    pref = (
        db.query(models.ChatConversationPref)
        .filter(
            models.ChatConversationPref.user_id == user_id,
            models.ChatConversationPref.patient_id == patient_id,
            models.ChatConversationPref.doctor_user_id == doctor_user_id,
        )
        .first()
    )
    if pref is None:
        pref = models.ChatConversationPref(
            user_id=user_id,
            patient_id=patient_id,
            doctor_user_id=doctor_user_id,
        )
        db.add(pref)
        db.flush()
    return pref


def _chat_privacy_row(
    db: Session, user_id: int, create: bool = False
) -> Optional[models.ChatPrivacy]:
    """Fetch a user's ChatPrivacy row. When ``create`` is True a missing row
    is created (used by the settings PUT); plain reads never create rows so
    the default all-enabled behaviour is cheap and side-effect free."""
    row = (
        db.query(models.ChatPrivacy)
        .filter(models.ChatPrivacy.user_id == user_id)
        .first()
    )
    if row is None and create:
        row = models.ChatPrivacy(user_id=user_id)
        db.add(row)
        db.flush()
    return row


def _chat_privacy_for(db: Session, user_id: int) -> dict:
    """Effective privacy settings for a user (defaults: everything visible)."""
    row = _chat_privacy_row(db, user_id)
    if row is None:
        return {
            "show_last_seen": True,
            "show_read_receipts": True,
            "show_typing": True,
        }
    return {
        "show_last_seen": bool(row.show_last_seen),
        "show_read_receipts": bool(row.show_read_receipts),
        "show_typing": bool(row.show_typing),
    }


def _chat_reactions_for(msg_id: int, db: Session) -> list[schemas.ChatReactionOut]:
    rows = (
        db.query(models.ChatMessageReaction, models.User)
        .join(models.User, models.User.id == models.ChatMessageReaction.user_id)
        .filter(models.ChatMessageReaction.message_id == msg_id)
        .order_by(models.ChatMessageReaction.created_at.asc())
        .all()
    )
    return [
        schemas.ChatReactionOut(
            reaction=r.reaction,
            user_id=r.user_id,
            user_name=_chat_user_name(u),
            created_at=r.created_at,
        )
        for r, u in rows
    ]


def _chat_reply_preview(msg: models.ChatMessage, db: Session) -> Optional[schemas.ChatReplyPreview]:
    if not msg.reply_to_id:
        return None
    orig = db.query(models.ChatMessage).filter(models.ChatMessage.id == msg.reply_to_id).first()
    if not orig:
        return None
    sender = db.query(models.User).filter(models.User.id == orig.sender_user_id).first()
    att_count = (
        db.query(sa_func.count(models.ChatAttachment.id))
        .filter(models.ChatAttachment.message_id == orig.id)
        .scalar()
        or 0
    )
    kind = "deleted"
    if orig.deleted_at is not None:
        kind = "deleted"
    elif att_count:
        first_att = (
            db.query(models.ChatAttachment)
            .filter(models.ChatAttachment.message_id == orig.id)
            .order_by(models.ChatAttachment.id.asc())
            .first()
        )
        kind = first_att.kind if first_att else "document"
    elif orig.body:
        kind = "text"
    return schemas.ChatReplyPreview(
        id=orig.id,
        sender_user_id=orig.sender_user_id,
        sender_name=_chat_user_name(sender) if sender else "Unknown",
        body=orig.body,
        has_attachments=bool(att_count),
        kind=kind,
    )


def _serialize_chat_message(
    msg: models.ChatMessage,
    db: Session,
    viewer: Optional[models.User] = None,
) -> schemas.ChatMessageOut:
    """Build a ChatMessageOut from a DB row, joining sender info, attachments,
    reactions, reply preview and per-viewer state (hidden / saved / read)."""
    sender = db.query(models.User).filter(models.User.id == msg.sender_user_id).first()
    sender_role = sender.role if sender else "unknown"
    sender_name = _chat_user_name(sender)
    attachments = (
        db.query(models.ChatAttachment)
        .filter(models.ChatAttachment.message_id == msg.id)
        .order_by(models.ChatAttachment.id.asc())
        .all()
    )

    saved_by_me = False
    hidden_from_me = False
    read_by_other = None
    if viewer is not None:
        hidden_from_me = _chat_is_hidden_from(msg, viewer.id)
        saved_by_me = (
            db.query(models.ChatSavedMessage.id)
            .filter(
                models.ChatSavedMessage.user_id == viewer.id,
                models.ChatSavedMessage.message_id == msg.id,
            )
            .first()
            is not None
        )
        if viewer.id == msg.sender_user_id and msg.deleted_at is None:
            # Read state from the sender's perspective: the OTHER side's
            # cursor (per the pair's two read columns) passing this message.
            patient_user_id = _chat_patient_user_id(db, msg.patient_id)
            if patient_user_id is not None:
                if viewer.id == patient_user_id:
                    other_user_id = msg.doctor_user_id
                    other_cursor = msg.doctor_last_read_at
                else:
                    other_user_id = patient_user_id
                    other_cursor = msg.patient_last_read_at
                # Privacy: when the reader turned read receipts off, never
                # broadcast the double-tick to the sender.
                other_priv = _chat_privacy_for(db, other_user_id)
                read_by_other = None
                if other_priv["show_read_receipts"]:
                    read_by_other = bool(
                        other_cursor is not None
                        and msg.created_at
                        and other_cursor >= msg.created_at
                    )

    body = msg.body
    if msg.deleted_at is not None:
        # Delete-for-everyone: content hidden from the normal UI but the row
        # (and attachments metadata) stay for audit/retention.
        body = None
        attachments_out: list[schemas.ChatAttachmentOut] = []
    else:
        attachments_out = [
            schemas.ChatAttachmentOut(
                id=a.id,
                file_name=a.file_name,
                mime_type=a.mime_type,
                file_size=a.file_size,
                kind=a.kind,
                download_url=f"/chat/attachments/{a.id}/download",
            )
            for a in attachments
        ]

    return schemas.ChatMessageOut(
        id=msg.id,
        patient_id=msg.patient_id,
        doctor_user_id=msg.doctor_user_id,
        sender_user_id=msg.sender_user_id,
        sender_role=sender_role,
        sender_name=sender_name,
        body=body,
        attachments=attachments_out,
        created_at=msg.created_at,
        edited_at=msg.edited_at,
        deleted_at=msg.deleted_at,
        deleted_by_user_id=msg.deleted_by_user_id,
        hidden_from_me=hidden_from_me,
        reply_to=_chat_reply_preview(msg, db),
        reactions=_chat_reactions_for(msg.id, db),
        saved_by_me=saved_by_me,
        read_by_other=read_by_other,
    )


def _build_chat_thread(
    db: Session,
    current_user: models.User,
    patient_id: int,
    doctor_user_id: int,
) -> schemas.ChatThreadOut:
    """Construct the ChatThreadOut for a single (patient, provider) pair.

    ``doctor_user_id`` holds the provider-side participant (legacy name — it
    may be a doctor, an assigned nurse, or a hospital admin). The thread is
    labelled for the CALLER (``thread_title`` / ``thread_subtitle``) so the
    same channel reads naturally from each care-team member's perspective.
    """
    patient = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    provider = db.query(models.User).filter(models.User.id == doctor_user_id).first()
    # Resolve the patient's User account (needed for WebRTC calls)
    patient_user = None
    if patient:
        patient_user = db.query(models.User).filter(
            models.User.patient_id == patient.id,
            models.User.role == "patient",
        ).first()

    # --- Partner identity + display label ------------------------------
    partner_role = None
    partner_display = None
    hospital_name = None
    department = None
    if provider:
        partner_role = provider.role
        if provider.role == "hospital":
            hospital_name = _hospital_name_for_user(db, provider.id)
            partner_display = hospital_name or _chat_user_name(provider)
        else:
            partner_display = _chat_user_name(provider)
        if provider.role == "doctor":
            link = (
                db.query(models.PatientDoctorLink)
                .filter(
                    models.PatientDoctorLink.patient_id == patient_id,
                    models.PatientDoctorLink.doctor_user_id == doctor_user_id,
                )
                .first()
            )
            department = None
            if link and link.department:
                department = link.department
            elif provider.role == "doctor":
                # Fall back to the doctor's specialization for readability.
                profile = (
                    db.query(models.DoctorProfile)
                    .filter(models.DoctorProfile.user_id == provider.id)
                    .first()
                )
                department = profile.specialization if (profile and profile.specialization) else None

    patient_label = patient.name if patient else "Unknown patient"
    # Title/subtitle for THIS caller's thread list.
    thread_title = partner_display or patient_label
    thread_subtitle = None
    if current_user.role == "patient":
        # Patient always sees the provider side as the contact.
        if partner_role == "doctor":
            thread_subtitle = department or "Doctor"
        elif partner_role == "nurse":
            thread_subtitle = "Assigned Nurse"
        elif partner_role == "hospital":
            thread_subtitle = "Your hospital"
        else:
            thread_subtitle = "Care team"
    elif current_user.role == "doctor":
        if current_user.id == doctor_user_id:
            # Their own channel with the patient → show the patient.
            thread_title = patient_label
            thread_subtitle = "Patient"
        elif partner_role == "nurse":
            thread_subtitle = f"Assigned Nurse · {patient_label}"
        elif partner_role == "hospital":
            thread_subtitle = f"Hospital · {patient_label}"
    elif current_user.role == "nurse":
        if current_user.id == doctor_user_id:
            thread_title = patient_label
            thread_subtitle = "Assigned patient"
        elif partner_role == "doctor":
            thread_subtitle = f"Doctor · {patient_label}"
        elif partner_role == "hospital":
            thread_subtitle = f"Hospital · {patient_label}"
    elif current_user.role == "hospital":
        thread_title = patient_label
        if partner_role == "doctor":
            dname = (partner_display or "").strip()
            thread_subtitle = f"Dr. {dname}" if dname and not dname.lower().startswith("dr") else (dname or "Doctor")
        elif partner_role == "nurse":
            thread_subtitle = f"Nurse · {(partner_display or '').strip()}"
        else:
            thread_subtitle = partner_display or "Hospital"

    # Latest message that is still visible to THIS caller (delete-for-me
    # hides only from the user who removed it; delete-for-everyone messages
    # are skipped so the preview falls back to an older message).
    last_msg_row = None
    for row in (
        db.query(models.ChatMessage)
        .filter(
            models.ChatMessage.patient_id == patient_id,
            models.ChatMessage.doctor_user_id == doctor_user_id,
            models.ChatMessage.deleted_at.is_(None),
        )
        .order_by(models.ChatMessage.created_at.desc(), models.ChatMessage.id.desc())
        .all()
    ):
        if not _chat_is_hidden_from(row, current_user.id):
            last_msg_row = row
            break
    last_message = (
        _serialize_chat_message(last_msg_row, db, current_user) if last_msg_row else None
    )

    # Read state. The (patient_id, provider) pair has two read columns:
    # patient_last_read_at is shared by every non-provider participant
    # (patient + third-party care members), doctor_last_read_at belongs to
    # the provider side of the pair (legacy name — a nurse/hospital admin
    # anchoring their own channel with a patient writes here too).
    if last_msg_row is not None:
        if current_user.role == "patient" and current_user.patient_id == patient_id:
            last_read_at = last_msg_row.patient_last_read_at
        elif current_user.id == doctor_user_id:
            last_read_at = last_msg_row.doctor_last_read_at
        else:
            last_read_at = last_msg_row.patient_last_read_at
    else:
        # No visible message — fall back to any row's cursors (the read
        # columns are thread-wide by convention: mark-read updates every row).
        any_row = (
            db.query(models.ChatMessage)
            .filter(
                models.ChatMessage.patient_id == patient_id,
                models.ChatMessage.doctor_user_id == doctor_user_id,
            )
            .order_by(models.ChatMessage.id.desc())
            .first()
        )
        last_read_at = None
        if any_row is not None:
            if current_user.role == "patient" and current_user.patient_id == patient_id:
                last_read_at = any_row.patient_last_read_at
            elif current_user.id == doctor_user_id:
                last_read_at = any_row.doctor_last_read_at
            else:
                last_read_at = any_row.patient_last_read_at

    q = (
        db.query(models.ChatMessage)
        .filter(
            models.ChatMessage.patient_id == patient_id,
            models.ChatMessage.doctor_user_id == doctor_user_id,
            models.ChatMessage.sender_user_id != current_user.id,
            models.ChatMessage.deleted_at.is_(None),
        )
    )
    if last_read_at is not None:
        q = q.filter(models.ChatMessage.created_at > last_read_at)
    # Exclude messages this caller hid (delete-for-me) from the unread count.
    rows_for_unread = q.all()
    unread_count = sum(1 for r in rows_for_unread if not _chat_is_hidden_from(r, current_user.id))

    # Per-caller conversation prefs + lightweight partner presence.
    my_pref = _get_or_create_chat_pref(db, current_user.id, patient_id, doctor_user_id)
    db.commit()  # persist newly-created pref rows lazily
    now = datetime.utcnow()
    muted = my_pref.muted_until is not None and my_pref.muted_until > now

    partner_online = False
    partner_last_seen = None
    partner_typing = False
    partner_user_ids: list[int] = []
    if current_user.role == "patient" and current_user.patient_id == patient_id and provider:
        partner_user_ids.append(provider.id)
    elif current_user.id == doctor_user_id:
        puid = patient_user.id if patient_user else None
        if puid:
            partner_user_ids.append(puid)
    else:
        # Third-party care member: partner is the anchor provider or the patient.
        if patient_user:
            partner_user_ids.append(patient_user.id)
        if provider and provider.id != current_user.id:
            partner_user_ids.append(provider.id)
    if partner_user_ids:
        partner_pref = (
            db.query(models.ChatConversationPref)
            .filter(
                models.ChatConversationPref.user_id.in_(partner_user_ids),
                models.ChatConversationPref.patient_id == patient_id,
                models.ChatConversationPref.doctor_user_id == doctor_user_id,
            )
            .order_by(models.ChatConversationPref.updated_at.desc())
            .first()
        )
        if partner_pref is not None:
            # Privacy: hide presence / typing based on the partner's own
            # per-user settings (the pref row's user is the one whose state
            # we would otherwise be broadcasting).
            partner_priv = _chat_privacy_for(db, partner_pref.user_id)
            if partner_priv["show_last_seen"]:
                partner_online = (
                    partner_pref.online_until is not None
                    and partner_pref.online_until > now
                )
                partner_last_seen = partner_pref.last_seen_at or partner_pref.online_until
            else:
                partner_online = False
                partner_last_seen = None
            if partner_priv["show_typing"]:
                partner_typing = (
                    partner_pref.typing_until is not None
                    and partner_pref.typing_until > now
                )
            else:
                partner_typing = False


    return schemas.ChatThreadOut(
        patient_id=patient_id,
        patient_name=patient_label,
        patient_user_id=patient_user.id if patient_user else None,
        doctor_user_id=doctor_user_id,
        doctor_name=_chat_user_name(provider) if provider else "Unknown",
        partner_role=partner_role,
        thread_title=thread_title,
        thread_subtitle=thread_subtitle,
        department=department,
        last_message=last_message,
        unread_count=unread_count,
        pinned=bool(my_pref.pinned),
        archived=bool(my_pref.archived),
        muted=muted,
        muted_until=my_pref.muted_until,
        partner_online=partner_online,
        partner_last_seen=partner_last_seen,
        partner_typing=partner_typing,
    )


@app.get("/chat/threads", response_model=list[schemas.ChatThreadOut])
def list_chat_threads(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List every chat thread the caller is a participant in. Doctors see
    one entry per linked patient; patients see one entry per linked doctor.
    Each entry includes the most recent message and the caller's unread
    count for that thread."""
    pairs = _chat_thread_pair(db, current_user)
    return [_build_chat_thread(db, current_user, pid, did) for (pid, did) in pairs]


@app.get(
    "/chat/threads/{patient_id}/{doctor_user_id}/messages",
    response_model=schemas.ChatMessagesOut,
)
def list_chat_messages(
    patient_id: int,
    doctor_user_id: int,
    limit: int = 50,
    before_id: Optional[int] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List messages in a thread, oldest first (chat convention). Pass
    ``?limit=N&before_id=<id>`` to scroll backwards through history."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    if limit < 1 or limit > 200:
        limit = 50

    q = (
        db.query(models.ChatMessage)
        .filter(
            models.ChatMessage.patient_id == patient_id,
            models.ChatMessage.doctor_user_id == doctor_user_id,
            # Delete-for-everyone rows are hidden from the normal UI (the
            # row is retained purely for audit/retention).
            models.ChatMessage.deleted_at.is_(None),
        )
    )
    if before_id is not None:
        q = q.filter(models.ChatMessage.id < before_id)
    # Fetch a little extra so delete-for-me filtering can't starve a page.
    fetch = limit + 8
    rows = q.order_by(models.ChatMessage.id.asc()).limit(fetch).all()
    rows = [r for r in rows if not _chat_is_hidden_from(r, current_user.id)]
    has_more = len(rows) > limit
    rows = rows[:limit]
    return schemas.ChatMessagesOut(
        messages=[_serialize_chat_message(m, db, current_user) for m in rows]
    )


@app.post(
    "/chat/threads/{patient_id}/{doctor_user_id}/messages",
    response_model=schemas.ChatMessageOut,
)
async def send_chat_message(
    patient_id: int,
    doctor_user_id: int,
    request: Request,
    body: Optional[str] = Form(None),
    reply_to_id: Optional[int] = Form(None),
    client_message_id: Optional[str] = Form(None),
    files: list[UploadFile] = File(default=[]),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Send a new message in a thread.

    Two modes, decided by the Content-Type:
      * application/json -> body ``{"body": "...", "reply_to_id": N,
        "client_message_id": "..."}`` (text-only message).
      * multipart/form-data -> optional ``body`` / ``reply_to_id`` form
        fields + one or more ``files`` for attachments. Empty body is
        allowed when at least one attachment is supplied.
    """
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)

    # Detect body mode from Content-Type so the same endpoint serves both.
    content_type = (request.headers.get("content-type") or "").lower()
    is_multipart = "multipart/form-data" in content_type

    attachments_meta: list[schemas.ChatAttachmentOut] = []
    text_body: Optional[str] = None
    client_message_id: Optional[str] = None

    if is_multipart:
        text_body = (body or "").strip() or None
        if client_message_id:
            client_message_id = client_message_id.strip() or None
        if not files:
            raise HTTPException(
                status_code=400,
                detail="Send either a body (JSON mode) or at least one file (multipart mode).",
            )
    else:
        # JSON mode — read the raw body.
        try:
            raw = await request.json()
        except json.JSONDecodeError:
            raise HTTPException(status_code=400, detail="Invalid JSON body.")
        if isinstance(raw, dict):
            text_body = (raw.get("body") or "").strip() or None
            reply_to_id = raw.get("reply_to_id")
            client_message_id = (raw.get("client_message_id") or "").strip() or None
        files = []

    # Idempotency: a retried send with the same client_message_id returns the
    # original message instead of creating a duplicate.
    if client_message_id:
        existing = (
            db.query(models.ChatMessage)
            .filter(
                models.ChatMessage.sender_user_id == current_user.id,
                models.ChatMessage.client_message_id == client_message_id,
                models.ChatMessage.patient_id == patient_id,
                models.ChatMessage.doctor_user_id == doctor_user_id,
            )
            .first()
        )
        if existing is not None:
            return _serialize_chat_message(existing, db, current_user)

    if not text_body and not files:
        raise HTTPException(
            status_code=400, detail="Message must include text or at least one attachment."
        )

    # Validate the reply target when supplied: must live in this thread and
    # be a normal (non-deleted) message.
    if reply_to_id is not None:
        target = (
            db.query(models.ChatMessage)
            .filter(models.ChatMessage.id == reply_to_id)
            .first()
        )
        if (
            target is None
            or target.patient_id != patient_id
            or target.doctor_user_id != doctor_user_id
            or target.deleted_at is not None
        ):
            raise HTTPException(status_code=400, detail="Invalid reply target.")

    # Persist the message first so we can hang attachments off its id.
    msg = models.ChatMessage(
        patient_id=patient_id,
        doctor_user_id=doctor_user_id,
        sender_user_id=current_user.id,
        body=text_body,
        reply_to_id=reply_to_id,
        client_message_id=client_message_id,
    )
    db.add(msg)
    db.flush()  # populate msg.id

    # Validate + store each uploaded file.
    chat_dir = os.path.join(UPLOAD_DIR, "chat")
    os.makedirs(chat_dir, exist_ok=True)
    for file in files or []:
        mime = file.content_type or ""
        if not _chat_attachment_allowed(mime):
            db.rollback()
            raise HTTPException(
                status_code=415,
                detail=f"Unsupported file type '{mime}'. Allowed: images, videos, "
                       f"PDF, DOC/DOCX, PPT/PPTX, TXT, CSV.",
            )
        content = await file.read()
        if len(content) > CHAT_MAX_UPLOAD_BYTES:
            db.rollback()
            raise HTTPException(
                status_code=413,
                detail=f"File '{file.filename}' is too large. "
                       f"Max {CHAT_MAX_UPLOAD_BYTES // (1024 * 1024)} MB per file.",
            )
        safe_original = os.path.basename(file.filename or "attachment")
        stored_name = f"{uuid.uuid4().hex}_{safe_original}"
        stored_path = os.path.join(chat_dir, stored_name)
        with open(stored_path, "wb") as fh:
            fh.write(content)
        att = models.ChatAttachment(
            message_id=msg.id,
            file_name=safe_original,
            stored_path=stored_path,
            mime_type=mime,
            file_size=len(content),
            kind=_chat_attachment_kind(mime),
        )
        db.add(att)

    db.commit()
    db.refresh(msg)

    # Refresh the sender's presence row (chat activity + last seen).
    try:
        sender_pref = _get_or_create_chat_pref(db, current_user.id, patient_id, doctor_user_id)
        now = datetime.utcnow()
        sender_pref.online_until = now + timedelta(seconds=75)
        sender_pref.last_seen_at = now
        db.commit()
    except Exception:
        db.rollback()

    # Notify the OTHER side of the thread. Honors their notif_chat_message
    # opt-out flag and their mute setting, and skips when the recipient has
    # already read past this message so we don't double-fire when a user has
    # the tab open.
    if current_user.id == doctor_user_id:
        recipient = (
            db.query(models.User)
            .filter(models.User.patient_id == patient_id)
            .first()
        )
        recipient_label = f"Patient #{patient_id}"
    else:
        recipient = (
            db.query(models.User)
            .filter(models.User.id == doctor_user_id)
            .first()
        )
        recipient_label = recipient.full_name if (recipient and recipient.full_name) else f"Doctor #{doctor_user_id}"

    muted = False
    if recipient is not None and recipient.id != current_user.id:
        rpref = _get_or_create_chat_pref(db, recipient.id, patient_id, doctor_user_id)
        muted = rpref.muted_until is not None and rpref.muted_until > datetime.utcnow()

    last_read = _chat_last_read_at(db, patient_id, doctor_user_id, current_user)
    if (
        recipient
        and recipient.id != current_user.id
        and not muted
        and (last_read is None or last_read < msg.created_at)
    ):
        sender_name = current_user.full_name or current_user.username
        preview = (text_body or "").strip().splitlines()[0][:80] if text_body else "📎 Attachment"
        title = f"New message from {sender_name}"
        _enqueue_notification(
            db,
            recipient_user_id=recipient.id,
            kind="chat_message",
            title=title,
            detail=f"{recipient_label}: {preview}",
            link=f"dashboard.html?chat={patient_id},{doctor_user_id}",
        )
        db.commit()

    # Re-fetch with attachments populated so the response includes the
    # download URLs.
    return _serialize_chat_message(msg, db, current_user)


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/read")
def mark_chat_thread_read(
    patient_id: int,
    doctor_user_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Mark every message in this thread as read for the calling side.
    Returns the new read timestamp."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    now = datetime.utcnow()

    if current_user.role == "patient" and current_user.patient_id == patient_id:
        # Patient side of the pair.
        db.query(models.ChatMessage).filter(
            models.ChatMessage.patient_id == patient_id,
            models.ChatMessage.doctor_user_id == doctor_user_id,
        ).update({models.ChatMessage.patient_last_read_at: now}, synchronize_session=False)
    elif current_user.id == doctor_user_id:
        # Provider side of the pair (doctor, or a nurse/hospital admin
        # anchoring their own channel with the patient).
        db.query(models.ChatMessage).filter(
            models.ChatMessage.patient_id == patient_id,
            models.ChatMessage.doctor_user_id == doctor_user_id,
        ).update({models.ChatMessage.doctor_last_read_at: now}, synchronize_session=False)
    else:
        # Any other participant (assigned nurse, hospital admin, caring
        # doctor) shares the patient_last_read_at column as their read state
        # — the same sharing the nurse flow always used.
        db.query(models.ChatMessage).filter(
            models.ChatMessage.patient_id == patient_id,
            models.ChatMessage.doctor_user_id == doctor_user_id,
        ).update({models.ChatMessage.patient_last_read_at: now}, synchronize_session=False)

    db.commit()

    # Reading a thread = activity: refresh presence + last seen.
    try:
        pref = _get_or_create_chat_pref(db, current_user.id, patient_id, doctor_user_id)
        pref.online_until = now + timedelta(seconds=75)
        pref.last_seen_at = now
        db.commit()
    except Exception:
        db.rollback()
    return {"read_at": now.isoformat()}


@app.get("/chat/attachments/{attachment_id}/download")
def download_chat_attachment(
    attachment_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Stream a chat attachment. Caller must be a participant in the
    attachment's thread."""
    att = (
        db.query(models.ChatAttachment)
        .filter(models.ChatAttachment.id == attachment_id)
        .first()
    )
    if not att:
        raise HTTPException(status_code=404, detail="Attachment not found")
    msg = (
        db.query(models.ChatMessage)
        .filter(models.ChatMessage.id == att.message_id)
        .first()
    )
    if not msg:
        raise HTTPException(status_code=404, detail="Attachment not found")
    _ensure_chat_access(current_user, msg.patient_id, msg.doctor_user_id, db)

    if not os.path.exists(att.stored_path):
        raise HTTPException(status_code=410, detail="Attachment file is missing on disk")

    return FileResponse(
        path=att.stored_path,
        media_type=att.mime_type or "application/octet-stream",
        filename=att.file_name,
    )



# ---- Chat Settings: block/unblock, clear history, lock, theme ----

def _get_or_create_chat_settings(db: Session, patient_id: int, doctor_user_id: int) -> models.ChatSettings:
    """Return the ChatSettings row for a (patient, doctor) thread, creating it
    on the fly if it doesn't exist yet."""
    settings = (
        db.query(models.ChatSettings)
        .filter(
            models.ChatSettings.patient_id == patient_id,
            models.ChatSettings.doctor_user_id == doctor_user_id,
        )
        .first()
    )
    if settings is None:
        settings = models.ChatSettings(
            patient_id=patient_id,
            doctor_user_id=doctor_user_id,
        )
        db.add(settings)
        db.flush()
    return settings


@app.get("/chat/threads/{patient_id}/{doctor_user_id}/settings")
def get_chat_settings(
    patient_id: int,
    doctor_user_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Get chat settings for a thread."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    s = _get_or_create_chat_settings(db, patient_id, doctor_user_id)
    db.commit()
    return {
        "is_blocked": bool(s.is_blocked),
        "blocked_by_user_id": s.blocked_by_user_id,
        "is_locked": bool(s.pin_hash),
        "locked_by_user_id": s.locked_by_user_id,
        "theme": s.theme or 'default',
    }


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/block")
def block_chat_thread(
    patient_id: int,
    doctor_user_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Block a chat thread. Only participants can block."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    s = _get_or_create_chat_settings(db, patient_id, doctor_user_id)
    s.is_blocked = 1
    s.blocked_by_user_id = current_user.id
    db.commit()
    return {"is_blocked": True}


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/unblock")
def unblock_chat_thread(
    patient_id: int,
    doctor_user_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Unblock a chat thread."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    s = _get_or_create_chat_settings(db, patient_id, doctor_user_id)
    s.is_blocked = 0
    s.blocked_by_user_id = None
    db.commit()
    return {"is_blocked": False}


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/clear")
def clear_chat_history(
    patient_id: int,
    doctor_user_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Delete all messages and attachments in a thread."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    # Delete attachments first (FK constraint)
    msg_ids = [mid for (mid,) in db.query(models.ChatMessage.id).filter(
        models.ChatMessage.patient_id == patient_id,
        models.ChatMessage.doctor_user_id == doctor_user_id,
    ).all()]
    if msg_ids:
        db.query(models.ChatAttachment).filter(
            models.ChatAttachment.message_id.in_(msg_ids)
        ).delete(synchronize_session=False)
    db.query(models.ChatMessage).filter(
        models.ChatMessage.patient_id == patient_id,
        models.ChatMessage.doctor_user_id == doctor_user_id,
    ).delete(synchronize_session=False)
    db.commit()
    return {"cleared": True, "deleted_messages": len(msg_ids)}


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/lock")
def lock_chat_thread(
    patient_id: int,
    doctor_user_id: int,
    body: schemas.ChatLockRequest,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Set a 4-digit PIN to lock the chat thread."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    import re as _re
    if not body.pin or not _re.match(r'^\d{4}$', body.pin):
        raise HTTPException(status_code=400, detail="PIN must be exactly 4 digits")
    s = _get_or_create_chat_settings(db, patient_id, doctor_user_id)
    s.pin_hash = auth.hash_password(body.pin)
    s.locked_by_user_id = current_user.id
    db.commit()
    return {"is_locked": True}


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/unlock")
def unlock_chat_thread(
    patient_id: int,
    doctor_user_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Remove the lock from a chat thread."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    s = _get_or_create_chat_settings(db, patient_id, doctor_user_id)
    s.pin_hash = None
    s.locked_by_user_id = None
    db.commit()
    return {"is_locked": False}


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/verify-pin")
def verify_chat_pin(
    patient_id: int,
    doctor_user_id: int,
    body: schemas.ChatLockRequest,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Verify the 4-digit PIN to unlock the chat view."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    s = _get_or_create_chat_settings(db, patient_id, doctor_user_id)
    if not s.pin_hash:
        return {"valid": True}  # no lock set
    if not body.pin:
        raise HTTPException(status_code=400, detail="PIN required")
    valid = auth.verify_password(body.pin, s.pin_hash)
    return {"valid": valid}


@app.put("/chat/threads/{patient_id}/{doctor_user_id}/theme")
def set_chat_theme(
    patient_id: int,
    doctor_user_id: int,
    body: schemas.ChatThemeRequest,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Set the chat theme for a thread."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    valid_themes = ['default', 'dark', 'ocean', 'sunset', 'forest', 'lavender']
    if body.theme not in valid_themes:
        raise HTTPException(status_code=400, detail=f'Invalid theme. Choose from: {valid_themes}')
    s = _get_or_create_chat_settings(db, patient_id, doctor_user_id)
    s.theme = body.theme
    db.commit()
    return {"theme": s.theme}


# ============================================================================
# Chat interactions: reactions, replies, edit/delete, star/save, pin/archive/
# mute, typing & presence, conversation search (2026-09).
# ============================================================================
# These build on the existing pair-thread chat and are additive — the message
# list/thread endpoints keep working for older clients.


def _chat_message_for_interaction(
    db: Session, current_user: models.User, message_id: int
) -> models.ChatMessage:
    """Fetch a message and enforce the caller is a participant of its thread."""
    msg = db.query(models.ChatMessage).filter(models.ChatMessage.id == message_id).first()
    if msg is None or msg.deleted_at is not None:
        raise HTTPException(status_code=404, detail="Message not found")
    _ensure_chat_access(current_user, msg.patient_id, msg.doctor_user_id, db)
    return msg


@app.post("/chat/messages/{message_id}/react", response_model=schemas.ChatMessageOut)
def react_to_chat_message(
    message_id: int,
    body: schemas.ChatReactIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Add or change the caller's reaction on a message (upsert per user)."""
    msg = _chat_message_for_interaction(db, current_user, message_id)
    emoji = (body.reaction or "").strip()
    if not emoji or len(emoji) > 16:
        raise HTTPException(status_code=400, detail="Invalid reaction.")
    reaction = (
        db.query(models.ChatMessageReaction)
        .filter(
            models.ChatMessageReaction.message_id == message_id,
            models.ChatMessageReaction.user_id == current_user.id,
        )
        .first()
    )
    if reaction is None:
        reaction = models.ChatMessageReaction(
            message_id=message_id,
            user_id=current_user.id,
            reaction=emoji,
        )
        db.add(reaction)
    else:
        reaction.reaction = emoji
    db.commit()
    return _serialize_chat_message(msg, db, current_user)


@app.delete("/chat/messages/{message_id}/react", response_model=schemas.ChatMessageOut)
def remove_chat_reaction(
    message_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Remove the caller's reaction from a message (no-op if none exists)."""
    msg = _chat_message_for_interaction(db, current_user, message_id)
    db.query(models.ChatMessageReaction).filter(
        models.ChatMessageReaction.message_id == message_id,
        models.ChatMessageReaction.user_id == current_user.id,
    ).delete(synchronize_session=False)
    db.commit()
    return _serialize_chat_message(msg, db, current_user)


@app.patch("/chat/messages/{message_id}", response_model=schemas.ChatMessageOut)
def edit_chat_message(
    message_id: int,
    body: schemas.ChatEditIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Edit the caller's own recently sent message. Marks edited_at so the UI
    can show an "edited" chip; the original content is not destroyed (audit)."""
    msg = _chat_message_for_interaction(db, current_user, message_id)
    if msg.sender_user_id != current_user.id:
        raise HTTPException(status_code=403, detail="You can only edit your own messages.")
    new_text = (body.body or "").strip()
    if not new_text:
        raise HTTPException(status_code=400, detail="Message cannot be empty.")
    # Editing is limited to a window (like mainstream messengers) and only
    # allowed while the message is not deleted-for-everyone.
    if msg.deleted_at is not None:
        raise HTTPException(status_code=400, detail="This message was deleted.")
    if msg.created_at and (datetime.utcnow() - msg.created_at).total_seconds() > 24 * 3600:
        raise HTTPException(status_code=400, detail="Messages older than 24 hours cannot be edited.")
    msg.body = new_text  # attachments, if any, stay untouched
    msg.edited_at = datetime.utcnow()
    db.commit()
    return _serialize_chat_message(msg, db, current_user)


@app.delete("/chat/messages/{message_id}", response_model=schemas.ChatMessageOut)
def delete_chat_message(
    message_id: int,
    for_everyone: bool = False,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Delete a message. ``?for_everyone=true`` (sender only) soft-deletes the
    row for every participant (audit retained). The default hides it just for
    the caller (delete-for-me)."""
    msg = db.query(models.ChatMessage).filter(models.ChatMessage.id == message_id).first()
    if msg is None or msg.deleted_at is not None:
        raise HTTPException(status_code=404, detail="Message not found")
    _ensure_chat_access(current_user, msg.patient_id, msg.doctor_user_id, db)

    if for_everyone:
        if msg.sender_user_id != current_user.id:
            raise HTTPException(
                status_code=403,
                detail="Only the sender can delete a message for everyone.",
            )
        if msg.created_at and (datetime.utcnow() - msg.created_at).total_seconds() > 24 * 3600:
            raise HTTPException(
                status_code=400,
                detail="Messages older than 24 hours can only be deleted for yourself.",
            )
        msg.deleted_at = datetime.utcnow()
        msg.deleted_by_user_id = current_user.id
        db.commit()
        return _serialize_chat_message(msg, db, current_user)

    # Delete for me: keep the row, record the user in the hidden list.
    hidden = _chat_parse_hidden_ids(msg)
    hidden.add(current_user.id)
    msg.hidden_from_user_ids = json.dumps(sorted(hidden))
    db.commit()
    return _serialize_chat_message(msg, db, current_user)


@app.post("/chat/messages/{message_id}/save", response_model=schemas.ChatMessageOut)
def save_chat_message(
    message_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Star/save a message to the caller's Saved view (idempotent)."""
    msg = _chat_message_for_interaction(db, current_user, message_id)
    existing = (
        db.query(models.ChatSavedMessage.id)
        .filter(
            models.ChatSavedMessage.user_id == current_user.id,
            models.ChatSavedMessage.message_id == message_id,
        )
        .first()
    )
    if existing is None:
        db.add(models.ChatSavedMessage(user_id=current_user.id, message_id=message_id))
        db.commit()
    return _serialize_chat_message(msg, db, current_user)


@app.delete("/chat/messages/{message_id}/save", response_model=schemas.ChatMessageOut)
def unsave_chat_message(
    message_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Remove a message from the caller's Saved view (idempotent)."""
    msg = _chat_message_for_interaction(db, current_user, message_id)
    db.query(models.ChatSavedMessage).filter(
        models.ChatSavedMessage.user_id == current_user.id,
        models.ChatSavedMessage.message_id == message_id,
    ).delete(synchronize_session=False)
    db.commit()
    return _serialize_chat_message(msg, db, current_user)


@app.post("/chat/messages/{message_id}/forward", response_model=schemas.ChatMessageOut)
def forward_chat_message(
    message_id: int,
    body: schemas.ChatForwardIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Forward a message into another conversation the caller belongs to.

    The original row is untouched — a brand-new message is created in the
    target thread with the original text (plus an optional note) and copies
    of the attachments (new attachment rows referencing the same stored file,
    so attachment authorization stays per-thread).
    """
    src = _chat_message_for_interaction(db, current_user, message_id)

    target_patient_id = body.patient_id
    target_doctor_user_id = body.doctor_user_id
    # The caller must be a member of the target conversation too.
    _ensure_chat_access(current_user, target_patient_id, target_doctor_user_id, db)
    if (
        target_patient_id == src.patient_id
        and target_doctor_user_id == src.doctor_user_id
    ):
        raise HTTPException(
            status_code=400,
            detail="This message already lives in that conversation.",
        )

    # Idempotency: same key -> return the already-forwarded message.
    client_message_id = (body.client_message_id or "").strip() or None
    if client_message_id:
        existing = (
            db.query(models.ChatMessage)
            .filter(
                models.ChatMessage.sender_user_id == current_user.id,
                models.ChatMessage.client_message_id == client_message_id,
                models.ChatMessage.patient_id == target_patient_id,
                models.ChatMessage.doctor_user_id == target_doctor_user_id,
            )
            .first()
        )
        if existing is not None:
            return _serialize_chat_message(existing, db, current_user)

    note = (body.body or "").strip() or None
    if note and src.body:
        text_body = src.body + "\n\n" + note
    elif note:
        text_body = note
    else:
        text_body = src.body

    msg = models.ChatMessage(
        patient_id=target_patient_id,
        doctor_user_id=target_doctor_user_id,
        sender_user_id=current_user.id,
        body=text_body,
        client_message_id=client_message_id,
    )
    db.add(msg)
    db.flush()

    # Clone attachments (reuse the stored file; each thread keeps its own
    # attachment rows so download authorization is scoped to the new thread).
    for att in (
        db.query(models.ChatAttachment)
        .filter(models.ChatAttachment.message_id == src.id)
        .order_by(models.ChatAttachment.id.asc())
        .all()
    ):
        db.add(
            models.ChatAttachment(
                message_id=msg.id,
                file_name=att.file_name,
                stored_path=att.stored_path,
                mime_type=att.mime_type,
                file_size=att.file_size,
                kind=att.kind,
            )
        )
    db.commit()
    db.refresh(msg)

    # Presence refresh for the caller.
    try:
        pref = _get_or_create_chat_pref(db, current_user.id, target_patient_id, target_doctor_user_id)
        now = datetime.utcnow()
        pref.online_until = now + timedelta(seconds=75)
        pref.last_seen_at = now
        db.commit()
    except Exception:
        db.rollback()

    # Notify the other side of the target thread (same rules as a normal
    # send: skip blocked/unrelated, mute, already-read).
    if current_user.id == target_doctor_user_id:
        recipient = (
            db.query(models.User)
            .filter(models.User.patient_id == target_patient_id)
            .first()
        )
        recipient_label = f"Patient #{target_patient_id}"
    else:
        recipient = (
            db.query(models.User)
            .filter(models.User.id == target_doctor_user_id)
            .first()
        )
        recipient_label = (
            recipient.full_name
            if (recipient and recipient.full_name)
            else f"Doctor #{target_doctor_user_id}"
        )

    muted = False
    if recipient is not None and recipient.id != current_user.id:
        rpref = _get_or_create_chat_pref(db, recipient.id, target_patient_id, target_doctor_user_id)
        muted = rpref.muted_until is not None and rpref.muted_until > datetime.utcnow()
    last_read = _chat_last_read_at(db, target_patient_id, target_doctor_user_id, current_user)
    if (
        recipient
        and recipient.id != current_user.id
        and not muted
        and (last_read is None or last_read < msg.created_at)
    ):
        sender_name = current_user.full_name or current_user.username
        preview = (
            (text_body or "").strip().splitlines()[0][:80]
            if text_body
            else "\U0001F4CE Attachment"
        )
        _enqueue_notification(
            db,
            recipient_user_id=recipient.id,
            kind="chat_message",
            title=f"New forwarded message from {sender_name}",
            detail=f"{recipient_label}: {preview}",
            link=f"dashboard.html?chat={target_patient_id},{target_doctor_user_id}",
        )
        db.commit()

    return _serialize_chat_message(msg, db, current_user)


@app.get("/chat/saved")
def list_saved_chat_messages(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Messages the caller starred, newest first, with their thread context."""
    rows = (
        db.query(models.ChatSavedMessage, models.ChatMessage)
        .join(models.ChatMessage, models.ChatMessage.id == models.ChatSavedMessage.message_id)
        .filter(models.ChatSavedMessage.user_id == current_user.id)
        .order_by(models.ChatSavedMessage.created_at.desc())
        .limit(100)
        .all()
    )
    items = []
    for saved, msg in rows:
        if msg.deleted_at is not None or _chat_is_hidden_from(msg, current_user.id):
            continue
        thread = _build_chat_thread(db, current_user, msg.patient_id, msg.doctor_user_id)
        items.append(
            {
                "thread": thread,
                "message": _serialize_chat_message(msg, db, current_user),
                "saved_at": saved.created_at,
            }
        )
    return {"items": items}


# ---- Conversation prefs: pin / archive / mute ----


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/pin")
def pin_chat_thread(
    patient_id: int,
    doctor_user_id: int,
    body: schemas.ChatPinIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Pin or unpin a conversation for the caller."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    pref = _get_or_create_chat_pref(db, current_user.id, patient_id, doctor_user_id)
    pref.pinned = 1 if body.pinned else 0
    db.commit()
    return {"pinned": bool(pref.pinned)}


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/archive")
def archive_chat_thread(
    patient_id: int,
    doctor_user_id: int,
    body: schemas.ChatArchiveIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Archive or un-archive a conversation for the caller."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    pref = _get_or_create_chat_pref(db, current_user.id, patient_id, doctor_user_id)
    pref.archived = 1 if body.archived else 0
    db.commit()
    return {"archived": bool(pref.archived)}


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/mute")
def mute_chat_thread(
    patient_id: int,
    doctor_user_id: int,
    body: schemas.ChatMuteIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Mute a conversation for the caller. ``minutes`` null => mute until
    explicitly unmuted (send minutes=0 to unmute)."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    pref = _get_or_create_chat_pref(db, current_user.id, patient_id, doctor_user_id)
    if body.minutes and body.minutes > 0:
        pref.muted_until = datetime.utcnow() + timedelta(minutes=body.minutes)
    else:
        pref.muted_until = None
    db.commit()
    return {"muted": pref.muted_until is not None, "muted_until": pref.muted_until}


# ---- Typing + presence ----


@app.post("/chat/threads/{patient_id}/{doctor_user_id}/typing")
def set_chat_typing(
    patient_id: int,
    doctor_user_id: int,
    body: schemas.ChatTypingIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Ping the thread with typing state. Typing pings expire automatically
    (typing_until ~7s) so a dropped connection never leaves a stuck state."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    now = datetime.utcnow()
    pref = _get_or_create_chat_pref(db, current_user.id, patient_id, doctor_user_id)
    pref.online_until = now + timedelta(seconds=75)
    pref.last_seen_at = now
    pref.typing_until = now + timedelta(seconds=7) if body.typing else None
    db.commit()
    return {"typing": body.typing, "until": pref.typing_until}


@app.post("/chat/presence/ping")
def ping_chat_presence(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Global presence heartbeat while the chat app is open. Marks the user
    online in every conversation they are a participant of (best-effort),
    mirroring the per-thread typing/online semantics the UI polls."""
    now = datetime.utcnow()
    pairs = _chat_thread_pair(db, current_user)
    for pid, did in pairs:
        try:
            pref = _get_or_create_chat_pref(db, current_user.id, pid, did)
            pref.online_until = now + timedelta(seconds=75)
            pref.last_seen_at = now
        except Exception:
            db.rollback()
    db.commit()
    return {"ok": True, "at": now.isoformat()}


# ---- Per-user privacy settings (2026-09) ----
# These gate what OTHER users see about the caller: presence/last seen,
# typing, and read receipts. They are honoured by _build_chat_thread and
# _serialize_chat_message above, so every consumer (full chat page and the
# dashboard drawer) inherits the same behaviour automatically.


@app.get("/chat/privacy", response_model=schemas.ChatPrivacyOut)
def get_chat_privacy(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Return the caller's chat privacy settings."""
    return schemas.ChatPrivacyOut(**_chat_privacy_for(db, current_user.id))


@app.put("/chat/privacy", response_model=schemas.ChatPrivacyOut)
def update_chat_privacy(
    body: schemas.ChatPrivacyUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Update the caller's chat privacy settings (partial updates allowed)."""
    row = _chat_privacy_row(db, current_user.id, create=True)
    if body.show_last_seen is not None:
        row.show_last_seen = 1 if body.show_last_seen else 0
    if body.show_read_receipts is not None:
        row.show_read_receipts = 1 if body.show_read_receipts else 0
    if body.show_typing is not None:
        row.show_typing = 1 if body.show_typing else 0
    db.commit()
    db.refresh(row)
    return schemas.ChatPrivacyOut(
        show_last_seen=bool(row.show_last_seen),
        show_read_receipts=bool(row.show_read_receipts),
        show_typing=bool(row.show_typing),
    )


# ---- Conversation search ----


def _chat_snippet(body_text: Optional[str], q: str) -> Optional[str]:
    """A short context window around the first match of q in text."""
    if not body_text:
        return None
    low = body_text.lower()
    idx = low.find(q.lower())
    if idx < 0:
        return body_text[:120]
    start = max(0, idx - 40)
    end = min(len(body_text), idx + len(q) + 60)
    prefix = "…" if start > 0 else ""
    suffix = "…" if end < len(body_text) else ""
    return prefix + body_text[start:end] + suffix


@app.get("/chat/threads/{patient_id}/{doctor_user_id}/search")
def search_chat_thread_messages(
    patient_id: int,
    doctor_user_id: int,
    q: str = "",
    limit: int = 30,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Search within one conversation (message text or attachment filename)."""
    _ensure_chat_access(current_user, patient_id, doctor_user_id, db)
    query = (q or "").strip()
    if not query or len(query) < 2:
        raise HTTPException(status_code=400, detail="Search query must be at least 2 characters.")
    limit = min(max(limit, 1), 100)

    base = (
        db.query(models.ChatMessage)
        .filter(
            models.ChatMessage.patient_id == patient_id,
            models.ChatMessage.doctor_user_id == doctor_user_id,
            models.ChatMessage.deleted_at.is_(None),
        )
    )
    like = f"%{query}%"
    matches = (
        base.filter(
            sa_or_(
                models.ChatMessage.body.ilike(like),
                models.ChatMessage.id.in_(
                    db.query(models.ChatAttachment.message_id)
                    .filter(models.ChatAttachment.file_name.ilike(like))
                ),
            )
        )
        .order_by(models.ChatMessage.created_at.desc())
        .limit(limit)
        .all()
    )
    visible = [m for m in matches if not _chat_is_hidden_from(m, current_user.id)]
    thread = _build_chat_thread(db, current_user, patient_id, doctor_user_id)
    return schemas.ChatSearchResults(
        query=query,
        thread=thread,
        matches=[
            schemas.ChatThreadSearchResult(
                message=_serialize_chat_message(m, db, current_user),
                snippet=_chat_snippet(m.body, query),
            )
            for m in visible
        ],
        total=len(visible),
    )


@app.get("/chat/search")
def global_chat_search(
    q: str = "",
    limit: int = 20,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Search every conversation the caller participates in. Returns matching
    messages grouped per thread (thread metadata + the matches)."""
    query = (q or "").strip()
    if not query or len(query) < 2:
        raise HTTPException(status_code=400, detail="Search query must be at least 2 characters.")
    limit = min(max(limit, 1), 50)
    like = f"%{query}%"

    pairs = _chat_thread_pair(db, current_user)
    results = []
    total = 0
    for pid, did in pairs:
        rows = (
            db.query(models.ChatMessage)
            .filter(
                models.ChatMessage.patient_id == pid,
                models.ChatMessage.doctor_user_id == did,
                models.ChatMessage.deleted_at.is_(None),
                models.ChatMessage.body.ilike(like),
            )
            .order_by(models.ChatMessage.created_at.desc())
            .limit(limit)
            .all()
        )
        visible = [m for m in rows if not _chat_is_hidden_from(m, current_user.id)]
        if not visible:
            continue
        thread = _build_chat_thread(db, current_user, pid, did)
        results.append(
            {
                "thread": thread,
                "matches": [
                    schemas.ChatThreadSearchResult(
                        message=_serialize_chat_message(m, db, current_user),
                        snippet=_chat_snippet(m.body, query),
                    )
                    for m in visible[:limit]
                ],
            }
        )
        total += len(visible)
        if total >= limit * 3:
            break
    return {"query": query, "items": results, "total": total}


