def _nav_for_role(role: str) -> list[dict]:
    """Return the sidebar nav list for the given role. Always includes the
    base Account entries (profile + settings) appended last."""
    if role == "admin":
        primary = _ADMIN_NAV
    elif role == "shopkeeper":
        primary = _SHOPKEEPER_NAV
    elif role == "patient":
        primary = _PATIENT_NAV
    elif role == "doctor":
        primary = _DOCTOR_NAV
    elif role == "nurse":
        primary = _NURSE_NAV
    elif role == "hospital":
        primary = _HOSPITAL_NAV
    else:
        primary = _DOCTOR_NAV  # unknown role gets the full menu, never the trimmed one
    return primary + _BASE_NAV


def _ensure_shopkeeper(current_user: models.User) -> None:
    """Raise 403 unless the caller is a shopkeeper. Used by every endpoint
    in this section so a doctor hand-crafting a URL gets blocked."""
    if current_user.role != "shopkeeper":
        raise HTTPException(status_code=403, detail="Shopkeeper access only.")


def _log_shopkeeper_activity(db: Session, shopkeeper_id: int, action: str,
                             detail: str, ref_type: Optional[str] = None,
                             ref_id: Optional[int] = None) -> models.ShopkeeperActivity:
    """Append one row to the shopkeeper's activity/audit feed.

    Feeds the dashboard Recent Live Updates, the activity heatmap, and the
    recent-activity analytics. Deleting these rows later only removes the
    feed entry — never the underlying bills/stock/customer data.
    """
    row = models.ShopkeeperActivity(
        shopkeeper_id=shopkeeper_id,
        action=action,
        detail=detail[:500],
        ref_type=ref_type,
        ref_id=ref_id,
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    return row


def _get_or_create_expiry_prefs(db: Session, shopkeeper_id: int) -> models.ExpiryAlertPreference:
    """Return the shopkeeper's prefs row, creating a default (30 days) if missing.

    Named distinctly from the notification-prefs helper (line 373) — Python
    would silently rebind the name to whichever function is defined last,
    which would otherwise break the /notifications/preferences endpoint by
    returning an ExpiryAlertPreference row when a NotificationPreference is
    expected. Both helpers happen to share the same shape, so the rename is
    the simplest safe fix.
    """
    prefs = (
        db.query(models.ExpiryAlertPreference)
        .filter(models.ExpiryAlertPreference.shopkeeper_id == shopkeeper_id)
        .first()
    )
    if prefs is None:
        prefs = models.ExpiryAlertPreference(shopkeeper_id=shopkeeper_id, lead_days=30)
        db.add(prefs)
        db.commit()
        db.refresh(prefs)
    return prefs


def _decorate_stock(stock: models.MedicineStock, lead_days: int) -> schemas.MedicineStockOut:
    """Build a MedicineStockOut with computed flags. Pulled into a helper so
    both /inventory list and /inventory/{id} return the same shape."""
    today = date.today()
    expiry = stock.expiry_date
    days_left = (expiry - today).days
    out = schemas.MedicineStockOut.model_validate(stock)
    out.days_to_expiry = days_left
    out.is_expired = days_left < 0
    out.is_expiring_soon = 0 <= days_left <= lead_days
    out.is_low_stock = stock.quantity <= stock.low_stock_threshold
    return out


@app.get("/me/nav")
def get_my_nav(current_user: models.User = Depends(auth.get_current_user)):
    """Sidebar source of truth. Returns the role and the nav list the
    frontend should render. Used by sidebar.js on every page load."""
    return {
        "role": current_user.role,
        "nav": _nav_for_role(current_user.role),
    }


# ---------- Inventory CRUD ----------

@app.get("/inventory/expiry-due", response_model=schemas.ExpiryDueOut)
def inventory_expiry_due(
    lead_days: Optional[int] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Dashboard of soon-to-expire / already-expired stock. Sorted by
    expiry_date ASC. The lead_days query param overrides the user's saved
    preference (handy for the UI's "show me everything expiring in 90 days"
    drill-down)."""
    _ensure_shopkeeper(current_user)
    prefs = _get_or_create_expiry_prefs(db, current_user.id)
    effective_lead = lead_days if lead_days is not None else prefs.lead_days

    today = date.today()
    rows = (
        db.query(models.MedicineStock)
        .filter(models.MedicineStock.shopkeeper_id == current_user.id)
        .all()
    )
    due_rows = []
    for r in rows:
        days_left = (r.expiry_date - today).days
        # Include rows that are already expired or expiring within the window.
        if days_left <= effective_lead:
            due_rows.append(schemas.ExpiryDueRow(
                id=r.id,
                medicine_name=r.medicine_name,
                batch_no=r.batch_no,
                manufacture_date=r.manufacture_date,
                expiry_date=r.expiry_date,
                quantity=r.quantity,
                supplier=r.supplier,
                days_to_expiry=days_left,
                is_expired=days_left < 0,
                is_expiring_soon=0 <= days_left <= effective_lead,
            ))
    due_rows.sort(key=lambda x: x.days_to_expiry)
    return schemas.ExpiryDueOut(lead_days=effective_lead, items=due_rows)


@app.get("/inventory", response_model=list[schemas.MedicineStockOut])
def list_inventory(
    expiring_within_days: Optional[int] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    _ensure_shopkeeper(current_user)
    prefs = _get_or_create_expiry_prefs(db, current_user.id)
    lead_days = expiring_within_days if expiring_within_days is not None else prefs.lead_days

    rows = (
        db.query(models.MedicineStock)
        .filter(models.MedicineStock.shopkeeper_id == current_user.id)
        .order_by(models.MedicineStock.expiry_date.asc())
        .all()
    )
    return [_decorate_stock(r, lead_days) for r in rows]


@app.get("/inventory/search", response_model=list[schemas.MedicineStockOut])
def search_inventory(
    q: str = "",
    limit: int = 10,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Fast debounced autocomplete over the shopkeeper's own inventory.
    Matches medicine name OR composition, LIMIT-bounded, index-friendly.
    Registered before /inventory/{stock_id} so the literal segment 'search'
    is never captured as a stock id."""
    _ensure_shopkeeper(current_user)
    limit = min(max(limit, 1), 25)
    prefs = _get_or_create_expiry_prefs(db, current_user.id)
    q = (q or "").strip()
    if not q:
        return []
    like = f"%{q}%"
    rows = (
        db.query(models.MedicineStock)
        .filter(models.MedicineStock.shopkeeper_id == current_user.id,
                sa_or_(models.MedicineStock.medicine_name.like(like),
                       models.MedicineStock.composition.like(like)))
        .order_by(models.MedicineStock.medicine_name.asc())
        .limit(limit)
        .all()
    )
    return [_decorate_stock(r, prefs.lead_days) for r in rows]


@app.post("/inventory", response_model=schemas.MedicineStockOut, status_code=201)
def create_inventory(
    payload: schemas.MedicineStockCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    _ensure_shopkeeper(current_user)
    if payload.expiry_date <= payload.manufacture_date:
        raise HTTPException(status_code=400, detail="expiry_date must be after manufacture_date")

    stock = models.MedicineStock(
        shopkeeper_id=current_user.id,
        **payload.model_dump(),
    )
    db.add(stock)
    db.commit()
    db.refresh(stock)

    try:
        _log_shopkeeper_activity(
            db, current_user.id, "medicine_added",
            f"Medicine {stock.medicine_name} (batch {stock.batch_no}) added",
            ref_type="stock", ref_id=stock.id,
        )
    except Exception:
        db.rollback()

    prefs = _get_or_create_expiry_prefs(db, current_user.id)
    return _decorate_stock(stock, prefs.lead_days)


