@app.put("/inventory/{stock_id}", response_model=schemas.MedicineStockOut)
def update_inventory_item(
    stock_id: int,
    payload: schemas.MedicineStockUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    _ensure_shopkeeper(current_user)
    stock = (
        db.query(models.MedicineStock)
        .filter(models.MedicineStock.id == stock_id,
                models.MedicineStock.shopkeeper_id == current_user.id)
        .first()
    )
    if not stock:
        raise HTTPException(status_code=404, detail="Stock item not found")

    old_qty = stock.quantity
    data = payload.model_dump(exclude_unset=True)
    for k, v in data.items():
        setattr(stock, k, v)
    db.commit()
    db.refresh(stock)

    try:
        changed_parts = []
        if "quantity" in data and data["quantity"] != old_qty:
            changed_parts.append(f"quantity {old_qty}→{data['quantity']}")
        if "unit_price" in data:
            changed_parts.append("price updated")
        if "medicine_name" in data:
            changed_parts.append("name updated")
        if "expiry_date" in data:
            changed_parts.append("expiry updated")
        _log_shopkeeper_activity(
            db, current_user.id, "stock_updated",
            f"Stock updated for {stock.medicine_name} ({', '.join(changed_parts) if changed_parts else 'details changed'})",
            ref_type="stock", ref_id=stock.id,
        )
    except Exception:
        db.rollback()

    prefs = _get_or_create_expiry_prefs(db, current_user.id)
    return _decorate_stock(stock, prefs.lead_days)


