# ---------- Billing ----------

def _next_bill_number(db: Session, shopkeeper_id: int, prefix: str = "INV") -> str:
    """Generate <prefix>-YYYYMMDD-#### based on how many bills the same
    shopkeeper has created today. Inventory bills use ``INV``, proforma
    bills use ``PRF`` so the two kinds are immediately distinguishable.
    The counter is unique per (shopkeeper, prefix, day) so two shops never
    collide."""
    today_prefix = datetime.utcnow().strftime(f"{prefix}-%Y%m%d-")
    count_today = (
        db.query(models.Bill)
        .filter(models.Bill.shopkeeper_id == shopkeeper_id,
                models.Bill.bill_number.like(today_prefix + "%"))
        .count()
    )
    # Walk forward until we find a free number — covers the rare case where
    # an earlier bill was deleted and the counter would otherwise reuse it.
    while True:
        candidate = f"{today_prefix}{count_today + 1:04d}"
        exists = (
            db.query(models.Bill)
            .filter(models.Bill.shopkeeper_id == shopkeeper_id,
                    models.Bill.bill_number == candidate)
            .first()
        )
        if not exists:
            return candidate
        count_today += 1


@app.post("/bills", response_model=schemas.BillOut, status_code=201)
def create_bill(
    payload: schemas.BillCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    _ensure_shopkeeper(current_user)
    if not payload.items:
        raise HTTPException(status_code=400, detail="Bill must contain at least one item")
    if payload.status not in ("paid", "pending", "cancelled"):
        raise HTTPException(status_code=400, detail="status must be paid, pending or cancelled")
    # 2026-09: optional authoritative patient link (patients.id). When set, the
    # patient sees the bill automatically under Manage → My Billings.
    if payload.patient_id is not None:
        pat = db.query(models.Patient).filter(models.Patient.id == payload.patient_id).first()
        if pat is None:
            raise HTTPException(status_code=404, detail="Patient not found.")

    # Compute subtotal + line totals (pure math — no DB writes yet, so a
    # validation failure below cannot leave partial state behind).
    subtotal = 0.0
    line_payloads = []
    for item in payload.items:
        if item.quantity <= 0:
            raise HTTPException(status_code=400, detail="quantity must be > 0")
        if item.unit_price < 0:
            raise HTTPException(status_code=400, detail="unit_price must be >= 0")
        line_total = round(item.quantity * item.unit_price, 2)
        subtotal += line_total
        line_payloads.append((item, line_total))

    subtotal = round(subtotal, 2)
    discount = round(max(0.0, payload.discount), 2)
    # Discount is applied before tax (standard retail).
    taxable = max(0.0, subtotal - discount)
    tax_amount = round(taxable * (payload.tax_percent / 100.0), 2)
    total = round(taxable + tax_amount, 2)

    prefix = "PRF" if not payload.affects_inventory else "INV"

    try:
        # ---- Strict stock validation for inventory bills (2026-09) ----
        # Proforma bills never touch stock. Inventory bills must be fully
        # covered by available stock — otherwise we roll back and tell the
        # shopkeeper exactly which medicine falls short, instead of silently
        # going negative (the previous best-effort behavior).
        if payload.affects_inventory:
            for item in line_payloads:
                name = (item[0].medicine_name or "").strip()
                if not name:
                    raise HTTPException(status_code=400, detail="medicine_name is required")
                want = int(item[0].quantity or 0)
                available = 0
                if item[0].batch_no:
                    stock = (
                        db.query(models.MedicineStock)
                        .filter(
                            models.MedicineStock.shopkeeper_id == current_user.id,
                            models.MedicineStock.medicine_name == name,
                            models.MedicineStock.batch_no == item[0].batch_no,
                        )
                        .first()
                    )
                    available = stock.quantity if stock else 0
                else:
                    available = (
                        db.query(models.MedicineStock)
                        .filter(
                            models.MedicineStock.shopkeeper_id == current_user.id,
                            models.MedicineStock.medicine_name == name,
                            models.MedicineStock.quantity > 0,
                        )
                        .with_entities(sa_func.coalesce(sa_func.sum(models.MedicineStock.quantity), 0))
                        .scalar()
                    ) or 0
                if available < want:
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            f"Insufficient stock for {name}: requested {want}, "
                            f"available {int(available)}."
                        ),
                    )

        bill = models.Bill(
            shopkeeper_id=current_user.id,
            patient_id=payload.patient_id,
            bill_number=_next_bill_number(db, current_user.id, prefix),
            customer_name=payload.customer_name,
            customer_phone=payload.customer_phone,
            customer_address=payload.customer_address,
            subtotal=subtotal,
            tax_percent=payload.tax_percent,
            tax_amount=tax_amount,
            discount=discount,
            total=total,
            payment_method=payload.payment_method,
            status=payload.status,
            notes=payload.notes,
            # Persist the bill kind (proforma vs inventory) so the bill list /
            # PDF can label it accordingly without re-deriving from data.
            affects_inventory=payload.affects_inventory,
        )
        db.add(bill)
        db.flush()  # need bill.id before adding line items

        for item, line_total in line_payloads:
            db.add(models.BillLineItem(
                bill_id=bill.id,
                medicine_name=item.medicine_name,
                batch_no=item.batch_no,
                quantity=item.quantity,
                unit_price=item.unit_price,
                line_total=line_total,
                # Persist the new optional per-line metadata (manufacture_date,
                # expiry_date, unit, mrp) on the line row so the bill record
                # carries the full context. All default to NULL on older clients.
                manufacture_date=getattr(item, "manufacture_date", None),
                expiry_date=getattr(item, "expiry_date", None),
                unit=getattr(item, "unit", None),
                mrp=getattr(item, "mrp", None),
            ))

            # Stock decrement for inventory bills. Skipped entirely for
            # proforma bills (affects_inventory=False), which still record
            # line items but must not change stock.
            #
            # Matching strategy (in priority order):
            #   1. exact (medicine_name + batch_no) — if a batch was captured
            #   2. FIFO across all batches of this medicine (earliest expiry
            #      first), drawing from each batch until the requested
            #      quantity is satisfied.
            if payload.affects_inventory:
                name = (item.medicine_name or "").strip()
                remaining = int(item.quantity or 0)
                if item.batch_no:
                    stock = (
                        db.query(models.MedicineStock)
                        .filter(
                            models.MedicineStock.shopkeeper_id == current_user.id,
                            models.MedicineStock.medicine_name == name,
                            models.MedicineStock.batch_no == item.batch_no,
                        )
                        .first()
                    )
                    if stock and stock.quantity > 0:
                        take = min(remaining, stock.quantity)
                        stock.quantity = stock.quantity - take
                        remaining -= take
                if remaining > 0:
                    fifo = (
                        db.query(models.MedicineStock)
                        .filter(
                            models.MedicineStock.shopkeeper_id == current_user.id,
                            models.MedicineStock.medicine_name == name,
                            models.MedicineStock.quantity > 0,
                        )
                        .order_by(models.MedicineStock.expiry_date.asc())
                        .all()
                    )
                    for stock in fifo:
                        if remaining <= 0:
                            break
                        take = min(remaining, stock.quantity)
                        stock.quantity = stock.quantity - take
                        remaining -= take

        db.commit()
    except HTTPException:
        db.rollback()
        raise
    except Exception:
        db.rollback()
        raise

    # Activity feed entry — separate commit so a feed-row failure never
    # rolls back the bill itself.
    try:
        if payload.affects_inventory:
            _log_shopkeeper_activity(
                db, current_user.id, "bill_created",
                f"Bill {bill.bill_number} generated for {bill.customer_name}",
                ref_type="bill", ref_id=bill.id,
            )
        else:
            _log_shopkeeper_activity(
                db, current_user.id, "proforma_created",
                f"Proforma bill {bill.bill_number} created for {bill.customer_name}",
                ref_type="bill", ref_id=bill.id,
            )
    except Exception:
        # Activity logging is best-effort; never fail the bill because of it.
        db.rollback()

    # Fetch the bill's line items and assemble the response. We do this
    # manually (rather than relying on a SQLAlchemy relationship) to keep
    # the data path simple and predictable.
    line_items_db = (
        db.query(models.BillLineItem)
        .filter(models.BillLineItem.bill_id == bill.id)
        .all()
    )
    item_payloads = [
        schemas.BillLineItemOut(
            id=li.id,
            medicine_name=li.medicine_name,
            batch_no=li.batch_no,
            quantity=li.quantity,
            unit_price=li.unit_price,
            line_total=li.line_total,
            manufacture_date=li.manufacture_date,
            expiry_date=li.expiry_date,
            unit=li.unit,
            mrp=li.mrp,
        )
        for li in line_items_db
    ]
    return schemas.BillOut(
        id=bill.id,
        patient_id=bill.patient_id,
        bill_number=bill.bill_number,
        customer_name=bill.customer_name,
        customer_phone=bill.customer_phone,
        customer_address=bill.customer_address,
        subtotal=bill.subtotal,
        tax_percent=bill.tax_percent,
        tax_amount=bill.tax_amount,
        discount=bill.discount,
        total=bill.total,
        payment_method=bill.payment_method,
        notes=bill.notes,
        created_at=bill.created_at,
        affects_inventory=bill.affects_inventory,
        items=item_payloads,
    )


@app.get("/bills", response_model=schemas.BillListOut)
def list_bills(
    limit: int = 50,
    offset: int = 0,
    q: Optional[str] = None,
    status: Optional[str] = None,
    bill_type: Optional[str] = None,     # "inventory" | "proforma"
    date_from: Optional[date] = None,
    date_to: Optional[date] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Bill list with server-side search + filters: free text (bill number /
    customer name / phone), payment status, bill kind, and date range. All
    filtering happens in SQL — the frontend never downloads the full table."""
    _ensure_shopkeeper(current_user)
    query = (
        db.query(models.Bill)
        .filter(models.Bill.shopkeeper_id == current_user.id)
    )
    if q:
        like = f"%{q.strip()}%"
        query = query.filter(sa_or_(
            models.Bill.bill_number.like(like),
            models.Bill.customer_name.like(like),
            models.Bill.customer_phone.like(like),
        ))
    if status:
        query = query.filter(models.Bill.status == status)
    if bill_type == "inventory":
        query = query.filter(models.Bill.affects_inventory.is_(True))
    elif bill_type == "proforma":
        query = query.filter(models.Bill.affects_inventory.is_(False))
    if date_from:
        query = query.filter(models.Bill.created_at >= datetime.combine(date_from, datetime.min.time()))
    if date_to:
        query = query.filter(models.Bill.created_at <= datetime.combine(date_to, datetime.max.time()))

    total = query.count()
    rows = query.order_by(models.Bill.created_at.desc()).offset(offset).limit(limit).all()
    items = [
        schemas.BillListItem(
            id=r.id,
            bill_number=r.bill_number,
            customer_name=r.customer_name,
            total=r.total,
            payment_method=r.payment_method,
            status=r.status or "paid",
            created_at=r.created_at,
            affects_inventory=r.affects_inventory,
        )
        for r in rows
    ]
    return schemas.BillListOut(items=items, total_count=total)


