@app.patch("/bills/{bill_id}/status", response_model=schemas.BillListItem)
def update_bill_status(
    bill_id: int,
    payload: dict,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Mark a bill paid / pending / cancelled. Cancelling an inventory bill
    does NOT restore stock automatically (that is a manual stock adjust), to
    keep the audit trail unambiguous."""
    _ensure_shopkeeper(current_user)
    new_status = (payload.get("status") or "").strip()
    if new_status not in ("paid", "pending", "cancelled"):
        raise HTTPException(status_code=400, detail="status must be paid, pending or cancelled")
    bill = (
        db.query(models.Bill)
        .filter(models.Bill.id == bill_id,
                models.Bill.shopkeeper_id == current_user.id)
        .first()
    )
    if not bill:
        raise HTTPException(status_code=404, detail="Bill not found")
    bill.status = new_status
    db.commit()
    try:
        _log_shopkeeper_activity(
            db, current_user.id, "bill_status_changed",
            f"Bill {bill.bill_number} marked {new_status}",
            ref_type="bill", ref_id=bill.id,
        )
    except Exception:
        db.rollback()
    return schemas.BillListItem(
        id=bill.id,
        bill_number=bill.bill_number,
        customer_name=bill.customer_name,
        total=bill.total,
        payment_method=bill.payment_method,
        status=bill.status or "paid",
        created_at=bill.created_at,
        affects_inventory=bill.affects_inventory,
    )


