@app.get("/hospitals/mine/nurses-v2", response_model=schemas.HospitalNursesListOut)
def list_my_hospital_nurses_v2(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List every nurse globally. /hospitals/mine/nurses is the legacy picker
    endpoint (kept for the admit-queue UI); this v2 endpoint powers the
    hospital-people.html Nurses tab with profile + registration flag."""
    profile = _ensure_hospital_admin(db, current_user)
    nurses = (
        db.query(models.User)
        .filter(models.User.role == "nurse")
        .order_by(models.User.full_name.asc().nullslast(), models.User.username.asc())
        .all()
    )
    if not nurses:
        return {"items": [], "total_count": 0}
    nurse_profile_by_uid = {
        p.user_id: p for p in db.query(models.NurseProfile).filter(
            models.NurseProfile.user_id.in_([u.id for u in nurses])
        ).all()
    }
    links_by_uid = {
        l.user_id: l for l in db.query(models.HospitalRegistrationLink).filter(
            models.HospitalRegistrationLink.hospital_id == profile.hospital_id,
            models.HospitalRegistrationLink.role == "nurse",
        ).all()
    }
    items = []
    for u in nurses:
        np = nurse_profile_by_uid.get(u.id)
        link = links_by_uid.get(u.id)
        items.append(schemas.HospitalNurseRow(
            id=u.id,
            username=u.username,
            full_name=u.full_name,
            email=u.email,
            department=np.department if np else None,
            qualifications=np.qualifications if np else None,
            experience_years=np.experience_years if np else None,
            registered_with_this_hospital=link is not None,
            registration_link_id=link.id if link else None,
        ))
    return {"items": items, "total_count": len(items)}


# ---- Patient listing (global) ----
@app.get("/hospitals/mine/patients", response_model=schemas.HospitalPatientsListOut)
def list_my_hospital_patients(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List every patient globally (auto-link), enriched with profile +
    medical-history count + report count + registered-with-this-hospital flag."""
    _ensure_hospital_admin(db, current_user)
    users = (
        db.query(models.User)
        .filter(models.User.role == "patient", models.User.patient_id.isnot(None))
        .order_by(models.User.full_name.asc().nullslast(), models.User.username.asc())
        .all()
    )
    if not users:
        return {"items": [], "total_count": 0}
    patient_ids = [u.patient_id for u in users if u.patient_id is not None]
    profiles_by_pid = {
        p.patient_id: p for p in db.query(models.PatientProfile).filter(
            models.PatientProfile.patient_id.in_(patient_ids)
        ).all()
    }
    mh_counts = {}
    for row in db.query(
        models.MedicalHistoryEntry.patient_id,
    ).filter(models.MedicalHistoryEntry.patient_id.in_(patient_ids)).all():
        mh_counts[row.patient_id] = mh_counts.get(row.patient_id, 0) + 1
    rep_counts = {}
    for row in db.query(models.PatientReport.patient_id).filter(
        models.PatientReport.patient_id.in_(patient_ids)
    ).all():
        rep_counts[row.patient_id] = rep_counts.get(row.patient_id, 0) + 1
    # Bulk-fetch links (any role='patient' for the admin's hospital)
    admin_profile = _ensure_hospital_admin(db, current_user)
    links_by_uid = {
        l.user_id: l for l in db.query(models.HospitalRegistrationLink).filter(
            models.HospitalRegistrationLink.hospital_id == admin_profile.hospital_id,
            models.HospitalRegistrationLink.role == "patient",
        ).all()
    }
    items = []
    for u in users:
        if u.patient_id is None:
            continue
        prof = profiles_by_pid.get(u.patient_id)
        link = links_by_uid.get(u.id)
        items.append(schemas.HospitalPatientRow(
            id=u.patient_id,
            user_id=u.id,
            username=u.username,
            full_name=u.full_name,
            email=u.email,
            phone=getattr(u, "phone", None),
            blood_group=prof.blood_group if prof else None,
            date_of_birth=prof.date_of_birth if prof else None,
            city=prof.city if prof else None,
            registered_with_this_hospital=link is not None,
            registration_link_id=link.id if link else None,
            medical_history_count=mh_counts.get(u.patient_id, 0),
            report_count=rep_counts.get(u.patient_id, 0),
        ))
    return {"items": items, "total_count": len(items)}


# ---- Register a doctor with the hospital ----
@app.post("/hospitals/mine/register/doctor", response_model=schemas.RegisterResponseOut)
def register_doctor_for_my_hospital(
    payload: schemas.DoctorRegisterIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Create (or attach to) a doctor User, populate the DoctorProfile,
    and create the HospitalRegistrationLink. Returns the new user_id +
    initial_password so the admin can hand it to the doctor."""
    profile = _ensure_hospital_admin(db, current_user)
    if not payload.username or len(payload.username) < 3:
        raise HTTPException(status_code=400, detail="username must be at least 3 characters.")

    user = db.query(models.User).filter(models.User.username == payload.username).first()
    initial_pw = payload.initial_password
    is_new_user = False
    if user is None:
        is_new_user = True
        initial_pw = initial_pw or secrets.token_urlsafe(8)
        if user is None:
            user = models.User(
                username=payload.username,
                email=payload.email or f"{payload.username}@hospital.local",
                full_name=payload.full_name,
                role="doctor",
                hashed_password=auth.hash_password(initial_pw),
            )
            db.add(user)
            db.flush()
    else:
        # Reattach: if username exists but is a different role, error out.
        if user.role != "doctor":
            raise HTTPException(
                status_code=409,
                detail=f"Username '{payload.username}' is already registered as {user.role}, not doctor.",
            )
        # Update contact fields if provided.
        if payload.full_name: user.full_name = payload.full_name
        if payload.email: user.email = payload.email

    # Upsert DoctorProfile
    dp = db.query(models.DoctorProfile).filter(models.DoctorProfile.user_id == user.id).first()
    if dp is None and payload.profile is not None:
        dp = models.DoctorProfile(user_id=user.id)
        db.add(dp)
    if dp is not None and payload.profile is not None:
        for f in ("specialization", "qualifications", "experience_years",
                  "clinic_name", "clinic_address", "consultation_fee", "bio",
                  "languages", "available_hours"):
            val = getattr(payload.profile, f, None)
            if val is not None:
                setattr(dp, f, val)

    link = _ensure_registration(db, profile.hospital_id, user.id, "doctor")
    link.registered_by_user_id = current_user.id

    db.commit()
    db.refresh(user)
    return schemas.RegisterResponseOut(
        user_id=user.id,
        patient_id=None,
        username=user.username,
        initial_password=initial_pw if is_new_user else None,
        registration_link_id=link.id,
    )


def _user_has_been_used(db: Session, user: models.User) -> bool:
    """Heuristic: did this user already log in? Used to decide whether to
    echo the password back to the admin. We use created_by_doctor_id is
    null AND the User.id is large (= recently created) as the signal that
    the row was just made by this admin's flow; otherwise it's an existing
    account and we don't echo the password.
    NOTE: User has no last_login_at column. We rely on whether the row is
    brand new (no profile yet attached) instead."""
    if user.id is None:
        return False
    # If the user has any linked profile rows of the matching role, it's
    # an established account. Otherwise it's likely fresh.
    if user.role == "doctor":
        return db.query(models.DoctorProfile).filter(models.DoctorProfile.user_id == user.id).first() is not None
    if user.role == "nurse":
        return db.query(models.NurseProfile).filter(models.NurseProfile.user_id == user.id).first() is not None
    if user.role == "patient":
        return db.query(models.PatientProfile).filter(models.PatientProfile.patient_id == user.patient_id).first() is not None
    return True


