# ---- Register a patient (with rich profile + medical history + media) ----
@app.post("/hospitals/mine/register/patient", response_model=schemas.RegisterResponseOut)
async def register_patient_for_my_hospital(
    # Multipart: a JSON 'payload' field plus one or more 'files' for media.
    payload: str = Form(...),
    files: list[UploadFile] = File(default=[]),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Create (or attach to) a patient User + Patient + PatientProfile +
    MedicalHistoryEntry rows + PatientReport rows (from uploaded files), and
    create the HospitalRegistrationLink. JSON payload is a PatientRegisterIn
    stringified; files are saved under UPLOAD_DIR."""
    import json
    profile = _ensure_hospital_admin(db, current_user)
    try:
        data = schemas.PatientRegisterIn(**json.loads(payload))
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Invalid JSON payload: {e}")

    if not data.username or len(data.username) < 3:
        raise HTTPException(status_code=400, detail="username must be at least 3 characters.")

    user = db.query(models.User).filter(models.User.username == data.username).first()
    initial_pw = data.initial_password
    is_new_user = False
    if user is None:
        is_new_user = True
        initial_pw = initial_pw or secrets.token_urlsafe(8)
        # Find an existing Patient row for this username, or create a fresh one.
        patient_row = db.query(models.Patient).filter(
            models.Patient.name == (data.full_name or data.username)
        ).first()
        if patient_row is None:
            patient_row = models.Patient(name=data.full_name or data.username)
            db.add(patient_row)
            db.flush()
        user = models.User(
            username=data.username,
            email=data.email or f"{data.username}@hospital.local",
            full_name=data.full_name,
            role="patient",
            patient_id=patient_row.id,
            hashed_password=auth.hash_password(initial_pw),
        )
        db.add(user)
        db.flush()
    else:
        if user.role != "patient":
            raise HTTPException(
                status_code=409,
                detail=f"Username '{data.username}' is already registered as {user.role}, not patient.",
            )
        if data.full_name: user.full_name = data.full_name
        if data.email: user.email = data.email
        # Make sure the User is linked to a Patient row.
        if user.patient_id is None:
            patient_row = models.Patient(name=data.full_name or data.username)
            db.add(patient_row)
            db.flush()
            user.patient_id = patient_row.id

    # Upsert PatientProfile
    pp = db.query(models.PatientProfile).filter(models.PatientProfile.patient_id == user.patient_id).first()
    if pp is None:
        pp = models.PatientProfile(patient_id=user.patient_id)
        db.add(pp)
    for f in ("date_of_birth", "blood_group", "address", "city", "state",
              "country", "pincode", "emergency_contact_name",
              "emergency_contact_phone", "emergency_contact_relation",
              "occupation", "marital_status", "smoking", "alcohol",
              "diet", "exercise", "sleep_hours"):
        val = getattr(data, f, None)
        if val is not None:
            setattr(pp, f, val)

    # Medical history rows
    if data.medical_history:
        for entry in data.medical_history:
            db.add(models.MedicalHistoryEntry(
                patient_id=user.patient_id,
                category=entry.category or "other",
                title=entry.title,
                details=entry.details,
                diagnosed_year=entry.diagnosed_year,
                is_ongoing=bool(entry.is_ongoing),
            ))

    # PatientReport rows from uploaded files
    if files:
        patient_dir = os.path.join(UPLOAD_DIR, f"patient_{user.patient_id}")
        os.makedirs(patient_dir, exist_ok=True)
        for f in files:
            content = await f.read()
            if not content:
                continue
            if len(content) > MAX_UPLOAD_BYTES:
                raise HTTPException(status_code=413, detail=f"File '{f.filename}' too large.")
            safe_original = os.path.basename(f.filename or "report")
            stored_name = f"{uuid.uuid4().hex}_{safe_original}"
            stored_path = os.path.join(patient_dir, stored_name)
            with open(stored_path, "wb") as fp:
                fp.write(content)
            db.add(models.PatientReport(
                patient_id=user.patient_id,
                title=safe_original,
                category="other",
                file_name=safe_original,
                stored_path=stored_path,
                mime_type=f.content_type,
                file_size=len(content),
                uploaded_by_user_id=current_user.id,
            ))

    link = _ensure_registration(db, profile.hospital_id, user.id, "patient")
    link.registered_by_user_id = current_user.id
    db.commit()
    db.refresh(user)
    return schemas.RegisterResponseOut(
        user_id=user.id,
        patient_id=user.patient_id,
        username=user.username,
        initial_password=initial_pw if is_new_user else None,
        registration_link_id=link.id,
    )


