@app.patch("/hospitals/mine/profile/doctor/{user_id}", response_model=schemas.DoctorProfileOut)
def edit_doctor_profile_for_my_hospital(
    user_id: int,
    payload: schemas.DoctorProfileCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Edit any signed-up doctor's DoctorProfile from the hospital page."""
    _ensure_hospital_admin(db, current_user)
    user = db.query(models.User).filter(models.User.id == user_id, models.User.role == "doctor").first()
    if user is None:
        raise HTTPException(status_code=404, detail="Doctor not found.")
    dp = db.query(models.DoctorProfile).filter(models.DoctorProfile.user_id == user_id).first()
    if dp is None:
        dp = models.DoctorProfile(user_id=user_id)
        db.add(dp)
    for f in ("specialization", "qualifications", "experience_years",
              "clinic_name", "clinic_address", "consultation_fee", "bio",
              "languages", "available_hours"):
        val = getattr(payload, f, None)
        if val is not None:
            setattr(dp, f, val)
    db.commit()
    db.refresh(dp)
    return dp


