# ---- Profile remove (hard-delete profile + link; keep User + Patient row) ----
@app.delete("/hospitals/mine/profile")
def remove_registration_for_my_hospital(
    user_id: Optional[int] = None,
    patient_id: Optional[int] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Drop the HospitalRegistrationLink and the role profile. User + Patient
    rows are preserved so chat/audit history stays intact."""
    profile = _ensure_hospital_admin(db, current_user)
    target_user_id = user_id
    if target_user_id is None and patient_id is not None:
        u = db.query(models.User).filter(models.User.patient_id == patient_id).first()
        if u is None:
            raise HTTPException(status_code=404, detail="Patient user not found.")
        target_user_id = u.id
    if target_user_id is None:
        raise HTTPException(status_code=400, detail="Provide user_id or patient_id.")

    # Find the link(s) for this user at this hospital (any role)
    links = (
        db.query(models.HospitalRegistrationLink)
        .filter(
            models.HospitalRegistrationLink.hospital_id == profile.hospital_id,
            models.HospitalRegistrationLink.user_id == target_user_id,
        )
        .all()
    )
    if not links:
        raise HTTPException(status_code=404, detail="No registration found for this user at your hospital.")
    for l in links:
        db.delete(l)

    # Drop the role profile(s). Try doctor + nurse; for patient we drop the
    # PatientProfile + MedicalHistoryEntry + PatientReport so the row count
    # shrinks back to "core Patient only". The User + Patient rows remain.
    user = db.query(models.User).filter(models.User.id == target_user_id).first()
    if user is None:
        db.commit()
        return {"removed": True}
    if user.role == "doctor":
        for p in db.query(models.DoctorProfile).filter(models.DoctorProfile.user_id == target_user_id).all():
            db.delete(p)
    elif user.role == "nurse":
        for p in db.query(models.NurseProfile).filter(models.NurseProfile.user_id == target_user_id).all():
            db.delete(p)
    elif user.role == "patient" and user.patient_id is not None:
        for p in db.query(models.PatientProfile).filter(models.PatientProfile.patient_id == user.patient_id).all():
            db.delete(p)
        for e in db.query(models.MedicalHistoryEntry).filter(models.MedicalHistoryEntry.patient_id == user.patient_id).all():
            db.delete(e)
        for r in db.query(models.PatientReport).filter(models.PatientReport.patient_id == user.patient_id).all():
            db.delete(r)
    db.commit()
    return {"removed": True, "user_id": target_user_id}


# ============================================================================
# Appointments
# ============================================================================

def _appointment_to_out(db: Session, a: models.Appointment) -> schemas.AppointmentOut:
    doc = db.query(models.User).filter(models.User.id == a.doctor_user_id).first()
    doc_prof = db.query(models.DoctorProfile).filter(models.DoctorProfile.user_id == a.doctor_user_id).first()
    pat_user = db.query(models.User).filter(models.User.patient_id == a.patient_id, models.User.role == "patient").first()
    pat_row = db.query(models.Patient).filter(models.Patient.id == a.patient_id).first()
    hosp = db.query(models.Hospital).filter(models.Hospital.id == a.hospital_id).first()
    return schemas.AppointmentOut(
        id=a.id,
        hospital_id=a.hospital_id,
        hospital_name=hosp.name if hosp else None,
        doctor_user_id=a.doctor_user_id,
        doctor_name=doc.full_name if doc else None,
        doctor_specialization=doc_prof.specialization if doc_prof else None,
        patient_id=a.patient_id,
        patient_name=(pat_user.full_name if pat_user else (pat_row.name if pat_row else None)),
        patient_username=(pat_user.username if pat_user else None),
        scheduled_at=a.scheduled_at,
        duration_minutes=a.duration_minutes or 30,
        room_number=a.room_number,
        department=a.department,
        reason=a.reason,
        notes=a.notes,
        status=a.status,
        booked_by_patient=bool(a.booked_by_patient),
        created_at=a.created_at,
        updated_at=a.updated_at,
    )


@app.post("/hospitals/mine/appointments", response_model=schemas.AppointmentOut)
def book_appointment_by_admin(
    payload: schemas.AppointmentCreateIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Hospital admin books an appointment for a doctor/patient pair at this hospital."""
    profile = _ensure_hospital_admin(db, current_user)
    doc = db.query(models.User).filter(models.User.id == payload.doctor_user_id, models.User.role == "doctor").first()
    if doc is None:
        raise HTTPException(status_code=404, detail="Doctor not found.")
    pat_user = db.query(models.User).filter(models.User.patient_id == payload.patient_id, models.User.role == "patient").first()
    if pat_user is None:
        raise HTTPException(status_code=404, detail="Patient not found.")
    a = models.Appointment(
        hospital_id=profile.hospital_id,
        doctor_user_id=payload.doctor_user_id,
        patient_id=payload.patient_id,
        scheduled_at=payload.scheduled_at,
        duration_minutes=payload.duration_minutes or 30,
        room_number=payload.room_number,
        department=payload.department,
        reason=payload.reason,
        status="scheduled",
        booked_by_patient=False,
        created_by_user_id=current_user.id,
    )
    db.add(a)
    db.flush()
    # Notify both doctor and patient.
    _enqueue_notification(
        db,
        recipient_user_id=doc.id,
        kind="appointment",
        title="New appointment scheduled",
        detail=f"Patient {pat_user.full_name or pat_user.username} on {a.scheduled_at.strftime('%Y-%m-%d %H:%M')}",
        link="dashboard.html",
    )
    _enqueue_notification(
        db,
        recipient_user_id=pat_user.id,
        kind="appointment",
        title="Appointment booked for you",
        detail=f"With Dr. {doc.full_name or doc.username} on {a.scheduled_at.strftime('%Y-%m-%d %H:%M')}",            link="my-admission.html",
        )
    _hook_appointment_activity(
        db, a, "appointment_booked", current_user.id, current_user.role,
        f"Appointment scheduled for {pat_user.full_name or pat_user.username} with Dr. {doc.full_name or doc.username}.",
    )
    db.commit()
    db.refresh(a)
    return _appointment_to_out(db, a)


@app.post("/patients/mine/appointments", response_model=schemas.AppointmentOut)
def book_appointment_by_patient(
    payload: schemas.AppointmentCreateIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Patient self-books an appointment with any doctor they've been linked to."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    if payload.patient_id != current_user.patient_id:
        raise HTTPException(status_code=403, detail="You can only book appointments for yourself.")
    if payload.doctor_user_id is None:
        raise HTTPException(status_code=400, detail="Please select a doctor.")
    # Appointment must be in the future — never allow booking in the past.
    if payload.scheduled_at <= datetime.utcnow():
        raise HTTPException(status_code=400, detail="Please select a future date and time.")
    doc = db.query(models.User).filter(models.User.id == payload.doctor_user_id, models.User.role == "doctor").first()
    if doc is None:
        raise HTTPException(status_code=404, detail="Doctor not found.")
    # Prevent duplicate bookings: same patient + doctor + overlapping time
    # with an active (scheduled/confirmed) appointment.
    clash = (
        db.query(models.Appointment)
        .filter(
            models.Appointment.patient_id == current_user.patient_id,
            models.Appointment.doctor_user_id == payload.doctor_user_id,
            models.Appointment.status.in_(("scheduled", "confirmed")),
            models.Appointment.scheduled_at >= payload.scheduled_at - timedelta(minutes=14),
            models.Appointment.scheduled_at <= payload.scheduled_at + timedelta(minutes=14),
        )
        .first()
    )
    if clash is not None:
        raise HTTPException(
            status_code=400,
            detail="You already have an appointment with this doctor at that time. Please pick a different slot.",
        )
    # Pick the hospital: prefer the most recent link between this patient and
    # this doctor. Fall back to any hospital that has the doctor registered.
    # Final fallback: pick any hospital (admin will see the appointment there).
    hospital_id = (
        db.query(models.HospitalRegistrationLink.hospital_id)
        .filter(
            models.HospitalRegistrationLink.user_id == doc.id,
            models.HospitalRegistrationLink.role == "doctor",
        )
        .order_by(models.HospitalRegistrationLink.created_at.desc())
        .first()
    )
    if hospital_id is not None:
        hospital_id = hospital_id[0]
    else:
        # Fallback: first hospital in the system.
        any_hosp = db.query(models.Hospital).order_by(models.Hospital.id.asc()).first()
        if any_hosp is None:
            raise HTTPException(status_code=400, detail="No hospitals exist yet. The hospital admin must register the doctor first.")
        hospital_id = any_hosp.id
    a = models.Appointment(
        hospital_id=hospital_id,
        doctor_user_id=payload.doctor_user_id,
        patient_id=current_user.patient_id,
        scheduled_at=payload.scheduled_at,
        duration_minutes=payload.duration_minutes or 30,
        department=payload.department,
        reason=payload.reason,
        status="scheduled",
        booked_by_patient=True,
        created_by_user_id=current_user.id,
    )
    db.add(a)
    db.flush()
    _enqueue_notification(
        db,
        recipient_user_id=doc.id,
        kind="appointment",            title=f"Appointment request from {current_user.full_name or current_user.username}",
        detail=f"{a.scheduled_at.strftime('%Y-%m-%d %H:%M')}",
        link="dashboard.html",
    )
    _hook_appointment_activity(
        db, a, "appointment_booked", current_user.id, current_user.role,
        f"{current_user.full_name or current_user.username} booked an appointment with {doc.full_name or doc.username}.",
    )
    # Notify the hospital admin(s) at this hospital.
    admins = (
        db.query(models.User)
        .join(models.HospitalProfile, models.HospitalProfile.user_id == models.User.id)
        .filter(models.HospitalProfile.hospital_id == hospital_id)
        .all()
    )
    for admin in admins:
        _enqueue_notification(
            db,
            recipient_user_id=admin.id,
            kind="appointment",
            title="Patient self-booked an appointment",
            detail=f"{current_user.full_name or current_user.username} → Dr. {doc.full_name or doc.username}",
            link="hospital-appointments.html",
        )
    db.commit()
    db.refresh(a)
    return _appointment_to_out(db, a)


@app.post("/doctors/mine/appointments", response_model=schemas.AppointmentOut)
def book_appointment_by_doctor(
    payload: schemas.AppointmentCreateIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Doctor books an appointment for one of their linked patients."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required.")
    pat = db.query(models.Patient).filter(models.Patient.id == payload.patient_id).first()
    if pat is None:
        raise HTTPException(status_code=404, detail="Patient not found.")
    # Find the hospital this doctor is linked to.
    link = (
        db.query(models.HospitalRegistrationLink)
        .filter(
            models.HospitalRegistrationLink.user_id == current_user.id,
            models.HospitalRegistrationLink.role == "doctor",
        )
        .order_by(models.HospitalRegistrationLink.created_at.desc())
        .first()
    )
    if link is None:
        any_hosp = db.query(models.Hospital).order_by(models.Hospital.id.asc()).first()
        if any_hosp is None:
            raise HTTPException(status_code=400, detail="No hospitals found.")
        hospital_id = any_hosp.id
    else:
        hospital_id = link.hospital_id
    a = models.Appointment(
        hospital_id=hospital_id,
        doctor_user_id=current_user.id,
        patient_id=payload.patient_id,
        scheduled_at=payload.scheduled_at,
        duration_minutes=payload.duration_minutes or 30,
        room_number=payload.room_number,
        department=payload.department,
        reason=payload.reason,
        status="scheduled",
        booked_by_patient=False,
        created_by_user_id=current_user.id,
    )
    db.add(a)
    db.flush()
    # Notify patient
    pat_user = db.query(models.User).filter(models.User.patient_id == pat.id).first()
    if pat_user:
        _enqueue_notification(
            db,
            recipient_user_id=pat_user.id,
            kind="appointment",
            title=f"Appointment with Dr. {current_user.full_name or current_user.username}",
            detail=f"{a.scheduled_at.strftime('%Y-%m-%d %H:%M')}",
            link="dashboard.html",
        )
    _hook_appointment_activity(
        db, a, "appointment_booked", current_user.id, current_user.role,
        f"Dr. {current_user.full_name or current_user.username} scheduled an appointment for {pat.name}.",
    )
    db.commit()
    db.refresh(a)
    return _appointment_to_out(db, a)


@app.get("/appointments/mine", response_model=schemas.AppointmentListOut)
def list_my_appointments(
    upcoming: bool = True,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Role-aware listing. Doctor sees doctor_user_id == me; patient sees
    patient_id == mine; hospital admin sees hospital_id == mine."""
    q = db.query(models.Appointment)
    if current_user.role == "doctor":
        q = q.filter(models.Appointment.doctor_user_id == current_user.id)
    elif current_user.role == "patient":
        if not current_user.patient_id:
            return {"items": [], "upcoming_count": 0, "past_count": 0}
        q = q.filter(models.Appointment.patient_id == current_user.patient_id)
    elif current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        q = q.filter(models.Appointment.hospital_id == profile.hospital_id)
    else:
        raise HTTPException(status_code=403, detail="Unsupported role.")
    now = datetime.utcnow()
    upcoming_rows = q.filter(models.Appointment.scheduled_at >= now).order_by(models.Appointment.scheduled_at.asc()).all()
    past_rows = q.filter(models.Appointment.scheduled_at < now).order_by(models.Appointment.scheduled_at.desc()).limit(50).all()
    rows = upcoming_rows if upcoming else past_rows
    return {
        "items": [_appointment_to_out(db, a) for a in rows],
        "upcoming_count": len(upcoming_rows),
        "past_count": len(past_rows),
    }


@app.patch("/appointments/{appointment_id}/status", response_model=schemas.AppointmentOut)
def update_appointment_status(
    appointment_id: int,
    payload: schemas.AppointmentStatusUpdateIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Mark an appointment as completed / cancelled / no_show.
    Hospital admin (must own the appointment's hospital) or the appointment's
    doctor can change status. Patients can only cancel their own."""
    if payload.status not in schemas.ALLOWED_APPOINTMENT_STATUSES:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid status. Must be one of: {sorted(schemas.ALLOWED_APPOINTMENT_STATUSES)}",
        )
    a = db.query(models.Appointment).filter(models.Appointment.id == appointment_id).first()
    if a is None:
        raise HTTPException(status_code=404, detail="Appointment not found.")
    allowed = False
    if current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        if a.hospital_id == profile.hospital_id:
            allowed = True
    elif current_user.role == "doctor" and a.doctor_user_id == current_user.id:
        allowed = True
    elif current_user.role == "patient" and current_user.patient_id == a.patient_id:
        if payload.status in ("cancelled", "completed"):
            allowed = True
    if not allowed:
        raise HTTPException(status_code=403, detail="You cannot change this appointment's status.")
    a.status = payload.status
    a.decided_by_user_id = current_user.id
    # Patient feedback on completion
    if payload.status == "completed" and hasattr(payload, 'feedback') and payload.feedback:
        a.feedback = payload.feedback
    if payload.status == "completed" and hasattr(payload, 'feedback_rating') and payload.feedback_rating:
        a.feedback_rating = payload.feedback_rating
        a.feedback_at = datetime.utcnow()
    a.updated_at = datetime.utcnow()
    _hook_appointment_activity(
        db, a, "appointment_status", current_user.id, current_user.role,
        f"Appointment #{a.id} marked {payload.status.replace('_', ' ')}.",
    )
    db.commit()
    db.refresh(a)
    return _appointment_to_out(db, a)


