@app.post("/hospital/appointments/{appointment_id}/reschedule", response_model=schemas.AppointmentOut)
async def hospital_reschedule_appointment(
    appointment_id: int,
    body: schemas.AppointmentRescheduleIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Reschedule an appointment to a new time."""
    profile = _ensure_hospital_admin(db, current_user)
    a = db.query(models.Appointment).get(appointment_id)
    if not a or a.hospital_id != profile.hospital_id:
        raise HTTPException(404, "Appointment not found")
    if a.status in ("completed", "cancelled", "no_show"):
        raise HTTPException(400, f"Cannot reschedule appointment with status '{a.status}'")
    # Check for conflicts at new time
    dur = body.duration_minutes or a.duration_minutes
    end_time = body.scheduled_at + timedelta(minutes=dur)
    conflict = db.query(models.Appointment).filter(
        models.Appointment.hospital_id == profile.hospital_id,
        models.Appointment.doctor_user_id == a.doctor_user_id,
        models.Appointment.id != a.id,
        models.Appointment.status.in_(["scheduled", "confirmed"]),
        models.Appointment.scheduled_at < end_time,
    ).first()
    if conflict:
        conflict_end = conflict.scheduled_at + timedelta(minutes=conflict.duration_minutes)
        if conflict_end > body.scheduled_at:
            raise HTTPException(409, f"Doctor has a conflicting appointment at {conflict.scheduled_at.strftime('%I:%M %p')}")
    a.scheduled_at = body.scheduled_at
    if body.duration_minutes:
        a.duration_minutes = body.duration_minutes
    a.rescheduled_from = a.id
    db.commit()
    db.refresh(a)
    return _appointment_to_out(db, a)


@app.get("/hospital/appointments/availability")
async def hospital_doctor_availability(
    doctor_user_id: int,
    date: str,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Get available time slots for a doctor on a given date."""
    profile = _ensure_hospital_admin(db, current_user)
    from datetime import date as _date
    try:
        target_date = _date.fromisoformat(date)
    except:
        raise HTTPException(400, "Invalid date format. Use YYYY-MM-DD.")
    day_start = datetime.combine(target_date, datetime.min.time())
    day_end = datetime.combine(target_date, datetime.max.time())
    existing = db.query(models.Appointment).filter(
        models.Appointment.hospital_id == profile.hospital_id,
        models.Appointment.doctor_user_id == doctor_user_id,
        models.Appointment.status.in_(["scheduled", "confirmed"]),
        models.Appointment.scheduled_at >= day_start,
        models.Appointment.scheduled_at <= day_end,
    ).all()
    booked = []
    for a in existing:
        booked.append({
            "start": a.scheduled_at.strftime("%H:%M"),
            "end": (a.scheduled_at + timedelta(minutes=a.duration_minutes)).strftime("%H:%M"),
        })
    # Generate all 30-min slots from 9 AM to 6 PM
    all_slots = []
    for hour in range(9, 18):
        for minute in [0, 30]:
            slot_start = f"{hour:02d}:{minute:02d}"
            slot_end_min = hour * 60 + minute + 30
            slot_end = f"{slot_end_min // 60:02d}:{slot_end_min % 60:02d}"
            is_available = True
            for b in booked:
                if not (slot_end <= b["start"] or slot_start >= b["end"]):
                    is_available = False
                    break
            all_slots.append({"start": slot_start, "end": slot_end, "available": is_available})
    return {"date": date, "doctor_user_id": doctor_user_id, "slots": all_slots, "booked": booked}


@app.get("/hospitals/mine/nurses")
def list_my_nurses(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List all users with role='nurse' for the hospital admin's nurse picker.
    Returns [{user_id, username, full_name, current_patient_count}] so the
    dropdown can flag busy nurses. (We surface the full nurse directory —
    nurses aren't scoped to a single hospital in this v1, so any nurse can
    be assigned to any hospital's patient.)"""
    profile = _ensure_hospital_admin(db, current_user)
    nurses = db.query(models.User).filter(models.User.role == "nurse").all()
    # Compute current assignment count for each nurse.
    active_counts = {}
    for na in (
        db.query(models.NurseAssignment)
        .filter(models.NurseAssignment.is_active == True)  # noqa: E712
        .all()
    ):
        active_counts[na.nurse_user_id] = active_counts.get(na.nurse_user_id, 0) + 1
    items = [
        {
            "user_id": u.id,
            "username": u.username,
            "full_name": u.full_name or u.username,
            "current_patient_count": active_counts.get(u.id, 0),
        }
        for u in nurses
    ]
    # Sort: least-busy first, then by name.
    items.sort(key=lambda x: (x["current_patient_count"], x["full_name"] or ""))
    return {"items": items, "total_count": len(items)}


@app.post("/hospitals/mine/wards/{ward_id}/claim", response_model=schemas.WardOut)
def claim_ward_for_my_hospital(
    ward_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Claim an unassigned ward (hospital_id IS NULL) for the caller's
    hospital. Idempotent: if the ward already belongs to the caller's
    hospital, returns the ward unchanged. Refuses if the ward belongs to
    a different hospital."""
    profile = _ensure_hospital_admin(db, current_user)
    w = db.query(models.Ward).filter(models.Ward.id == ward_id).first()
    if w is None:
        raise HTTPException(status_code=404, detail="Ward not found.")
    if w.hospital_id is not None and w.hospital_id != profile.hospital_id:
        raise HTTPException(
            status_code=409,
            detail="That ward belongs to a different hospital.",
        )
    if w.hospital_id is None:
        w.hospital_id = profile.hospital_id
        db.commit()
        db.refresh(w)
    return _ward_to_out(db, w)


@app.post("/hospitals/mine/wards", response_model=schemas.WardOut)
def create_ward_for_my_hospital(
    payload: schemas.WardCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Create a new ward already-owned by the caller's hospital. Convenience
    over POST /wards + claim — atomic create-and-claim."""
    profile = _ensure_hospital_admin(db, current_user)
    w = models.Ward(
        name=payload.name.strip(),
        ward_type=payload.ward_type,
        daily_rate=payload.daily_rate,
        total_beds=payload.total_beds,
        notes=payload.notes,
        hospital_id=profile.hospital_id,
    )
    db.add(w)
    db.commit()
    db.refresh(w)
    return _ward_to_out(db, w)


# ---------- Doctor → hospital admit requests ----------

def _har_to_out(
    db: Session, r: models.AdmissionRequest, current_user: models.User
) -> schemas.HospitalAdmitRequestOut:
    """Helper: AdmissionRequest row (with request_kind=doctor_to_hospital)
    → HospitalAdmitRequestOut. Joins patient + hospital + doctor names.

    Names are looked up by ID. If the row is missing (e.g. FK was never
    set during a data migration), we fall back to the raw ID so the
    frontend at least has something to render — and we never crash on
    a stale row."""
    patient = db.query(models.Patient).filter(models.Patient.id == r.patient_id).first()
    # Hospital lookup: target_hospital_id is the canonical column for the
    # doctor→hospital flow. Older rows may have a NULL here (legacy
    # patient→doctor flow), so we don't crash on that — we just leave
    # hospital_id and hospital_name as None / 0 and the UI shows "—".
    hospital = None
    if r.target_hospital_id:
        hospital = (
            db.query(models.Hospital)
            .filter(models.Hospital.id == r.target_hospital_id)
            .first()
        )
    doctor = None
    if r.requested_by_doctor_user_id:
        doctor = (
            db.query(models.User)
            .filter(models.User.id == r.requested_by_doctor_user_id)
            .first()
        )
    # Fallbacks: if the join returns nothing (e.g. orphan id from an old
    # test or a manual INSERT), surface the raw id so the user can still
    # tell *something* is wrong instead of seeing a blank row.
    patient_name = patient.name if patient else (f"Patient #{r.patient_id}" if r.patient_id else None)
    hospital_name = hospital.name if hospital else None
    doctor_name = (
        (doctor.full_name or doctor.username) if doctor else None
    )
    return schemas.HospitalAdmitRequestOut(
        id=r.id,
        patient_id=r.patient_id or 0,
        patient_name=patient_name,
        hospital_id=r.target_hospital_id or 0,
        hospital_name=hospital_name,
        requested_by_doctor_user_id=r.requested_by_doctor_user_id or 0,
        requested_by_doctor_name=doctor_name,
        requested_at=r.requested_at,
        status=r.status,
        reason=r.request_reason,
        placed_admission_id=r.placed_admission_id,
        decided_at=r.decided_at,
        decided_by_user_id=r.decided_by_user_id,
    )


def _hospital_admin_user_ids(db: Session, hospital_id: int) -> list[int]:
    """Helper: every user_id that admins the given hospital. Used to fan
    out notifications when an admit request is filed."""
    return [
        hp.user_id
        for hp in db.query(models.HospitalProfile)
        .filter(models.HospitalProfile.hospital_id == hospital_id)
        .all()
    ]


@app.post("/hospital-admit-requests", response_model=schemas.HospitalAdmitRequestOut)
def file_hospital_admit_request(
    payload: schemas.HospitalAdmitRequestCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Doctor files a request to admit a patient to a specific hospital.
    No bed is picked — the hospital admin does that on the place flow.
    Validates: doctor has a PatientDoctorLink for the patient; the
    hospital exists. Notifies every admin of the target hospital."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required.")
    # Ownership: doctor must be linked to the patient.
    if not _doctor_has_patient_link(db, current_user.id, payload.patient_id):
        raise HTTPException(
            status_code=403,
            detail="You are not linked to this patient.",
        )
    hospital = (
        db.query(models.Hospital)
        .filter(models.Hospital.id == payload.hospital_id)
        .first()
    )
    if hospital is None:
        raise HTTPException(status_code=404, detail="Hospital not found.")
    # Idempotency: refuse to file a duplicate pending request.
    existing = (
        db.query(models.AdmissionRequest)
        .filter(
            models.AdmissionRequest.patient_id == payload.patient_id,
            models.AdmissionRequest.target_hospital_id == payload.hospital_id,
            models.AdmissionRequest.request_kind == "doctor_to_hospital",
            models.AdmissionRequest.status == "pending",
        )
        .first()
    )
    if existing is not None:
        raise HTTPException(
            status_code=409,
            detail="A pending request to this hospital for this patient already exists.",
        )
    # 2026-08-17: refuse to file a new request when the patient is already
    # admitted (anywhere — discharged_at IS NULL is the global active
    # signal). The doctor must discharge the patient before re-filing.
    active_admission = (
        db.query(models.Admission)
        .filter(
            models.Admission.patient_id == payload.patient_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if active_admission is not None:
        raise HTTPException(
            status_code=409,
            detail=(
                f"Patient is currently admitted (admission #{active_admission.id}) "
                "and not yet discharged. Please discharge first before filing a new request."
            ),
        )

    r = models.AdmissionRequest(
        patient_id=payload.patient_id,
        # bed_id is NOT NULL on the column but meaningless in the
        # doctor_to_hospital flow (hospital admin picks the bed at place
        # time). Use 0 as a temporary placeholder — it satisfies the NOT
        # NULL constraint and we override it with the row's own id right
        # after the INSERT to dodge the legacy UNIQUE(patient_id, bed_id,
        # status) constraint when multiple requests for the same patient
        # transition out of pending.
        bed_id=0,
        requested_by_user_id=current_user.id,
        requested_at=datetime.utcnow(),
        status="pending",
        request_reason=payload.reason,
        request_kind="doctor_to_hospital",
        target_hospital_id=payload.hospital_id,
        requested_by_doctor_user_id=current_user.id,
    )
    db.add(r)
    db.flush()  # so r.id is populated
    r.bed_id = r.id
    # Notify every hospital admin of the target hospital.
    patient = db.query(models.Patient).filter(models.Patient.id == payload.patient_id).first()
    for admin_id in _hospital_admin_user_ids(db, payload.hospital_id):
        _enqueue_notification(
            db,
            recipient_user_id=admin_id,
            kind="admit_pending_placement",
            title=f"New admit request: {patient.name if patient else 'patient'}",
            detail=f"Dr. {current_user.full_name or current_user.username} is requesting placement at {hospital.name}.",
            link="hospital-admit-queue.html",
        )
    db.commit()
    db.refresh(r)
    return _har_to_out(db, r, current_user)


@app.get("/hospital-admit-requests", response_model=schemas.HospitalAdmitRequestListOut)
def list_hospital_admit_requests(
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Role-scoped:
      - doctor: sees requests they filed.
      - hospital admin: sees requests for their hospital.
      - nurse: sees requests for the hospital they belong to (via a
        NurseAssignment that references an admission — fall back to
        listing all pending across hospitals they could be placed in).
        For v1 nurses see all pending across hospitals for visibility.
    status filter is exact-match; omit to get all statuses."""
    q = db.query(models.AdmissionRequest).filter(
        models.AdmissionRequest.request_kind == "doctor_to_hospital"
    )
    if status:
        q = q.filter(models.AdmissionRequest.status == status)
    if current_user.role == "doctor":
        q = q.filter(
            models.AdmissionRequest.requested_by_doctor_user_id == current_user.id
        )
    elif current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        q = q.filter(models.AdmissionRequest.target_hospital_id == profile.hospital_id)
    elif current_user.role == "nurse":
        # Nurses see all pending across hospitals. Restrict to their
        # assignment hospitals if you want — for v1 a global view is
        # more useful (matches the existing patient-side patterns).
        pass
    else:
        return schemas.HospitalAdmitRequestListOut(items=[], total_count=0)
    rows = q.order_by(models.AdmissionRequest.requested_at.desc()).all()
    items = [_har_to_out(db, r, current_user) for r in rows]
    return schemas.HospitalAdmitRequestListOut(items=items, total_count=len(items))


@app.post("/hospital-admit-requests/{request_id}/cancel", response_model=schemas.HospitalAdmitRequestOut)
def cancel_hospital_admit_request(
    request_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Doctor cancels their own pending request. Only the filing doctor
    can cancel, and only while status=pending."""
    r = (
        db.query(models.AdmissionRequest)
        .filter(
            models.AdmissionRequest.id == request_id,
            models.AdmissionRequest.request_kind == "doctor_to_hospital",
        )
        .first()
    )
    if r is None:
        raise HTTPException(status_code=404, detail="Request not found.")
    if r.requested_by_doctor_user_id != current_user.id:
        raise HTTPException(status_code=403, detail="Only the filing doctor can cancel this request.")
    if r.status != "pending":
        raise HTTPException(
            status_code=409,
            detail=f"Request is already {r.status} — only pending requests can be cancelled.",
        )
    # bed_id is meaningless in this flow but the legacy
    # UNIQUE(patient_id, bed_id, status) constraint fires on UPDATE —
    # use the row's own id as a unique-per-row placeholder so multiple
    # cancelled requests for the same patient don't collide.
    r.bed_id = r.id
    r.status = "cancelled"
    r.decided_at = datetime.utcnow()
    r.decided_by_user_id = current_user.id
    db.commit()
    db.refresh(r)

    # 2026-08: notify every hospital admin at the target hospital that
    # the doctor withdrew their request, so the queue view's bell stays
    # accurate. Skip silently if the request has no target_hospital_id
    # (a back-dated row from before the doctor_to_hospital flow).
    if r.target_hospital_id:
        admins = (
            db.query(models.User)
            .join(
                models.HospitalProfile,
                models.HospitalProfile.user_id == models.User.id,
            )
            .filter(
                models.HospitalProfile.hospital_id == r.target_hospital_id,
                models.User.role == "hospital",
            )
            .all()
        )
        patient = (
            db.query(models.Patient)
            .filter(models.Patient.id == r.patient_id)
            .first()
        )
        patient_name = patient.name if patient else "a patient"
        doctor_name = current_user.full_name or current_user.username
        for admin in admins:
            _enqueue_notification(
                db,
                recipient_user_id=admin.id,
                kind="admit_cancelled",
                title=f"Doctor withdrew admit request for {patient_name}",
                detail=f"{doctor_name} cancelled their pending request.",
                link="hospital-admit-queue.html",
            )
        # Flush so cancelled-request banner can include this event in the
        # admin's next poll without the request handler needing another
        # commit.
        if admins:
            db.commit()

    return _har_to_out(db, r, current_user)


class _BulkDeleteHARIn(BaseModel):
    ids: list[int]


@app.post("/hospital-admit-requests/bulk-delete", response_model=schemas.HospitalAdmitRequestBulkDeleteOut)
def bulk_delete_hospital_admit_requests(
    payload: _BulkDeleteHARIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Doctor hard-deletes terminal-state requests they own (one POST,
    many ids). Pending requests are NOT deleted here — the doctor must
    cancel them via /hospital-admit-requests/{id}/cancel so the hospital
    admin sees the withdrawal notice. Any id not owned by the calling
    doctor, not of kind doctor_to_hospital, or already gone is reported
    back in `skipped_ids` so the UI can show what was actually deleted."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required.")
    if not payload.ids:
        return schemas.HospitalAdmitRequestBulkDeleteOut(deleted_count=0, skipped_ids=[])
    rows = (
        db.query(models.AdmissionRequest)
        .filter(
            models.AdmissionRequest.id.in_(payload.ids),
            models.AdmissionRequest.request_kind == "doctor_to_hospital",
            models.AdmissionRequest.requested_by_doctor_user_id == current_user.id,
        )
        .all()
    )
    matched_ids = {r.id for r in rows}
    skipped: list[int] = []
    deleted = 0
    for r in rows:
        if r.status == "pending":
            skipped.append(r.id)
            continue
        db.delete(r)
        deleted += 1
    db.commit()
    # Surface every input id we couldn't act on (not owned, wrong kind,
    # already deleted, or pending-skipped above) so the UI can tell the
    # doctor exactly what didn't get removed.
    for rid in payload.ids:
        if rid not in matched_ids and rid not in skipped:
            skipped.append(rid)
    return schemas.HospitalAdmitRequestBulkDeleteOut(deleted_count=deleted, skipped_ids=skipped)


# ---------- Hospital admin: place the patient ----------

@app.post("/hospital-admit-requests/{request_id}/place", response_model=schemas.AdmissionOut)
def place_hospital_admit_request(
    request_id: int,
    payload: schemas.PlacementIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Hospital admin picks a free bed in their own hospital. This creates
    the Admission row, sets the request status to 'accepted', and links
    the request to the admission via placed_admission_id. The hospital
    is inferred from the bed's ward. Validates: bed.ward.hospital_id ==
    caller's hospital; bed is free; no other active admission for the
    same patient."""
    profile = _ensure_hospital_admin(db, current_user)
    r = (
        db.query(models.AdmissionRequest)
        .filter(
            models.AdmissionRequest.id == request_id,
            models.AdmissionRequest.request_kind == "doctor_to_hospital",
        )
        .first()
    )
    if r is None:
        raise HTTPException(status_code=404, detail="Request not found.")
    if r.target_hospital_id != profile.hospital_id:
        raise HTTPException(
            status_code=403,
            detail="This request is for a different hospital.",
        )
    if r.status != "pending":
        raise HTTPException(
            status_code=409,
            detail=f"Request is {r.status} — only pending requests can be placed.",
        )

    # Validate bed ownership and free-status.
    bed = db.query(models.Bed).filter(models.Bed.id == payload.bed_id).first()
    if bed is None:
        raise HTTPException(status_code=404, detail="Bed not found.")
    ward = db.query(models.Ward).filter(models.Ward.id == bed.ward_id).first()
    if ward is None or ward.hospital_id != profile.hospital_id:
        raise HTTPException(
            status_code=403,
            detail="That bed belongs to a different hospital.",
        )
    occupied = (
        db.query(models.Admission)
        .filter(
            models.Admission.bed_id == bed.id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if occupied is not None:
        raise HTTPException(
            status_code=409,
            detail="That bed is already occupied.",
        )

    # Patient must not have another active admission.
    other_active = (
        db.query(models.Admission)
        .filter(
            models.Admission.patient_id == r.patient_id,
            models.Admission.discharged_at.is_(None),
        )
        .first()
    )
    if other_active is not None:
        raise HTTPException(
            status_code=409,
            detail="This patient already has an active admission. Discharge it first.",
        )

    # Create the Admission row. The doctor who filed the request is
    # recorded as admitted_by so the notes-edit guard and the discharge
    # appeal's doctor step both point at the right person. The hospital
    # is inferred from the bed's ward (no separate hospital pick needed).
    a = models.Admission(
        patient_id=r.patient_id,
        bed_id=bed.id,
        admitted_by=r.requested_by_doctor_user_id,
        admitted_at=datetime.utcnow(),
        ward_id_at_admit=ward.id,
        hospital_id=profile.hospital_id,
        notes=payload.notes,
    )
    db.add(a)
    db.flush()  # so a.id is populated

    # Mark the request accepted and back-link to the admission.
    # bed_id stays at the per-row unique value set at create time —
    # the legacy UNIQUE(patient_id, bed_id, status) constraint would
    # otherwise collide on UPDATE when multiple doctor_to_hospital
    # requests for the same patient reach status='accepted'.
    r.status = "accepted"
    r.decided_at = datetime.utcnow()
    r.decided_by_user_id = current_user.id
    r.placed_admission_id = a.id

    # Notify the filing doctor that the patient has been placed.
    patient = db.query(models.Patient).filter(models.Patient.id == r.patient_id).first()
    if r.requested_by_doctor_user_id:
        _enqueue_notification(
            db,
            recipient_user_id=r.requested_by_doctor_user_id,
            kind="admit_placed",
            title=f"Patient placed: {patient.name if patient else 'patient'}",
            detail=(
                f"{current_user.full_name or current_user.username} placed the patient in bed "
                f"{bed.bed_number} ({ward.name})."
            ),
            link="dashboard.html",
        )

    # Optional: assign a nurse at placement time. If the caller passed
    # nurse_user_id, deactivate any existing active assignment for this
    # patient (regardless of which hospital issued it) and create a fresh
    # one pointing at this admission. Nurses are looked up by role='nurse'
    # so a stray doctor/hospital-admin id fails with a clear 400.
    if payload.nurse_user_id is not None:
        nurse = (
            db.query(models.User)
            .filter(models.User.id == payload.nurse_user_id, models.User.role == "nurse")
            .first()
        )
        if nurse is None:
            raise HTTPException(
                status_code=400,
                detail="nurse_user_id does not refer to a user with role='nurse'.",
            )
        # Clear any existing active assignment for this patient. We DELETE rather
        # than flip is_active=1→0 because the legacy table-level UNIQUE
        # constraint on (patient_id, nurse_user_id, is_active) (still
        # present in old DBs) makes a deactivate + insert impossible
        # without an immediate unique-pair collision. Deleting the prior
        # active row and committing leaves the table in a state where the
        # INSERT below can proceed regardless of which UNIQUE flavor the
        # DB has. Audit trail is preserved in the admission's
        # ``notes``/notifications instead.
        from sqlalchemy import text as _sa_text
        db.execute(
            _sa_text(
                "DELETE FROM nurse_assignments "
                "WHERE patient_id = :pid AND is_active = 1"
            ),
            {"pid": r.patient_id},
        )
        db.commit()

        na = models.NurseAssignment(
            patient_id=r.patient_id,
            nurse_user_id=nurse.id,
            assigned_by_user_id=current_user.id,
            assigned_at=datetime.utcnow(),
            is_active=True,
            notes=None,
        )
        db.add(na)
        db.flush()
        _enqueue_notification(
            db,
            recipient_user_id=nurse.id,
            kind="nurse_assigned",
            title=f"New patient assigned: {patient.name if patient else 'patient'}",
            detail=(
                f"{current_user.full_name or current_user.username} assigned you to "
                f"{patient.name if patient else 'a patient'} in bed {bed.bed_number} ({ward.name})."
            ),
            link="nurse-dashboard.html",
        )

    db.commit()
    db.refresh(a)
    return _admission_to_out(db, a)


# ---------- Nurse assignment (post-placement adjustments) ----------

def _na_to_out(
    db: Session, na: models.NurseAssignment
) -> schemas.NurseAssignmentOut:
    """Helper: NurseAssignment row → NurseAssignmentOut. Joins nurse + assigner + patient names."""
    nurse = db.query(models.User).filter(models.User.id == na.nurse_user_id).first()
    patient = db.query(models.Patient).filter(models.Patient.id == na.patient_id).first()
    assigner = (
        db.query(models.User).filter(models.User.id == na.assigned_by_user_id).first()
        if na.assigned_by_user_id else None
    )
    return schemas.NurseAssignmentOut(
        id=na.id,
        patient_id=na.patient_id,
        patient_name=patient.name if patient else None,
        nurse_user_id=na.nurse_user_id,
        nurse_name=(nurse.full_name or nurse.username) if nurse else None,
        assigned_by_user_id=na.assigned_by_user_id,
        assigned_by_name=(
            (assigner.full_name or assigner.username) if assigner else None
        ),
        assigned_at=na.assigned_at,
        is_active=na.is_active,
        notes=na.notes,
    )


@app.post("/admissions/{admission_id}/nurse", response_model=schemas.NurseAssignmentOut)
def assign_nurse(
    admission_id: int,
    payload: schemas.NurseAssignmentCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Hospital admin assigns (or replaces) the nurse for an admission.
    Deactivates any existing active assignment for the same patient."""
    _admission_belongs_to_hospital(db, current_user, admission_id)
    nurse = (
        db.query(models.User)
        .filter(models.User.id == payload.nurse_user_id, models.User.role == "nurse")
        .first()
    )
    if nurse is None:
        raise HTTPException(status_code=404, detail="That user is not a registered nurse.")
    adm = db.query(models.Admission).filter(models.Admission.id == admission_id).first()

    # Clear prior active assignments for this patient. We DELETE rather than
    # flip is_active=1→0 because the legacy table-level UNIQUE constraint
    # on (patient_id, nurse_user_id, is_active) (still present in old DBs)
    # makes a deactivate + insert impossible without an immediate
    # unique-pair collision. Audit trail for the swap is preserved in
    # notifications (new nurse + admitting doctor both get an event).
    from sqlalchemy import text as _sa_text
    db.execute(
        _sa_text(
            "DELETE FROM nurse_assignments "
            "WHERE patient_id = :pid AND is_active = 1"
        ),
        {"pid": adm.patient_id},
    )
    db.commit()

    na = models.NurseAssignment(
        patient_id=adm.patient_id,
        nurse_user_id=nurse.id,
        assigned_by_user_id=current_user.id,
        assigned_at=datetime.utcnow(),
        is_active=True,
        notes=payload.notes,
    )
    db.add(na)
    # Notify nurse + the admitting doctor.
    patient = db.query(models.Patient).filter(models.Patient.id == adm.patient_id).first()
    _enqueue_notification(
        db,
        recipient_user_id=nurse.id,
        kind="nurse_assigned",
        title=f"New patient: {patient.name if patient else 'patient'}",
        detail=f"You've been assigned to {patient.name if patient else 'a patient'}.",
        link="nurse-dashboard.html",
    )
    if adm.admitted_by:
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_assigned",
            title=f"Nurse updated for {patient.name if patient else 'patient'}",
            detail=f"{nurse.full_name or nurse.username} is now responsible for this patient.",
            link="dashboard.html",
        )
    db.commit()
    db.refresh(na)
    return _na_to_out(db, na)


@app.delete("/admissions/{admission_id}/nurse")
def unassign_nurse(
    admission_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Hospital admin deactivates the current active nurse assignment."""
    _admission_belongs_to_hospital(db, current_user, admission_id)
    adm = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    # DELETE rather than flip is_active=1→0: the legacy table-level UNIQUE
    # constraint on (patient_id, nurse_user_id, is_active) would conflict
    # if an inactive row already exists for the same pair (which is common
    # in production data from earlier transitions). DELETE leaves the
    # partial unique index satisfied and is the right semantic anyway —
    # unassigning permanently removes the nurse for this patient.
    from sqlalchemy import text as _sa_text
    result = db.execute(
        _sa_text(
            "DELETE FROM nurse_assignments "
            "WHERE patient_id = :pid AND is_active = 1"
        ),
        {"pid": adm.patient_id},
    )
    db.commit()
    return {"message": "Nurse unassigned.", "deactivated": result.rowcount}


@app.post(
    "/admissions/{admission_id}/transfer-nurse",
    response_model=schemas.TransferNurseOut,
)
def transfer_nurse(
    admission_id: int,
    payload: schemas.TransferNurseIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Currently-assigned nurse transfers the patient to another nurse at
    the same hospital. Same access gate as ``_admission_for_nurse`` — only
    the active nurse can initiate, and the destination nurse must belong
    to the same hospital as the admission. Uses the DELETE-then-INSERT
    pattern from ``assign_nurse`` to sidestep the legacy table-level
    UNIQUE constraint on (patient_id, nurse_user_id, is_active).

    Fires:
      * ``nurse_assigned``     → new nurse
      * ``nurse_transferred_away`` → old (current_user) nurse
    """
    adm = _admission_for_nurse(db, current_user, admission_id)
    if adm.hospital_id is None:
        raise HTTPException(
            status_code=409,
            detail="This admission isn't tied to a hospital yet, so a transfer "
                   "across nurses isn't possible. Use Unassign/Reassign instead.",
        )

    new_nurse = (
        db.query(models.User)
        .filter(
            models.User.id == payload.new_nurse_user_id,
            models.User.role == "nurse",
        )
        .first()
    )
    if new_nurse is None:
        raise HTTPException(
            status_code=404,
            detail="That user is not a registered nurse.",
        )
    if new_nurse.id == current_user.id:
        raise HTTPException(
            status_code=400,
            detail="You're already the assigned nurse for this patient.",
        )

    # Destination nurse must already have a footprint at the same
    # hospital as the admission. We allow transfer if ANY of these hold:
    #   (a) the destination nurse has had a NurseAssignment at this
    #       hospital before, OR
    #   (b) the destination nurse IS the currently active nurse on the
    #       source admin's hospital membership (list_my_nurses() returns
    #       them as eligible).
    # Nurses don't have HospitalProfile rows in v1 (they're scoped via
    # assignments). We surface them all in /hospitals/mine/nurses because
    # the admin picks them at place-time anyway; treating that list as
    # "members of this hospital" for transfer purposes keeps the surface
    # small without a separate membership table.
    same_hospital_before = (
        db.query(models.NurseAssignment)
        .join(models.Admission, models.Admission.patient_id == models.NurseAssignment.patient_id)
        .filter(
            models.NurseAssignment.nurse_user_id == new_nurse.id,
            models.Admission.hospital_id == adm.hospital_id,
        )
        .first()
    )
    if same_hospital_before is None and adm.hospital_id is not None:
        # Fallback: is this nurse already "reachable" from this hospital?
        # The hospital admin's /hospitals/mine/nurses endpoint returns ALL
        # role='nurse' users as the picking set; treating that whole set
        # as in-scope for transfers matches existing behaviour without
        # introducing a new membership table.
        # Distinguish cross-hospital by checking whether the destination
        # nurse has assignments at a *different* hospital (active).
        cross = (
            db.query(models.NurseAssignment)
            .join(models.Admission, models.Admission.patient_id == models.NurseAssignment.patient_id)
            .filter(
                models.NurseAssignment.nurse_user_id == new_nurse.id,
                models.Admission.hospital_id != adm.hospital_id,
                models.NurseAssignment.is_active == True,  # noqa: E712
            )
            .first()
        )
        if cross is not None:
            raise HTTPException(
                status_code=403,
                detail="That nurse is assigned to a different hospital.",
            )

    # DELETE prior active assignment (avoids UNIQUE collision). Then
    # fresh INSERT. Mirror the assign_nurse pattern exactly.
    from sqlalchemy import text as _sa_text
    db.execute(
        _sa_text(
            "DELETE FROM nurse_assignments "
            "WHERE patient_id = :pid AND is_active = 1"
        ),
        {"pid": adm.patient_id},
    )
    db.commit()

    na = models.NurseAssignment(
        patient_id=adm.patient_id,
        nurse_user_id=new_nurse.id,
        assigned_by_user_id=current_user.id,
        assigned_at=datetime.utcnow(),
        is_active=True,
        notes=payload.reason,
    )
    db.add(na)
    db.flush()

    patient = (
        db.query(models.Patient)
        .filter(models.Patient.id == adm.patient_id)
        .first()
    )
    patient_name = patient.name if patient else "patient"

    # Notify the new nurse.
    _enqueue_notification(
        db,
        recipient_user_id=new_nurse.id,
        kind="nurse_assigned",
        title=f"New patient via transfer: {patient_name}",
        detail=(
            f"{current_user.full_name or current_user.username} transferred "
            f"{patient_name} to you."
            + (f" Reason: {payload.reason}" if payload.reason else "")
        ),
        link="nurse-dashboard.html",
    )

    # Notify the OLD nurse (current_user) that they're now off the case.
    # Skip if current_user happens to be the patient themselves (shouldn't
    # happen — _admission_for_nurse enforces role='nurse').
    if current_user.id != new_nurse.id:
        _enqueue_notification(
            db,
            recipient_user_id=current_user.id,
            kind="nurse_transferred_away",
            title=f"Patient transferred away: {patient_name}",
            detail=(
                f"You transferred {patient_name} to "
                f"{new_nurse.full_name or new_nurse.username}."
            ),
            link="nurse-dashboard.html",
        )

    # Also let the admitting doctor know the case moved.
    if adm.admitted_by:
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_assigned",
            title=f"Nurse changed for {patient_name}",
            detail=(
                f"{current_user.full_name or current_user.username} → "
                f"{new_nurse.full_name or new_nurse.username}."
            ),
            link="dashboard.html",
        )

    db.commit()
    db.refresh(na)

    return schemas.TransferNurseOut(
        admission_id=adm.id,
        patient_id=adm.patient_id,
        old_nurse_user_id=current_user.id,
        new_assignment=_na_to_out(db, na),
        reason=payload.reason,
    )


@app.post("/admissions/{admission_id}/send-back-to-hospital")
def send_back_to_hospital(
    admission_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Currently-assigned nurse returns the patient to the hospital pool —
    the active assignment is cleared and every hospital admin at the
    admission's hospital gets a ``patient_needs_new_nurse`` notification
    so one of them can pick a new nurse via the dashboard's
    "+ Add nurse" action.

    Same access gate as the transfer endpoint: only the active nurse can
    initiate. Removes the nurse assignment via DELETE (works around the
    legacy UNIQUE constraint the same way ``unassign_nurse`` does).
    """
    adm = _admission_for_nurse(db, current_user, admission_id)
    if adm.hospital_id is None:
        raise HTTPException(
            status_code=409,
            detail="This admission isn't tied to a hospital — nothing to send back.",
        )

    patient = (
        db.query(models.Patient)
        .filter(models.Patient.id == adm.patient_id)
        .first()
    )
    patient_name = patient.name if patient else "a patient"

    # Clear the active assignment (DELETE — same UNIQUE workaround).
    from sqlalchemy import text as _sa_text
    db.execute(
        _sa_text(
            "DELETE FROM nurse_assignments "
            "WHERE patient_id = :pid AND is_active = 1"
        ),
        {"pid": adm.patient_id},
    )
    db.commit()

    # Fan out a notification to every hospital admin at this hospital.
    admins = (
        db.query(models.User)
        .join(
            models.HospitalProfile,
            models.HospitalProfile.user_id == models.User.id,
        )
        .filter(
            models.HospitalProfile.hospital_id == adm.hospital_id,
            models.User.role == "hospital",
        )
        .all()
    )
    for admin in admins:
        _enqueue_notification(
            db,
            recipient_user_id=admin.id,
            kind="patient_needs_new_nurse",
            title=f"Nurse handed back: {patient_name}",
            detail=(
                f"{current_user.full_name or current_user.username} returned "
                f"this patient. Please allot a new nurse."
            ),
            link="hospital-dashboard.html",
        )
    if admins:
        db.commit()

    # Let the admitting doctor know the patient is unstaffed.
    if adm.admitted_by:
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_assigned",
            title=f"Nurse removed for {patient_name}",
            detail=(
                f"{current_user.full_name or current_user.username} sent "
                f"this patient back to the hospital for re-allotment."
            ),
            link="dashboard.html",
        )
        db.commit()

    return {
        "message": "Patient returned to the hospital pool.",
        "admission_id": adm.id,
        "patient_id": adm.patient_id,
        "patient_name": patient_name,
        "notified_admins": len(admins),
    }


@app.get("/admissions/{admission_id}/nurse", response_model=schemas.NurseAssignmentOut)
def get_admission_nurse(
    admission_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Return the active nurse assignment for an admission, or 404."""
    adm = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    if adm is None:
        raise HTTPException(status_code=404, detail="Admission not found.")
    na = (
        db.query(models.NurseAssignment)
        .filter(
            models.NurseAssignment.patient_id == adm.patient_id,
            models.NurseAssignment.is_active == True,  # noqa: E712
        )
        .first()
    )
    if na is None:
        raise HTTPException(status_code=404, detail="No active nurse assignment.")
    return _na_to_out(db, na)


@app.get("/nurse/patients", response_model=schemas.NurseAssignmentListOut)
def list_nurse_patients(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List patients currently assigned to the calling nurse. Includes
    inactive assignments ordered newest-first so a nurse who just had
    a patient reassigned still sees the history."""
    _ensure_nurse(current_user)
    rows = (
        db.query(models.NurseAssignment)
        .filter(models.NurseAssignment.nurse_user_id == current_user.id)
        .order_by(
            models.NurseAssignment.is_active.desc(),
            models.NurseAssignment.assigned_at.desc(),
        )
        .all()
    )
    items = [_na_to_out(db, r) for r in rows]
    return schemas.NurseAssignmentListOut(items=items, total_count=len(items))


@app.get("/nurse/patients/active", response_model=schemas.NursePatientListOut)
def list_nurse_patients_active(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Return the calling nurse's currently assigned patients with their
    active admission + bed/ward/hospital context. Distinct from
    /nurse/patients which returns the raw assignment rows (history)."""
    _ensure_nurse(current_user)
    active_rows = (
        db.query(models.NurseAssignment)
        .filter(
            models.NurseAssignment.nurse_user_id == current_user.id,
            models.NurseAssignment.is_active == True,  # noqa: E712
        )
        .all()
    )
    items: list[schemas.NursePatientOut] = []
    for na in active_rows:
        # Convert the Patient ORM row to PatientOut via the existing
        # batch helper so linked_doctors stays consistent with the rest
        # of the API.
        patient = db.query(models.Patient).filter(models.Patient.id == na.patient_id).first()
        if patient is None:
            continue
        [p_out] = _attach_patient_links(db, [patient])
        # Find the active admission (the only one we'd ever want here).
        adm = (
            db.query(models.Admission)
            .filter(
                models.Admission.patient_id == patient.id,
                models.Admission.discharged_at.is_(None),
            )
            .first()
        )
        bed_number = ward_name = hospital_name = None
        admitted_at = None
        admission_id = None
        admitting_doctor_user_id = None
        admitting_doctor_name = None
        if adm is not None:
            admission_id = adm.id
            admitted_at = adm.admitted_at
            admitting_doctor_user_id = adm.admitted_by
            if adm.admitted_by:
                doc_user = db.query(models.User).filter(models.User.id == adm.admitted_by).first()
                if doc_user:
                    admitting_doctor_name = doc_user.full_name or doc_user.username
            bed = db.query(models.Bed).filter(models.Bed.id == adm.bed_id).first()
            if bed:
                bed_number = bed.bed_number
                ward = db.query(models.Ward).filter(models.Ward.id == bed.ward_id).first()
                if ward:
                    ward_name = ward.name
            if adm.hospital_id:
                h = db.query(models.Hospital).filter(models.Hospital.id == adm.hospital_id).first()
                if h:
                    hospital_name = h.name
        items.append(schemas.NursePatientOut(
            patient=p_out,
            admission_id=admission_id,
            bed_number=bed_number,
            ward_name=ward_name,
            hospital_name=hospital_name,
            admitted_at=admitted_at,
            nurse_assignment_id=na.id,
            admitting_doctor_user_id=admitting_doctor_user_id,
            admitting_doctor_name=admitting_doctor_name,
        ))
    return schemas.NursePatientListOut(items=items, total_count=len(items))


@app.get("/nurse/patients/history", response_model=schemas.NursePatientListOut)
def list_nurse_patients_history(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Return the calling nurse's PAST patients — i.e. ones whose latest
    admission is now discharged. Mirrors /nurse/patients/active but for
    discharged assignments; used by the nurse page "Discharged patients"
    card so the nurse can see who they used to care for and when."""
    _ensure_nurse(current_user)
    rows = (
        db.query(models.NurseAssignment)
        .filter(models.NurseAssignment.nurse_user_id == current_user.id)
        .order_by(models.NurseAssignment.assigned_at.desc())
        .all()
    )
    items: list[schemas.NursePatientOut] = []
    seen: set[int] = set()
    for na in rows:
        if na.patient_id in seen:
            continue
        # Latest admission for this patient (any status).
        adm = (
            db.query(models.Admission)
            .filter(models.Admission.patient_id == na.patient_id)
            .order_by(models.Admission.admitted_at.desc())
            .first()
        )
        # Only discharged patients belong here.
        if adm is None or adm.discharged_at is None:
            continue
        seen.add(na.patient_id)
        patient = db.query(models.Patient).filter(models.Patient.id == na.patient_id).first()
        if patient is None:
            continue
        [p_out] = _attach_patient_links(db, [patient])
        bed_number = ward_name = hospital_name = None
        admitting_doctor_user_id = adm.admitted_by
        admitting_doctor_name = None
        if adm.admitted_by:
            doc_user = db.query(models.User).filter(models.User.id == adm.admitted_by).first()
            if doc_user:
                admitting_doctor_name = doc_user.full_name or doc_user.username
        bed = db.query(models.Bed).filter(models.Bed.id == adm.bed_id).first()
        if bed:
            bed_number = bed.bed_number
            ward = db.query(models.Ward).filter(models.Ward.id == bed.ward_id).first()
            if ward:
                ward_name = ward.name
        if adm.hospital_id:
            h = db.query(models.Hospital).filter(models.Hospital.id == adm.hospital_id).first()
            if h:
                hospital_name = h.name
        items.append(schemas.NursePatientOut(
            patient=p_out,
            admission_id=adm.id,
            bed_number=bed_number,
            ward_name=ward_name,
            hospital_name=hospital_name,
            admitted_at=adm.admitted_at,
            nurse_assignment_id=na.id,
            admitting_doctor_user_id=admitting_doctor_user_id,
            admitting_doctor_name=admitting_doctor_name,
            discharged_at=adm.discharged_at,
        ))
    return schemas.NursePatientListOut(items=items, total_count=len(items))


# ---------- Nurse dashboard stats ----------

@app.get("/nurse/dashboard-stats")
def nurse_dashboard_stats(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Aggregate statistics for the nurse dashboard KPI cards."""
    _ensure_nurse(current_user)
    active_rows = (
        db.query(models.NurseAssignment)
        .filter(
            models.NurseAssignment.nurse_user_id == current_user.id,
            models.NurseAssignment.is_active == True,
        ).all()
    )
    total_patients = len(active_rows)
    patient_ids = [na.patient_id for na in active_rows]
    admissions = []
    for pid in patient_ids:
        adm = (
            db.query(models.Admission)
            .filter(
                models.Admission.patient_id == pid,
                models.Admission.discharged_at.is_(None),
            ).first()
        )
        if adm:
            admissions.append(adm)
    # Count nurse notes today
    today_start = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    notes_today = (
        db.query(models.NurseNote)
        .filter(
            models.NurseNote.author_user_id == current_user.id,
            models.NurseNote.created_at >= today_start,
        ).count()
    )
    # Count pending medications (from admissions)
    pending_meds = 0
    pending_treatments = 0
    for adm in admissions:
        meds = (
            db.query(models.Medication)
            .filter(models.Medication.admission_id == adm.id)
            .all()
        )
        pending_meds += sum(1 for m in meds if getattr(m, 'status', '') != 'completed')
        treats = (
            db.query(models.Treatment)
            .filter(models.Treatment.admission_id == adm.id)
            .all()
        )
        pending_treatments += sum(1 for t in treats if getattr(t, 'status', '') != 'completed')
    # Discharged patients count
    discharged_count = (
        db.query(models.NurseAssignment)
        .filter(models.NurseAssignment.nurse_user_id == current_user.id)
        .count()
    ) - total_patients
    # Vital warnings: count patients with recent abnormal vitals
    vital_warnings = 0
    attention_patients = 0
    for na in active_rows:
        adm = (
            db.query(models.Admission)
            .filter(models.Admission.patient_id == na.patient_id, models.Admission.discharged_at.is_(None))
            .first()
        )
        if not adm:
            continue
        latest_note = (
            db.query(models.NurseNote)
            .filter(
                models.NurseNote.admission_id == adm.id,
                models.NurseNote.category == 'vitals',
            )
            .order_by(models.NurseNote.created_at.desc())
            .first()
        )
        if latest_note and latest_note.note:
            note_lower = latest_note.note.lower()
            # Simple heuristic for vital warnings
            warning_keywords = ['abnormal', 'high', 'low', 'critical', 'elevated', 'decreased', 'warning', 'alert']
            if any(kw in note_lower for kw in warning_keywords):
                vital_warnings += 1
            elif any(kw in note_lower for kw in ['critical', 'emergency', 'severe', 'urgent']):
                attention_patients += 1

    return {
        "total_patients": total_patients,
        "critical_patients": 0,
        "attention_patients": attention_patients,
        "today_tasks": notes_today,
        "pending_treatments": pending_treatments,
        "pending_medications": pending_meds,
        "pending_vitals": total_patients,
        "notes_today": notes_today,
        "discharged_patients": discharged_count,
        "vital_warnings": vital_warnings,
    }


# ---------- Nurse KPI analytics ----------

@app.get("/nurse/kpi-analytics")
def nurse_kpi_analytics(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Return detailed analytics data for each KPI card on the nurse dashboard.
    Provides per-KPI breakdown, trend data (last 7 days), and chart-ready data."""
    _ensure_nurse(current_user)
    today = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    seven_days_ago = today - timedelta(days=6)

    # --- Active assignments ---
    active_rows = (
        db.query(models.NurseAssignment)
        .filter(
            models.NurseAssignment.nurse_user_id == current_user.id,
            models.NurseAssignment.is_active == True,
        ).all()
    )
    active_count = len(active_rows)
    patient_ids = [na.patient_id for na in active_rows]

    # Discharged count
    all_assignments = (
        db.query(models.NurseAssignment)
        .filter(models.NurseAssignment.nurse_user_id == current_user.id)
        .all()
    )
    discharged_count = len(all_assignments) - active_count

    # Daily assignment trend (last 7 days)
    assignment_trend = []
    for i in range(7):
        day = seven_days_ago + timedelta(days=i)
        day_start = day.replace(hour=0, minute=0, second=0, microsecond=0)
        day_end = day_start + timedelta(days=1)
        count = (
            db.query(models.NurseAssignment)
            .filter(
                models.NurseAssignment.nurse_user_id == current_user.id,
                models.NurseAssignment.assigned_at >= day_start,
                models.NurseAssignment.assigned_at < day_end,
            ).count()
        )
        assignment_trend.append({
            'date': day.strftime('%b %d'),
            'count': count,
        })

    # --- Attention / critical patients ---
    attention_patients = 0
    critical_patients = 0
    attention_details = []
    for na in active_rows:
        adm = (
            db.query(models.Admission)
            .filter(models.Admission.patient_id == na.patient_id, models.Admission.discharged_at.is_(None))
            .first()
        )
        if not adm:
            continue
        latest_note = (
            db.query(models.NurseNote)
            .filter(
                models.NurseNote.admission_id == adm.id,
                models.NurseNote.category == 'vitals',
            )
            .order_by(models.NurseNote.created_at.desc())
            .first()
        )
        if latest_note and latest_note.note:
            note_lower = latest_note.note.lower()
            if any(kw in note_lower for kw in ['critical', 'emergency', 'severe', 'urgent']):
                critical_patients += 1
                patient = db.query(models.User).filter(models.User.id == na.patient_id).first()
                attention_details.append({
                    'patient_name': patient.full_name or patient.username if patient else 'Patient',
                    'reason': 'Critical vital detected',
                    'level': 'critical',
                })
            elif any(kw in note_lower for kw in ['abnormal', 'high', 'low', 'elevated', 'decreased', 'warning', 'alert']):
                attention_patients += 1
                patient = db.query(models.User).filter(models.User.id == na.patient_id).first()
                attention_details.append({
                    'patient_name': patient.full_name or patient.username if patient else 'Patient',
                    'reason': 'Abnormal vital reading',
                    'level': 'attention',
                })

    # --- Care tasks ---
    pending_meds = 0
    completed_meds = 0
    pending_treatments = 0
    completed_treatments = 0
    for adm_id in [na.admission_id if hasattr(na, 'admission_id') else (
        db.query(models.Admission.id).filter(
            models.Admission.patient_id == na.patient_id, models.Admission.discharged_at.is_(None)
        ).scalar()
    ) for na in active_rows]:
        if not adm_id:
            continue
        meds = db.query(models.Medication).filter(models.Medication.admission_id == adm_id).all()
        pending_meds += sum(1 for m in meds if m.status != 'completed')
        completed_meds += sum(1 for m in meds if m.status == 'completed')
        treats = db.query(models.Treatment).filter(models.Treatment.admission_id == adm_id).all()
        pending_treatments += sum(1 for t in treats if t.status not in ('completed', 'cancelled'))
        completed_treatments += sum(1 for t in treats if t.status == 'completed')

    # Daily task trend (last 7 days)
    task_trend = []
    for i in range(7):
        day = seven_days_ago + timedelta(days=i)
        day_start = day.replace(hour=0, minute=0, second=0, microsecond=0)
        day_end = day_start + timedelta(days=1)
        notes_count = (
            db.query(models.NurseNote)
            .filter(
                models.NurseNote.author_user_id == current_user.id,
                models.NurseNote.created_at >= day_start,
                models.NurseNote.created_at < day_end,
            ).count()
        )
        task_trend.append({
            'date': day.strftime('%b %d'),
            'notes': notes_count,
        })

    # --- Vital warnings ---
    vital_warnings = 0
    vital_normal = 0
    vital_categories = {'temperature': 0, 'blood_pressure': 0, 'heart_rate': 0, 'spo2': 0, 'other': 0}
    for na in active_rows:
        adm = (
            db.query(models.Admission)
            .filter(models.Admission.patient_id == na.patient_id, models.Admission.discharged_at.is_(None))
            .first()
        )
        if not adm:
            continue
        latest_note = (
            db.query(models.NurseNote)
            .filter(
                models.NurseNote.admission_id == adm.id,
                models.NurseNote.category == 'vitals',
            )
            .order_by(models.NurseNote.created_at.desc())
            .first()
        )
        if latest_note and latest_note.note:
            note_lower = latest_note.note.lower()
            if any(kw in note_lower for kw in ['abnormal', 'high', 'low', 'critical', 'elevated', 'decreased', 'warning', 'alert']):
                vital_warnings += 1
                # Categorize
                if 'temperature' in note_lower or 'fever' in note_lower:
                    vital_categories['temperature'] += 1
                elif 'blood pressure' in note_lower or 'bp' in note_lower:
                    vital_categories['blood_pressure'] += 1
                elif 'heart rate' in note_lower or 'pulse' in note_lower:
                    vital_categories['heart_rate'] += 1
                elif 'spo2' in note_lower or 'oxygen' in note_lower:
                    vital_categories['spo2'] += 1
                else:
                    vital_categories['other'] += 1
            else:
                vital_normal += 1
        else:
            vital_normal += 1

    return {
        'my_patients': {
            'active': active_count,
            'discharged': discharged_count,
            'trend': assignment_trend,
        },
        'need_attention': {
            'total': attention_patients + critical_patients,
            'critical': critical_patients,
            'attention': attention_patients,
            'details': attention_details[:10],
        },
        'care_tasks': {
            'pending_meds': pending_meds,
            'completed_meds': completed_meds,
            'pending_treatments': pending_treatments,
            'completed_treatments': completed_treatments,
            'trend': task_trend,
        },
        'vital_warning': {
            'warnings': vital_warnings,
            'normal': vital_normal,
            'categories': vital_categories,
        },
    }


# ---------- Nurse recent activity feed ----------

@app.get("/nurse/recent-activity")
def nurse_recent_activity(
    limit: int = 20,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Return recent activity events relevant to this nurse.
    Events include: nurse notes, vital records, medication changes,
    treatment updates, doctor messages, notifications, and admission
    status changes. Ordered by most recent first."""
    _ensure_nurse(current_user)
    events = []
    # Active admissions for this nurse
    active_rows = (
        db.query(models.NurseAssignment)
        .filter(
            models.NurseAssignment.nurse_user_id == current_user.id,
            models.NurseAssignment.is_active == True,
        ).all()
    )
    admission_ids = []
    patient_map = {}
    for na in active_rows:
        adm = (
            db.query(models.Admission)
            .filter(models.Admission.patient_id == na.patient_id, models.Admission.discharged_at.is_(None))
            .first()
        )
        if adm:
            admission_ids.append(adm.id)
            patient = db.query(models.User).filter(models.User.id == na.patient_id).first()
            patient_map[na.patient_id] = patient.full_name or patient.username if patient else 'Patient'

    # Recent nurse notes
    for note in (
        db.query(models.NurseNote)
        .filter(models.NurseNote.author_user_id == current_user.id)
        .order_by(models.NurseNote.created_at.desc())
        .limit(10)
        .all()
    ):
        pname = patient_map.get(
            (db.query(models.Admission.patient_id).filter(models.Admission.id == note.admission_id).scalar()),
            'Patient'
        )
        category = note.category or 'note'
        is_report = getattr(note, 'sent_to_doctor', False)
        events.append({
            'id': f'note-{note.id}',
            'type': 'report' if is_report else category,
            'title': f'{category.replace("_", " ").title()} recorded' if not is_report else 'Report sent to doctor',
            'patient': pname,
            'detail': (note.note or '')[:120],
            'timestamp': str(note.created_at),
        })

    # Recent vital records (nurse notes with category='vitals')
    for note in (
        db.query(models.NurseNote)
        .filter(
            models.NurseNote.author_user_id == current_user.id,
            models.NurseNote.category == 'vitals',
        )
        .order_by(models.NurseNote.created_at.desc())
        .limit(5)
        .all()
    ):
        pname = patient_map.get(
            (db.query(models.Admission.patient_id).filter(models.Admission.id == note.admission_id).scalar()),
            'Patient'
        )
        events.append({
            'id': f'vital-{note.id}',
            'type': 'vitals',
            'title': 'Vitals recorded',
            'patient': pname,
            'detail': (note.note or '')[:120],
            'timestamp': str(note.created_at),
        })

    # Recent notifications
    for notif in (
        db.query(models.NotificationEvent)
        .filter(models.NotificationEvent.recipient_user_id == current_user.id)
        .order_by(models.NotificationEvent.created_at.desc())
        .limit(10)
        .all()
    ):
        events.append({
            'id': f'notif-{notif.id}',
            'type': 'notification',
            'title': notif.title or 'Notification',
            'patient': '',
            'detail': (notif.detail or '')[:120],
            'timestamp': str(notif.created_at),
        })

    # Sort all events by timestamp descending and limit
    events.sort(key=lambda e: e.get('timestamp', ''), reverse=True)
    events = events[:limit]

    return {'items': events}


@app.post("/nurse/recent-activity/{event_id}/delete")
def nurse_delete_activity(
    event_id: str,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Delete a single recent activity event (nurse note, notification).
    Only deletes dashboard-facing items — never medical records."""
    _ensure_nurse(current_user)
    deleted = False
    # Handle note-* events
    if event_id.startswith('note-') or event_id.startswith('vital-'):
        try:
            nid = int(event_id.split('-', 1)[1])
            note = db.query(models.NurseNote).filter(
                models.NurseNote.id == nid,
                models.NurseNote.author_user_id == current_user.id,
            ).first()
            if note:
                db.delete(note)
                db.commit()
                deleted = True
        except (ValueError, IndexError):
            pass
    elif event_id.startswith('notif-'):
        try:
            nid = int(event_id.split('-', 1)[1])
            notif = db.query(models.NotificationEvent).filter(
                models.NotificationEvent.id == nid,
                models.NotificationEvent.recipient_user_id == current_user.id,
            ).first()
            if notif:
                db.delete(notif)
                db.commit()
                deleted = True
        except (ValueError, IndexError):
            pass
    return {'deleted': deleted}


@app.post("/nurse/recent-activity/bulk-delete")
def nurse_bulk_delete_activity(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Delete multiple recent activity events by their IDs."""
    _ensure_nurse(current_user)
    event_ids = payload.get('ids', [])
    deleted_count = 0
    for event_id in event_ids:
        if event_id.startswith('note-') or event_id.startswith('vital-'):
            try:
                nid = int(event_id.split('-', 1)[1])
                note = db.query(models.NurseNote).filter(
                    models.NurseNote.id == nid,
                    models.NurseNote.author_user_id == current_user.id,
                ).first()
                if note:
                    db.delete(note)
                    deleted_count += 1
            except (ValueError, IndexError):
                pass
        elif event_id.startswith('notif-'):
            try:
                nid = int(event_id.split('-', 1)[1])
                notif = db.query(models.NotificationEvent).filter(
                    models.NotificationEvent.id == nid,
                    models.NotificationEvent.recipient_user_id == current_user.id,
                ).first()
                if notif:
                    db.delete(notif)
                    deleted_count += 1
            except (ValueError, IndexError):
                pass
    db.commit()
    return {'deleted': deleted_count}


