# ---------- Discharge appeals (3-step) ----------

DISCHARGE_APPEAL_DECISIONS = {"approved", "rejected"}


def _appeal_to_out(
    db: Session, a: models.DischargeAppeal
) -> schemas.DischargeAppealOut:
    """Helper: DischargeAppeal row → DischargeAppealOut with joined names
    and admission context (hospital, bed, ward, patient)."""
    adm = db.query(models.Admission).filter(models.Admission.id == a.admission_id).first()
    patient = (
        db.query(models.Patient).filter(models.Patient.id == adm.patient_id).first()
        if adm else None
    )
    hospital = None
    bed = None
    ward = None
    if adm is not None:
        if adm.hospital_id:
            hospital = (
                db.query(models.Hospital)
                .filter(models.Hospital.id == adm.hospital_id)
                .first()
            )
        bed = db.query(models.Bed).filter(models.Bed.id == adm.bed_id).first()
        if bed:
            ward = db.query(models.Ward).filter(models.Ward.id == bed.ward_id).first()

    requester = (
        db.query(models.User).filter(models.User.id == a.requested_by_user_id).first()
    )
    hospital_user = (
        db.query(models.User).filter(models.User.id == a.hospital_decided_by_user_id).first()
        if a.hospital_decided_by_user_id else None
    )
    doctor_user = (
        db.query(models.User).filter(models.User.id == a.doctor_decided_by_user_id).first()
        if a.doctor_decided_by_user_id else None
    )

    return schemas.DischargeAppealOut(
        id=a.id,
        admission_id=a.admission_id,
        patient_id=adm.patient_id if adm else None,
        patient_name=patient.name if patient else None,
        hospital_id=adm.hospital_id if adm else None,
        hospital_name=hospital.name if hospital else None,
        bed_number=bed.bed_number if bed else None,
        ward_name=ward.name if ward else None,
        requested_by_user_id=a.requested_by_user_id,
        requested_by_name=(
            (requester.full_name or requester.username) if requester else None
        ),
        requested_at=a.requested_at,
        nurse_reason=a.nurse_reason,
        hospital_decision=a.hospital_decision,
        hospital_decided_by_user_id=a.hospital_decided_by_user_id,
        hospital_decided_by_name=(
            (hospital_user.full_name or hospital_user.username) if hospital_user else None
        ),
        hospital_decided_at=a.hospital_decided_at,
        hospital_reason=a.hospital_reason,
        doctor_decision=a.doctor_decision,
        doctor_decided_by_user_id=a.doctor_decided_by_user_id,
        doctor_decided_by_name=(
            (doctor_user.full_name or doctor_user.username) if doctor_user else None
        ),
        doctor_decided_at=a.doctor_decided_at,
        doctor_reason=a.doctor_reason,
        status=a.status,
    )


@app.post("/discharge-appeals", response_model=schemas.DischargeAppealOut)
def file_discharge_appeal(
    payload: schemas.DischargeAppealCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Nurse files a discharge appeal for a patient they're currently
    assigned to. Creates a row with status=pending_hospital. Notifies
    every hospital admin of the admission's hospital (if any)."""
    _ensure_nurse(current_user)
    adm = db.query(models.Admission).filter(models.Admission.id == payload.admission_id).first()
    if adm is None:
        raise HTTPException(status_code=404, detail="Admission not found.")
    if adm.discharged_at is not None:
        raise HTTPException(status_code=409, detail="This admission is already discharged.")
    # The nurse must be currently assigned to the patient.
    _nurse_for_patient(db, current_user, adm.patient_id)
    # Only one active appeal per admission at a time.
    active = (
        db.query(models.DischargeAppeal)
        .filter(
            models.DischargeAppeal.admission_id == adm.id,
            models.DischargeAppeal.status.in_(["pending_hospital", "pending_doctor"]),
        )
        .first()
    )
    if active is not None:
        raise HTTPException(
            status_code=409,
            detail="An active appeal already exists for this admission.",
        )

    appeal = models.DischargeAppeal(
        admission_id=adm.id,
        requested_by_user_id=current_user.id,
        requested_at=datetime.utcnow(),
        nurse_reason=payload.reason,
        status="pending_hospital",
    )
    db.add(appeal)
    # Notify hospital admins.
    patient = db.query(models.Patient).filter(models.Patient.id == adm.patient_id).first()
    if adm.hospital_id:
        for admin_id in _hospital_admin_user_ids(db, adm.hospital_id):
            _enqueue_notification(
                db,
                recipient_user_id=admin_id,
                kind="discharge_appeal_filed",
                title=f"Discharge appeal: {patient.name if patient else 'patient'}",
                detail=(
                    f"Nurse {current_user.full_name or current_user.username} is requesting "
                    f"discharge for {patient.name if patient else 'this patient'}."
                ),
                link="hospital-dashboard.html",
            )
    db.commit()
    db.refresh(appeal)
    return _appeal_to_out(db, appeal)


@app.post("/discharge-appeals/{appeal_id}/hospital-decide", response_model=schemas.DischargeAppealOut)
def hospital_decide_appeal(
    appeal_id: int,
    payload: schemas.DischargeAppealDecision = schemas.DischargeAppealDecision(decision="approved"),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Hospital admin's first decision. If approved, the appeal moves to
    pending_doctor and the doctor is notified. If rejected, terminal —
    the nurse is notified."""
    profile = _ensure_hospital_admin(db, current_user)
    if payload.decision not in DISCHARGE_APPEAL_DECISIONS:
        raise HTTPException(
            status_code=400,
            detail=f"decision must be one of {sorted(DISCHARGE_APPEAL_DECISIONS)}",
        )
    appeal = (
        db.query(models.DischargeAppeal)
        .filter(models.DischargeAppeal.id == appeal_id)
        .first()
    )
    if appeal is None:
        raise HTTPException(status_code=404, detail="Appeal not found.")
    if appeal.status != "pending_hospital":
        raise HTTPException(
            status_code=409,
            detail=f"Appeal is already {appeal.status} — only pending_hospital can be hospital-decided.",
        )
    adm = db.query(models.Admission).filter(models.Admission.id == appeal.admission_id).first()
    if adm.hospital_id != profile.hospital_id:
        raise HTTPException(
            status_code=403,
            detail="This appeal does not belong to your hospital.",
        )
    appeal.hospital_decision = payload.decision
    appeal.hospital_decided_by_user_id = current_user.id
    appeal.hospital_decided_at = datetime.utcnow()
    appeal.hospital_reason = payload.reason
    if payload.decision == "rejected":
        appeal.status = "rejected"
    else:
        appeal.status = "pending_doctor"

    # Notify the other party.
    patient = db.query(models.Patient).filter(models.Patient.id == adm.patient_id).first()
    if payload.decision == "approved" and adm.admitted_by:
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="discharge_appeal_hospital_approved",
            title=f"Discharge appeal awaiting your sign-off: {patient.name if patient else 'patient'}",
            detail="The hospital admin approved. Please confirm to discharge the patient.",
            link="hospital-admit-requests.html",
        )
    else:
        # rejected — notify the filing nurse
        _enqueue_notification(
            db,
            recipient_user_id=appeal.requested_by_user_id,
            kind="discharge_appeal_hospital_approved",
            title=f"Discharge appeal rejected: {patient.name if patient else 'patient'}",
            detail=(
                f"Hospital admin {current_user.full_name or current_user.username} rejected "
                f"your discharge appeal. Reason: {payload.reason or '—'}"
            ),
            link="nurse-dashboard.html",
        )
    db.commit()
    db.refresh(appeal)
    return _appeal_to_out(db, appeal)


@app.post("/discharge-appeals/{appeal_id}/doctor-decide", response_model=schemas.AdmissionOut)
def doctor_decide_appeal(
    appeal_id: int,
    payload: schemas.DischargeAppealDecision = schemas.DischargeAppealDecision(decision="approved"),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Doctor's final sign-off. Only the admitting doctor can decide.
    On approval, the underlying Admission is discharged in the same
    transaction and the nurse + hospital admins are notified."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required.")
    if payload.decision not in DISCHARGE_APPEAL_DECISIONS:
        raise HTTPException(
            status_code=400,
            detail=f"decision must be one of {sorted(DISCHARGE_APPEAL_DECISIONS)}",
        )
    appeal = (
        db.query(models.DischargeAppeal)
        .filter(models.DischargeAppeal.id == appeal_id)
        .first()
    )
    if appeal is None:
        raise HTTPException(status_code=404, detail="Appeal not found.")
    if appeal.status != "pending_doctor":
        raise HTTPException(
            status_code=409,
            detail=f"Appeal is {appeal.status} — only pending_doctor can be doctor-decided.",
        )
    adm = db.query(models.Admission).filter(models.Admission.id == appeal.admission_id).first()
    if adm is None:
        raise HTTPException(status_code=404, detail="Admission not found.")
    if adm.admitted_by != current_user.id:
        raise HTTPException(
            status_code=403,
            detail="Only the admitting doctor can sign off on this discharge.",
        )

    appeal.doctor_decision = payload.decision
    appeal.doctor_decided_by_user_id = current_user.id
    appeal.doctor_decided_at = datetime.utcnow()
    appeal.doctor_reason = payload.reason

    patient = db.query(models.Patient).filter(models.Patient.id == adm.patient_id).first()
    if payload.decision == "approved":
        appeal.status = "approved"
        adm.discharged_at = datetime.utcnow()
        adm.discharged_by = current_user.id
        adm.discharge_reason = (
            f"Doctor-approved appeal #{appeal.id}: {payload.reason or ''}".strip()
        )
        # Notify nurse + hospital.
        _enqueue_notification(
            db,
            recipient_user_id=appeal.requested_by_user_id,
            kind="discharge_complete",
            title=f"Patient discharged: {patient.name if patient else 'patient'}",
            detail="Your discharge appeal was approved by the doctor.",
            link="nurse-dashboard.html",
        )
        if adm.hospital_id:
            for admin_id in _hospital_admin_user_ids(db, adm.hospital_id):
                _enqueue_notification(
                    db,
                    recipient_user_id=admin_id,
                    kind="discharge_complete",
                    title=f"Patient discharged: {patient.name if patient else 'patient'}",
                    detail="The admitting doctor signed off on the discharge.",
                    link="hospital-dashboard.html",
                )
    else:
        appeal.status = "rejected"
        # Notify nurse that the appeal was rejected.
        _enqueue_notification(
            db,
            recipient_user_id=appeal.requested_by_user_id,
            kind="discharge_appeal_doctor_approved",
            title=f"Discharge appeal rejected: {patient.name if patient else 'patient'}",
            detail=(
                f"Dr. {current_user.full_name or current_user.username} did not approve the discharge."
            ),
            link="nurse-dashboard.html",
        )
    db.commit()
    db.refresh(adm)
    return _admission_to_out(db, adm)


@app.post("/discharge-appeals/{appeal_id}/cancel", response_model=schemas.DischargeAppealOut)
def cancel_discharge_appeal(
    appeal_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Filing nurse cancels their own appeal while still pending."""
    appeal = (
        db.query(models.DischargeAppeal)
        .filter(models.DischargeAppeal.id == appeal_id)
        .first()
    )
    if appeal is None:
        raise HTTPException(status_code=404, detail="Appeal not found.")
    if appeal.requested_by_user_id != current_user.id:
        raise HTTPException(status_code=403, detail="Only the filing nurse can cancel this appeal.")
    if appeal.status not in ("pending_hospital", "pending_doctor"):
        raise HTTPException(
            status_code=409,
            detail=f"Appeal is already {appeal.status}.",
        )
    appeal.status = "cancelled"
    db.commit()
    db.refresh(appeal)
    return _appeal_to_out(db, appeal)


@app.get("/discharge-appeals", response_model=schemas.DischargeAppealListOut)
def list_discharge_appeals(
    status: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Role-scoped listing of discharge appeals. status filter is exact-match."""
    q = db.query(models.DischargeAppeal)
    if status:
        q = q.filter(models.DischargeAppeal.status == status)
    if current_user.role == "nurse":
        q = q.filter(models.DischargeAppeal.requested_by_user_id == current_user.id)
    elif current_user.role == "doctor":
        # Doctor sees appeals on admissions they admitted.
        q = q.join(models.Admission, models.Admission.id == models.DischargeAppeal.admission_id)
        q = q.filter(models.Admission.admitted_by == current_user.id)
    elif current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        q = q.join(models.Admission, models.Admission.id == models.DischargeAppeal.admission_id)
        q = q.filter(models.Admission.hospital_id == profile.hospital_id)
    else:
        return schemas.DischargeAppealListOut(items=[], total_count=0)
    rows = q.order_by(models.DischargeAppeal.requested_at.desc()).all()
    items = [_appeal_to_out(db, r) for r in rows]
    return schemas.DischargeAppealListOut(items=items, total_count=len(items))


@app.post("/admissions/{admission_id}/direct-discharge", response_model=schemas.AdmissionOut)
def doctor_direct_discharge(
    admission_id: int,
    payload: schemas.AdmissionDischargeIn = schemas.AdmissionDischargeIn(),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Doctor shortcut: skip the 3-step appeal and discharge directly.
    Only the admitting doctor can use this. Writes a synthetic
    DischargeAppeal row with status=approved for the audit trail."""
    if current_user.role != "doctor":
        raise HTTPException(status_code=403, detail="Doctor access required.")
    adm = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    if adm is None:
        raise HTTPException(status_code=404, detail="Admission not found.")
    if adm.admitted_by != current_user.id:
        raise HTTPException(
            status_code=403,
            detail="Only the admitting doctor can direct-discharge.",
        )
    if adm.discharged_at is not None:
        raise HTTPException(status_code=409, detail="Already discharged.")

    # Synthetic appeal for audit. The route stamps hospital/doctor decisions
    # as "approved by system" and "approved by doctor" so the table tells
    # the same story either way.
    doctor_reason_text = (payload.reason or "").strip() or "Doctor-direct discharge."
    appeal = models.DischargeAppeal(
        admission_id=adm.id,
        requested_by_user_id=current_user.id,
        requested_at=datetime.utcnow(),
        nurse_reason="Doctor-direct discharge (no appeal).",
        hospital_decision="approved",
        hospital_decided_by_user_id=None,
        hospital_decided_at=datetime.utcnow(),
        hospital_reason="Doctor-direct discharge — system-approved.",
        doctor_decision="approved",
        doctor_decided_by_user_id=current_user.id,
        doctor_decided_at=datetime.utcnow(),
        doctor_reason=doctor_reason_text,
        status="approved",
    )
    db.add(appeal)

    adm.discharged_at = datetime.utcnow()
    adm.discharged_by = current_user.id
    adm.discharge_reason = doctor_reason_text

    patient = db.query(models.Patient).filter(models.Patient.id == adm.patient_id).first()
    # Notify the assigned nurse (if any) and hospital admins.
    active_nurse = (
        db.query(models.NurseAssignment)
        .filter(
            models.NurseAssignment.patient_id == adm.patient_id,
            models.NurseAssignment.is_active == True,  # noqa: E712
        )
        .first()
    )
    if active_nurse is not None:
        _enqueue_notification(
            db,
            recipient_user_id=active_nurse.nurse_user_id,
            kind="discharge_complete",
            title=f"Patient discharged: {patient.name if patient else 'patient'}",
            detail="The admitting doctor discharged this patient directly.",
            link="nurse-dashboard.html",
        )
    if adm.hospital_id:
        for admin_id in _hospital_admin_user_ids(db, adm.hospital_id):
            _enqueue_notification(
                db,
                recipient_user_id=admin_id,
                kind="discharge_complete",
                title=f"Patient discharged: {patient.name if patient else 'patient'}",
                detail="The admitting doctor discharged this patient directly.",
                link="hospital-dashboard.html",
            )
    db.commit()
    db.refresh(adm)
    return _admission_to_out(db, adm)


# ============================================================
# Nurse: Medications / Treatments / Notes
# ============================================================
# Active nurses create, edit, discontinue medications; schedule, complete,
# or cancel treatments; and file free-form notes (which can be "sent" to
# the patient's admitting doctor as a bell-feed notification). All endpoints
# gate on (a) nurse role and (b) the caller having an active NurseAssignment
# for the admission's patient — so a nurse on Ward A can't touch Ward B's
# patients.

def _admission_for_nurse(
    db: Session,
    current_user: models.User,
    admission_id: int,
) -> models.Admission:
    """Return the admission row iff the caller is a nurse AND has an active
    NurseAssignment for that admission's patient. Raise 403/404 otherwise.
    Shared guard so all med/treatment/note endpoints enforce the same gate."""
    _ensure_nurse(current_user)
    adm = (
        db.query(models.Admission)
        .filter(models.Admission.id == admission_id)
        .first()
    )
    if adm is None:
        raise HTTPException(status_code=404, detail="Admission not found.")
    if adm.discharged_at is not None:
        raise HTTPException(
            status_code=409,
            detail="This admission has already been discharged.",
        )
    has_assignment = (
        db.query(models.NurseAssignment)
        .filter(
            models.NurseAssignment.nurse_user_id == current_user.id,
            models.NurseAssignment.patient_id == adm.patient_id,
            models.NurseAssignment.is_active == True,  # noqa: E712
        )
        .first()
    )
    if has_assignment is None:
        raise HTTPException(
            status_code=403,
            detail="You aren't currently assigned to this patient.",
        )
    return adm


def _medication_to_out(m: models.Medication) -> schemas.MedicationOut:
    return schemas.MedicationOut(
        id=m.id,
        admission_id=m.admission_id,
        patient_id=m.patient_id,
        name=m.name,
        dosage=m.dosage,
        frequency=m.frequency,
        route=m.route,
        notes=m.notes,
        status=m.status,
        started_at=m.started_at,
        stopped_at=m.stopped_at,
        created_by_user_id=m.created_by_user_id,
        created_at=m.created_at,
    )


def _treatment_to_out(t: models.Treatment) -> schemas.TreatmentOut:
    return schemas.TreatmentOut(
        id=t.id,
        admission_id=t.admission_id,
        patient_id=t.patient_id,
        name=t.name,
        category=t.category,
        description=t.description,
        schedule=t.schedule,
        notes=t.notes,
        status=t.status,
        scheduled_at=t.scheduled_at,
        completed_at=t.completed_at,
        created_by_user_id=t.created_by_user_id,
        created_at=t.created_at,
    )


def _build_admission_clinical_context(
    db: Session, adm: models.Admission
) -> dict:
    """Assemble the slimmed-down clinical context that
    ``gemini_client.summarize_patient`` consumes when the nurse files a
    report. Mirrors the patient-summary call used in the doctor's
    Patient Detail view but doesn't try to feed it personal profile /
    prescriptions / vitals trends — a nurse report should focus on what
    the nurse actually did during this admission.

    Returns a dict the gemini helper can render. Pass straight to
    ``summarize_patient`` with the placeholder positional arguments
    populated so it doesn't crash on the missing ones.
    """
    patient = (
        db.query(models.Patient).filter(models.Patient.id == adm.patient_id).first()
    )

    meds = (
        db.query(models.Medication)
        .filter(models.Medication.admission_id == adm.id)
        .order_by(models.Medication.created_at.desc())
        .limit(20)
        .all()
    )
    treatments = (
        db.query(models.Treatment)
        .filter(models.Treatment.admission_id == adm.id)
        .order_by(models.Treatment.created_at.desc())
        .limit(20)
        .all()
    )
    prior_notes = (
        db.query(models.NurseNote)
        .filter(
            models.NurseNote.admission_id == adm.id,
            models.NurseNote.sent_to_doctor == 1,
        )
        .order_by(models.NurseNote.created_at.desc())
        .limit(5)
        .all()
    )

    return {
        "patient_info": {
            "name": patient.name if patient else "unknown",
            "patient_id": patient.id if patient else adm.patient_id,
        },
        "records": [
            {
                "name": m.name,
                "dosage": m.dosage,
                "frequency": m.frequency,
                "route": m.route,
                "status": m.status,
                "notes": m.notes,
            }
            for m in meds
        ],
        "prescriptions": [
            # gemini keeps the "prescriptions" slot separate from
            # "records"; for a nurse report we treat active meds as
            # the prescriptions too.
            {
                "medicine": m.name,
                "dosage": m.dosage,
                "frequency": m.frequency,
                "status": m.status,
            }
            for m in meds
        ],
        "trends_data": {},  # nurse reports don't track vitals trends
        "reminders": [],    # same — patient-side concern
        "patient_profile": None,
        "medical_history": None,
        "reports": [
            # Treat the prior sent-to-doctor nurse notes as report-like
            # context — gives Gemini the running picture.
            {
                "title": (
                    f"[{n.category or 'note'} · "
                    f"{n.created_at.strftime('%Y-%m-%d %H:%M') if n.created_at else ''}]"
                ),
                "category": n.category or "report",
                "notes": n.note,
                "summary": (n.summary or "")[:280],
            }
            for n in prior_notes
        ],
        # Extra fields used by the per-note summarizer (not all of
        # these are passed to gemini but the helper exposes them so
        # future callers can read them).
        "treatments": [
            {
                "name": t.name,
                "category": t.category,
                "schedule": t.schedule,
                "status": t.status,
                "notes": t.notes,
            }
            for t in treatments
        ],
        "admission_reason": (adm.notes or "").strip() or None,
    }


def _summarize_and_persist_note(
    db: Session, note: models.NurseNote, adm: models.Admission
) -> None:
    """Run ``gemini_client.summarize_patient`` on the patient's clinical
    context + this note's body, write the result onto
    ``NurseNote.summary``, and persist. Wrapped in try/except so a
    missing GEMINI_API_KEY or gemini outage doesn't crash the request —
    the doctor still sees the raw body.

    Tags the note with ``kind="free_text"`` (default for nurse-typed
    shift reports / observations). Aggregate reports go through the
    parallel :func:`_summarize_and_persist_aggregate_note`.
    """
    # Default-tag free-text notes so the renderer can branch. Legacy
    # rows with kind=NULL are still rendered as free_text (the chat
    # drawer's `note.kind || 'free_text'` handles NULLs).
    if not getattr(note, "kind", None):
        note.kind = "free_text"
    try:
        import gemini_client  # imported lazily so unit tests can stub
    except Exception:  # pragma: no cover
        return
    try:
        ctx = _build_admission_clinical_context(db, adm)
        # The gemini helper expects positional args matching its
        # signature (patient_info, records, prescriptions,
        # trends_data, reminders). We pre-loaded the dict so it's a
        # thin call.
        text = gemini_client.summarize_patient(
            ctx["patient_info"],
            ctx["records"],
            ctx["prescriptions"],
            ctx["trends_data"],
            ctx["reminders"],
            ctx.get("patient_profile"),
            ctx.get("medical_history"),
            ctx.get("reports"),
        )
        # Append the note's own body so the summary covers what the
        # nurse just wrote too.
        note_body = (note.note or "").strip()
        if note_body and note_body not in text:
            full = f"{text}\n\nLatest nurse note ({note.category or 'report'}): {note_body}"
        else:
            full = text
        note.summary = (full or "").strip() or None
        note.summary_generated_at = datetime.utcnow() if note.summary else None
        db.add(note)
    except Exception as exc:
        # Don't bubble up — the note is already saved and the raw body
        # is the canonical text. Just log a warning.
        import logging
        logging.getLogger("uvicorn.error").warning(
            "summarize_patient failed for NurseNote %s: %s", note.id, exc
        )


def _summarize_and_persist_aggregate_note(
    db: Session, note: models.NurseNote, adm: models.Admission
) -> None:
    """Run ``gemini_client.summarize_aggregate_report`` on the full
    admission context (meds + treatments + prior sent-to-doctor notes)
    and write the sectioned markdown result onto ``NurseNote.summary``.

    Wrapped in try/except so a missing ``GEMINI_API_KEY`` or Gemini
    outage doesn't crash the request — the row is still saved with
    ``summary=None`` and the doctor can still download the .md file (the
    file body just notes "AI summary unavailable" instead of the Gemini
    text).

    Tags the note with ``kind="report_aggregate"`` so the renderer and
    regenerate-summary branch pick the right code path.
    """
    note.kind = "report_aggregate"
    try:
        import gemini_client  # imported lazily so unit tests can stub
    except Exception:  # pragma: no cover
        return
    try:
        ctx = _build_admission_clinical_context(db, adm)
        text = gemini_client.summarize_aggregate_report(ctx)
        note.summary = (text or "").strip() or None
        note.summary_generated_at = datetime.utcnow() if note.summary else None
        db.add(note)
    except Exception as exc:
        import logging
        logging.getLogger("uvicorn.error").warning(
            "summarize_aggregate_report failed for NurseNote %s: %s",
            note.id, exc,
        )


def _nurse_note_to_out(
    db: Session, n: models.NurseNote
) -> schemas.NurseNoteOut:
    author = None
    if n.author_user_id:
        author = (
            db.query(models.User)
            .filter(models.User.id == n.author_user_id)
            .first()
        )
    patient = (
        db.query(models.Patient)
        .filter(models.Patient.id == n.patient_id)
        .first()
    )
    attachments_rows = (
        db.query(models.NurseNoteAttachment)
        .filter(models.NurseNoteAttachment.note_id == n.id)
        .order_by(models.NurseNoteAttachment.id.asc())
        .all()
    )
    attachments = [
        schemas.NurseNoteAttachmentOut(
            id=a.id,
            file_name=a.file_name,
            mime_type=a.mime_type,
            file_size=a.file_size,
            kind=a.kind,
            download_url=f"/nurse-note-attachments/{a.id}/download",
        )
        for a in attachments_rows
    ]
    return schemas.NurseNoteOut(
        id=n.id,
        admission_id=n.admission_id,
        patient_id=n.patient_id,
        patient_name=patient.name if patient else None,
        author_user_id=n.author_user_id,
        author_name=(author.full_name or author.username) if author else None,
        note=n.note,
        category=n.category,
        sent_to_doctor=bool(n.sent_to_doctor),
        summary=getattr(n, "summary", None),
        summary_generated_at=getattr(n, "summary_generated_at", None),
        kind=getattr(n, "kind", None),
        created_at=n.created_at,
        attachments=attachments,
    )


@app.post(
    "/admissions/{admission_id}/medications",
    response_model=schemas.MedicationOut,
)
def create_medication(
    admission_id: int,
    payload: schemas.MedicationCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    adm = _admission_for_nurse(db, current_user, admission_id)
    m = models.Medication(
        admission_id=adm.id,
        patient_id=adm.patient_id,
        name=payload.name,
        dosage=payload.dosage,
        frequency=payload.frequency,
        route=payload.route,
        notes=payload.notes,
        status="active",
        created_by_user_id=current_user.id,
    )
    db.add(m)
    db.flush()
    # Notify the admitting doctor (if any) so the medication shows up on
    # their dashboard without the nurse needing to "send a report" first.
    if adm.admitted_by:
        patient = (
            db.query(models.Patient)
            .filter(models.Patient.id == adm.patient_id)
            .first()
        )
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_medication_added",
            title=f"Medication started: {patient.name if patient else 'patient'}",
            detail=f"{payload.name}" + (f" · {payload.dosage}" if payload.dosage else "")
                  + (f" · {payload.frequency}" if payload.frequency else ""),
            link=f"patient-detail.html?patient_id={adm.patient_id}",
        )
    db.commit()
    db.refresh(m)
    return _medication_to_out(m)


@app.get(
    "/admissions/{admission_id}/medications",
    response_model=schemas.MedicationListOut,
)
def list_medications(
    admission_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    adm = _admission_for_nurse(db, current_user, admission_id)
    rows = (
        db.query(models.Medication)
        .filter(models.Medication.admission_id == adm.id)
        .order_by(models.Medication.started_at.desc())
        .all()
    )
    items = [_medication_to_out(m) for m in rows]
    return schemas.MedicationListOut(items=items, total_count=len(items))


@app.patch(
    "/medications/{medication_id}",
    response_model=schemas.MedicationOut,
)
def update_medication(
    medication_id: int,
    payload: schemas.MedicationUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    _ensure_nurse(current_user)
    m = (
        db.query(models.Medication)
        .filter(models.Medication.id == medication_id)
        .first()
    )
    if m is None:
        raise HTTPException(status_code=404, detail="Medication not found.")
    # Re-use the same gate: admission must be active AND caller must still be
    # assigned to the patient. A nurse who was re-assigned away from this
    # patient must not be able to mutate meds after the fact.
    adm = _admission_for_nurse(db, current_user, m.admission_id)
    data = payload.model_dump(exclude_unset=True)
    if "status" in data and data["status"] not in schemas.ALLOWED_MEDICATION_STATUSES:
        raise HTTPException(
            status_code=422,
            detail=f"status must be one of {sorted(schemas.ALLOWED_MEDICATION_STATUSES)}",
        )
    for k, v in data.items():
        setattr(m, k, v)
    # If status moved away from "active", stamp stopped_at so history is clear.
    if "status" in data and data["status"] != "active" and m.stopped_at is None:
        m.stopped_at = datetime.utcnow()
    db.flush()
    # Notify the admitting doctor about discontinuations / completions.
    if "status" in data and data["status"] in ("discontinued", "completed") and adm.admitted_by:
        patient = (
            db.query(models.Patient)
            .filter(models.Patient.id == m.patient_id)
            .first()
        )
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_medication_stopped",
            title=f"Medication {data['status']}: {patient.name if patient else 'patient'}",
            detail=m.name,
            link=f"patient-detail.html?patient_id={m.patient_id}",
        )
    db.commit()
    db.refresh(m)
    return _medication_to_out(m)


@app.post(
    "/admissions/{admission_id}/treatments",
    response_model=schemas.TreatmentOut,
)
def create_treatment(
    admission_id: int,
    payload: schemas.TreatmentCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    adm = _admission_for_nurse(db, current_user, admission_id)
    t = models.Treatment(
        admission_id=adm.id,
        patient_id=adm.patient_id,
        name=payload.name,
        category=payload.category,
        description=payload.description,
        schedule=payload.schedule,
        scheduled_at=payload.scheduled_at,
        notes=payload.notes,
        status="scheduled",
        created_by_user_id=current_user.id,
    )
    db.add(t)
    db.flush()
    if adm.admitted_by:
        patient = (
            db.query(models.Patient)
            .filter(models.Patient.id == adm.patient_id)
            .first()
        )
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_treatment_added",
            title=f"Treatment scheduled: {patient.name if patient else 'patient'}",
            detail=payload.name + (f" · {payload.schedule}" if payload.schedule else ""),
            link=f"patient-detail.html?patient_id={adm.patient_id}",
        )
    db.commit()
    db.refresh(t)
    return _treatment_to_out(t)


@app.get(
    "/admissions/{admission_id}/treatments",
    response_model=schemas.TreatmentListOut,
)
def list_treatments(
    admission_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    adm = _admission_for_nurse(db, current_user, admission_id)
    rows = (
        db.query(models.Treatment)
        .filter(models.Treatment.admission_id == adm.id)
        .order_by(models.Treatment.created_at.desc())
        .all()
    )
    items = [_treatment_to_out(t) for t in rows]
    return schemas.TreatmentListOut(items=items, total_count=len(items))


@app.patch(
    "/treatments/{treatment_id}",
    response_model=schemas.TreatmentOut,
)
def update_treatment(
    treatment_id: int,
    payload: schemas.TreatmentUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    _ensure_nurse(current_user)
    t = (
        db.query(models.Treatment)
        .filter(models.Treatment.id == treatment_id)
        .first()
    )
    if t is None:
        raise HTTPException(status_code=404, detail="Treatment not found.")
    adm = _admission_for_nurse(db, current_user, t.admission_id)
    data = payload.model_dump(exclude_unset=True)
    if "status" in data and data["status"] not in schemas.ALLOWED_TREATMENT_STATUSES:
        raise HTTPException(
            status_code=422,
            detail=f"status must be one of {sorted(schemas.ALLOWED_TREATMENT_STATUSES)}",
        )
    for k, v in data.items():
        setattr(t, k, v)
    if "status" in data and data["status"] == "completed" and t.completed_at is None:
        t.completed_at = datetime.utcnow()
    db.flush()
    if "status" in data and data["status"] == "completed" and adm.admitted_by:
        patient = (
            db.query(models.Patient)
            .filter(models.Patient.id == t.patient_id)
            .first()
        )
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_treatment_completed",
            title=f"Treatment completed: {patient.name if patient else 'patient'}",
            detail=t.name,
            link=f"patient-detail.html?patient_id={t.patient_id}",
        )
    db.commit()
    db.refresh(t)
    return _treatment_to_out(t)


@app.post(
    "/admissions/{admission_id}/nurse-notes",
    response_model=schemas.NurseNoteOut,
)
async def create_nurse_note(
    admission_id: int,
    request: Request,
    body: Optional[str] = Form(None),
    category: Optional[str] = Form(None),
    send_to_doctor: Optional[str] = Form(None),
    files: list[UploadFile] = File(default=[]),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Create a nurse-note with optional file attachments.

    Two modes (mirrors the chat-message endpoint):
      * application/json with {note, category, send_to_doctor} — text only.
      * multipart/form-data with `body` (text), optional `category`,
        optional `send_to_doctor` ("true"/"false"), and zero or more
        `files` for attachments. ``body`` is allowed to be empty as long
        as at least one file is supplied — useful for sending a photo-only
        report.
    """
    adm = _admission_for_nurse(db, current_user, admission_id)

    content_type = (request.headers.get("content-type") or "").lower()
    is_multipart = "multipart/form-data" in content_type

    note_text: Optional[str] = None
    cat_value: Optional[str] = None
    send_value = False

    if is_multipart:
        note_text = (body or "").strip() or None
        cat_value = (category or "").strip() or None
        send_value = str(send_to_doctor or "").lower() in ("1", "true", "yes", "on")
        if not note_text and not files:
            raise HTTPException(
                status_code=400,
                detail="Provide a note body or at least one attachment.",
            )
    else:
        # JSON mode — body was sent as raw JSON, not form fields.
        try:
            raw = await request.json()
        except Exception:
            raise HTTPException(status_code=400, detail="Invalid JSON body.")
        if not isinstance(raw, dict):
            raise HTTPException(status_code=400, detail="JSON body must be an object.")
        note_text = (raw.get("note") or "").strip() or None
        cat_value = raw.get("category")
        send_value = bool(raw.get("send_to_doctor"))
        if not note_text:
            raise HTTPException(status_code=400, detail="Note text is required.")
        files = []

    note = models.NurseNote(
        admission_id=adm.id,
        patient_id=adm.patient_id,
        author_user_id=current_user.id,
        note=note_text or "",
        category=cat_value,
        sent_to_doctor=1 if send_value else 0,
    )
    db.add(note)
    db.flush()  # so note.id is available for attachments

    # Store attachments — same validation rules as chat attachments
    # (images, videos, or a fixed list of document mimes).
    note_dir = os.path.join(UPLOAD_DIR, "nurse_notes")
    os.makedirs(note_dir, exist_ok=True)
    for file in files or []:
        mime = file.content_type or ""
        if not _chat_attachment_allowed(mime):
            db.rollback()
            raise HTTPException(
                status_code=415,
                detail=f"Unsupported file type '{mime}'. Allowed: images, videos, "
                       f"PDF, DOC/DOCX, PPT/PPTX, TXT, CSV.",
            )
        content = await file.read()
        if len(content) > CHAT_MAX_UPLOAD_BYTES:
            db.rollback()
            raise HTTPException(
                status_code=413,
                detail=f"File '{file.filename}' is too large. "
                       f"Max {CHAT_MAX_UPLOAD_BYTES // (1024 * 1024)} MB per file.",
            )
        safe_original = os.path.basename(file.filename or "attachment")
        stored_name = f"{uuid.uuid4().hex}_{safe_original}"
        stored_path = os.path.join(note_dir, stored_name)
        with open(stored_path, "wb") as fh:
            fh.write(content)
        att = models.NurseNoteAttachment(
            note_id=note.id,
            file_name=safe_original,
            stored_path=stored_path,
            mime_type=mime,
            file_size=len(content),
            kind=_chat_attachment_kind(mime),
        )
        db.add(att)

    # If the nurse ticked "send to doctor", notify the admitting doctor.
    # This is the dedicated "send report directly to related doctor page" flow.
    if send_value and adm.admitted_by:
        patient = (
            db.query(models.Patient)
            .filter(models.Patient.id == adm.patient_id)
            .first()
        )
        preview_source = note_text or ""
        if files:
            names = [os.path.basename(f.filename or "file") for f in files]
            preview_source = (preview_source + " · 📎 " + ", ".join(names)) if preview_source else "📎 " + ", ".join(names)
        detail = (preview_source[:140] + "…") if len(preview_source) > 140 else preview_source
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_report_sent",
            title=f"Nurse report: {patient.name if patient else 'patient'}",
            detail=detail,
            link=f"patient-detail.html?patient_id={adm.patient_id}",
        )
    db.commit()
    db.refresh(note)

    # 2026-08: if the nurse ticked "send to doctor", generate an AI
    # summary of the admission's meds + treatments + note so the doctor
    # gets a short, readable summary in their chat bubble. Wrapped in
    # try/except inside the helper so a missing GEMINI_API_KEY doesn't
    # crash the report send.
    if send_value:
        try:
            _summarize_and_persist_note(db, note, adm)
            if note.summary:
                db.commit()
                db.refresh(note)
        except Exception:
            # Helper already swallowed the failure but make sure we
            # don't leak a half-flushed session.
            db.rollback()

    return _nurse_note_to_out(db, note)


@app.get("/nurse-note-attachments/{attachment_id}/download")
def download_nurse_note_attachment(
    attachment_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Stream a nurse-note attachment. Caller must be either the nurse
    who created the note (active assignment) or the admitting doctor on
    the related patient — same gate as chat attachments."""
    att = (
        db.query(models.NurseNoteAttachment)
        .filter(models.NurseNoteAttachment.id == attachment_id)
        .first()
    )
    if not att:
        raise HTTPException(status_code=404, detail="Attachment not found")
    note = (
        db.query(models.NurseNote)
        .filter(models.NurseNote.id == att.note_id)
        .first()
    )
    if not note:
        raise HTTPException(status_code=404, detail="Attachment not found")
    # Re-use the chat-access gate (works for nurse + doctor + patient).
    adm = (
        db.query(models.Admission)
        .filter(models.Admission.id == note.admission_id)
        .first()
    )
    if adm is None:
        raise HTTPException(status_code=404, detail="Attachment not found")
    _ensure_chat_access(current_user, adm.patient_id, adm.admitted_by, db)

    if not os.path.exists(att.stored_path):
        raise HTTPException(status_code=410, detail="Attachment file is missing on disk")

    return FileResponse(
        path=att.stored_path,
        media_type=att.mime_type or "application/octet-stream",
        filename=att.file_name,
    )


# ---------------------------------------------------------------------------
# 2026-08: AI-aggregated summary report (nurse → doctor).
#
# The nurse pushes one click on "🤖 Send AI summary report" which:
#   1. Aggregates the admission's medications + treatments + the last
#      five sent-to-doctor nurse notes via
#      ``_build_admission_clinical_context``.
#   2. Asks Gemini for a sectioned markdown clinical brief
#      (``gemini_client.summarize_aggregate_report``).
#   3. Saves a new ``NurseNote`` with ``kind="report_aggregate"`` and
#      notifies the admitting doctor.
#
# The doctor reads the summary inline in the chat (chat-drawer.js
# renders a "📊 AI summary report" bubble) AND can download the full
# markdown file via ``GET /ai-summary-reports/{id}/download``.
# ---------------------------------------------------------------------------


def _slugify(value: Optional[str], fallback: str = "patient") -> str:
    """Lowercase, ascii-only, non-alnum → '-' — for the .md filename."""
    if not value:
        return fallback
    out = []
    for ch in value.lower():
        if ch.isalnum():
            out.append(ch)
        elif ch in (" ", "_", "-"):
            out.append("-")
    slug = "".join(out).strip("-")
    return slug or fallback


def _build_aggregate_report_markdown(
    note: models.NurseNote, adm: models.Admission,
    db: Session,
) -> str:
    """Assemble the markdown body of an AI-aggregated summary report
    file. Used by the download endpoint. The note's ``note`` column
    holds the JSON snapshot of the clinical context at the time the
    report was generated; we re-load it to keep the file stable across
    re-summarization."""

    patient = (
        db.query(models.Patient)
        .filter(models.Patient.id == adm.patient_id)
        .first()
    )
    author = (
        db.query(models.User)
        .filter(models.User.id == note.author_user_id)
        .first()
        if note.author_user_id
        else None
    )

    # Parse the JSON snapshot (best effort — falls back to a placeholder
    # if the column is empty / not JSON for legacy reasons).
    snapshot = None
    if note.note:
        try:
            snapshot = json.loads(note.note)
        except Exception:
            snapshot = None

    patient_info = (snapshot or {}).get("patient_info") or {}
    records = (snapshot or {}).get("records") or []
    treatments = (snapshot or {}).get("treatments") or []
    reports = (snapshot or {}).get("reports") or []
    admission_reason = (
        (snapshot or {}).get("admission_reason")
        or (adm.notes or "").strip()
        or "—"
    )

    generated_at = (
        note.summary_generated_at.strftime("%Y-%m-%d %H:%M UTC")
        if note.summary_generated_at
        else datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC")
    )
    author_name = (
        (author.full_name or author.username)
        if author else "Nurse"
    )

    lines: list[str] = []
    lines.append(f"# AI summary report — {patient.name if patient else 'patient'} (adm-{adm.id})")
    lines.append("")
    lines.append(f"Generated {generated_at} by {author_name}")
    lines.append("")

    lines.append("## Patient")
    lines.append(f"- Name: {patient.name if patient else 'unknown'}")
    if patient is not None:
        if getattr(patient, "age", None) is not None:
            lines.append(f"- Age: {patient.age}")
        if getattr(patient, "gender", None):
            lines.append(f"- Gender: {patient.gender}")
        if patient_info.get("patient_id"):
            lines.append(f"- Patient ID: {patient_info.get('patient_id')}")
    lines.append("")

    lines.append("## Admission reason")
    lines.append(admission_reason)
    lines.append("")

    lines.append(f"## Medications ({len(records)})")
    if not records:
        lines.append("_(none recorded)_")
    else:
        for m in records:
            parts = [str(m.get("name") or "?")]
            if m.get("dosage"):
                parts.append(str(m["dosage"]))
            if m.get("frequency"):
                parts.append(str(m["frequency"]))
            if m.get("route"):
                parts.append(str(m["route"]))
            if m.get("status"):
                parts.append(f"status: {m['status']}")
            lines.append(f"- {' — '.join(parts)}")
            if m.get("notes"):
                lines.append(f"  - notes: {m['notes']}")
    lines.append("")

    lines.append(f"## Treatments ({len(treatments)})")
    if not treatments:
        lines.append("_(none recorded)_")
    else:
        for t in treatments:
            parts = [str(t.get("name") or "?")]
            if t.get("category"):
                parts.append(str(t["category"]))
            if t.get("schedule"):
                parts.append(str(t["schedule"]))
            if t.get("status"):
                parts.append(f"status: {t['status']}")
            lines.append(f"- {' — '.join(parts)}")
            if t.get("notes"):
                lines.append(f"  - notes: {t['notes']}")
    lines.append("")

    lines.append(f"## Recent sent-to-doctor notes ({len(reports)})")
    if not reports:
        lines.append("_(none recorded)_")
    else:
        for r in reports:
            title = r.get("title") or ""
            notes_body = r.get("notes") or ""
            lines.append(f"- {title}: {notes_body}".rstrip())
            if r.get("summary"):
                prev_summary = str(r["summary"]).strip()
                if prev_summary:
                    lines.append(f"  - previous AI summary: {prev_summary}")
    lines.append("")

    lines.append("## AI summary")
    if note.summary and note.summary.strip():
        lines.append(note.summary.strip())
    else:
        lines.append(
            "_AI summary unavailable — GEMINI_API_KEY not configured or the "
            "Gemini call failed. The structured context above is the "
            "source of truth._"
        )
    lines.append("")

    lines.append("---")
    lines.append(
        f"_Report ID: nurse-note #{note.id} · admission #{adm.id} · "
        f"generated by Medical Intelligence System_"
    )
    lines.append("")

    return "\n".join(lines)


@app.post(
    "/admissions/{admission_id}/ai-summary-reports",
    response_model=schemas.NurseNoteOut,
)
def create_ai_summary_report(
    admission_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Nurse pushes an aggregated AI summary of the admission to the
    doctor. Aggregates medications + treatments + prior sent-to-doctor
    notes via :func:`_build_admission_clinical_context`, asks Gemini
    for a sectioned markdown brief, and saves a new
    ``NurseNote(kind="report_aggregate")``. The doctor sees the
    summary inline in chat AND can download the full markdown file
    via ``GET /ai-summary-reports/{id}/download``.

    Gate: the same as ``create_nurse_note`` — the calling nurse must
    be currently assigned to this admission
    (:func:`_admission_for_nurse`).
    """
    adm = _admission_for_nurse(db, current_user, admission_id)
    ctx = _build_admission_clinical_context(db, adm)
    snapshot = {
        # Strip the patient_profile/medical_history placeholders — they
        # aren't filled by the nurse-report context and the .md file
        # would just print "not provided" for them.
        "patient_info": ctx.get("patient_info") or {},
        "records": ctx.get("records") or [],
        "prescriptions": ctx.get("prescriptions") or [],
        "treatments": ctx.get("treatments") or [],
        "reports": ctx.get("reports") or [],
        "admission_reason": ctx.get("admission_reason"),
    }
    note = models.NurseNote(
        admission_id=adm.id,
        patient_id=adm.patient_id,
        author_user_id=current_user.id,
        note=json.dumps(snapshot, default=str),
        category="ai_summary",
        sent_to_doctor=1,
        kind="report_aggregate",
    )
    db.add(note)
    db.flush()  # so note.id is available for the summary write

    # Run the gemini helper. Failure is non-fatal (the row is already
    # saved and the doctor can still download the file).
    try:
        _summarize_and_persist_aggregate_note(db, note, adm)
    except Exception:
        db.rollback()
    db.commit()
    db.refresh(note)

    # Notify the admitting doctor — mirrors create_nurse_note's
    # nurse_report_sent enqueue.
    if adm.admitted_by:
        patient = (
            db.query(models.Patient)
            .filter(models.Patient.id == adm.patient_id)
            .first()
        )
        detail = (
            f"AI summary report — medications + treatments + prior notes"
            + (
                f" for {patient.name}"
                if patient and patient.name
                else ""
            )
        )
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_ai_report",
            title=(
                f"AI summary report: {patient.name if patient else 'patient'}"
            ),
            detail=detail[:140],
            link=f"patient-detail.html?patient_id={adm.patient_id}",
        )
        db.commit()

    return _nurse_note_to_out(db, note)


@app.get("/ai-summary-reports/{note_id}/download")
def download_ai_summary_report(
    note_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Stream the markdown body of an AI-aggregated summary report as a
    downloadable ``.md`` file. Gated by ``_ensure_chat_access`` so the
    assigned nurse, the admitting doctor, and the patient can all read
    it; everyone else gets 404 (we don't leak free-text notes as
    files)."""
    note = (
        db.query(models.NurseNote)
        .filter(models.NurseNote.id == note_id)
        .first()
    )
    if note is None:
        raise HTTPException(status_code=404, detail="Report not found.")
    if (note.kind or "") != "report_aggregate":
        # Don't leak free-text shift notes as files.
        raise HTTPException(status_code=404, detail="Report not found.")
    adm = (
        db.query(models.Admission)
        .filter(models.Admission.id == note.admission_id)
        .first()
    )
    if adm is None:
        raise HTTPException(status_code=404, detail="Admission not found.")
    _ensure_chat_access(current_user, adm.patient_id, adm.admitted_by, db)

    patient = (
        db.query(models.Patient)
        .filter(models.Patient.id == adm.patient_id)
        .first()
    )
    slug = _slugify(patient.name if patient else None, fallback="patient")
    stamp = (
        note.created_at.strftime("%Y%m%dT%H%M%SZ")
        if note.created_at
        else datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")
    )
    filename = f"report-{slug}-adm{adm.id}-{stamp}.md"

    body = _build_aggregate_report_markdown(note, adm, db)
    return StreamingResponse(
        BytesIO(body.encode("utf-8")),
        media_type="text/markdown; charset=utf-8",
        headers={
            "Content-Disposition": f'attachment; filename="{filename}"',
            "Content-Length": str(len(body.encode("utf-8"))),
        },
    )


@app.get(
    "/admissions/{admission_id}/nurse-notes",
    response_model=schemas.NurseNoteListOut,
)
def list_nurse_notes(
    admission_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """2026-08: gate now matches the chat-access gate so the doctor (and
    patient themselves) can also pull notes for the chat-drawer report
    bubble merger. Previously nurse-only — the AI-summary feature
    requires the doctor to be able to read NurseNote rows for an
    admission they admitted."""
    adm = db.query(models.Admission).filter(models.Admission.id == admission_id).first()
    if adm is None:
        raise HTTPException(status_code=404, detail="Admission not found.")
    _ensure_chat_access(current_user, adm.patient_id, adm.admitted_by, db)
    rows = (
        db.query(models.NurseNote)
        .filter(models.NurseNote.admission_id == adm.id)
        .order_by(models.NurseNote.created_at.desc())
        .all()
    )
    items = [_nurse_note_to_out(db, n) for n in rows]
    return schemas.NurseNoteListOut(items=items, total_count=len(items))


@app.post(
    "/nurse-notes/{note_id}/summarize",
    response_model=schemas.NurseNoteSummaryOut,
)
def regenerate_nurse_note_summary(
    note_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Re-run the Gemini summary on an existing nurse note. Either the
    note's author (active nurse on the admission) or the admitting
    doctor can call this — matches the chat access gate.

    Stores the new summary on ``NurseNote.summary`` and returns it. If
    Gemini is unavailable we surface a 200 with ``summary=None`` rather
    than 500 — the UI just keeps the previous text.
    """
    note = (
        db.query(models.NurseNote)
        .filter(models.NurseNote.id == note_id)
        .first()
    )
    if note is None:
        raise HTTPException(status_code=404, detail="Note not found.")
    adm = (
        db.query(models.Admission)
        .filter(models.Admission.id == note.admission_id)
        .first()
    )
    if adm is None:
        raise HTTPException(status_code=404, detail="Admission not found.")

    # Gate: nurse who wrote this note (still active on the admission)
    # OR the admitting doctor.
    is_author_nurse = (
        current_user.role == "nurse"
        and note.author_user_id == current_user.id
        and any(
            a.patient_id == adm.patient_id
            for a in (
                db.query(models.NurseAssignment)
                .filter(
                    models.NurseAssignment.nurse_user_id == current_user.id,
                    models.NurseAssignment.is_active == True,  # noqa: E712
                )
                .all()
            )
        )
    )
    is_admitting_doctor = (
        current_user.role == "doctor"
        and adm.admitted_by == current_user.id
    )
    if not (is_author_nurse or is_admitting_doctor):
        raise HTTPException(
            status_code=403,
            detail="Only the note's nurse or the admitting doctor can regenerate the summary.",
        )

    # 2026-08: aggregate reports use the sectioned-markdown helper;
    # free-text notes (legacy + new shift reports) keep using the plain
    # 3-5-sentence summarize_patient helper.
    if (note.kind or "") == "report_aggregate":
        _summarize_and_persist_aggregate_note(db, note, adm)
    else:
        _summarize_and_persist_note(db, note, adm)
    if note.summary:
        db.commit()
        db.refresh(note)

    return schemas.NurseNoteSummaryOut(
        note_id=note.id,
        summary=note.summary or "",
        summary_generated_at=note.summary_generated_at or datetime.utcnow(),
    )


# ----- Bulk create endpoints -----
# Nurses usually log several meds / treatments in one go (a full morning
# med round, a list of physiotherapy exercises, …). These endpoints let
# them POST a single batch and get back the full list of created rows in
# one response. Each batch produces ONE notification for the doctor
# (summarising the count + names) instead of one per row, so the bell
# feed doesn't get spammed when a nurse logs 6 meds at once.

@app.post(
    "/admissions/{admission_id}/medications/bulk",
    response_model=schemas.MedicationListOut,
)
def bulk_create_medications(
    admission_id: int,
    payload: schemas.MedicationBulkCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    adm = _admission_for_nurse(db, current_user, admission_id)
    items_in = payload.items or []
    if not items_in:
        raise HTTPException(status_code=422, detail="Provide at least one medication.")
    # Validate: ignore rows with a blank name but count them so the user
    # gets a clear error message instead of silent drops.
    clean: list[models.Medication] = []
    skipped = 0
    for item in items_in:
        if not (item.name or "").strip():
            skipped += 1
            continue
        m = models.Medication(
            admission_id=adm.id,
            patient_id=adm.patient_id,
            name=item.name.strip(),
            dosage=item.dosage,
            frequency=item.frequency,
            route=item.route,
            notes=item.notes,
            status="active",
            created_by_user_id=current_user.id,
        )
        db.add(m)
        clean.append(m)
    db.flush()
    # One combined notification, not N.
    if clean and adm.admitted_by:
        patient = (
            db.query(models.Patient)
            .filter(models.Patient.id == adm.patient_id)
            .first()
        )
        summary = ", ".join(m.name for m in clean[:5])
        if len(clean) > 5:
            summary += f", +{len(clean) - 5} more"
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_medication_added",
            title=f"{len(clean)} medication{'s' if len(clean) != 1 else ''} started: {patient.name if patient else 'patient'}",
            detail=summary,
            link=f"patient-detail.html?patient_id={adm.patient_id}",
        )
    db.commit()
    for m in clean:
        db.refresh(m)
    return schemas.MedicationListOut(
        items=[_medication_to_out(m) for m in clean],
        total_count=len(clean),
    )


@app.post(
    "/admissions/{admission_id}/treatments/bulk",
    response_model=schemas.TreatmentListOut,
)
def bulk_create_treatments(
    admission_id: int,
    payload: schemas.TreatmentBulkCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    adm = _admission_for_nurse(db, current_user, admission_id)
    items_in = payload.items or []
    if not items_in:
        raise HTTPException(status_code=422, detail="Provide at least one treatment.")
    clean: list[models.Treatment] = []
    for item in items_in:
        if not (item.name or "").strip():
            continue
        t = models.Treatment(
            admission_id=adm.id,
            patient_id=adm.patient_id,
            name=item.name.strip(),
            category=item.category,
            description=item.description,
            schedule=item.schedule,
            scheduled_at=item.scheduled_at,
            notes=item.notes,
            status="scheduled",
            created_by_user_id=current_user.id,
        )
        db.add(t)
        clean.append(t)
    db.flush()
    if clean and adm.admitted_by:
        patient = (
            db.query(models.Patient)
            .filter(models.Patient.id == adm.patient_id)
            .first()
        )
        summary = ", ".join(t.name for t in clean[:5])
        if len(clean) > 5:
            summary += f", +{len(clean) - 5} more"
        _enqueue_notification(
            db,
            recipient_user_id=adm.admitted_by,
            kind="nurse_treatment_added",
            title=f"{len(clean)} treatment{'s' if len(clean) != 1 else ''} scheduled: {patient.name if patient else 'patient'}",
            detail=summary,
            link=f"patient-detail.html?patient_id={adm.patient_id}",
        )
    db.commit()
    for t in clean:
        db.refresh(t)
    return schemas.TreatmentListOut(
        items=[_treatment_to_out(t) for t in clean],
        total_count=len(clean),
    )


# ============================================================
# MediEcho — AI clinical conversation intelligence
# ============================================================
# A doctor captures a doctor-patient consultation (upload or live mic
# upload), we run Whisper STT with a lightweight two-speaker heuristic,
# then call Gemini to extract a structured clinical note. The doctor
# reviews, edits, approves, and optionally saves the note as a real
# MedicalRecord (with optional Prescriptions) on the patient chart.
#
# The flow:
#   1. POST /mediecho/sessions                 → create empty session
#   2. POST /mediecho/sessions/{id}/transcribe  → audio file → transcript
#   3. POST /mediecho/sessions/{id}/analyze     → transcript → structured note
#   4. GET  /mediecho/sessions/{id}             → fetch session + note
#   5. PUT  /mediecho/sessions/{id}/note        → save doctor edits
#   6. POST /mediecho/sessions/{id}/save-to-record → promote note to chart
#
# GET endpoints are idempotent + cheap. POST/PUT are doctor-only.

ALLOWED_MEDIECHO_AUDIO_MIMES = {
    "audio/webm", "audio/ogg", "audio/wav", "audio/x-wav",
    "audio/mpeg", "audio/mp3", "audio/mp4", "audio/x-m4a", "audio/m4a",
    "audio/flac", "audio/aac",
}
ALLOWED_MEDIECHO_AUDIO_EXTS = {
    ".webm", ".ogg", ".wav", ".mp3", ".m4a", ".mp4", ".flac", ".aac", ".oga",
}


def _mediecho_session_to_out(
    db: Session, sess: models.MediEchoSession
) -> schemas.MediEchoSessionOut:
    """Build a MediEchoSessionOut, joining patient name + has_note flag."""
    patient_name = None
    if sess.patient_id is not None:
        p = db.query(models.Patient).filter(models.Patient.id == sess.patient_id).first()
        if p:
            patient_name = p.name
    has_note = (
        db.query(models.MediEchoNote)
        .filter(models.MediEchoNote.session_id == sess.id)
        .first()
        is not None
    )
    out = schemas.MediEchoSessionOut.model_validate(sess)
    out.patient_name = patient_name
    out.has_note = has_note
    return out


def _mediecho_parse_transcript_json(raw: str | None) -> list[dict]:
    """Decode transcript_json into a list of segments. Returns [] on empty/garbage."""
    if not raw:
        return []
    try:
        rows = json.loads(raw)
    except json.JSONDecodeError:
        return []
    if not isinstance(rows, list):
        return []
    out: list[dict] = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        speaker = (r.get("speaker") or "").strip().lower()
        if speaker not in schemas.ALLOWED_MEDIECHO_SPEAKERS:
            speaker = "patient"
        text = (r.get("text") or "").strip()
        if not text:
            continue
        try:
            start = float(r.get("start") or 0.0)
        except (TypeError, ValueError):
            start = 0.0
        try:
            end = float(r.get("end") or start)
        except (TypeError, ValueError):
            end = start
        out.append({"start": start, "end": end, "speaker": speaker, "text": text})
    return out


def _mediecho_load_note(
    db: Session, sess: models.MediEchoSession
) -> models.MediEchoNote | None:
    """Return the (single) note row attached to this session, or None."""
    return (
        db.query(models.MediEchoNote)
        .filter(models.MediEchoNote.session_id == sess.id)
        .first()
    )


def _mediecho_note_to_out(note: models.MediEchoNote) -> schemas.MediEchoNoteOut:
    """Build the wire-shape MediEchoNoteOut from the ORM row, including
    parsing the JSON blobs into nested Pydantic objects."""
    extracted = None
    if note.extracted_json:
        try:
            extracted = schemas.MediEchoExtractedNote.model_validate_json(note.extracted_json)
        except Exception:
            extracted = None
    edited = None
    if note.edited_json:
        try:
            edited = schemas.MediEchoExtractedNote.model_validate_json(note.edited_json)
        except Exception:
            edited = None
    highlights: list[schemas.MediEchoHighlight] = []
    if note.highlights_json:
        try:
            raw_h = json.loads(note.highlights_json)
            if isinstance(raw_h, list):
                for entry in raw_h:
                    if not isinstance(entry, dict):
                        continue
                    kind = (entry.get("kind") or "").strip().lower()
                    quote = (entry.get("quote") or "").strip()
                    why = (entry.get("why") or "").strip()
                    if not quote or not why:
                        continue
                    if kind not in {"red_flag", "allergy", "med_change", "follow_up", "test_order"}:
                        kind = "follow_up"
                    highlights.append(schemas.MediEchoHighlight(kind=kind, quote=quote[:240], why=why[:240]))
        except json.JSONDecodeError:
            pass
    out = schemas.MediEchoNoteOut.model_validate(note)
    out.extracted = extracted
    out.edited = edited
    out.highlights = highlights
    return out


@app.post("/mediecho/sessions", response_model=schemas.MediEchoSessionOut, status_code=201)
def create_mediecho_session(
    payload: schemas.MediEchoSessionCreate = schemas.MediEchoSessionCreate(),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Create an empty MediEcho session. Doctor + patient flows:
      * doctor → standard. patient_id is optional.
      * patient → automatically linked to the patient's own record,
        patient_id defaults to current_user.patient_id if absent.
    """
    if current_user.role not in {"doctor", "patient"}:
        raise HTTPException(status_code=403, detail="Doctor or patient access required.")

    # Patients always create sessions on their own patient_id. They
    # can't pick someone else's.
    patient_id = payload.patient_id
    if current_user.role == "patient":
        if not current_user.patient_id:
            raise HTTPException(
                status_code=404,
                detail="Your account is not linked to a patient record yet.",
            )
        patient_id = current_user.patient_id
    sess = models.MediEchoSession(
        doctor_user_id=(current_user.id if current_user.role == "doctor" else None),
        patient_id=patient_id,
        title=payload.title,
        status="recording",
    )
    db.add(sess)
    db.commit()
    db.refresh(sess)
    return _mediecho_session_to_out(db, sess)


@app.get("/mediecho/sessions", response_model=schemas.MediEchoSessionListOut)
def list_mediecho_sessions(
    limit: int = 50,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List the calling user's MediEcho sessions, most recent first.
    Doctors see their own; patients see sessions on their patient_id."""
    if current_user.role not in {"doctor", "patient"}:
        raise HTTPException(status_code=403, detail="Doctor or patient access required.")
    limit = max(1, min(200, int(limit or 50)))
    if current_user.role == "doctor":
        rows = (
            db.query(models.MediEchoSession)
            .filter(models.MediEchoSession.doctor_user_id == current_user.id)
            .order_by(models.MediEchoSession.created_at.desc())
            .limit(limit)
            .all()
        )
    else:
        rows = (
            db.query(models.MediEchoSession)
            .filter(models.MediEchoSession.patient_id == current_user.patient_id)
            .order_by(models.MediEchoSession.created_at.desc())
            .limit(limit)
            .all()
        )
    items = [_mediecho_session_to_out(db, r) for r in rows]
    return schemas.MediEchoSessionListOut(
        items=items, total_count=len(items),
    )


@app.get("/mediecho/sessions/{session_id}")
def get_mediecho_session(
    session_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Return the session + its transcript + its note (if any).
    Doctor or patient access; scope to caller."""
    if current_user.role not in {"doctor", "patient"}:
        raise HTTPException(status_code=403, detail="Doctor or patient access required.")
    if current_user.role == "doctor":
        sess = (
            db.query(models.MediEchoSession)
            .filter(
                models.MediEchoSession.id == session_id,
                models.MediEchoSession.doctor_user_id == current_user.id,
            )
            .first()
        )
    else:
        sess = (
            db.query(models.MediEchoSession)
            .filter(
                models.MediEchoSession.id == session_id,
                models.MediEchoSession.patient_id == current_user.patient_id,
            )
            .first()
        )
    if not sess:
        raise HTTPException(status_code=404, detail="MediEcho session not found")
    out = _mediecho_session_to_out(db, sess).model_dump()
    out["transcript"] = _mediecho_parse_transcript_json(sess.transcript_json)
    note = _mediecho_load_note(db, sess)
    out["note"] = _mediecho_note_to_out(note).model_dump() if note else None
    return out


@app.post("/mediecho/sessions/{session_id}/transcribe", response_model=schemas.MediEchoTranscribeOut)
async def transcribe_mediecho_session(
    session_id: int,
    file: UploadFile = File(...),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Accept an audio file, run Whisper STT, persist the segments to the
    session row, and return the structured transcript.

    The audio file is also stored on disk under UPLOAD_DIR so the doctor
    can re-transcribe later (e.g. after upgrading the model).

    Authorization: doctors can transcribe any of their own sessions
    (`doctor_user_id == current_user.id`); patients can transcribe any
    session on their own patient record (regardless of which doctor
    created it, if any). This used to be doctor-only, which 403'd the
    patient page after the 2026-08 patient-side recording flow was
    added.
    """
    if current_user.role not in ("doctor", "patient"):
        raise HTTPException(
            status_code=403,
            detail="Only doctor or patient accounts can transcribe MediEcho sessions.",
        )
    sess_q = (
        db.query(models.MediEchoSession)
        .filter(models.MediEchoSession.id == session_id)
    )
    if current_user.role == "doctor":
        sess_q = sess_q.filter(models.MediEchoSession.doctor_user_id == current_user.id)
    else:  # patient
        if not current_user.patient_id:
            raise HTTPException(status_code=404, detail="MediEcho session not found")
        sess_q = sess_q.filter(models.MediEchoSession.patient_id == current_user.patient_id)
    sess = sess_q.first()
    if not sess:
        raise HTTPException(status_code=404, detail="MediEcho session not found")

    content = await file.read()
    if not content:
        raise HTTPException(status_code=400, detail="Uploaded audio file is empty.")
    if len(content) > MAX_UPLOAD_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"File too large. Max {MAX_UPLOAD_BYTES // (1024 * 1024)} MB.",
        )

    # Validate it's actually an audio file we accept. We check both the
    # declared mime type AND the extension because browsers vary widely.
    safe_original = os.path.basename(file.filename or "recording.webm")
    ext = os.path.splitext(safe_original)[1].lower()
    declared_mime = (file.content_type or "").split(";")[0].strip().lower()
    if declared_mime not in ALLOWED_MEDIECHO_AUDIO_MIMES and ext not in ALLOWED_MEDIECHO_AUDIO_EXTS:
        raise HTTPException(
            status_code=415,
            detail=(
                "Unsupported audio format. Please upload webm / wav / mp3 / "
                "m4a / ogg / flac / aac."
            ),
        )

    if whisper_client is None:
        raise HTTPException(
            status_code=503,
            detail=(
                "Whisper STT is not available on the server. "
                "Install openai-whisper to enable MediEcho transcription."
            ),
        )

    # Persist the audio file first so a crash mid-STT still leaves the
    # audio on disk for retry.
    stored_name = f"mediecho_{sess.id}_{uuid.uuid4().hex}{ext or '.webm'}"
    stored_path = os.path.join(UPLOAD_DIR, stored_name)
    try:
        with open(stored_path, "wb") as f:
            f.write(content)
    except OSError as e:
        raise HTTPException(status_code=500, detail=f"Could not save the audio: {e}")

    # Run STT. This is the slow step (~5-30s on tiny.en, longer on bigger
    # models). We mark the session "transcribing" so the UI can show a
    # spinner on retry.
    sess.status = "transcribing"
    sess.audio_filename = safe_original
    sess.audio_stored_path = stored_path
    sess.mime_type = declared_mime or None
    sess.file_size = len(content)
    sess.error_message = None
    db.commit()

    try:
        result = whisper_client.transcribe_audio(stored_path, language="en")
    except Exception as e:
        sess.status = "failed"
        sess.error_message = f"STT failed: {e}"
        db.commit()
        raise HTTPException(status_code=500, detail=f"Transcription failed: {e}")

    segments = result.get("segments") or []
    sess.transcript_json = json.dumps(segments)
    sess.duration_seconds = float(result.get("duration") or 0.0)
    sess.stt_model = result.get("model")
    sess.status = "transcribed"
    db.commit()
    db.refresh(sess)

    return schemas.MediEchoTranscribeOut(
        session_id=sess.id,
        status=sess.status,
        duration=sess.duration_seconds or 0.0,
        model=sess.stt_model or "unknown",
        language=result.get("language") or "en",
        segments=[
            schemas.MediEchoTranscribeSegment(
                start=float(s.get("start") or 0.0),
                end=float(s.get("end") or 0.0),
                speaker=(s.get("speaker") or "patient"),
                text=(s.get("text") or "").strip(),
            )
            for s in segments
        ],
    )


@app.post("/mediecho/sessions/{session_id}/analyze", response_model=schemas.MediEchoAnalyzeOut)
def analyze_mediecho_session(
    session_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Run Gemini on the saved transcript and persist the structured note.
    Idempotent: re-running overwrites the previous extraction but never
    clobbers the doctor's manual edits (those live on edited_json)."""
    if current_user.role not in ("doctor", "patient"):
        raise HTTPException(
            status_code=403,
            detail="Only doctor or patient accounts can analyze MediEcho sessions.",
        )
    sess_q = (
        db.query(models.MediEchoSession)
        .filter(models.MediEchoSession.id == session_id)
    )
    if current_user.role == "doctor":
        sess_q = sess_q.filter(models.MediEchoSession.doctor_user_id == current_user.id)
    else:
        if not current_user.patient_id:
            raise HTTPException(status_code=404, detail="MediEcho session not found")
        sess_q = sess_q.filter(models.MediEchoSession.patient_id == current_user.patient_id)
    sess = sess_q.first()
    if not sess:
        raise HTTPException(status_code=404, detail="MediEcho session not found")
    if not sess.transcript_json:
        raise HTTPException(
            status_code=400,
            detail="No transcript on this session yet. Upload audio first.",
        )

    segments = _mediecho_parse_transcript_json(sess.transcript_json)
    if not segments:
        raise HTTPException(status_code=400, detail="Transcript is empty.")

    # Build a short patient context string so Gemini can resolve ambiguous
    # references ("my BP pill", "the diabetes drug"). Keeps the prompt
    # grounded and reduces hallucinated meds.
    ctx_parts: list[str] = []
    if sess.patient_id is not None:
        p = db.query(models.Patient).filter(models.Patient.id == sess.patient_id).first()
        if p:
            ctx_parts.append(f"{p.name}" + (f", age {p.age}" if p.age else "") + (f", {p.gender}" if p.gender else ""))
            profile = (
                db.query(models.PatientProfile)
                .filter(models.PatientProfile.patient_id == p.id)
                .first()
            )
            if profile and profile.blood_group:
                ctx_parts.append(f"blood group {profile.blood_group}")
    # Pull the 5 most recent medical history entries for this patient as
    # further grounding.
    if sess.patient_id is not None:
        history = (
            db.query(models.MedicalHistoryEntry)
            .filter(models.MedicalHistoryEntry.patient_id == sess.patient_id)
            .order_by(models.MedicalHistoryEntry.created_at.desc())
            .limit(5)
            .all()
        )
        for h in history:
            ctx_parts.append(f"{h.category}: {h.title}")
    patient_context = ", ".join(ctx_parts) if ctx_parts else None

    sess.status = "analyzing"
    sess.error_message = None
    db.commit()

    try:
        extracted = gemini_client.analyze_conversation(segments, patient_context=patient_context)
    except Exception as e:
        sess.status = "failed"
        sess.error_message = f"Analysis failed: {e}"
        db.commit()
        raise HTTPException(status_code=500, detail=f"Analysis failed: {e}")

    extracted_obj = schemas.MediEchoExtractedNote.model_validate(extracted)
    highlights = extracted.get("highlights") or []
    summary_text = extracted.get("summary") or ""

    note = _mediecho_load_note(db, sess)
    if note is None:
        note = models.MediEchoNote(session_id=sess.id, status="draft")
        db.add(note)
    note.extracted_json = json.dumps(extracted_obj.model_dump())
    note.summary = summary_text
    note.highlights_json = json.dumps(highlights)
    # Preserve edited_json if the doctor has already edited; otherwise
    # seed it from the extracted output so the editor is populated.
    if not note.edited_json:
        note.edited_json = json.dumps(extracted_obj.model_dump())
    # status stays "draft" until the doctor explicitly approves.
    sess.status = "ready"
    db.commit()
    db.refresh(note)
    db.refresh(sess)

    return schemas.MediEchoAnalyzeOut(
        session_id=sess.id,
        status=sess.status,
        extracted=extracted_obj,
        transcript=[
            schemas.MediEchoTranscribeSegment(
                start=float(s.get("start") or 0.0),
                end=float(s.get("end") or 0.0),
                speaker=(s.get("speaker") or "patient"),
                text=(s.get("text") or "").strip(),
            )
            for s in segments
        ],
    )


@app.put("/mediecho/sessions/{session_id}/note", response_model=schemas.MediEchoNoteOut)
def update_mediecho_note(
    session_id: int,
    payload: schemas.MediEchoNoteUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Save edits to the structured note. Edits are stored on the note's
    edited_json column so the AI's first pass is preserved for audit.
    Passing ``summary`` updates the note's standalone summary field,
    which is what gets used when the note is saved to a chart.

    Both doctors and patients can edit notes on sessions they own. The
    2026-08 patient flow lets patients review and correct their own
    MediEcho before saving it to their record, so locking this to
    doctors would 403 the patient page.
    """
    if current_user.role not in ("doctor", "patient"):
        raise HTTPException(
            status_code=403,
            detail="Only doctor or patient accounts can edit MediEcho notes.",
        )
    sess_q = (
        db.query(models.MediEchoSession)
        .filter(models.MediEchoSession.id == session_id)
    )
    if current_user.role == "doctor":
        sess_q = sess_q.filter(models.MediEchoSession.doctor_user_id == current_user.id)
    else:
        if not current_user.patient_id:
            raise HTTPException(status_code=404, detail="MediEcho session not found")
        sess_q = sess_q.filter(models.MediEchoSession.patient_id == current_user.patient_id)
    sess = sess_q.first()
    if not sess:
        raise HTTPException(status_code=404, detail="MediEcho session not found")
    note = _mediecho_load_note(db, sess)
    if note is None:
        raise HTTPException(
            status_code=400,
            detail="No note on this session yet. Run /analyze first.",
        )

    # Start from the previous edited_json (or extracted_json if never edited)
    # so partial PATCHes merge correctly.
    base_raw = note.edited_json or note.extracted_json or "{}"
    try:
        base = json.loads(base_raw)
    except json.JSONDecodeError:
        base = {}
    if not isinstance(base, dict):
        base = {}

    incoming = payload.model_dump(exclude_unset=True)
    for k, v in incoming.items():
        if v is not None:
            base[k] = v
    # Validate severity.
    if "severity" in base:
        sev = (str(base["severity"] or "unknown")).strip().lower()
        base["severity"] = sev if sev in {"mild", "moderate", "severe", "unknown"} else "unknown"

    note.edited_json = json.dumps(base)
    if payload.summary is not None:
        note.summary = payload.summary.strip() or None
    db.commit()
    db.refresh(note)
    return _mediecho_note_to_out(note)


@app.post("/mediecho/sessions/{session_id}/approve", response_model=schemas.MediEchoNoteOut)
def approve_mediecho_note(
    session_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Mark the note as approved. Approval is required before the note
    can be saved to a patient chart. Doesn't write to the chart by itself."""
    _ensure_doctor(current_user)
    sess = (
        db.query(models.MediEchoSession)
        .filter(
            models.MediEchoSession.id == session_id,
            models.MediEchoSession.doctor_user_id == current_user.id,
        )
        .first()
    )
    if not sess:
        raise HTTPException(status_code=404, detail="MediEcho session not found")
    note = _mediecho_load_note(db, sess)
    if note is None:
        raise HTTPException(status_code=400, detail="No note to approve.")
    note.status = "approved"
    note.approved_at = datetime.utcnow()
    db.commit()
    db.refresh(note)
    return _mediecho_note_to_out(note)


@app.post("/mediecho/sessions/{session_id}/save-to-record", response_model=schemas.MediEchoSaveToRecordOut)
def save_mediecho_to_record(
    session_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Promote the approved note to a real MedicalRecord on the patient
    chart. Each prescribed medicine becomes a Prescription row. This is
    the terminal save — once done, the MediEcho session is marked saved.

    Both doctors and patients can drive this endpoint. The ownership
    check is relaxed for patients — they have to have the session
    linked to their own patient_id. When a patient is the caller, the
    flow also auto-creates a MedicalHistoryEntry (transcript + summary
    in text form) and a PatientReport (audio file as a downloadable
    document)."""
    role = current_user.role
    if role not in {"doctor", "patient"}:
        raise HTTPException(
            status_code=403,
            detail="Only doctors or patients can save MediEcho sessions.",
        )
    # Scope to the caller's row. Doctors see their own session; patients
    # see sessions created on their own patient_id. The patient's
    # session has doctor_user_id NULL (created standalone) — we
    # bypass that for the patient branch with a "patient-only" query.
    if role == "doctor":
        sess = (
            db.query(models.MediEchoSession)
            .filter(
                models.MediEchoSession.id == session_id,
                models.MediEchoSession.doctor_user_id == current_user.id,
            )
            .first()
        )
    else:
        # Patient branch — own session only (allow NULL doctor_user_id).
        sess = (
            db.query(models.MediEchoSession)
            .filter(
                models.MediEchoSession.id == session_id,
                models.MediEchoSession.patient_id == current_user.patient_id,
            )
            .first()
        )
    if not sess:
        raise HTTPException(status_code=404, detail="MediEcho session not found")
    if sess.patient_id is None:
        raise HTTPException(
            status_code=400,
            detail="This session is not linked to a patient. Link a patient to save the note.",
        )
    note = _mediecho_load_note(db, sess)
    if note is None:
        raise HTTPException(status_code=400, detail="No note on this session.")
    if role == "doctor" and note.status not in {"approved", "saved"}:
        raise HTTPException(
            status_code=400,
            detail="Note must be approved before it can be saved to the chart.",
        )
    if role == "patient" and note.status not in {"draft", "saved"}:
        # Patients can save without an explicit approve step. Drafts
        # move straight to "saved". Approved doctor's notes stay
        # permission-gated.
        pass
    if note.saved_to_record_id is not None:
        # Already saved — return the existing record id so re-clicks are idempotent.
        return schemas.MediEchoSaveToRecordOut(
            medical_record_id=note.saved_to_record_id,
            prescription_ids=[],
            note_status=note.status,
        )

    # Ensure the caller has access to the patient.
    _ensure_patient_access(current_user, sess.patient_id, db)

    # Load the edited (or extracted) note payload for fields.
    raw = note.edited_json or note.extracted_json or "{}"
    try:
        edited = json.loads(raw)
    except json.JSONDecodeError:
        edited = {}
    if not isinstance(edited, dict):
        edited = {}

    # Build the MedicalRecord. We store the chief complaint in 'symptoms'
    # and the structured findings in 'diagnosis' so the existing chart
    # renderer picks them up. Notes get the doctor's edited summary plus
    # the rest of the structured fields as a JSON blob for downstream
    # consumers (chart pages, exports, etc.).
    symptoms_field = (edited.get("chief_complaint") or "").strip()
    diagnosis_parts: list[str] = []
    sev = (edited.get("severity") or "unknown").strip().lower()
    if sev in {"mild", "moderate", "severe", "unknown"} and sev != "unknown":
        diagnosis_parts.append(f"Severity: {sev}")
    if edited.get("doctor_observations"):
        diagnosis_parts.append("Observations: " + "; ".join(edited["doctor_observations"]))
    if edited.get("recommended_tests"):
        diagnosis_parts.append("Tests ordered: " + "; ".join(edited["recommended_tests"]))
    if edited.get("referrals"):
        diagnosis_parts.append("Referrals: " + "; ".join(edited["referrals"]))
    if edited.get("follow_ups"):
        diagnosis_parts.append("Follow-ups: " + "; ".join(edited["follow_ups"]))
    diagnosis_field = "\n".join(diagnosis_parts) or None

    notes_parts: list[str] = []
    summary_text = (note.summary or edited.get("summary") or "").strip()
    if summary_text:
        notes_parts.append(summary_text)
    if edited.get("symptoms"):
        notes_parts.append("Symptoms: " + "; ".join(edited["symptoms"]))
    if edited.get("history"):
        notes_parts.append("History: " + "; ".join(edited["history"]))
    if edited.get("allergies"):
        notes_parts.append("Allergies: " + "; ".join(edited["allergies"]))
    if edited.get("current_medications"):
        notes_parts.append("Current medications: " + "; ".join(edited["current_medications"]))
    if edited.get("duration"):
        notes_parts.append(f"Duration: {edited['duration']}")
    notes_parts.append(
        f"\n[Source: MediEcho session #{sess.id}, generated from doctor-patient conversation]"
    )
    notes_field = "\n".join(notes_parts)

    record = models.MedicalRecord(
        patient_id=sess.patient_id,
        symptoms=symptoms_field or None,
        diagnosis=diagnosis_field,
        notes=notes_field,
    )
    db.add(record)
    db.flush()  # populate record.id

    # Persist prescribed medicines as Prescription rows.
    prescription_ids: list[int] = []
    for med in (edited.get("prescribed_medicines") or []):
        if not isinstance(med, dict):
            continue
        name = (med.get("name") or "").strip()
        if not name:
            continue
        dosage = (med.get("dosage") or "").strip()
        freq = (med.get("frequency") or "").strip()
        duration = (med.get("duration") or "").strip()
        notes_blob = (med.get("notes") or "").strip()
        instructions = " | ".join(
            [p for p in [freq, duration, notes_blob] if p]
        ) or None
        rx = models.Prescription(
            patient_id=sess.patient_id,
            medicine_name=name,
            dosage=dosage or None,
            instructions=instructions,
        )
        db.add(rx)
        db.flush()
        prescription_ids.append(rx.id)

    note.saved_to_record_id = record.id
    note.status = "saved"
    note.saved_at = datetime.utcnow()
    sess.status = "saved"

    # 2026-08: Patient-driven MediEcho also drops two artefacts onto
    # the patient's chart so the record history tab immediately surfaces
    # the session:
    #   1. A MedicalHistoryEntry (category "other") carrying the
    #      session's transcript + summary in text form. Doctors can
    #      later move / edit it if they want.
    #   2. A PatientReport row pointing at the original audio file —
    #      it shows up under the documents tab with a download link.
    if current_user.role == "patient" and sess.patient_id:
        try:
            transcript_json = sess.transcript_json or "[]"
            try:
                transcript_obj = json.loads(transcript_json)
                transcript_lines = []
                if isinstance(transcript_obj, list):
                    for turn in transcript_obj:
                        if not isinstance(turn, dict):
                            continue
                        spk = turn.get("speaker") or "speaker"
                        txt = (turn.get("text") or "").strip()
                        if txt:
                            transcript_lines.append(f"{spk}: {txt}")
                transcript_text = "\n".join(transcript_lines)
            except Exception:
                transcript_text = transcript_json

            db.add(models.MedicalHistoryEntry(
                patient_id=sess.patient_id,
                category="other",
                title=f"MediEcho session #{sess.id} — patient upload",
                details=((note.summary or "") + ("\n\nTranscript:\n" + transcript_text if transcript_text else "")).strip(),
                is_ongoing=False,
            ))
            if sess.audio_stored_path and os.path.exists(sess.audio_stored_path):
                db.add(models.PatientReport(
                    patient_id=sess.patient_id,
                    title=(sess.title or f"MediEcho session #{sess.id}"),
                    category="other",
                    file_name=os.path.basename(sess.audio_stored_path),
                    stored_path=sess.audio_stored_path,
                    mime_type=sess.mime_type or "audio/webm",
                    file_size=sess.file_size,
                    uploaded_by_user_id=current_user.id,
                    notes="Auto-saved from MediEcho session #" + str(sess.id),
                ))
        except Exception as e:
            # Don't crash the save on a best-effort artefact.
            print(f"[mediecho save-to-record] patient artefact step skipped: {e}")

    db.commit()

    return schemas.MediEchoSaveToRecordOut(
        medical_record_id=record.id,
        prescription_ids=prescription_ids,
        note_status=note.status,
    )


@app.delete("/mediecho/sessions/{session_id}", status_code=204)
def delete_mediecho_session(
    session_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Delete a MediEcho session + its note + the audio file on disk.
    If the note was already saved to a chart, the chart entry stays —
    MediEcho is a 'source', not the canonical chart record.

    Doctors delete their own sessions; patients delete sessions linked
    to their own patient_id."""
    if current_user.role not in ("doctor", "patient"):
        raise HTTPException(
            status_code=403,
            detail="Only doctor or patient accounts can delete MediEcho sessions.",
        )
    sess_q = (
        db.query(models.MediEchoSession)
        .filter(models.MediEchoSession.id == session_id)
    )
    if current_user.role == "doctor":
        sess_q = sess_q.filter(models.MediEchoSession.doctor_user_id == current_user.id)
    else:
        if not current_user.patient_id:
            raise HTTPException(status_code=404, detail="MediEcho session not found")
        sess_q = sess_q.filter(models.MediEchoSession.patient_id == current_user.patient_id)
    sess = sess_q.first()
    if not sess:
        raise HTTPException(status_code=404, detail="MediEcho session not found")
    # Best-effort: remove audio from disk.
    if sess.audio_stored_path and os.path.exists(sess.audio_stored_path):
        try:
            os.remove(sess.audio_stored_path)
        except OSError:
            pass
    db.delete(sess)  # cascades to note
    db.commit()
    return Response(status_code=204)


# ============================================================
# AI Doctor (2026-08-23) — patient-only chat with Dr. Mira
# ---------------------------------------------------------------------
# Patient-facing text + image chat. The backend holds the
# authoritative session + message history (so a refresh doesn't lose
# context). All endpoints are scoped to the caller's user_id so two
# patients on the same account — or one patient using two devices —
# can never see each other's chats. The AI reply is generated by
# gemini_client.ai_doctor_chat which uses a conservative, clinically-
# grounded persona and refuses anything that smells like a medical
# emergency or a prescription request.
# ============================================================


def _ai_doctor_route_query(message: str, db: Session, patient_id: int,
                          session_id: int = None):
    """Intent-route a user message: classify intent, execute only the
    required tools, gather medical evidence if needed, and return the
    tools_context + medical_evidence + metadata.

    Uses conversation state tracking to detect follow-ups and context switches.
    """
    metadata = {
        "intent": "NORMAL_CHAT",
        "used_patient_data": False,
        "tools_called": [],
        "sources_used": [],
    }
    tools_context = {"context_text": "", "tools_called": [], "intent": "NORMAL_CHAT"}

    # Get conversation state for follow-up detection
    conv_state = None
    if session_id and intent_router:
        conv_state = intent_router.get_conversation_state(session_id)

    # Step 1: Classify intent
    intent_result = None
    if intent_router:
        try:
            from gemini_client import _nemotron_chat as _llm
            # Classify intent first (keyword-based is fast and reliable)
            intent_result = intent_router.classify_intent(message, llm_func=_llm)
            # Only use follow-up detection for ambiguous messages that
            # the keyword classifier couldn't handle (confidence < 0.8)
            if (intent_result and intent_result.confidence < 0.8 and
                    conv_state and conv_state.is_follow_up(message) and
                    conv_state.last_patient_data_used):
                intent_result = intent_router.IntentResult(
                    intent=conv_state.last_intent or "PATIENT_SPECIFIC",
                    requires_patient_data=True,
                    required_tools=conv_state.last_tools_used,
                    confidence=0.7,
                    reasoning="Follow-up to previous patient-data topic",
                )
        except Exception as exc:
            logger.debug("Intent classification failed: %s", exc)
    if intent_result is None:
        from dataclasses import dataclass
        @dataclass
        class _FallbackIntent:
            intent: str = "GENERAL_MEDICAL"
            requires_patient_data: bool = False
            required_tools: list = None
            confidence: float = 0.5
        intent_result = _FallbackIntent()
        intent_result.required_tools = []

    metadata["intent"] = intent_result.intent
    tools_context["intent"] = intent_result.intent

    logger.info(
        "AI Doctor intent: %s (confidence=%.2f, patient_data=%s, tools=%s)",
        intent_result.intent, intent_result.confidence,
        intent_result.requires_patient_data, intent_result.required_tools,
    )

    # Step 2: Execute tools ONLY if the intent requires patient data
    if intent_result.requires_patient_data and tools_registry and patient_id:
        tool_names = intent_router.get_tool_names_for_intent(intent_result)
        if tool_names:
            try:
                tool_result = tools_registry.execute_tools(
                    tool_names, db, patient_id, user_query=message,
                )
                tools_context["context_text"] = tool_result.get("context_text", "")
                tools_context["tools_called"] = tool_result.get("tools_called", [])
                metadata["used_patient_data"] = True
                metadata["tools_called"] = tool_result.get("tools_called", [])
            except Exception as exc:
                logger.warning("Tool execution failed: %s", exc)

    # Step 3: Gather medical knowledge for GENERAL_MEDICAL, PATIENT_SPECIFIC,
    # MEDICINE_INFO, MEDICINE_INTERACTION
    medical_evidence = None
    knowledge_intents = {
        intent_router.Intent.GENERAL_MEDICAL if intent_router else "GENERAL_MEDICAL",
        intent_router.Intent.MEDICINE_INFO if intent_router else "MEDICINE_INFO",
        intent_router.Intent.MEDICINE_INTERACTION if intent_router else "MEDICINE_INTERACTION",
        intent_router.Intent.PATIENT_SPECIFIC if intent_router else "PATIENT_SPECIFIC",
    }
    if intent_result.intent in knowledge_intents and med_knowledge and getattr(config, 'EVIDENCE_SERVICE_ENABLED', True):
        try:
            med_ev = med_knowledge.gather_medical_evidence(message, db)
            medical_evidence = {
                "medical_evidence": med_knowledge.format_evidence_for_prompt(med_ev),
                "sources_used": [
                    {"name": s.get("source", ""), "url": s.get("source_url", "")}
                    for s in (med_ev or {}).values()
                    if isinstance(s, dict) and s.get("available")
                ],
            }
            metadata["sources_used"] = [s["name"] for s in medical_evidence["sources_used"]]
        except Exception as exc:
            logger.debug("Medical knowledge fetch failed: %s", exc)

    return tools_context, medical_evidence, metadata


def _ai_doctor_session_to_out(db: Session, s: models.AIDoctorSession) -> schemas.AIDoctorSessionOut:
    """Build the session summary with denormalized message_count + last
    assistant preview so the history sidebar doesn't need a join."""
    msg_count = (
        db.query(models.AIDoctorMessage)
        .filter(models.AIDoctorMessage.session_id == s.id)
        .count()
    )
    last_assistant = (
        db.query(models.AIDoctorMessage)
        .filter(
            models.AIDoctorMessage.session_id == s.id,
            models.AIDoctorMessage.role == "assistant",
        )
        .order_by(models.AIDoctorMessage.created_at.desc())
        .first()
    )
    preview = None
    if last_assistant and last_assistant.content:
        preview = last_assistant.content[:120].replace("\n", " ").strip()
    return schemas.AIDoctorSessionOut(
        id=s.id,
        patient_id=s.patient_id,
        user_id=s.user_id,
        title=s.title,
        status=s.status,
        summary=s.summary,
        created_at=s.created_at,
        last_active_at=s.last_active_at,
        message_count=msg_count,
        last_message_preview=preview,
    )


def _ai_doctor_message_to_out(m: models.AIDoctorMessage) -> schemas.AIDoctorMessageOut:
    """Build a message DTO. media_url is built relative to /uploads/ —
    the static handler in main.py already serves UPLOAD_DIR there."""
    media_url = None
    if m.media_stored_path and m.media_filename:
        # Stored_path is absolute (under UPLOAD_DIR); we only need the
        # basename so /uploads/ can find it.
        try:
            media_url = f"/uploads/{os.path.basename(m.media_stored_path)}"
        except Exception:
            media_url = None
    return schemas.AIDoctorMessageOut(
        id=m.id,
        session_id=m.session_id,
        role=m.role,
        content=m.content,
        media_filename=m.media_filename,
        media_mime=m.media_mime,
        media_size=m.media_size,
        media_url=media_url,
        status=m.status,
        latency_ms=m.latency_ms,
        created_at=m.created_at,
    )


def _ai_doctor_patient_context(db: Session, patient_id: int) -> str:
    """Build a comprehensive clinical context from all available patient
    evidence: demographics, medical history, prescriptions, lab values,
    scan results, treatments, vitals, and nursing notes.

    Captured once at session-create time so the demographic profile is
    stable for the lifetime of the session.
    """
    # Use the evidence service for comprehensive context
    if evidence_service:
        try:
            evidence = evidence_service.build_patient_evidence(db, patient_id)
            return evidence_service.format_patient_evidence_for_prompt(
                evidence, max_chars=getattr(config, 'EVIDENCE_MAX_CONTEXT_CHARS', 4000)
            )
        except Exception as exc:
            logger.warning("Evidence service failed, falling back to basic context: %s", exc)

    # Fallback: basic context (original implementation)
    p = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    if not p:
        return ""
    profile = (
        db.query(models.PatientProfile)
        .filter(models.PatientProfile.patient_id == patient_id)
        .first()
    )
    bits = []
    if p.name: bits.append(f"Name: {p.name}")
    if p.age is not None: bits.append(f"Age: {p.age}")
    if p.gender: bits.append(f"Gender: {p.gender}")
    if p.contact: bits.append(f"Contact on file: {p.contact}")
    recent_history = (
        db.query(models.MedicalHistoryEntry)
        .filter(models.MedicalHistoryEntry.patient_id == patient_id)
        .order_by(models.MedicalHistoryEntry.created_at.desc())
        .limit(6)
        .all()
    )
    if recent_history:
        titles = [h.title for h in recent_history if h.title]
        if titles:
            bits.append("Known history on file: " + "; ".join(titles[:6]))
    if profile:
        for label, attr in (
            ("Blood group", "blood_group"),
            ("Occupation", "occupation"),
            ("Marital status", "marital_status"),
            ("Smoking", "smoking"),
            ("Alcohol", "alcohol"),
            ("Diet", "diet"),
            ("Exercise", "exercise"),
            ("Sleep", "sleep_hours"),
            ("City", "city"),
            ("State", "country"),
        ):
            try:
                val = getattr(profile, attr)
            except AttributeError:
                continue
            if val:
                bits.append(f"{label}: {val}")
    return "\n".join(bits) if bits else "Patient has no profile data on file yet."


def _ai_doctor_title_from_message(text: str) -> str:
    """Auto-generate a session title from the first user message —
    first sentence, capped at 60 chars."""
    text = (text or "").strip()
    if not text:
        return "New chat"
    # Take first sentence (split on . ! ?).
    for sep in (".", "!", "?"):
        idx = text.find(sep)
        if 0 < idx < 80:
            text = text[:idx]
            break
    text = " ".join(text.split())  # collapse whitespace
    if len(text) > 60:
        text = text[:57].rstrip() + "…"
    return text or "New chat"


@app.post("/ai-doctor/sessions", response_model=schemas.AIDoctorSessionDetailOut, status_code=201)
def create_ai_doctor_session(
    payload: schemas.AIDoctorSessionCreate = schemas.AIDoctorSessionCreate(),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Open a new AI Doctor chat session. Patient-only — doctors have
    their own Mediecho + MediScan workflows. The optional `initial_message`
    seeds the first user turn and immediately generates the AI reply
    so the chat UI can land the patient straight into the conversation."""
    if current_user.role != "patient":
        raise HTTPException(
            status_code=403,
            detail="AI Doctor is only available to patient accounts.",
        )
    if not current_user.patient_id:
        raise HTTPException(
            status_code=404,
            detail="Your account is not linked to a patient record yet.",
        )
    # Store minimal demographic context at creation — full patient data
    # is loaded on-demand by the intent router when the user's question
    # actually requires it.
    patient = db.query(models.Patient).filter(models.Patient.id == current_user.patient_id).first()
    ctx = f"Patient: {patient.name or ''}, Age: {patient.age or ''}, Gender: {patient.gender or ''}".strip() if patient else ""
    sess = models.AIDoctorSession(
        patient_id=current_user.patient_id,
        user_id=current_user.id,
        title=(payload.title or "").strip() or None,
        status="active",
        patient_context_json=ctx,
        created_at=datetime.utcnow(),
        last_active_at=datetime.utcnow(),
    )
    db.add(sess)
    db.flush()  # need sess.id

    messages_out = []
    initial_text = (payload.initial_message or "").strip()
    if initial_text:
        user_msg = models.AIDoctorMessage(
            session_id=sess.id,
            role="user",
            content=initial_text,
            created_at=datetime.utcnow(),
        )
        db.add(user_msg)
        db.flush()
        messages_out.append(_ai_doctor_message_to_out(user_msg))
        if not sess.title:
            sess.title = _ai_doctor_title_from_message(initial_text)

        # First-turn AI reply. Use intent router for selective data retrieval.
        history_for_ai = [
            {"role": "user", "content": initial_text, "has_media": False},
        ]
        t0 = datetime.utcnow()
        persona_name = _ai_doctor_resolve_persona(db, current_user)
        tools_ctx, medical_ev, intent_meta = _ai_doctor_route_query(
            initial_text, db, current_user.patient_id,
            session_id=sess.id,
        )
        reply = gemini_client.ai_doctor_chat(
            history_for_ai,
            patient_context=ctx,
            persona_name=persona_name,
            patient_id=current_user.patient_id,
            medical_evidence=medical_ev,
            tools_context=tools_ctx,
        )
        latency = int((datetime.utcnow() - t0).total_seconds() * 1000)
        ai_msg = models.AIDoctorMessage(
            session_id=sess.id,
            role="assistant",
            content=reply.get("text") or "",
            status=reply.get("status") or "ok",
            latency_ms=latency,
            created_at=datetime.utcnow(),
        )
        db.add(ai_msg)
        db.flush()
        messages_out.append(_ai_doctor_message_to_out(ai_msg))
        sess.last_active_at = datetime.utcnow()
        # Surface Gemini errors so the client doesn't see an empty bubble.
        first_turn_failed = (reply.get("status") or "ok") != "ok"
        first_turn_error = reply.get("error_message")

    db.commit()
    db.refresh(sess)
    # RAG: index the new messages so the next turn has context.
    if initial_text and (user_msg.content or "").strip():
        db.refresh(user_msg)
        _ai_doctor_index_message(user_msg)
    if initial_text and (ai_msg.content or "").strip():
        db.refresh(ai_msg)
        _ai_doctor_index_message(ai_msg)
    # Fire-and-forget bulk index of the patient's existing corpus so the
    # very next message in this session has history to retrieve from.
    _ai_doctor_index_patient_corpus(current_user.patient_id)
    if initial_text and first_turn_failed:
        err = first_turn_error or "AI service error"
        logger.warning("AI Doctor first-turn Gemini call failed: %s", err)
        raise HTTPException(status_code=502, detail=err)
    return schemas.AIDoctorSessionDetailOut(
        session=_ai_doctor_session_to_out(db, sess),
        messages=messages_out,
    )


@app.get("/ai-doctor/sessions", response_model=schemas.AIDoctorSessionListOut)
def list_ai_doctor_sessions(
    limit: int = 50,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List the caller's own AI Doctor sessions, most recent first."""
    if current_user.role != "patient":
        raise HTTPException(
            status_code=403,
            detail="AI Doctor is only available to patient accounts.",
        )
    limit = max(1, min(200, int(limit or 50)))
    rows = (
        db.query(models.AIDoctorSession)
        .filter(models.AIDoctorSession.user_id == current_user.id)
        .order_by(models.AIDoctorSession.last_active_at.desc())
        .limit(limit)
        .all()
    )
    items = [_ai_doctor_session_to_out(db, s) for s in rows]
    return schemas.AIDoctorSessionListOut(items=items, total_count=len(items))


@app.get("/ai-doctor/sessions/{session_id}", response_model=schemas.AIDoctorSessionDetailOut)
def get_ai_doctor_session(
    session_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Get a session + its full message list. Scope to the caller so a
    patient can never read another patient's chat."""
    if current_user.role != "patient":
        raise HTTPException(
            status_code=403,
            detail="AI Doctor is only available to patient accounts.",
        )
    sess = (
        db.query(models.AIDoctorSession)
        .filter(
            models.AIDoctorSession.id == session_id,
            models.AIDoctorSession.user_id == current_user.id,
        )
        .first()
    )
    if not sess:
        raise HTTPException(status_code=404, detail="Chat session not found")
    msgs = (
        db.query(models.AIDoctorMessage)
        .filter(models.AIDoctorMessage.session_id == sess.id)
        .order_by(models.AIDoctorMessage.created_at.asc())
        .all()
    )
    return schemas.AIDoctorSessionDetailOut(
        session=_ai_doctor_session_to_out(db, sess),
        messages=[_ai_doctor_message_to_out(m) for m in msgs],
    )


@app.delete("/ai-doctor/sessions/{session_id}", status_code=204)
def delete_ai_doctor_session(
    session_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Delete a chat session. Cascades to messages. The patient can
    always start a new one — we don't preserve chats forever."""
    if current_user.role != "patient":
        raise HTTPException(
            status_code=403,
            detail="AI Doctor is only available to patient accounts.",
        )
    sess = (
        db.query(models.AIDoctorSession)
        .filter(
            models.AIDoctorSession.id == session_id,
            models.AIDoctorSession.user_id == current_user.id,
        )
        .first()
    )
    if not sess:
        raise HTTPException(status_code=404, detail="Chat session not found")
    # Best-effort: remove uploaded media files. Skip silently if a
    # file's already gone — deleting the row is the important bit.
    for m in (
        db.query(models.AIDoctorMessage)
        .filter(
            models.AIDoctorMessage.session_id == sess.id,
            models.AIDoctorMessage.media_stored_path.isnot(None),
        )
        .all()
    ):
        if m.media_stored_path and os.path.exists(m.media_stored_path):
            try:
                os.remove(m.media_stored_path)
            except OSError:
                pass
    db.delete(sess)
    db.commit()
    return Response(status_code=204)


def _ai_doctor_ensure_session_active(db: Session, current_user, session_id):
    """Helper: load + authorize + refuse closed sessions. Returns the
    AIDoctorSession row."""
    if current_user.role != "patient":
        raise HTTPException(
            status_code=403,
            detail="AI Doctor is only available to patient accounts.",
        )
    sess = (
        db.query(models.AIDoctorSession)
        .filter(
            models.AIDoctorSession.id == session_id,
            models.AIDoctorSession.user_id == current_user.id,
        )
        .first()
    )
    if not sess:
        raise HTTPException(status_code=404, detail="Chat session not found")
    return sess


def _ai_doctor_build_history(db: Session, session_id: int, max_turns: int = 30):
    """Pull the most recent N messages as a list of plain dicts ready
    for gemini_client.ai_doctor_chat. We use the newlines-preserved
    `content` field directly; media_filename is collapsed to a marker
    because Gemini already saw the actual bytes on the turn they were
    attached to."""
    msgs = (
        db.query(models.AIDoctorMessage)
        .filter(models.AIDoctorMessage.session_id == session_id)
        .order_by(models.AIDoctorMessage.created_at.asc())
        .all()
    )
    out = []
    for m in msgs[-max_turns:]:
        out.append({
            "role": m.role,
            "content": m.content or "",
            "has_media": bool(m.media_filename),
        })
    return out


@app.post(
    "/ai-doctor/sessions/{session_id}/messages-text",
    response_model=schemas.AIDoctorMessageListOut,
)
def post_ai_doctor_text_message(
    session_id: int,
    payload: schemas.AIDoctorMessageCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Append a text-only user turn and stream the AI reply back as two
    new messages. Media attachments go through the multipart endpoint
    below — keeping the JSON path clean means the frontend can call it
    with a regular fetch."""
    sess = _ai_doctor_ensure_session_active(db, current_user, session_id)
    if sess.status == "closed":
        raise HTTPException(status_code=409, detail="This chat is closed. Open a new one to continue.")
    if not payload.content:
        raise HTTPException(status_code=400, detail="Message can't be empty.")

    user_msg = models.AIDoctorMessage(
        session_id=sess.id,
        role="user",
        content=payload.content,
        created_at=datetime.utcnow(),
    )
    db.add(user_msg)
    if not sess.title:
        sess.title = _ai_doctor_title_from_message(payload.content)
    db.flush()

    history = _ai_doctor_build_history(db, sess.id)
    ctx = sess.patient_context_json or _ai_doctor_patient_context(db, sess.patient_id or 0)

    t0 = datetime.utcnow()
    persona_name = _ai_doctor_resolve_persona(db, current_user)
    # Intent-based routing for selective data retrieval
    tools_ctx, medical_ev, intent_meta = _ai_doctor_route_query(
        payload.content, db, sess.patient_id or 0,
        session_id=sess.id,
    )
    reply = gemini_client.ai_doctor_chat(
        history,
        patient_context=ctx,
        persona_name=persona_name,
        patient_id=sess.patient_id,
        medical_evidence=medical_ev,
        tools_context=tools_ctx,
    )
    latency = int((datetime.utcnow() - t0).total_seconds() * 1000)

    ai_msg = models.AIDoctorMessage(
        session_id=sess.id,
        role="assistant",
        content=reply.get("text") or "",
        status=reply.get("status") or "ok",
        latency_ms=latency,
        created_at=datetime.utcnow(),
    )
    if (reply.get("status") or "ok") != "ok" and reply.get("error_message"):
        logger.warning("AI Doctor Gemini call failed: %s", reply["error_message"])
        raise HTTPException(status_code=502, detail=reply["error_message"])
    db.add(ai_msg)
    sess.last_active_at = datetime.utcnow()
    db.commit()
    db.refresh(user_msg)
    db.refresh(ai_msg)
    # Record conversation state for follow-up detection
    if intent_router and sess.id:
        try:
            conv = intent_router.get_conversation_state(sess.id)
            conv.record_turn(
                payload.content,
                intent_meta.get("intent", "NORMAL_CHAT"),
                tools_used=intent_meta.get("tools_called", []),
                used_patient_data=intent_meta.get("used_patient_data", False),
            )
        except Exception:
            pass
    # RAG: index the new user/assistant messages so future turns can
    # recall them. Best-effort — never blocks the response.
    if (user_msg.content or "").strip():
        _ai_doctor_index_message(user_msg)
    if (ai_msg.content or "").strip():
        _ai_doctor_index_message(ai_msg)
    return schemas.AIDoctorMessageListOut(
        items=[_ai_doctor_message_to_out(user_msg), _ai_doctor_message_to_out(ai_msg)],
        total_count=2,
    )


# Multipart with optional media. Capped at 8 MB (medical images can be
# big) and accepted mime types are images + PDF.
AI_DOCTOR_MAX_UPLOAD_BYTES = 8 * 1024 * 1024
AI_DOCTOR_ACCEPTED_MIMES = {
    "image/jpeg", "image/jpg", "image/png", "image/webp", "image/gif",
    "application/pdf",
}


@app.post(
    "/ai-doctor/sessions/{session_id}/messages",
    response_model=schemas.AIDoctorMessageListOut,
)
async def post_ai_doctor_message(
    session_id: int,
    content: str = Form(""),
    file: Optional[UploadFile] = File(None),
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Append a user turn (text + optional image/PDF attachment) and
    generate the AI reply. The media is sent to Gemini as a multimodal
    part on THIS turn so the AI can actually look at the image."""
    sess = _ai_doctor_ensure_session_active(db, current_user, session_id)
    if sess.status == "closed":
        raise HTTPException(status_code=409, detail="This chat is closed. Open a new one to continue.")

    content = (content or "").strip()
    if not content and not file:
        raise HTTPException(status_code=400, detail="Type a message or attach an image.")

    media_bytes: Optional[bytes] = None
    media_mime: Optional[str] = None
    media_stored_path: Optional[str] = None
    media_filename: Optional[str] = None
    media_size: Optional[int] = None

    if file is not None:
        media_bytes = await file.read()
        if len(media_bytes) > AI_DOCTOR_MAX_UPLOAD_BYTES:
            raise HTTPException(
                status_code=413,
                detail=f"File too large. Max {AI_DOCTOR_MAX_UPLOAD_BYTES // (1024*1024)} MB.",
            )
        if not media_bytes:
            raise HTTPException(status_code=400, detail="Uploaded file is empty.")
        media_mime = (file.content_type or "").lower() or None
        if media_mime and media_mime not in AI_DOCTOR_ACCEPTED_MIMES:
            raise HTTPException(
                status_code=415,
                detail=(
                    "Unsupported file type. AI Doctor accepts images (JPG/PNG/WEBP/GIF) "
                    "and PDF only."
                ),
            )
        # Persist on disk with a uuid prefix so we don't collide on filenames.
        from uuid import uuid4
        safe_orig = os.path.basename(file.filename or "upload")
        stored_name = f"{uuid4().hex}_{safe_orig}"
        media_stored_path = os.path.join(UPLOAD_DIR, stored_name)
        try:
            with open(media_stored_path, "wb") as f:
                f.write(media_bytes)
        except OSError as exc:
            raise HTTPException(status_code=500, detail=f"Could not save upload: {exc}")
        media_filename = safe_orig
        media_size = len(media_bytes)

    user_msg = models.AIDoctorMessage(
        session_id=sess.id,
        role="user",
        content=content or "",
        media_filename=media_filename,
        media_stored_path=media_stored_path,
        media_mime=media_mime,
        media_size=media_size,
        created_at=datetime.utcnow(),
    )
    db.add(user_msg)
    if not sess.title and content:
        sess.title = _ai_doctor_title_from_message(content)
    db.flush()

    history = _ai_doctor_build_history(db, sess.id)
    ctx = sess.patient_context_json or _ai_doctor_patient_context(db, sess.patient_id or 0)

    t0 = datetime.utcnow()
    persona_name = _ai_doctor_resolve_persona(db, current_user)
    # Intent-based routing for multipart (image/document) messages
    query_text = content or "analyze attached image"
    tools_ctx, medical_ev, intent_meta = _ai_doctor_route_query(
        query_text, db, sess.patient_id or 0,
        session_id=sess.id,
    )
    reply = gemini_client.ai_doctor_chat(
        history,
        patient_context=ctx,
        media_bytes=media_bytes,
        media_mime=media_mime,
        persona_name=persona_name,
        patient_id=sess.patient_id,
        medical_evidence=medical_ev,
        tools_context=tools_ctx,
    )
    latency = int((datetime.utcnow() - t0).total_seconds() * 1000)

    ai_msg = models.AIDoctorMessage(
        session_id=sess.id,
        role="assistant",
        content=reply.get("text") or "",
        status=reply.get("status") or "ok",
        latency_ms=latency,
        created_at=datetime.utcnow(),
    )
    if (reply.get("status") or "ok") != "ok" and reply.get("error_message"):
        logger.warning("AI Doctor Gemini call failed: %s", reply["error_message"])
        raise HTTPException(status_code=502, detail=reply["error_message"])
    db.add(ai_msg)
    sess.last_active_at = datetime.utcnow()
    db.commit()
    db.refresh(user_msg)
    db.refresh(ai_msg)
    if (user_msg.content or "").strip():
        _ai_doctor_index_message(user_msg)
    if (ai_msg.content or "").strip():
        _ai_doctor_index_message(ai_msg)
    return schemas.AIDoctorMessageListOut(
        items=[_ai_doctor_message_to_out(user_msg), _ai_doctor_message_to_out(ai_msg)],
        total_count=2,
    )


@app.post(
    "/ai-doctor/sessions/{session_id}/summarize",
    response_model=schemas.AIDoctorSummaryOut,
)
def summarize_ai_doctor_session(
    session_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Generate (or fetch cached) medical summary for the conversation.
    Always re-generates so the patient always sees the freshest version —
    the previous one is overwritten on the session row."""
    sess = _ai_doctor_ensure_session_active(db, current_user, session_id)
    history = _ai_doctor_build_history(db, sess.id)
    ctx = sess.patient_context_json or _ai_doctor_patient_context(db, sess.patient_id or 0)
    persona_name = _ai_doctor_resolve_persona(db, current_user)
    out = gemini_client.ai_doctor_summarize(history, patient_context=ctx, persona_name=persona_name)
    sess.summary = out.get("text") or ""
    db.commit()
    db.refresh(sess)
    return schemas.AIDoctorSummaryOut(
        text=out.get("text") or "",
        generated=True,
        generated_at=datetime.utcnow(),
    )


@app.post("/ai-doctor/sessions/{session_id}/close", response_model=schemas.AIDoctorSessionOut)
def close_ai_doctor_session(
    session_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Mark the session as closed (read-only). The patient can still view
    it; they just can't append more messages until they open a new one."""
    sess = _ai_doctor_ensure_session_active(db, current_user, session_id)
    sess.status = "closed"
    sess.last_active_at = datetime.utcnow()
    db.commit()
    db.refresh(sess)

    # Auto-save AI Doctor session to report history
    if current_user.patient_id:
        _hook_save_ai_report(
            db,
            patient_id=current_user.patient_id,
            feature_type="ai_doctor",
            report_type="AI Doctor Consultation",
            title=sess.title or f"AI Doctor session #{sess.id}",
            generated_result=sess.summary or f"AI Doctor session closed. ID: {sess.id}",
            findings=sess.summary or None,
            input_summary=json.dumps({"session_id": sess.id, "title": sess.title}),
            ai_model="gemini",
            source_entity_type="session",
            source_entity_id=sess.id,
        )

    return _ai_doctor_session_to_out(db, sess)


# ---- 2026-08-24: AI Doctor persona rename ----------------------------------
# Per-account persistent rename of the AI Doctor (default "Dr. Mira"). The
# safety preamble itself stays server-locked; only the display name swaps.
# Both endpoints are patient-only — doctors don't see this surface.

_AI_DOCTOR_DEFAULT_NAME = "Dr. Mira"
_AI_DOCTOR_NAME_MIN = 1
_AI_DOCTOR_NAME_MAX = 40
# Lightweight profanity guard. Not exhaustive — this is a UX safeguard,
# not content moderation. Server-side error stays 422 so the UI can
# show the reason inline. Word-boundary only on the LEFT side so that
# "fuckface" still trips (the suffix is non-alpha).
_AI_DOCTOR_PROFANITY = re.compile(
    r"(?i)\b(fuck|shit|bitch|cunt|asshole|nigger|faggot)"
)


def _ai_doctor_get_settings(db: Session, user: models.User) -> models.AIDoctorSettings:
    """Lazy-creates the settings row on first read. Returning the model
    directly keeps the API simple; the schema layer handles serialization."""
    row = (
        db.query(models.AIDoctorSettings)
        .filter(models.AIDoctorSettings.user_id == user.id)
        .first()
    )
    if row:
        return row
    row = models.AIDoctorSettings(
        user_id=user.id,
        persona_name=_AI_DOCTOR_DEFAULT_NAME,
        persona_avatar_url=None,
        updated_at=datetime.utcnow(),
    )
    db.add(row)
    db.commit()
    db.refresh(row)
    return row


def _ai_doctor_resolve_persona(db: Session, user: models.User) -> str:
    """Return the persona name to use for THIS call. Reads the settings
    row (creating it if missing) and trims to a sane length. Falls back
    to 'Dr. Mira' if anything looks off."""
    try:
        row = _ai_doctor_get_settings(db, user)
        name = (row.persona_name or "").strip()
        if not name:
            return _AI_DOCTOR_DEFAULT_NAME
        return name[:_AI_DOCTOR_NAME_MAX]
    except Exception:
        return _AI_DOCTOR_DEFAULT_NAME


def _ai_doctor_index_message(msg: models.AIDoctorMessage) -> None:
    """Best-effort RAG indexing of one message. Failures are logged but
    never raised — RAG is an enhancement, not a requirement."""
    try:
        import rag_client
        rag_client.index_chat_message(msg)
    except Exception as exc:
        logger.warning("RAG index_chat_message failed for msg=%s: %s", msg.id, exc)


def _ai_doctor_index_patient_corpus(patient_id: int) -> None:
    """Best-effort bulk index of one patient's history + reports."""
    try:
        import rag_client
        from database import SessionLocal
        with SessionLocal() as db:
            n = rag_client.index_patient_corpus(db, patient_id)
            logger.info("RAG indexed %s chunks for patient %s", n, patient_id)
    except Exception as exc:
        logger.warning("RAG index_patient_corpus failed for patient=%s: %s", patient_id, exc)


@app.get("/ai-doctor/settings", response_model=schemas.AIDoctorSettingsOut)
def get_ai_doctor_settings(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Return the caller's persona settings. Patient-only — doctors can
    use Mediecho + MediScan instead. Lazy-creates the row with the
    default name on first call."""
    if current_user.role != "patient":
        raise HTTPException(
            status_code=403,
            detail="AI Doctor is only available to patient accounts.",
        )
    row = _ai_doctor_get_settings(db, current_user)
    return schemas.AIDoctorSettingsOut(
        user_id=row.user_id,
        persona_name=row.persona_name,
        persona_avatar_url=row.persona_avatar_url,
        updated_at=row.updated_at,
    )


@app.put("/ai-doctor/settings", response_model=schemas.AIDoctorSettingsOut)
def update_ai_doctor_settings(
    payload: schemas.AIDoctorSettingsUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Update the caller's persona settings. Validates length + a
    minimal profanity guard. persona_avatar_url is accepted for
    forward compatibility but currently ignored on the client."""
    if current_user.role != "patient":
        raise HTTPException(
            status_code=403,
            detail="AI Doctor is only available to patient accounts.",
        )
    name = (payload.persona_name or "").strip()
    if len(name) < _AI_DOCTOR_NAME_MIN or len(name) > _AI_DOCTOR_NAME_MAX:
        raise HTTPException(
            status_code=422,
            detail=f"Persona name must be {_AI_DOCTOR_NAME_MIN}-{_AI_DOCTOR_NAME_MAX} characters.",
        )
    if _AI_DOCTOR_PROFANITY.search(name):
        raise HTTPException(
            status_code=422,
            detail="That name isn't allowed. Please choose something appropriate for a clinical assistant.",
        )
    # Block obviously fake medical titles so the renamed bot can't claim
    # to be a real doctor. Not a full title list — just the common ones.
    title_words = ("dr.", "doctor", "md", "mbbs", "physician")
    lower = name.lower()
    if any(w in lower for w in title_words) and name.strip().lower() != _AI_DOCTOR_DEFAULT_NAME.lower():
        # Allow "Dr. Mira" by default but block other "Dr. X" renames.
        raise HTTPException(
            status_code=422,
            detail="Persona names can't claim a medical title. Drop the 'Dr.' prefix.",
        )

    row = _ai_doctor_get_settings(db, current_user)
    row.persona_name = name
    if payload.persona_avatar_url is not None:
        # Accept any URL for now — UI doesn't render avatars yet, but we
        # persist so the column exists in the DB for future use.
        row.persona_avatar_url = (payload.persona_avatar_url or "").strip() or None
    row.updated_at = datetime.utcnow()
    db.commit()
    db.refresh(row)
    return schemas.AIDoctorSettingsOut(
        user_id=row.user_id,
        persona_name=row.persona_name,
        persona_avatar_url=row.persona_avatar_url,
        updated_at=row.updated_at,
    )


# ---- 2026-08-24: AI Doctor streaming WebSocket ----------------------------
# Browser-friendly transport for the same chat. REST endpoints stay as the
# fallback path used when WS connect fails or is disabled by config.
#
# Wire protocol (all JSON, one event per message):
#
#   client → server:
#     {"type": "user_message", "content": "...", "media": {filename, mime, data_b64} | null}
#     {"type": "pong"}        # reply to server ping
#
#   server → client:
#     {"type": "ready",        "session_id": <int>}
#     {"type": "user_persisted","message_id": <int>}
#     {"type": "token",        "delta": "..."}    # repeated
#     {"type": "tool_call",    "name":..., "args":...}     # Phase 4
#     {"type": "tool_result",  "name":..., "result":...}   # Phase 4
#     {"type": "error",        "detail": "..."}
#     {"type": "done",         "message_id":..., "full_text":..., "status": "ok"|"blocked"|"error"}
#     {"type": "ping"}         # heartbeat
#     {"type": "closed"}       # server-initiated close
#
# Persistence: user msg → DB before streaming starts; assistant msg → DB
# after the stream finishes (or disconnects mid-stream, partial text preserved).
# Heartbeat: server pings every 25s; client must reply `pong` within 60s of
# silence or we close with 1011.

_WS_HEARTBEAT_INTERVAL = 25  # seconds between server pings
_WS_PONG_TIMEOUT = 60        # seconds of silence before forced close


def _ws_message_payload_to_text_and_media(payload: dict) -> tuple[str, Optional[bytes], Optional[str]]:
    """Pull the user-supplied text and optional image off an inbound WS frame.
    Returns (content, media_bytes, media_mime). Mirrors the REST multipart path
    so the same Gemini prompt gets built either way."""
    content = (payload.get("content") or "").strip()
    media = payload.get("media") or None
    media_bytes: Optional[bytes] = None
    media_mime: Optional[str] = None
    if isinstance(media, dict) and media.get("data_b64"):
        try:
            media_bytes = base64.b64decode(media["data_b64"])
        except Exception:
            media_bytes = None
        media_mime = (media.get("mime") or "").strip() or None
    return content, media_bytes, media_mime


async def _ws_send_heartbeat(websocket: WebSocket, stop: asyncio.Event, last_pong: dict) -> None:
    """Background task: pings the client periodically and forces a close
    if the client hasn't sent `pong` within `_WS_PONG_TIMEOUT` of silence.
    `last_pong` is a mutable dict with `last_seen` (loop.time()) so the
    main coroutine can update it on every received frame."""
    try:
        while not stop.is_set():
            await asyncio.sleep(_WS_HEARTBEAT_INTERVAL)
            if stop.is_set():
                return
            if (asyncio.get_event_loop().time() - last_pong["last_seen"]) > _WS_PONG_TIMEOUT:
                try:
                    await websocket.close(code=1011)
                finally:
                    stop.set()
                return
            try:
                await websocket.send_json({"type": "ping"})
            except Exception:
                stop.set()
                return
    except asyncio.CancelledError:
        # Normal shutdown when the main loop ends; swallow.
        return


@app.websocket("/ai-doctor/sessions/{session_id}/stream")
async def ai_doctor_stream(websocket: WebSocket, session_id: int):
    """Open a streaming chat session. Token comes via query string because
    browsers can't send custom headers on the WS handshake. Closes 1008
    on auth failure, 1011 on heartbeat timeout, 1000 on clean disconnect."""
    await websocket.accept()

    # Pull token + db session before any send so a bad token closes early.
    token = websocket.query_params.get("token", "") or ""
    from database import SessionLocal
    db = SessionLocal()
    user = None
    try:
        from ws_auth import authenticate_ws_token
        user = authenticate_ws_token(token, db)
    except Exception:
        try:
            await websocket.close(code=1008)
        except Exception:
            pass
        db.close()
        return

    if user.role != "patient":
        try:
            await websocket.send_json({"type": "error", "detail": "AI Doctor is only available to patient accounts."})
            await websocket.close(code=1008)
        except Exception:
            pass
        db.close()
        return

    # Scope to the patient's session.
    sess = (
        db.query(models.AIDoctorSession)
        .filter(models.AIDoctorSession.id == session_id, models.AIDoctorSession.user_id == user.id)
        .first()
    )
    if not sess or sess.status == "closed":
        try:
            await websocket.send_json({"type": "error", "detail": "session_unavailable"})
            await websocket.close(code=1008)
        except Exception:
            pass
        db.close()
        return

    # Heartbeat machinery. last_pong["last_seen"] is bumped by the receive
    # loop on every frame (ping reply or user_message).
    stop = asyncio.Event()
    last_pong = {"last_seen": asyncio.get_event_loop().time()}
    heartbeat_task = asyncio.create_task(_ws_send_heartbeat(websocket, stop, last_pong))

    try:
        await websocket.send_json({"type": "ready", "session_id": sess.id})

        while True:
            try:
                raw = await websocket.receive_json()
            except WebSocketDisconnect:
                return
            except Exception:
                # Bad frame — keep the connection alive but ignore.
                continue

            # Heartbeat reply — update last_seen and loop.
            if not isinstance(raw, dict):
                continue
            msg_type = raw.get("type")
            last_pong["last_seen"] = asyncio.get_event_loop().time()
            if msg_type == "pong":
                continue

            if msg_type != "user_message":
                # Unknown frame types are ignored silently — keeps the
                # protocol forward-compatible.
                continue

            content, media_bytes, media_mime = _ws_message_payload_to_text_and_media(raw)
            if not content and not media_bytes:
                # Empty turn — tell the client so the UI doesn't spin.
                await websocket.send_json({"type": "error", "detail": "empty_message"})
                continue

            # Persist media to disk so the row matches what the REST multipart
            # path writes (filename + stored path). The Gemini call still
            # needs the bytes in-process for the multimodal prompt part.
            media_filename: Optional[str] = None
            media_stored_path: Optional[str] = None
            media_size: Optional[int] = None
            if media_bytes:
                if len(media_bytes) > AI_DOCTOR_MAX_UPLOAD_BYTES:
                    await websocket.send_json({"type": "error", "detail": "file_too_large"})
                    continue
                if media_mime and media_mime not in AI_DOCTOR_ACCEPTED_MIMES:
                    await websocket.send_json({"type": "error", "detail": "unsupported_media_type"})
                    continue
                from uuid import uuid4
                safe_orig = "ws_upload"
                stored_name = f"{uuid4().hex}_{safe_orig}"
                media_stored_path = os.path.join(UPLOAD_DIR, stored_name)
                try:
                    with open(media_stored_path, "wb") as f:
                        f.write(media_bytes)
                except OSError as exc:
                    logger.warning("WS media save failed: %s", exc)
                    await websocket.send_json({"type": "error", "detail": "upload_save_failed"})
                    continue
                media_filename = safe_orig
                media_size = len(media_bytes)

            # 1. Persist the user message.
            user_msg = models.AIDoctorMessage(
                session_id=sess.id,
                role="user",
                content=content or "",
                media_filename=media_filename,
                media_stored_path=media_stored_path,
                media_mime=media_mime,
                media_size=media_size,
                created_at=datetime.utcnow(),
            )
            db.add(user_msg)
            db.commit()
            db.refresh(user_msg)
            await websocket.send_json({"type": "user_persisted", "message_id": user_msg.id})

            # 2. Build history + persona and ask Gemini to stream.
            sess.last_active_at = datetime.utcnow()
            db.commit()

            history = _ai_doctor_build_history(db, sess.id)
            ctx = sess.patient_context_json or _ai_doctor_patient_context(db, sess.patient_id or 0)
            persona_name = _ai_doctor_resolve_persona(db, user)
            # Intent-based routing for WS streaming
            query_text = content or "analyze attached image"
            tools_ctx, medical_ev, intent_meta = _ai_doctor_route_query(
                query_text, db, sess.patient_id or 0,
                session_id=sess.id,
            )

            started_at = datetime.utcnow()
            full_text_parts: list[str] = []
            status = "ok"
            tool_calls_emitted: list[dict] = []
            tool_args_by_id: dict[str, dict] = {}
            _tool_seq = 0
            try:
                gen = gemini_client.ai_doctor_chat_stream_with_tools(
                    history,
                    patient_context=ctx,
                    media_bytes=media_bytes,
                    media_mime=media_mime,
                    persona_name=persona_name,
                    patient_id=(sess.patient_id or None),
                    tools_context=tools_ctx,
                    db=db,
                    user=user,
                    medical_evidence=medical_ev,
                )

                def _step_sync(g):
                    try:
                        return next(g), False
                    except StopIteration:
                        return None, True

                while True:
                    try:
                        ev, done = await asyncio.to_thread(_step_sync, gen)
                    except WebSocketDisconnect:
                        _persist_streamed_assistant(db, sess, user_msg, full_text_parts, started_at, status)
                        return
                    except Exception as exc:
                        logger.warning("tool-loop step raised: %s", exc)
                        status = "error"
                        try:
                            await websocket.send_json({"type": "error", "detail": "stream_failed"})
                        except Exception:
                            pass
                        break
                    if done or ev is None:
                        break
                    kind, payload = ev
                    if kind == "token":
                        full_text_parts.append(payload)
                        try:
                            await websocket.send_json({"type": "token", "delta": payload})
                        except WebSocketDisconnect:
                            _persist_streamed_assistant(db, sess, user_msg, full_text_parts, started_at, status)
                            return
                    elif kind == "tool_call":
                        _tool_seq += 1
                        tool_id = f"{payload['name']}#{_tool_seq}"
                        tool_args_by_id[tool_id] = payload.get("args") or {}
                        try:
                            await websocket.send_json(
                                {"type": "tool_call", "id": tool_id, "name": payload["name"], "args": payload["args"]}
                            )
                        except WebSocketDisconnect:
                            _persist_streamed_assistant(db, sess, user_msg, full_text_parts, started_at, status)
                            return
                    elif kind == "tool_result":
                        # Pair this result with the most-recent unmatched
                        # tool_call of the same name (typical 1:1 pattern).
                        args_for_audit: dict = {}
                        for tid, args in list(tool_args_by_id.items()):
                            if tid.startswith(payload["name"] + "#"):
                                args_for_audit = args
                                tool_args_by_id.pop(tid, None)
                                break
                        tool_calls_emitted.append({"name": payload["name"], "args": args_for_audit, "result": payload["result"]})
                        try:
                            await websocket.send_json(
                                {"type": "tool_result", "name": payload["name"], "result": payload["result"]}
                            )
                        except WebSocketDisconnect:
                            _persist_streamed_assistant(db, sess, user_msg, full_text_parts, started_at, status)
                            return
                        # Write an audit row immediately so even a mid-stream
                        # disconnect keeps the tool trail in the transcript.
                        try:
                            import ai_doctor_tools
                            audit = models.AIDoctorMessage(
                                session_id=sess.id,
                                role="system",
                                content=ai_doctor_tools.tool_audit_text(
                                    payload["name"], args_for_audit, payload["result"]
                                ),
                                status="ok",
                                created_at=datetime.utcnow(),
                            )
                            db.add(audit)
                            db.commit()
                        except Exception as exc:
                            logger.warning("audit row insert failed: %s", exc)
                            try:
                                db.rollback()
                            except Exception:
                                pass
                    elif kind == "done":
                        status = payload.get("status", status)
                        break
            except Exception as exc:
                logger.warning("ai_doctor_chat_stream_with_tools raise on entry: %s", exc)
                status = "error"
                try:
                    await websocket.send_json({"type": "error", "detail": "stream_unavailable"})
                except Exception:
                    pass

            # 3. Persist assistant row + send `done` + index into RAG.
            ai_msg = _persist_streamed_assistant(db, sess, user_msg, full_text_parts, started_at, status)
            try:
                await websocket.send_json(
                    {
                        "type": "done",
                        "message_id": (ai_msg.id if ai_msg else None),
                        "full_text": "".join(full_text_parts),
                        "status": status,
                        "latency_ms": int((datetime.utcnow() - started_at).total_seconds() * 1000),
                        "tool_calls": tool_calls_emitted,
                    }
                )
            except Exception:
                # Client probably already closed — nothing to do.
                pass

            if ai_msg is not None:
                _ai_doctor_index_message(ai_msg)

    except WebSocketDisconnect:
        return
    except Exception as exc:
        logger.exception("ai_doctor_stream crashed: %s", exc)
        try:
            await websocket.close(code=1011)
        except Exception:
            pass
    finally:
        stop.set()
        try:
            heartbeat_task.cancel()
        except Exception:
            pass
        try:
            db.close()
        except Exception:
            pass


def _next_chunk(stream):
    """Pull one chunk from a Gemini sync stream iterator. Wraps the SDK's
    StopIteration so we can drive it from an async loop via to_thread."""
    try:
        return next(stream)
    except StopIteration:
        return None


def _extract_chunk_text(chunk) -> str:
    """Pull the .text out of a Gemini streaming chunk. Defensive — the SDK
    shape has changed across versions (delta vs aggregated text)."""
    if chunk is None:
        return ""
    try:
        return chunk.text or ""
    except Exception:
        pass
    try:
        for cand in (chunk.candidates or []):
            for part in (getattr(cand.content, "parts", None) or []):
                t = getattr(part, "text", None)
                if t:
                    return t
    except Exception:
        pass
    return ""


def _persist_streamed_assistant(
    db: Session,
    sess: models.AIDoctorSession,
    user_msg: models.AIDoctorMessage,
    text_parts: list[str],
    started_at: datetime,
    status: str,
) -> Optional[models.AIDoctorMessage]:
    """Write the assistant message that came back from the stream. Returns
    the row (or None on hard failure). Truncated-but-non-empty text is
    still persisted so partial turns survive a mid-stream disconnect."""
    full_text = "".join(text_parts).strip()
    latency_ms = int((datetime.utcnow() - started_at).total_seconds() * 1000)
    if not full_text and status != "error":
        # Nothing came back from Gemini and it wasn't a reported error —
        # skip the row so we don't pollute the transcript.
        return None
    ai_msg = models.AIDoctorMessage(
        session_id=sess.id,
        role="assistant",
        content=full_text or "(no response)",
        status=status,
        latency_ms=latency_ms,
        created_at=datetime.utcnow(),
    )
    try:
        db.add(ai_msg)
        db.commit()
        db.refresh(ai_msg)
    except Exception as exc:
        logger.warning("Failed to persist streamed assistant msg: %s", exc)
        try:
            db.rollback()
        except Exception:
            pass
        return None
    # Best-effort: bump session title from the first user turn.
    try:
        if not sess.title:
            sess.title = _ai_doctor_title_from_message(user_msg.content or "")
            sess.last_active_at = datetime.utcnow()
            db.commit()
    except Exception:
        try:
            db.rollback()
        except Exception:
            pass
    return ai_msg


# ============================================================
# Evidence-Based AI Doctor — External Medical Knowledge APIs
# ---------------------------------------------------------------------
# Endpoints for searching medical knowledge, medicines, and checking
# food-drug interactions. Used by the AI Doctor and available to
# authenticated users.
# ============================================================

@app.get("/medical/search")
def search_medical_knowledge(
    q: str,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Search medical knowledge from authoritative sources.
    Returns results from MedlinePlus, RxNorm, DailyMed, and openFDA."""
    if not med_knowledge:
        raise HTTPException(status_code=503, detail="Medical knowledge service not available.")
    q = (q or "").strip()
    if not q:
        raise HTTPException(status_code=400, detail="Query is required.")
    evidence = med_knowledge.gather_medical_evidence(q, db)
    return {
        "query": q,
        "sources": {
            "medlineplus": evidence.get("medlineplus", {}),
            "rxnorm": evidence.get("rxnorm", {}),
            "dailymed": evidence.get("dailymed", {}),
            "openfda": evidence.get("openfda", {}),
        },
        "timestamp": evidence.get("timestamp"),
    }


@app.get("/medicines/search")
def search_medicines(
    q: str,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Search for a medicine across RxNorm, DailyMed, and openFDA.
    Returns combined evidence with generic name, indications,
    contraindications, warnings, and interactions."""
    if not med_knowledge:
        raise HTTPException(status_code=503, detail="Medical knowledge service not available.")
    q = (q or "").strip()
    if not q:
        raise HTTPException(status_code=400, detail="Medicine name is required.")
    result = med_knowledge.search_medicine(q, db)
    return result


@app.get("/medicines/{medicine_name}/details")
def get_medicine_details(
    medicine_name: str,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Get detailed information about a specific medicine.
    Returns data from all available authoritative sources."""
    if not med_knowledge:
        raise HTTPException(status_code=503, detail="Medical knowledge service not available.")
    result = med_knowledge.search_medicine(medicine_name, db)
    return result


@app.post("/interactions/check")
def check_interactions(
    medicine: str,
    food: str = "",
    other_medicine: str = "",
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Check for food-drug or drug-drug interactions.
    Uses DailyMed, openFDA, and RxNorm for evidence."""
    if not med_knowledge:
        raise HTTPException(status_code=503, detail="Medical knowledge service not available.")
    medicine = (medicine or "").strip()
    if not medicine:
        raise HTTPException(status_code=400, detail="Medicine name is required.")
    if food:
        result = med_knowledge.check_food_drug_interaction(medicine, food, db)
    elif other_medicine:
        # Check drug-drug interaction via RxNorm
        rxnorm = med_knowledge.search_rxnorm(medicine, db)
        interactions = []
        if rxnorm.get("available"):
            for r in rxnorm.get("results", []):
                interactions.extend(r.get("interactions", []))
        result = {
            "medicine": medicine,
            "other_medicine": other_medicine,
            "interactions_found": any(
                other_medicine.lower() in (i.get("drug", "").lower() or "")
                for i in interactions
            ),
            "interactions": [i for i in interactions if other_medicine.lower() in (i.get("drug", "").lower() or "")],
            "all_interactions": interactions[:10],
            "sources": ["RxNorm"],
            "disclaimer": "This information is from publicly available medical databases. Always consult a pharmacist or doctor.",
        }
    else:
        raise HTTPException(status_code=400, detail="Provide either 'food' or 'other_medicine' parameter.")
    return result


@app.get("/ai-doctor/context/{patient_id}")
def get_ai_doctor_context(
    patient_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Get the full patient evidence context that the AI Doctor uses.
    Patients can only see their own context; doctors can see any patient."""
    if current_user.role == "patient" and current_user.patient_id != patient_id:
        raise HTTPException(status_code=403, detail="Access denied.")
    if not evidence_service:
        raise HTTPException(status_code=503, detail="Evidence service not available.")
    evidence = evidence_service.build_patient_evidence(db, patient_id)
    formatted = evidence_service.format_patient_evidence_for_prompt(evidence)
    return {
        "patient_id": patient_id,
        "raw_evidence": evidence,
        "formatted_context": formatted,
        "sections": {
            "demographics": bool(evidence.get("demographics")),
            "medical_history": len(evidence.get("medical_history", [])),
            "allergies": len(evidence.get("allergies", [])),
            "current_medications": len(evidence.get("current_medications", [])),
            "prescriptions": len(evidence.get("prescriptions", [])),
            "lab_values": len(evidence.get("lab_values", [])),
            "scan_results": len(evidence.get("scan_results", [])),
            "treatments": len(evidence.get("treatments", [])),
            "nursing_notes": len(evidence.get("nursing_notes", [])),
            "vital_records": len(evidence.get("vital_records", [])),
        },
    }


