def _sg_page_id_for_url(page_url: str) -> str:
    """Map a URL to a generic page id. Dashboard is the default.
    Handles both extensioned ('appointments.html') and extensionless
    ('/appointments') URLs that the static server serves."""
    raw = page_url or ""
    # Strip query string and leading scheme/host if present.
    if "?" in raw:
        raw = raw.split("?", 1)[0]
    if "://" in raw:
        raw = raw.split("://", 1)[1]
        # strip path past the host: keep from first '/' (or whole if none)
        slash = raw.find("/")
        if slash == -1:
            raw = "/"
        else:
            raw = raw[slash:]
    # Normalise trailing slashes and the bare server root.
    if raw in ("", "/", "/index.html"):
        return "dashboard"
    url_l = raw.lower()
    # Specific-first list already ordered; test extensioned and
    # extensionless forms of every keyword.
    for keyword, page_id in _PAGE_KEYWORD_MAP:
        if keyword in url_l:
            return page_id
        extless = keyword.replace(".html", "")
        if len(extless) > 4 and extless in url_l:
            return page_id
    # Generic fallback: map by filename stem at the end of the path.
    stem = url_l.rstrip("/").split("/")[-1].replace(".html", "")
    if stem and stem not in ("dashboard", "index", "login"):
        for keyword, page_id in _PAGE_KEYWORD_MAP:
            if keyword.replace(".html", "") == stem:
                return page_id
    return "dashboard"


def _sg_expand_role_kb(role: str) -> dict:
    """Return the role knowledge with shared capability + shared feature
    descriptions merged in, so every role understands chat/calls/media even
    if the per-role dict doesn't repeat them."""
    kb = dict(_SYSTEM_GUIDANCE_KB.get(role, {}))
    features = kb.get("features", [])
    shared = dict(_SG_SHARED)
    pages = dict(kb.get("pages", {}))
    pages.update({k: v for k, v in shared.items() if k not in pages})
    # Map feature ids -> descriptions + shared feature descriptions.
    feat_desc = {fid: _SG_FEATURES.get(fid, "") for fid in features if _SG_FEATURES.get(fid)}
    workflows = dict(kb.get("workflows", {}))
    return {
        "pages": pages,
        "features": feat_desc,
        "feature_ids": features,
        "workflows": workflows,
        "tips": kb.get("tips", []),
    }


# Lightweight per-user conversation memory: {user_id: [(role, text), ...]}
# Kept in-process and capped; only short system-guide turns are stored.
_SG_MEM = {}
_SG_MEM_LOCK = _sg_threading.Lock()
_SG_MEM_MAX = 6          # keep last 6 turns
_SG_MEM_USERS = 500      # hard cap on tracked users
_SG_MEM_CHARS = 400      # per-turn char cap


def _sg_mem_get(user_id: int) -> list:
    with _SG_MEM_LOCK:
        return list(_SG_MEM.get(user_id, []))


def _sg_mem_push(user_id: int, role: str, text: str) -> None:
    text = (text or "")[: _SG_MEM_CHARS]
    with _SG_MEM_LOCK:
        arr = _SG_MEM.setdefault(user_id, [])
        arr.append((role, text))
        if len(arr) > _SG_MEM_MAX:
            del arr[: len(arr) - _SG_MEM_MAX]
        # Simple guard: if the dict grew too large, drop the oldest users.
        if len(_SG_MEM) > _SG_MEM_USERS:
            for k in list(_SG_MEM.keys())[: len(_SG_MEM) - _SG_MEM_USERS]:
                _SG_MEM.pop(k, None)


def _sg_prev_question(user_id: int) -> str:
    """Return the last user question stored in memory, if any."""
    for role, text in reversed(_sg_mem_get(user_id)):
        if role == "user":
            return text
    return ""


_FOLLOWUP_RE = re.compile(
    r"^\s*(and\s+)?(what|how|why|where|when|who|can\s+i|do\s+i|is\s+it|does\s+it|is\s+that|does\s+that|what\s+about|how\s+about|tell\s+me\s+more|more|that|this|it|one)\b",
    re.IGNORECASE,
)


def _sg_is_medical_question(q: str, role: str) -> bool:
    """Decide whether a question is a request for personal medical advice
    (-> redirect to AI Doctor) vs a question about using the app (-> guide).
    Questions that clearly talk about the software ("how do I use Symptom
    Checker", "where do I upload a report", "what is this button") are
    always treated as system guidance, never medical."""
    ql = " " + q.lower() + " "
    # Explicit system-language takes precedence (navigation / feature words).
    system_terms = [
        "how do i", "how can i", "how to", "where is", "where are", "where can i",
        "what is this", "what does this", "what does that", "button", "page",
        "section", "tab", "menu", "sidebar", "icon", "screen", "upload",
        "download", "open the", "go to", "navigate", "feature", "dashboard",
        "setting", "in the app", "on this page", "how do i use", "where do i",
        "symptom checker", "mediscan", "medicine info", "mediecho", "ai doctor",
        "chat", "video call", "audio call", "discharge appeal", "report",
        "appointment", "invite", "link a doctor", "add a patient",
    ]
    if any(t in ql for t in system_terms):
        return False
    # Personal-health phrasing -> medical.
    medical_terms = [
        "what disease", "what illness", "do i have", "am i sick", "should i take",
        "what medicine", "what drug", "my fever", "my cough", "my pain",
        "my headache", "my stomach", "my chest", "my throat", "my back",
        "i have", "i've been having", "i am feeling", "i'm feeling", "diagnos",
        "is it serious", "will i", "can i take", "prescribe", "treatment for",
        "cure for", "symptom of", "medical advice", "paracetamol", "tablet for",
    ]
    return any(t in ql for t in medical_terms)


def _sg_medical_answer(role: str) -> dict:
    base = (
        "I'm the System Guide — I help you use this application. "
        "For medical questions like diagnosis, treatment, or medication advice, "
        "please use the AI Doctor feature or consult a licensed medical professional."
    )
    if role == "patient":
        return {"answer": base, "suggestion": {"label": "Open AI Doctor", "href": "ai-doctor.html"}}
    return {"answer": base, "suggestion": None}


def _sg_role_feature_ids(role: str) -> list:
    return list(_SYSTEM_GUIDANCE_KB.get(role, {}).get("features", []))


def _sg_find_page_suggestion(role: str, text: str):
    """Pick a nav suggestion by matching page labels / ids in a text."""
    text_l = (text or "").lower()
    pages = _SYSTEM_PAGES.get(role, [])
    for p in pages:
        label = p["label"].lower()
        if label in text_l or p["id"].replace("-", " ") in text_l:
            return {"label": f"Open {p['label']}", "href": p["href"]}
    return None


@app.post("/system-guide")
def system_guide(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """System Guidance Assistant — answers questions about using the application.
    Accepts: { "question": "...", "page": "current-page-url", "history": [...] }
    Returns: { "answer": "...", "suggestion": {...}, "intent": "..." }"""
    question = (payload.get("question") or "").strip()
    page_url = (payload.get("page") or "").strip()
    role = current_user.role

    if not question:
        raise HTTPException(status_code=400, detail="Question is required.")

    # Don't serve admin users
    if role == "admin":
        raise HTTPException(status_code=403, detail="System Guide is not available for admin users.")

    # Current page detection
    current_page_id = _sg_page_id_for_url(page_url)

    # Conversation memory: seed from the client-supplied history (last few
    # turns) so follow-up questions have context even across page loads,
    # then push the new question.
    client_history = payload.get("history") or []
    if isinstance(client_history, list):
        for turn in client_history[-_SG_MEM_MAX:]:
            if not isinstance(turn, dict):
                continue
            r = "assistant" if str(turn.get("role", "")).lower() in ("assistant", "bot", "model") else "user"
            c = str(turn.get("content") or turn.get("text") or "").strip()
            if c:
                _sg_mem_push(current_user.id, r, c)
    _sg_mem_push(current_user.id, "user", question)

    role_kb = _sg_expand_role_kb(role)
    pages_info = role_kb["pages"]
    features_info = role_kb["features"]
    workflows_info = role_kb["workflows"]
    available_pages = _SYSTEM_PAGES.get(role, [])

    # Medical questions -> redirect (never try to diagnose through the guide)
    if _sg_is_medical_question(question, role):
        return _sg_medical_answer(role)

    # --- FAST PATH: deterministic answer from knowledge base (no LLM) ---
    fast_answer, fast_suggestion = _fast_system_answer(
        question, role, current_page_id, role_kb, available_pages,
        prev_question=_sg_prev_question(current_user.id),
    )
    if fast_answer is not None:
        _sg_mem_push(current_user.id, "assistant", fast_answer)
        return {"answer": fast_answer, "suggestion": fast_suggestion, "intent": "knowledge"}

    # --- SLOW PATH: complex/unrecognised questions reach the LLM once ---
    current_page_desc = pages_info.get(current_page_id, "The current page of the application.")
    pages_text = "\n".join([f"- {k}: {v}" for k, v in pages_info.items()])
    features_text = "\n".join([f"- {k}: {v}" for k, v in features_info.items()])
    workflows_text = "\n".join([f"- {k}: {v}" for k, v in workflows_info.items()]) if workflows_info else ""
    pages_for_nav = "\n".join([f"- {p['label']} \u2192 {p['href']}" for p in available_pages])

    # Recent conversation (compact, most recent last).
    recent = _sg_mem_get(current_user.id)[:-1]
    convo_lines = []
    for r, c in recent[-4:]:
        who = "User" if r == "user" else "Guide"
        convo_lines.append(f"{who}: {c}")
    convo_text = "\n".join(convo_lines) if convo_lines else "(none yet)"

    system_prompt = (
        f"{_SYSTEM_GUIDANCE_KB['_rules']}\n\n"
        f"Current user role: {role.upper()} (guide only features available to this role)\n"
        f"Current page: {current_page_desc}\n\n"
        f"PAGES:\n{pages_text}\n\n"
        f"FEATURES:\n{features_text}\n"
    )
    if workflows_text:
        system_prompt += f"\nWORKFLOWS:\n{workflows_text}\n"
    system_prompt += (
        f"\nNAV (use these for navigation suggestions):\n{pages_for_nav}\n\n"
        f"RECENT CONVERSATION:\n{convo_text}\n\n"
        f"Answer the user's latest question concisely (1-3 sentences). "
        f"If it refers to something from the recent conversation, use that context. "
        f"If the requested feature does not exist for this role, say so briefly."
    )

    llm_question = question
    try:
        answer = gemini_client._nemotron_chat(
            llm_question,
            system=system_prompt,
            temperature=0.2,
            max_tokens=160,
        )
    except Exception:
        answer = ""

    if not answer or len(answer) < 4:
        answer = _fallback_system_guide(question, role, current_page_id, role_kb)

    # Suggest a matching page when the answer names one.
    suggestion = _sg_find_page_suggestion(role, answer)
    _sg_mem_push(current_user.id, "assistant", answer)
    return {"answer": answer, "suggestion": suggestion, "intent": "llm"}


# ---------------------------------------------------------------
# FAST DETERMINISTIC ANSWERS — no LLM needed for simple questions
# ---------------------------------------------------------------
_SG_GREETINGS = re.compile(
    r"^\s*(hello|hi|hey|good\s*(morning|afternoon|evening)|howdy|greetings|sup|yo|what'?s\s*up|namaste|hola)\s*[!.?]*\s*$",
    re.IGNORECASE,
)
_SG_THANKS = re.compile(
    r"^\s*(thanks?|thank\s*you|thx|ty|cheers|appreciate|grateful)\s*[!.?]*\s*$",
    re.IGNORECASE,
)
_SG_BYE = re.compile(
    r"^\s*(bye|goodbye|see\s*ya|later|good\s*night|gn|cya)\s*[!.?]*\s*$",
    re.IGNORECASE,
)
_SG_WHAT_IS_THIS = re.compile(
    r"^\s*(what\s+(is|does)\s+(this|here|the\s*(page|section|screen|app|application|system)|this\s*(page|section|screen|do|system)?)\s*(do)?|what\s+is\s*$|what\s*am\s*i\s*(looking\s*at|on|viewing)|describe\s*(this|the)\s*(page|section|screen))\s*[?.]*\s*$",
    re.IGNORECASE,
)
_SG_HOW_TO_USE = re.compile(
    r"^\s*(how\s+(do\s+i|can\s+i|to)\s+(use\s*this|use\s*the|navigate|go\s*back|return\s*(to\s*)?(the\s*)?dashboard|get\s*started|start)|how\s*(do\s+i|can\s+i)\s+(record|add|submit|send|create|open|check|view|find|search|manage))\s*[?.]*\s*$",
    re.IGNORECASE,
)
_SG_WHERE_IS = re.compile(
    r"^\s*(where\s+(is|are|can\s+i\s*find|do\s+i\s*find|should\s+i\s*go|do\s+i|can\s+i|should\s+i))\s+(.*)\s*[?.]*\s*$",
    re.IGNORECASE,
)
_SG_WHAT_CAN_I = re.compile(
    r"^\s*(what\s+can\s+i\s*(do|see|access|use)(\s+here|\s+on\s+this\s+page)?|what\s*(features?|options?)\s+(are\s+)?(available|here|on\s*this)|help|menu|options|what\s*should\s+i\s*(do|start|use))\s*[?.]*\s*$",
    re.IGNORECASE,
)
_SG_WHAT_IS_CARD = re.compile(
    r"^\s*what\s+(is|does|are)\s+(a|an|the)?\s*(today|active|average\s*wait|compliance|my\s*patients\s*active|need\s*attention|care\s*tasks|vital\s*warning)(\s+card|\s+box)?(\s+mean|\s+do|\s+show)?\s*[?.]*\s*$",
    re.IGNORECASE,
)


# Cross-role alias map: phrases users use for real pages/features.
_SG_PHRASE_MAP = [
    ("symptom checker", "symptom-checker"),
    ("symptom-checker", "symptom-checker"),
    ("mediscan", "mediscan"),
    ("medicine info", "medicine-info"),
    ("mediecho", "medi-echo"),
    ("medi echo", "medi-echo"),
    ("ai doctor", "ai-doctor"),
    ("diet & fitness", "diet-plan"),
    ("diet plan", "diet-plan"),
    ("health trends", "health-trends"),
    ("reminders", "reminders"),
    ("my patients", "my-patients"),
    ("patients", "my-patients"),
    ("my admission", "my-admission"),
    ("beds", "beds"),
    ("chat", "chat"),
    ("video call", "video-call"),
    ("audio call", "audio-call"),
    ("call", "audio-call"),
    ("messages", "chat"),
    ("patient records", "patient-records"),
    ("discharge appeal", "discharge-appeal"),
]


_SG_CARD_MAP = {
    "doctor": {
        "today": "Today shows your appointments for today — total, completed, upcoming, pending, and cancelled.",
        "active": "Active shows your current workload — patients waiting or in consultation right now.",
        "average wait": "Average Wait shows how long patients typically wait before being seen, computed from your schedule.",
        "compliance": "Compliance shows how reliably you complete your scheduled work — appointments attended vs missed.",
    },
    "patient": {
        "today": "Today summarises your health activity for today — records, appointments, and updates.",
        "active": "Active shows your currently open health items, like an active admission or pending action.",
        "average wait": "Average Wait shows typical wait times where the system has appointment data.",
        "compliance": "Compliance shows how consistently you have kept up with your scheduled care.",
    },
    "nurse": {
        "my patients active": "My Patients Active counts the patients currently assigned to you.",
        "need attention": "Need Attention counts patients that need a nursing action — alerts, abnormal vitals, or pending instructions.",
        "care tasks": "Care Tasks shows pending vs completed nursing tasks (medications, treatments).",
        "vital warning": "Vital Warning counts patients whose latest vitals are outside normal range.",
    },
}


_SG_CARD_KEYWORDS = ["my patients active", "need attention", "care tasks", "vital warning",
                      "average wait", "compliance", "active", "today"]


def _sg_card_explain(role: str, card: str):
    """Return a friendly explanation for a dashboard KPI card if it exists
    for the role, else None."""
    for key in _SG_CARD_KEYWORDS:
        if key in card:
            desc = _SG_CARD_MAP.get(role, {}).get(key)
            if desc:
                return desc + " Click the card on your dashboard to see the full breakdown with charts."
            return None
    return None


def _sg_resolve_target(ql: str) -> str:
    """Return the canonical page id a phrase refers to, or '' if none."""
    for phrase, pid in _SG_PHRASE_MAP:
        if phrase in ql:
            return pid
    for pid in _SG_ALL_PAGE_IDS:
        spaced = pid.replace("-", " ")
        if spaced in ql or pid in ql:
            return pid
    # Workflow keys live in each role KB; handle below via generic word scan.
    return ""


def _sg_lookup_phrase(role: str, role_kb: dict, target: str):
    """Look up a resolved target in pages / features / workflows / shared.
    Returns (kind, description, suggestion) or None."""
    pages_info = role_kb.get("pages", {})
    features_info = role_kb.get("features", {})
    workflows_info = role_kb.get("workflows", {})
    pages = _SYSTEM_PAGES.get(role, [])

    if target in pages_info:
        link = next((p for p in pages if p["id"] == target), None)
        return ("page", pages_info[target], {"label": f"Open {link['label']}", "href": link["href"]} if link else None)
    if target in features_info:
        link = next((p for p in pages if p["href"] == f"{target}.html"), None)
        return ("feature", features_info[target], {"label": "Open it", "href": f"{target}.html"} if link is None else {"label": f"Open {link['label']}", "href": link["href"]})
    if target in workflows_info:
        return ("workflow", workflows_info[target], None)
    return None


def _fast_system_answer(question: str, role: str, page_id: str, role_kb: dict, pages: list, prev_question: str = "") -> tuple:
    """Try to answer deterministically from knowledge base. Returns (answer, suggestion) or (None, None) if LLM is needed.
    `prev_question` enables follow-up resolution (e.g. 'how do I reduce it?')."""
    q = question.strip()
    ql = q.lower().strip()
    pages_info = role_kb.get("pages", {})
    features_info = role_kb.get("features", {})
    workflows_info = role_kb.get("workflows", {})

    # 1) Greetings
    if _SG_GREETINGS.match(ql):
        suggestions = {
            "patient": "You can check your appointments, link doctors, upload a prescription in MediScan, or chat with the AI Doctor.",
            "nurse": "You can check your dashboard KPIs, manage your patients, record vitals, or file a discharge appeal.",
            "doctor": "You can check your Today / Active / Wait / Compliance cards, manage patients, or review clinical tools.",
            "hospital": "You can manage the admit queue, review discharge appeals, or manage members.",
            "shopkeeper": "You can manage inventory, view expiry alerts, or create bills.",
        }
        return f"Hello! I'm your System Guide. {suggestions.get(role, 'Ask me how to use any feature.')}", None

    # 2) Thanks
    if _SG_THANKS.match(ql):
        return "You're welcome! Let me know if you need help with anything else.", None

    # 3) Goodbye
    if _SG_BYE.match(ql):
        return "Goodbye! Feel free to come back anytime you need help.", None

    # 4) What is this page? (page-aware)
    if _SG_WHAT_IS_THIS.match(ql):
        desc = pages_info.get(page_id)
        if not desc and page_id in features_info:
            desc = features_info.get(page_id)
        if not desc:
            desc = "the current page"
        return desc + (" You can navigate to other sections from the sidebar." if pages else ""), None

    # 4b) What does this KPI card mean? (role-aware card explainer)
    m_card = _SG_WHAT_IS_CARD.match(ql)
    if m_card:
        card = m_card.group(3).lower().strip()
        desc = _sg_card_explain(role, card)
        if desc:
            return desc, None
        # Card exists on another role's dashboard -> polite denial.
        card_exists_elsewhere = any(
            key in card and _SG_CARD_MAP.get(other, {}).get(key)
            for other in ("doctor", "nurse", "patient")
            for key in _SG_CARD_KEYWORDS
        )
        if card_exists_elsewhere:
            return f"That card isn't part of the {_SG_ROLE_LABEL.get(role, role)} dashboard in this application.", None

    # 4c) Follow-up without an explicit subject: "...it/this/that/one"
    follow = _FOLLOWUP_RE.match(ql)
    if follow and (" it" in ql or " this" in ql or " that" in ql or " one" in ql or ql in ("how?", "what?", "why?")):
        prev_l = prev_question.lower()
        # Card follow-up (e.g. prev: "what does Active mean?" -> "how do I reduce it?")
        card_desc = _sg_card_explain(role, prev_l)
        if card_desc and ("reduce" in ql or "lower" in ql or "increase" in ql or "mean" in ql or "is it" in ql):
            return card_desc, None
        subj = _sg_resolve_target(prev_l)
        if subj:
            hit = _sg_lookup_phrase(role, role_kb, subj)
            if hit and hit[1]:
                return hit[1], hit[2]

    # 5) How do I use this / go back to dashboard?
    if _SG_HOW_TO_USE.match(ql):
        if "dashboard" in ql:
            for p in pages:
                if p["id"] == "dashboard":
                    return f"Click **Dashboard** in the sidebar to return to your main dashboard.", {"label": "Open Dashboard", "href": p["href"]}
        desc = pages_info.get(page_id, "the current page")
        return f"You're on the {page_id.replace('-', ' ').title()} page. {desc}", None

    # 5b) How do I do <workflow>? e.g. record vitals, file appeal, upload a file
    if ql.startswith(("how do i", "how can i", "how to", "how do you")):
        for wid, desc in workflows_info.items():
            words = wid.replace("-", " ").split()
            if all(any(w in ql for w in words[i:i + 2]) for i in range(0, len(words), 2)) or any(
                w in ql for w in words if len(w) > 3
            ):
                # Skip weak matches like 'view' matching many workflows.
                if len(words) > 1 or wid in ("chat", "call"):
                    return desc, _sg_find_page_suggestion(role, desc)
        # Media / file questions (shared guidance)
        if any(t in ql for t in ["upload", "file", "document", "image", "pdf", "attach", "media", "photo"]):
            return _SG_SHARED["chat-media"], None
        if "video" in ql or "camera" in ql or "face" in ql:
            return _SG_SHARED["video-call"], None
        if "call" in ql or "phone" in ql:
            return _SG_SHARED["audio-call"], None

    # 6) Where is X? / find X
    m = _SG_WHERE_IS.match(ql)
    if m:
        target = m.group(3).strip().rstrip("?.")
        target_l = target.lower()
        # Map colloquial phrases like "my reports" to canonical ids.
        target_l = target_l.replace("my ", "").replace("the ", "").replace("a ", "")
        # Role-aware aliases for records / reports.
        if role == "patient" and ("report" in target_l or "record" in target_l or "history" in target_l):
            desc = pages_info.get("my-records", "")
            link = next((p for p in pages if p["id"] == "my-records"), None)
            sug = {"label": "Open My records", "href": link["href"]} if link else None
            return desc, sug
        if role in ("doctor", "nurse", "hospital") and ("report" in target_l or "record" in target_l):
            desc = pages_info.get("patient-records", "")
            link = next((p for p in pages if p["id"] == "patient-records"), None)
            sug = {"label": "Open Patient Records", "href": link["href"]} if link else None
            return desc, sug
        canonical = _sg_resolve_target(target_l)
        if canonical:
            hit = _sg_lookup_phrase(role, role_kb, canonical)
            if hit:
                kind, desc, sug = hit
                return desc, sug
        # Role gate: feature exists for another role but not this one.
        for other, pages_other in _SYSTEM_PAGES.items():
            if other == role:
                continue
            for p in pages_other:
                lbl = p["label"].lower()
                pid = p["id"]
                if (canonical and pid == canonical) or lbl in target_l or pid.replace("-", " ") in target_l:
                    return (f"**{p['label']}** isn't available to {_SG_ROLE_LABEL.get(role, role)} accounts "
                            f"in this application.", None)
        return f"I don't see \"{target}\" in the current system. Try asking about a page or feature from your sidebar.", None

    # 7) What can I do / help / features? (page-aware)
    if _SG_WHAT_CAN_I.match(ql):
        current_desc = pages_info.get(page_id, "")
        feature_list = ", ".join([f.replace("-", " ").title() for f in features_info.keys()])
        page_list = ", ".join([p["label"] for p in pages if p["id"] != "chat"])
        answer = f"On this page: {current_desc}"
        if page_list:
            answer += f"\n\nYou can use: {page_list}."
        if feature_list:
            answer += f"\n\nFeatures available: {feature_list}."
        return answer, None

    # 7b) Chat / call / media questions phrased freely
    if "video call" in ql or "video-call" in ql:
        return _SG_SHARED["video-call"], None
    if ("audio call" in ql or "phone call" in ql) or (
        "call" in ql and any(t in ql for t in ["start", "make", "how", "contact", "doctor", "nurse"])
    ):
        return _SG_SHARED["audio-call"], None
    if ql in ("chat",) or "send a document" in ql or "send a file" in ql or "send media" in ql or "attach" in ql:
        if "document" in ql or "file" in ql or "media" in ql or "image" in ql:
            return _SG_SHARED["chat-media"], None
        return _SG_SHARED["chat"], None
    if "notification" in ql and any(t in ql for t in ["where", "see", "check", "find", "open"]):
        return _SG_SHARED["notifications"], None

    # 8) Feature-specific: check if the question mentions a known feature
    for fid, desc in features_info.items():
        fid_concat = fid.replace("-", "")
        fid_space = fid.replace("-", " ")
        if fid_concat in ql.replace(" ", "") or fid_space in ql:
            fid_words = fid_space.split()
            if not any(
                re.search(r'\b' + re.escape(w) + r'\b', ql) for w in fid_words if len(w) > 3
            ):
                continue
            link = next((p for p in pages if fid in p.get("href", "")), None)
            if link:
                return f"**{fid_space.title()}**: {desc}", {"label": f"Open {link['label']}", "href": link["href"]}
            return f"**{fid_space.title()}**: {desc}", {"label": "Open it", "href": f"{fid}.html"}

    # 8b) Feature exists in the system but NOT for this role -> polite denial.
    for other, kb in _SYSTEM_GUIDANCE_KB.items():
        if other.startswith("_") or other == role:
            continue
        for fid in kb.get("features", []):
            spaced = fid.replace("-", " ")
            if spaced in ql:
                return f"**{spaced.title()}** isn't part of the {_SG_ROLE_LABEL.get(role, role)} experience. " \
                       f"It's only available to {_SG_ROLE_LABEL.get(other, other)} accounts.", None

    # 9) Workflow-specific: check if the question mentions a known workflow
    for wid, desc in workflows_info.items():
        wid_words = wid.replace("-", " ").split()
        if any(w in ql for w in wid_words if len(w) > 3):
            return desc, _sg_find_page_suggestion(role, desc)

    # 10) Page-specific: check if question mentions a known page
    for pid, desc in pages_info.items():
        if pid.replace("-", " ") in ql:
            link = next((p for p in pages if p["id"] == pid), None)
            if link:
                return f"**{link['label']}**: {desc}", {"label": f"Open {link['label']}", "href": link["href"]}
            return desc, None

    # No fast answer available — need LLM
    return None, None


def _fallback_system_guide(question: str, role: str, page_id: str, role_kb: dict) -> str:
    """Keyword-based fallback when LLM is unavailable."""
    q = question.lower()
    pages = role_kb.get("pages", {})
    features = role_kb.get("features", {})
    workflows = role_kb.get("workflows", {})

    # Check features
    for fid, desc in features.items():
        if fid.replace("-", " ") in q or fid.replace("-", "") in q.replace(" ", ""):
            return f"{fid.replace('-', ' ').title()}: {desc}"

    # Check workflows
    for wid, desc in workflows.items():
        if wid.replace("-", " ") in q:
            return desc

    # Check pages
    for pid, desc in pages.items():
        if pid.replace("-", " ") in q:
            return desc

    # Role-gated feature exists elsewhere
    for other, kb in _SYSTEM_GUIDANCE_KB.items():
        if other.startswith("_") or other == role:
            continue
        for fid in kb.get("features", []):
            if fid.replace("-", " ") in q:
                return (f"{fid.replace('-', ' ').title()} isn't available to "
                        f"{_SG_ROLE_LABEL.get(role, role)} accounts in this application.")

    # Generic response
    role_hint = {
        "patient": "your health dashboard, doctors, appointments, records, and AI tools",
        "nurse": "your dashboard KPIs, patients, vitals, notes, and discharge appeals",
        "doctor": "your dashboard analytics, patients, appointments, and clinical tools",
        "hospital": "admissions, beds, members, and discharge appeals",
        "shopkeeper": "inventory, expiry alerts, and billing",
    }
    return (
        f"I can help you navigate the {_SG_ROLE_LABEL.get(role, role)} area — {role_hint.get(role, 'the available pages')}. "
        f"Try asking like 'Where are my appointments?' or 'How do I use MediScan?'"
    )


# ============================================================
# PatientRecords (2026-08)
# ---------------------------------------------------------------------
# Doctor / Hospital / Nurse page that surfaces "everything about one
# patient" — profile, history, records, prescriptions, vitals, reminders,
# reports, scans, admissions — with first-class search (id, aadhar,
# place, name, gender, age-range, linked-doctor) and the ability to
# add / edit any field including Aadhaar. Patients get a separate
# self-edit endpoint below.
# ============================================================


def _patient_records_visible_to(current_user: models.User, db: Session):
    """Build a `db.query(Patient)` that's pre-filtered to records the
    caller is allowed to see.

    Visibility rules:
      * doctor  → any patient they have a PatientDoctorLink to
      * hospital → any patient admitted to one of their hospital's wards
      * nurse   → any patient they have an active NurseAssignment on
      * patient → only their own record
      * anything else → denied (caller raises 403 themselves)

    Returning a query (not a list) lets the search endpoint keep its
    filter chain — count / paging can be applied after this scoping.
    """
    role = current_user.role
    if role == "doctor":
        linked_ids = [
            pid for (pid,) in db.query(models.PatientDoctorLink.patient_id)
            .filter(models.PatientDoctorLink.doctor_user_id == current_user.id)
            .all()
        ]
        if not linked_ids:
            return db.query(models.Patient).filter(models.Patient.id == -1)
        return db.query(models.Patient).filter(models.Patient.id.in_(linked_ids))

    if role == "hospital":
        # Hospital admin sees patients admitted to their hospital's wards.
        # Use _ensure_hospital_admin to fetch hospital_id safely.
        try:
            profile = _ensure_hospital_admin(db, current_user)
        except HTTPException:
            return db.query(models.Patient).filter(models.Patient.id == -1)
        hid = profile.hospital_id
        admitted_ids = [
            pid for (pid,) in db.query(models.Admission.patient_id)
            .join(models.Bed, models.Bed.id == models.Admission.bed_id, isouter=True)
            .join(models.Ward, models.Ward.id == models.Bed.ward_id, isouter=True)
            .filter(models.Ward.hospital_id == hid)
            .distinct()
            .all()
        ]
        if not admitted_ids:
            return db.query(models.Patient).filter(models.Patient.id == -1)
        return db.query(models.Patient).filter(models.Patient.id.in_(admitted_ids))

    if role == "nurse":
        assigned_ids = [
            pid for (pid,) in db.query(models.NurseAssignment.patient_id)
            .filter(
                models.NurseAssignment.nurse_user_id == current_user.id,
                models.NurseAssignment.is_active == True,  # noqa: E712
            )
            .all()
        ]
        if not assigned_ids:
            return db.query(models.Patient).filter(models.Patient.id == -1)
        return db.query(models.Patient).filter(models.Patient.id.in_(assigned_ids))

    if role == "patient":
        if not current_user.patient_id:
            return db.query(models.Patient).filter(models.Patient.id == -1)
        return db.query(models.Patient).filter(models.Patient.id == current_user.patient_id)

    return db.query(models.Patient).filter(models.Patient.id == -1)


@app.get("/patient-records/search", response_model=schemas.PatientRecordSearchOut)
def patient_records_search(
    q: Optional[str] = None,
    aadhar: Optional[str] = None,
    city: Optional[str] = None,
    state: Optional[str] = None,
    place: Optional[str] = None,
    gender: Optional[str] = None,
    age_min: Optional[int] = None,
    age_max: Optional[int] = None,
    linked_doctor_id: Optional[int] = None,
    has_user_account: Optional[bool] = None,
    limit: int = 25,
    offset: int = 0,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Search the patient roster with the supported filters.

    All filters are AND-combined. ``q`` is a generic case-insensitive
    substring match across name / place / contact — useful when the
    doctor remembers a fragment but not the full value. ``aadhar``
    matches exact or normalised digits (spaces / dashes stripped).

    Result rows are scoped to the caller: a doctor sees only their
    linked patients; a hospital admin sees only patients admitted to
    their hospital; a nurse sees only their assigned patients. This
    never leaks patient existence across boundaries (returns 404-style
    "empty list" instead of "you don't have permission").
    """
    if current_user.role not in {"doctor", "hospital", "nurse", "patient"}:
        raise HTTPException(status_code=403, detail="Not allowed")

    limit = max(1, min(limit, 100))
    offset = max(0, offset)

    query = _patient_records_visible_to(current_user, db)

    if aadhar:
        # Strip spaces/dashes so users can search with or without them.
        digits = "".join(ch for ch in aadhar if ch.isdigit())
        if digits:
            query = query.filter(models.Patient.aadhar_number.like(f"%{digits}%"))
        else:
            query = query.filter(models.Patient.aadhar_number.like(f"%{aadhar}%"))

    if place:
        query = query.filter(models.Patient.place.ilike(f"%{place}%"))
    if city:
        # Free-text on place but anchored on a leading match so "Pun" finds
        # "Pune" without dragging in "Kar-Pune" etc.
        query = query.filter(models.Patient.place.ilike(f"{city}%"))
    if state:
        query = query.filter(models.Patient.place.ilike(f"%{state}%"))

    if gender:
        if gender not in schemas.PATIENTRECORDS_GENDERS:
            raise HTTPException(
                status_code=400,
                detail=f"Invalid gender. Must be one of: {sorted(schemas.PATIENTRECORDS_GENDERS)}",
            )
        query = query.filter(models.Patient.gender == gender)

    if age_min is not None:
        query = query.filter(models.Patient.age >= age_min)
    if age_max is not None:
        query = query.filter(models.Patient.age <= age_max)

    if linked_doctor_id:
        linked_ids = [
            pid for (pid,) in db.query(models.PatientDoctorLink.patient_id)
            .filter(models.PatientDoctorLink.doctor_user_id == linked_doctor_id)
            .all()
        ]
        if linked_ids:
            query = query.filter(models.Patient.id.in_(linked_ids))
        else:
            query = query.filter(models.Patient.id == -1)

    if has_user_account is not None:
        # A patient has a user account ↔ users.patient_id == patients.id.
        user_patient_ids = {
            pid for (pid,) in db.query(models.User.patient_id)
            .filter(models.User.patient_id.isnot(None))
            .all()
        }
        if has_user_account:
            query = query.filter(models.Patient.id.in_(list(user_patient_ids) or [-1]))
        else:
            query = query.filter(~models.Patient.id.in_(list(user_patient_ids) or [0]))

    if q:
        like = f"%{q}%"
        query = query.filter(
            models.Patient.name.ilike(like)
            | models.Patient.place.ilike(like)
            | models.Patient.contact.ilike(like)
        )

    total = query.count()
    rows = (
        query.order_by(models.Patient.created_at.desc())
        .offset(offset)
        .limit(limit)
        .all()
    )

    # Build the response shape — inline aggregate counts so the page can
    # show badges without N+1 roundtrips.
    results: list[schemas.PatientRecordSearchResult] = []
    for pat in rows:
        records_count = (
            db.query(models.MedicalRecord)
            .filter(models.MedicalRecord.patient_id == pat.id)
            .count()
        )
        prescriptions_count = (
            db.query(models.Prescription)
            .filter(models.Prescription.patient_id == pat.id)
            .count()
        )
        reports_count = (
            db.query(models.PatientReport)
            .filter(models.PatientReport.patient_id == pat.id)
            .count()
        )
        history_count = (
            db.query(models.MedicalHistoryEntry)
            .filter(models.MedicalHistoryEntry.patient_id == pat.id)
            .count()
        )
        primary_link = (
            db.query(models.PatientDoctorLink)
            .filter(models.PatientDoctorLink.patient_id == pat.id)
            .order_by(models.PatientDoctorLink.created_at.asc())
            .first()
        )
        primary_link_name = None
        if primary_link:
            doc_user = (
                db.query(models.User)
                .filter(models.User.id == primary_link.doctor_user_id)
                .first()
            )
            primary_link_name = (
                doc_user.full_name
                if doc_user and doc_user.full_name
                else (doc_user.username if doc_user else None)
            )

        user = (
            db.query(models.User)
            .filter(models.User.patient_id == pat.id)
            .order_by(models.User.id.asc())
            .first()
        )

        results.append(
            schemas.PatientRecordSearchResult(
                patient_id=pat.id,
                name=pat.name,
                age=pat.age,
                gender=pat.gender,
                contact=pat.contact,
                aadhar_number=pat.aadhar_number,
                place=pat.place,
                records_count=records_count,
                prescriptions_count=prescriptions_count,
                reports_count=reports_count,
                history_count=history_count,
                primary_linked_doctor_id=(
                    primary_link.doctor_user_id if primary_link else None
                ),
                primary_linked_doctor_name=primary_link_name,
                has_user_account=bool(user),
                user_id=user.id if user else None,
                username=user.username if user else None,
                created_at=pat.created_at,
            )
        )

    applied = {
        "q": q,
        "aadhar": aadhar,
        "city": city,
        "state": state,
        "place": place,
        "gender": gender,
        "age_min": age_min,
        "age_max": age_max,
        "linked_doctor_id": linked_doctor_id,
        "has_user_account": has_user_account,
        "limit": limit,
        "offset": offset,
    }
    return schemas.PatientRecordSearchOut(
        items=results, total_count=total, applied_filters=applied
    )


@app.get(
    "/patient-records/{patient_id}/bundle",
    response_model=schemas.PatientRecordBundle,
)
def patient_records_bundle(
    patient_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Return everything we know about one patient, in a single GET.

    Populates the right-hand "detail panel" with profile + history +
    records + prescriptions + vitals + reminders + reports + scans +
    admissions + linked-doctors. Access scoping is enforced via
    ``_ensure_patient_access`` — a doctor without a PatientDoctorLink
    gets 404 (so we don't leak existence), and a patient can only see
    their own bundle."""
    _ensure_patient_access(current_user, patient_id, db)

    patient = (
        db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    )
    if not patient:
        raise HTTPException(status_code=404, detail="Patient not found")

    # Hydrate the PatientOut-shaped payload (includes linked_doctors).
    # Reuses the same shape returned by /patients/{id} so the JS can
    # render with one code path.
    patient_out = schemas.PatientOut(
        id=patient.id,
        name=patient.name,
        age=patient.age,
        gender=patient.gender,
        contact=patient.contact,
        aadhar_number=getattr(patient, "aadhar_number", None),
        place=getattr(patient, "place", None),
        created_at=patient.created_at,
        onboarded_by_doctor_id=getattr(patient, "onboarded_by_doctor_id", None),
        linked_doctors=_serialize_patient_links(db, patient.id),
    )

    profile = (
        db.query(models.PatientProfile)
        .filter(models.PatientProfile.patient_id == patient_id)
        .first()
    )
    history = (
        db.query(models.MedicalHistoryEntry)
        .filter(models.MedicalHistoryEntry.patient_id == patient_id)
        .order_by(models.MedicalHistoryEntry.created_at.desc())
        .all()
    )
    records = (
        db.query(models.MedicalRecord)
        .filter(models.MedicalRecord.patient_id == patient_id)
        .order_by(models.MedicalRecord.created_at.desc())
        .all()
    )
    prescriptions = (
        db.query(models.Prescription)
        .filter(models.Prescription.patient_id == patient_id)
        .order_by(models.Prescription.created_at.desc())
        .all()
    )
    vitals = (
        db.query(models.VitalRecord)
        .filter(models.VitalRecord.patient_id == patient_id)
        .order_by(models.VitalRecord.recorded_at.desc())
        .all()
    )
    reminders = (
        db.query(models.Reminder)
        .filter(models.Reminder.patient_id == patient_id)
        .order_by(models.Reminder.created_at.asc())
        .all()
    )
    reports = (
        db.query(models.PatientReport)
        .filter(models.PatientReport.patient_id == patient_id)
        .order_by(models.PatientReport.uploaded_at.desc())
        .all()
    )
    documents = (
        db.query(models.DocumentScan)
        .filter(models.DocumentScan.patient_id == patient_id)
        .order_by(models.DocumentScan.created_at.desc())
        .all()
    )
    admissions = (
        db.query(models.Admission)
        .filter(models.Admission.patient_id == patient_id)
        .order_by(models.Admission.admitted_at.desc())
        .all()
    )
    links = (
        db.query(models.PatientDoctorLink)
        .filter(models.PatientDoctorLink.patient_id == patient_id)
        .order_by(models.PatientDoctorLink.created_at.asc())
        .all()
    )

    # --- Generate AI summary ---
    ai_summary = None
    try:
        active_reminders_q = (
            db.query(models.Reminder)
            .filter(models.Reminder.patient_id == patient_id, models.Reminder.is_active == True)
            .all()
        )
        ai_summary = gemini_client.summarize_patient(
            patient_info={"name": patient.name, "age": patient.age, "gender": patient.gender},
            records=[{"symptoms": r.symptoms, "diagnosis": r.diagnosis, "notes": r.notes} for r in records],
            prescriptions=[{"medicine_name": p.medicine_name, "dosage": p.dosage} for p in prescriptions],
            trends_data={},
            reminders=[{"medicine_name": r2.medicine_name, "times": r2.times} for r2 in active_reminders_q],
            patient_profile={
                "blood_group": profile.blood_group if profile else None,
                "address": profile.address if profile else None,
                "city": profile.city if profile else None,
                "state": profile.state if profile else None,
            } if profile else None,
            medical_history=[{"category": h.category, "title": h.title, "details": h.details,
                              "diagnosed_year": h.diagnosed_year, "is_ongoing": h.is_ongoing}
                             for h in history],
            reports=[{"title": rp.title, "category": rp.category, "file_name": rp.file_name,
                      "notes": rp.notes} for rp in reports],
        )
    except Exception:
        ai_summary = None

    # --- Quick stats ---
    last_visit_date = None
    if records:
        last_visit_date = records[0].created_at.isoformat() if records[0].created_at else None
    elif prescriptions:
        last_visit_date = prescriptions[0].created_at.isoformat() if prescriptions[0].created_at else None

    return schemas.PatientRecordBundle(
        patient=patient_out,
        profile=schemas.PatientProfileOut.model_validate(profile) if profile else None,
        history=[schemas.MedicalHistoryOut.model_validate(h) for h in history],
        records=[schemas.RecordOut.model_validate(r) for r in records],
        prescriptions=[schemas.PrescriptionOut.model_validate(p) for p in prescriptions],
        vitals=[schemas.VitalOut.model_validate(v) for v in vitals],
        reminders=[schemas.ReminderOut.model_validate(rem) for rem in reminders],
        reports=[schemas.PatientReportOut.model_validate(r) for r in reports],
        documents=[schemas.DocumentScanOut.model_validate(d) for d in documents],
        admissions=[schemas.AdmissionOut.model_validate(a) for a in admissions],
        linked_doctors=[schemas.PatientDoctorLinkOut.model_validate(l) for l in links],
        ai_summary=ai_summary,
        total_visits=len(records) + len(prescriptions),
        active_prescriptions=len(prescriptions),
        last_visit=last_visit_date,
    )


@app.patch("/patient-records/{patient_id}/demographics")
def patient_records_update_demographics(
    patient_id: int,
    payload: dict,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Partial update of the demographic fields on Patient + PatientProfile.

    Accepts: name, age, gender, contact, place, aadhar_number (on the
    Patient row) and blood_group, address, city, state,
    emergency_contact_name, emergency_contact_phone, notes (on
    PatientProfile). Empty strings are coerced to NULL.

    Doctor / hospital / nurse only — patients edit their own record via
    /patients/me/profile instead."""
    if current_user.role not in {"doctor", "hospital", "nurse"}:
        raise HTTPException(status_code=403, detail="Not allowed")
    _ensure_patient_access(current_user, patient_id, db)

    patient = (
        db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    )
    if not patient:
        raise HTTPException(status_code=404, detail="Patient not found")

    patient_fields = {"name", "age", "gender", "contact", "place", "aadhar_number"}
    for f, v in payload.items():
        if f in patient_fields:
            if isinstance(v, str) and not v.strip():
                v = None
            setattr(patient, f, v)

    profile_fields = {
        "blood_group",
        "address",
        "city",
        "state",
        "emergency_contact_name",
        "emergency_contact_phone",
        "notes",
    }
    if any(f in payload for f in profile_fields):
        profile = (
            db.query(models.PatientProfile)
            .filter(models.PatientProfile.patient_id == patient_id)
            .first()
        )
        if not profile:
            profile = models.PatientProfile(patient_id=patient_id)
            db.add(profile)
        for f, v in payload.items():
            if f in profile_fields:
                if isinstance(v, str) and not v.strip():
                    v = None
                setattr(profile, f, v)

    db.commit()
    db.refresh(patient)
    return {"ok": True, "patient_id": patient_id}


# ---------- Patient self-edit (2026-08) ----------
# Patients get a single endpoint that lets them update their own
# demographics + profile + aadhaar. Doctors/hospitals/nurses use
# PATCH /patient-records/{id}/demographics instead.

@app.patch("/patients/me/profile")
def patient_me_update_profile(
    payload: schemas.PatientSelfProfileUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Patient self-edit: update contact, age, gender, place, aadhaar,
    address, blood group, etc. on the patient's own record.

    Both the top-level Patient row and the PatientProfile row are
    patched in a single call so the patient doesn't have to call two
    endpoints. Empty strings get coerced to NULL by the schema's
    field validator."""
    if current_user.role != "patient":
        raise HTTPException(
            status_code=403,
            detail="Only patient accounts can self-edit via /patients/me/profile",
        )
    if not current_user.patient_id:
        raise HTTPException(
            status_code=404,
            detail="Your account is not linked to a patient record yet.",
        )

    patient = (
        db.query(models.Patient)
        .filter(models.Patient.id == current_user.patient_id)
        .first()
    )
    if not patient:
        raise HTTPException(status_code=404, detail="Patient record not found")

    # Top-level Patient fields. ``name`` is required by the model, so
    # always fall back to the existing value if the payload omits it.
    data = payload.model_dump(exclude_unset=True)
    for f in ("name", "age", "gender", "contact", "place", "aadhar_number"):
        if f in data:
            setattr(patient, f, data[f])

    # Extended fields live on PatientProfile.
    profile_fields = {
        "blood_group",
        "address",
        "city",
        "state",
        "emergency_contact_name",
        "emergency_contact_phone",
        "notes",
    }
    if any(f in data for f in profile_fields):
        profile = (
            db.query(models.PatientProfile)
            .filter(models.PatientProfile.patient_id == patient.id)
            .first()
        )
        if not profile:
            profile = models.PatientProfile(patient_id=patient.id)
            db.add(profile)
        for f in profile_fields:
            if f in data:
                setattr(profile, f, data[f])

    db.commit()
    db.refresh(patient)
    return {
        "ok": True,
        "patient_id": patient.id,
        "name": patient.name,
        "age": patient.age,
        "gender": patient.gender,
        "contact": patient.contact,
        "place": getattr(patient, "place", None),
        "aadhar_number": getattr(patient, "aadhar_number", None),
    }


@app.post("/patients/me/history")
def patient_me_add_history(
    payload: schemas.PatientMedicalHistoryUpsert,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Patient self-service: append a MedicalHistoryEntry on their own
    record. The existing /patients/{id}/history endpoint already accepts
    patient-role callers (via _ensure_patient_access), but this alias
    keeps the patient UX clean — no need to know one's own patient_id."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=404, detail="Patient record not found")
    if payload.category not in ALLOWED_HISTORY_CATEGORIES:
        raise HTTPException(status_code=400, detail=f"Invalid category. Must be one of: {sorted(ALLOWED_HISTORY_CATEGORIES)}")
    entry = models.MedicalHistoryEntry(
        patient_id=current_user.patient_id,
        category=payload.category,
        title=payload.title,
        details=payload.description,
        is_ongoing=payload.is_ongoing,
    )
    db.add(entry)
    db.commit()
    db.refresh(entry)
    return schemas.MedicalHistoryOut.model_validate(entry)


@app.delete("/patients/me/history/{entry_id}")
def patient_me_delete_history(
    entry_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=404, detail="Patient record not found")
    entry = (
        db.query(models.MedicalHistoryEntry)
        .filter(
            models.MedicalHistoryEntry.id == entry_id,
            models.MedicalHistoryEntry.patient_id == current_user.patient_id,
        )
        .first()
    )
    if not entry:
        raise HTTPException(status_code=404, detail="History entry not found")
    db.delete(entry)
    db.commit()
    return {"message": "History entry deleted", "id": entry_id}


# ===========================================================================
# Admin Panel — User Management
# ===========================================================================

def _ensure_admin(current_user: models.User) -> None:
    """Raise 403 unless the caller is an admin."""
    if current_user.role != "admin":
        raise HTTPException(status_code=403, detail="Admin access only.")


class AdminUserUpdate(BaseModel):
    username: Optional[str] = None
    email: Optional[str] = None
    full_name: Optional[str] = None
    password: Optional[str] = None  # plain text, will be hashed
    role: Optional[str] = None


class AdminUserCreate(BaseModel):
    username: str
    email: str
    full_name: Optional[str] = None
    password: str
    role: str = "patient"


@app.get("/admin/users")
def admin_list_users(
    role: Optional[str] = None,
    search: Optional[str] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List all user accounts. Optionally filter by role or search by name/email/username."""
    _ensure_admin(current_user)
    q = db.query(models.User)
    if role and role != "all":
        q = q.filter(models.User.role == role)
    if search:
        term = f"%{search}%"
        q = q.filter(
            (models.User.username.ilike(term)) |
            (models.User.email.ilike(term)) |
            (models.User.full_name.ilike(term))
        )
    users = q.order_by(models.User.id).all()
    result = []
    for u in users:
        result.append({
            "id": u.id,
            "username": u.username,
            "email": u.email,
            "full_name": u.full_name or "",
            "role": u.role or "patient",
            "patient_id": u.patient_id,
            "created_at": u.created_at.isoformat() if hasattr(u, 'created_at') and u.created_at else None,
        })
    return {"users": result, "total": len(result)}


@app.get("/admin/users/{user_id}")
def admin_get_user(
    user_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Get a single user's details."""
    _ensure_admin(current_user)
    user = db.query(models.User).filter(models.User.id == user_id).first()
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    return {
        "id": user.id,
        "username": user.username,
        "email": user.email,
        "full_name": user.full_name or "",
        "role": user.role or "patient",
        "patient_id": user.patient_id,
    }


@app.put("/admin/users/{user_id}")
def admin_update_user(
    user_id: int,
    body: AdminUserUpdate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Edit a user's credentials (email, name, password, role)."""
    _ensure_admin(current_user)
    user = db.query(models.User).filter(models.User.id == user_id).first()
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    if body.username is not None and body.username.strip():
        # Check uniqueness
        existing = db.query(models.User).filter(
            models.User.username == body.username, models.User.id != user_id
        ).first()
        if existing:
            raise HTTPException(status_code=409, detail="Username already taken")
        user.username = body.username.strip()
    if body.email is not None:
        # Check uniqueness
        existing = db.query(models.User).filter(
            models.User.email == body.email, models.User.id != user_id
        ).first()
        if existing:
            raise HTTPException(status_code=409, detail="Email already in use")
        user.email = body.email
    if body.full_name is not None:
        user.full_name = body.full_name
    if body.password is not None and body.password.strip():
        user.hashed_password = auth.hash_password(body.password)
    if body.role is not None:
        user.role = body.role
    db.commit()
    return {"message": "User updated", "id": user.id}


@app.post("/admin/users")
def admin_create_user(
    body: AdminUserCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Create a new user account."""
    _ensure_admin(current_user)
    # Check uniqueness
    if db.query(models.User).filter(models.User.username == body.username).first():
        raise HTTPException(status_code=409, detail="Username already exists")
    if db.query(models.User).filter(models.User.email == body.email).first():
        raise HTTPException(status_code=409, detail="Email already exists")
    new_user = models.User(
        username=body.username,
        email=body.email,
        full_name=body.full_name,
        hashed_password=auth.hash_password(body.password),
        role=body.role,
    )
    db.add(new_user)
    db.commit()
    db.refresh(new_user)
    return {"message": "User created", "id": new_user.id}


@app.delete("/admin/users/{user_id}")
def admin_delete_user(
    user_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Delete a user account and all associated data."""
    _ensure_admin(current_user)
    if user_id == current_user.id:
        raise HTTPException(status_code=400, detail="Cannot delete your own account")
    user = db.query(models.User).filter(models.User.id == user_id).first()
    if not user:
        raise HTTPException(status_code=404, detail="User not found")

    # Delete associated data in order to avoid FK violations
    pid = user.patient_id
    uid = user.id
    role = user.role

    # Delete patient-specific data
    if pid:
        db.query(models.ChatMessage).filter(models.ChatMessage.patient_id == pid).delete(synchronize_session=False)
        db.query(models.Prescription).filter(models.Prescription.patient_id == pid).delete(synchronize_session=False)
        db.query(models.MedicalRecord).filter(models.MedicalRecord.patient_id == pid).delete(synchronize_session=False)
        db.query(models.PatientDoctorLink).filter(models.PatientDoctorLink.patient_id == pid).delete(synchronize_session=False)
        db.query(models.Appointment).filter(models.Appointment.patient_id == pid).delete(synchronize_session=False)
        # Delete the patient record itself
        db.query(models.Patient).filter(models.Patient.id == pid).delete(synchronize_session=False)

    # Delete user-specific data
    db.query(models.Notification).filter(models.Notification.user_id == uid).delete(synchronize_session=False)
    db.query(models.NotificationPreference).filter(models.NotificationPreference.user_id == uid).delete(synchronize_session=False)

    # Delete the user
    db.delete(user)
    db.commit()
    return {"message": "User deleted", "id": user_id}


@app.get("/admin/stats")
def admin_stats(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Dashboard stats for admin panel."""
    _ensure_admin(current_user)
    total = db.query(models.User).count()
    patients = db.query(models.User).filter(models.User.role == "patient").count()
    doctors = db.query(models.User).filter(models.User.role == "doctor").count()
    nurses = db.query(models.User).filter(models.User.role == "nurse").count()
    hospitals = db.query(models.User).filter(models.User.role == "hospital").count()
    shopkeepers = db.query(models.User).filter(models.User.role == "shopkeeper").count()
    return {
        "total": total,
        "patients": patients,
        "doctors": doctors,
        "nurses": nurses,
        "hospitals": hospitals,
        "shopkeepers": shopkeepers,
    }


# ===========================================================================
# WebRTC Signaling for Voice & Video Calls
# ===========================================================================
# In-memory signaling store. In production, use Redis or a dedicated
# signaling server. For this single-server setup, we keep it simple.
import asyncio

# call_sessions maps call_id -> {caller_id, callee_id, status, ...}
_call_sessions: dict = {}
# pending_calls maps callee_user_id -> call_id (one pending call per user)
_pending_calls: dict = {}
# connected_users maps user_id -> WebSocket (for push notifications)
_user_websockets: dict = {}


class CallSession(BaseModel):
    call_id: str
    caller_id: int
    caller_name: str
    callee_id: int
    callee_name: str
    call_type: str  # "voice" | "video"
    status: str = "ringing"  # ringing | connected | ended
    created_at: str = ""


class SignalMessage(BaseModel):
    type: str  # "offer" | "answer" | "ice-candidate" | "accept" | "reject" | "end"
    call_id: Optional[str] = None
    data: Optional[dict] = None


@app.get("/calls/online-users")
def get_online_users(
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Returns which of the user's linked contacts are online (have an active
    WebSocket connection). Doctors see their patients; patients see their doctors."""
    online = []
    if current_user.role == "doctor":
        pids = [
            pid for (pid,) in (
                db.query(models.PatientDoctorLink.patient_id)
                .filter(models.PatientDoctorLink.doctor_user_id == current_user.id)
                .all()
            )
        ]
        if pids:
            users = db.query(models.User).filter(
                models.User.patient_id.in_(pids),
                models.User.role == "patient",
            ).all()
            for u in users:
                if u.id in _user_websockets:
                    online.append({"user_id": u.id, "name": u.full_name or u.username})
    elif current_user.role == "patient":
        links = db.query(models.PatientDoctorLink).filter(
            models.PatientDoctorLink.patient_id == current_user.patient_id,
        ).all()
        for link in links:
            if link.doctor_user_id in _user_websockets:
                u = db.query(models.User).filter(models.User.id == link.doctor_user_id).first()
                if u:
                    online.append({"user_id": u.id, "name": u.full_name or u.username})
    return {"online": online}


def _validate_call_authorization(caller, callee_id, db):
    """Verify the caller is allowed to call the callee via existing care-team relationships.
    Returns True if authorized, raises HTTPException otherwise."""
    if caller.role == "admin":
        return True  # admin can reach anyone

    callee = db.query(models.User).filter(models.User.id == callee_id).first()
    if not callee:
        raise HTTPException(status_code=404, detail="User not found")

    if caller.role == "doctor":
        # Doctor can call: linked patients, assigned nurses, hospital admins
        patient_ids = [
            pid for (pid,) in db.query(models.PatientDoctorLink.patient_id)
            .filter(models.PatientDoctorLink.doctor_user_id == caller.id).all()
        ]
        patient_user_ids = [
            u.id for u in db.query(models.User)
            .filter(models.User.patient_id.in_(patient_ids or [0]), models.User.role == "patient").all()
        ]
        nurse_ids = [
            na.nurse_user_id for na in db.query(models.NurseAssignment)
            .filter(models.NurseAssignment.patient_id.in_(patient_ids or [0])).all()
            if na.nurse_user_id
        ]
        # Hospital admins linked to the doctor's patients
        hosp_ids = [
            a.hospital_id for a in db.query(models.Admission)
            .filter(models.Admission.patient_id.in_(patient_ids or [0]), models.Admission.discharged_at.is_(None)).all()
        ]
        hosp_admin_ids = [
            hp.user_id for hp in db.query(models.HospitalProfile)
            .filter(models.HospitalProfile.hospital_id.in_(hosp_ids or [0]), models.HospitalProfile.user_id.isnot(None)).all()
            if hp.user_id
        ]
        allowed = set(patient_user_ids + nurse_ids + hosp_admin_ids)
        if callee_id not in allowed:
            raise HTTPException(status_code=403, detail="Not authorized to call this user")

    elif caller.role == "patient":
        # Patient can call: linked doctors, assigned nurse, hospital admin
        links = db.query(models.PatientDoctorLink).filter(models.PatientDoctorLink.patient_id == caller.patient_id).all()
        doctor_ids = [l.doctor_user_id for l in links]
        nurse_assigns = db.query(models.NurseAssignment).filter(models.NurseAssignment.patient_id == caller.patient_id).all()
        nurse_ids = [na.nurse_user_id for na in nurse_assigns if na.nurse_user_id]
        hosp_ids = [a.hospital_id for a in db.query(models.Admission).filter(
            models.Admission.patient_id == caller.patient_id, models.Admission.discharged_at.is_(None)).all()]
        hosp_admin_ids = [
            hp.user_id for hp in db.query(models.HospitalProfile)
            .filter(models.HospitalProfile.hospital_id.in_(hosp_ids or [0]), models.HospitalProfile.user_id.isnot(None)).all()
            if hp.user_id
        ]
        allowed = set(doctor_ids + nurse_ids + hosp_admin_ids)
        if callee_id not in allowed:
            raise HTTPException(status_code=403, detail="Not authorized to call this user")

    elif caller.role == "nurse":
        # Nurse can call: assigned patients, linked doctors, hospital admin
        assigns = db.query(models.NurseAssignment).filter(models.NurseAssignment.nurse_user_id == caller.id).all()
        patient_ids = [a.patient_id for a in assigns]
        patient_user_ids = [
            u.id for u in db.query(models.User)
            .filter(models.User.patient_id.in_(patient_ids or [0]), models.User.role == "patient").all()
        ]
        doctor_ids = [
            l.doctor_user_id for l in db.query(models.PatientDoctorLink)
            .filter(models.PatientDoctorLink.patient_id.in_(patient_ids or [0])).all()
        ]
        allowed = set(patient_user_ids + doctor_ids)
        if callee_id not in allowed:
            raise HTTPException(status_code=403, detail="Not authorized to call this user")

    elif caller.role == "hospital":
        # Hospital can call: registered patients, linked doctors/nurses
        from sqlalchemy import or_
        hp = db.query(models.HospitalProfile).filter(models.HospitalProfile.user_id == caller.id).first()
        if hp:
            reg_links = db.query(models.HospitalRegistrationLink).filter(
                models.HospitalRegistrationLink.hospital_id == hp.hospital_id).all()
            patient_ids = [rl.patient_id for rl in reg_links]
            patient_user_ids = [
                u.id for u in db.query(models.User)
                .filter(models.User.patient_id.in_(patient_ids or [0]), models.User.role == "patient").all()
            ]
            allowed = set(patient_user_ids)
            if callee_id not in allowed:
                raise HTTPException(status_code=403, detail="Not authorized to call this user")

    return True


@app.post("/calls/initiate")
def initiate_call(
    callee_id: int,
    call_type: str = "voice",
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Initiate a voice or video call to a linked contact."""
    import uuid
    from datetime import datetime

    # Validate authorization
    _validate_call_authorization(current_user, callee_id, db)

    call_id = str(uuid.uuid4())[:8]
    callee = db.query(models.User).filter(models.User.id == callee_id).first()

    # Double-call protection: reject if caller already has an active call
    for sid, sess in _call_sessions.items():
        if sess["caller_id"] == current_user.id and sess["status"] in ("ringing", "connected"):
            raise HTTPException(status_code=409, detail="You already have an active call")
    # Also reject if callee is busy
    for sid, sess in _call_sessions.items():
        if sess["callee_id"] == callee_id and sess["status"] in ("ringing", "connected"):
            raise HTTPException(status_code=409, detail="User is already in a call")

    session = {
        "call_id": call_id,
        "caller_id": current_user.id,
        "caller_name": current_user.full_name or current_user.username,
        "callee_id": callee_id,
        "callee_name": callee.full_name or callee.username,
        "call_type": call_type,
        "status": "ringing",
        "created_at": datetime.utcnow().isoformat(),
    }
    _call_sessions[call_id] = session
    _pending_calls[callee_id] = call_id

    # Persist to database
    try:
        db_call = models.CallSession(
            call_id=call_id,
            caller_id=current_user.id,
            callee_id=callee_id,
            call_type=call_type,
            status="ringing",
            started_at=datetime.utcnow(),
        )
        db.add(db_call)
        db.commit()
    except Exception:
        db.rollback()

    # Notify callee via WebSocket if they're connected
    callee_ws = _user_websockets.get(callee_id)
    if callee_ws:
        import asyncio
        try:
            loop = asyncio.get_event_loop()
            loop.create_task(callee_ws.send_json({
                "type": "incoming_call",
                "call_id": call_id,
                "caller_id": current_user.id,
                "caller_name": current_user.full_name or current_user.username,
                "call_type": call_type,
            }))
        except Exception:
            pass

    # Set a 30-second timeout for ringing
    import asyncio as _aio
    async def _call_timeout():
        await _aio.sleep(30)
        sess = _call_sessions.get(call_id)
        if sess and sess["status"] == "ringing":
            sess["status"] = "ended"
            _pending_calls.pop(callee_id, None)
            _pending_calls.pop(current_user.id, None)
            callee_ws2 = _user_websockets.get(callee_id)
            if callee_ws2:
                try:
                    await callee_ws2.send_json({"type": "call_ended", "call_id": call_id, "reason": "timeout"})
                except Exception:
                    pass
            caller_ws2 = _user_websockets.get(current_user.id)
            if caller_ws2:
                try:
                    await caller_ws2.send_json({"type": "call_ended", "call_id": call_id, "reason": "timeout"})
                except Exception:
                    pass
            # Update DB
            try:
                db_call = db.query(models.CallSession).filter(models.CallSession.call_id == call_id).first()
                if db_call:
                    db_call.status = "timeout"
                    db_call.ended_at = datetime.utcnow()
                    db_call.ended_reason = "timeout"
                    db.commit()
            except Exception:
                db.rollback()
    try:
        loop = asyncio.get_event_loop()
        loop.create_task(_call_timeout())
    except Exception:
        pass

    return {"call_id": call_id, "status": "ringing", "callee_name": session["callee_name"]}


@app.post("/calls/{call_id}/accept")
def accept_call(
    call_id: str,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Accept an incoming call."""
    from datetime import datetime
    session = _call_sessions.get(call_id)
    if not session:
        raise HTTPException(status_code=404, detail="Call not found")
    if session["callee_id"] != current_user.id:
        raise HTTPException(status_code=403, detail="Not your call")
    session["status"] = "connected"
    _pending_calls.pop(session["callee_id"], None)

    # Persist to database
    try:
        db_call = db.query(models.CallSession).filter(models.CallSession.call_id == call_id).first()
        if db_call:
            db_call.status = "connected"
            db_call.accepted_at = datetime.utcnow()
            db_call.connected_at = datetime.utcnow()
            db.commit()
    except Exception:
        db.rollback()

    # Notify caller
    caller_ws = _user_websockets.get(session["caller_id"])
    if caller_ws:
        import asyncio
        try:
            loop = asyncio.get_event_loop()
            loop.create_task(caller_ws.send_json({
                "type": "call_accepted",
                "call_id": call_id,
            }))
        except Exception:
            pass

    return {"call_id": call_id, "status": "connected"}


@app.post("/calls/{call_id}/reject")
def reject_call(
    call_id: str,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """Reject an incoming call."""
    from datetime import datetime
    session = _call_sessions.get(call_id)
    if not session:
        raise HTTPException(status_code=404, detail="Call not found")
    session["status"] = "ended"
    _pending_calls.pop(session["callee_id"], None)

    # Persist to database
    try:
        db_call = db.query(models.CallSession).filter(models.CallSession.call_id == call_id).first()
        if db_call:
            db_call.status = "rejected"
            db_call.ended_at = datetime.utcnow()
            db_call.ended_reason = "callee_rejected"
            db.commit()
    except Exception:
        db.rollback()

    caller_ws = _user_websockets.get(session["caller_id"])
    if caller_ws:
        import asyncio
        try:
            loop = asyncio.get_event_loop()
            loop.create_task(caller_ws.send_json({
                "type": "call_rejected",
                "call_id": call_id,
            }))
        except Exception:
            pass

    return {"call_id": call_id, "status": "ended"}


@app.post("/calls/{call_id}/end")
def end_call(
    call_id: str,
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
):
    """End an active call."""
    from datetime import datetime
    session = _call_sessions.get(call_id)
    if not session:
        raise HTTPException(status_code=404, detail="Call not found")
    session["status"] = "ended"
    _pending_calls.pop(session["callee_id"], None)
    _pending_calls.pop(session["caller_id"], None)

    # Persist to database with duration
    try:
        db_call = db.query(models.CallSession).filter(models.CallSession.call_id == call_id).first()
        if db_call:
            now = datetime.utcnow()
            db_call.status = "ended"
            db_call.ended_at = now
            db_call.ended_reason = "caller_hung_up"
            if db_call.connected_at:
                db_call.duration_seconds = int((now - db_call.connected_at).total_seconds())
            db.commit()
    except Exception:
        db.rollback()

    # Notify the other party
    other_id = session["callee_id"] if session["caller_id"] == current_user.id else session["caller_id"]
    other_ws = _user_websockets.get(other_id)
    if other_ws:
        import asyncio
        try:
            loop = asyncio.get_event_loop()
            loop.create_task(other_ws.send_json({
                "type": "call_ended",
                "call_id": call_id,
            }))
        except Exception:
            pass

    return {"call_id": call_id, "status": "ended"}


@app.get("/calls/history")
def get_call_history(
    current_user: models.User = Depends(auth.get_current_user),
    db: Session = Depends(get_db),
    limit: int = 20,
):
    """Get call history for the authenticated user."""
    calls = (
        db.query(models.CallSession)
        .filter(
            (models.CallSession.caller_id == current_user.id) |
            (models.CallSession.callee_id == current_user.id)
        )
        .order_by(models.CallSession.started_at.desc())
        .limit(limit)
        .all()
    )
    result = []
    for c in calls:
        # Look up names
        caller = db.query(models.User).filter(models.User.id == c.caller_id).first()
        callee = db.query(models.User).filter(models.User.id == c.callee_id).first()
        result.append({
            "call_id": c.call_id,
            "caller_name": (caller.full_name or caller.username) if caller else "Unknown",
            "callee_name": (callee.full_name or callee.username) if callee else "Unknown",
            "call_type": c.call_type,
            "status": c.status,
            "ended_reason": c.ended_reason,
            "started_at": c.started_at.isoformat() if c.started_at else None,
            "duration_seconds": c.duration_seconds,
            "is_incoming": c.callee_id == current_user.id,
        })
    return {"calls": result}


@app.get("/calls/{call_id}")
def get_call_status(
    call_id: str,
    current_user: models.User = Depends(auth.get_current_user),
):
    """Get current call status."""
    session = _call_sessions.get(call_id)
    if not session:
        raise HTTPException(status_code=404, detail="Call not found")
    return session


@app.websocket("/ws/signaling/{user_id}")
def signaling_websocket(websocket: WebSocket, user_id: int):
    """WebSocket endpoint for WebRTC signaling.
    Handles: offer, answer, ice-candidate exchange between caller and callee."""
    asyncio.get_event_loop().run_until_complete(
        _handle_signaling_ws(websocket, user_id)
    )


async def _handle_signaling_ws(websocket: WebSocket, user_id: int):
    await websocket.accept()
    _user_websockets[user_id] = websocket
    try:
        while True:
            data = await websocket.receive_json()
            msg_type = data.get("type", "")
            target_id = data.get("target_id")

            if msg_type in ("offer", "answer", "ice-candidate"):
                # Forward the signaling message to the target user
                target_ws = _user_websockets.get(target_id)
                if target_ws:
                    await target_ws.send_json({
                        "type": msg_type,
                        "sender_id": user_id,
                        "data": data.get("data"),
                        "call_id": data.get("call_id"),
                    })
            elif msg_type == "ping":
                await websocket.send_json({"type": "pong"})
    except Exception:
        pass
    finally:
        _user_websockets.pop(user_id, None)
        # Clean up any active calls for this user
        for cid, sess in list(_call_sessions.items()):
            if (sess["caller_id"] == user_id or sess["callee_id"] == user_id) and sess["status"] != "ended":
                sess["status"] = "ended"
                _pending_calls.pop(sess.get("callee_id"), None)


# ================================================================
#  Admission Queue  —  Hospital admission management
# ================================================================

import models as _queue_models
from sqlalchemy import func as _queue_func
from datetime import datetime as _queue_dt, timedelta as _queue_td

# ---- Real-time queue WebSocket hub ----
_queue_connections: dict[int, set] = {}  # hospital_id -> set of websockets

async def _queue_broadcast(hospital_id: int, event: dict):
    """Send a JSON event to every WebSocket watching this hospital's queue."""
    dead = []
    for ws in _queue_connections.get(hospital_id, set()):
        try:
            await ws.send_json(event)
        except Exception:
            dead.append(ws)
    for ws in dead:
        _queue_connections.get(hospital_id, set()).discard(ws)


@app.websocket("/ws/admission-queue/{hospital_id}")
async def admission_queue_ws(websocket: WebSocket, hospital_id: int):
    """Hospital-only WebSocket for real-time queue updates."""
    await websocket.accept()
    _queue_connections.setdefault(hospital_id, set()).add(websocket)
    try:
        while True:
            try:
                await asyncio.wait_for(websocket.receive_text(), timeout=30)
            except asyncio.TimeoutError:
                try:
                    await websocket.send_json({"type": "ping"})
                except Exception:
                    break
    except Exception:
        pass
    finally:
        _queue_connections.get(hospital_id, set()).discard(websocket)


def _next_queue_number(db, hospital_id: int) -> int:
    """Return the next queue number for this hospital (sequential)."""
    last = (
        db.query(_queue_models.AdmissionQueue.queue_number)
        .filter(_queue_models.AdmissionQueue.hospital_id == hospital_id)
        .order_by(_queue_models.AdmissionQueue.id.desc())
        .first()
    )
    return (last[0] + 1) if last else 1


def _queue_to_out(q, db) -> dict:
    """Convert a queue ORM row to an AdmissionQueueOut dict."""
    patient_name = None
    patient_age = None
    patient_gender = None
    doctor_name = None
    if q.patient_id:
        pt = db.query(_queue_models.Patient).filter(_queue_models.Patient.id == q.patient_id).first()
        if pt:
            patient_name = pt.name
            patient_age = pt.age
            patient_gender = pt.gender
    if q.doctor_user_id:
        doc = db.query(_queue_models.User).filter(_queue_models.User.id == q.doctor_user_id).first()
        if doc:
            doctor_name = doc.full_name or doc.username
    return {
        "id": q.id,
        "hospital_id": q.hospital_id,
        "patient_id": q.patient_id,
        "patient_name": patient_name,
        "patient_age": patient_age,
        "patient_gender": patient_gender,
        "doctor_user_id": q.doctor_user_id,
        "doctor_name": doctor_name,
        "department": q.department,
        "admission_type": q.admission_type,
        "priority": q.priority,
        "status": q.status,
        "queue_number": q.queue_number,
        "reason": q.reason,
        "notes": q.notes,
        "waiting_since": q.waiting_since,
        "called_at": q.called_at,
        "started_at": q.started_at,
        "admitted_at": q.admitted_at,
        "completed_at": q.completed_at,
        "cancelled_at": q.cancelled_at,
        "on_hold_since": q.on_hold_since,
        "transferred_department": q.transferred_department,
        "created_at": q.created_at,
        "updated_at": q.updated_at,
    }


@app.get("/admission-queue", response_model=schemas.AdmissionQueueListOut)
async def admission_queue_list(
    status: str = None,
    priority: str = None,
    department: str = None,
    doctor_id: int = None,
    search: str = None,
    sort: str = "queue_number",
    order: str = "asc",
    page: int = 1,
    page_size: int = 20,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List queue entries for the current user's hospital. Supports filtering,
    search, sorting, and pagination."""
    # Determine hospital_id from user's hospital profile
    profile = db.query(models.HospitalProfile).filter(
        models.HospitalProfile.user_id == current_user.id
    ).first()
    if not profile or not profile.hospital_id:
        raise HTTPException(403, "No hospital linked to your account")
    hosp_id = profile.hospital_id

    q = db.query(_queue_models.AdmissionQueue).filter(
        _queue_models.AdmissionQueue.hospital_id == hosp_id
    )
    if status:
        q = q.filter(_queue_models.AdmissionQueue.status == status)
    if priority:
        q = q.filter(_queue_models.AdmissionQueue.priority == priority)
    if department:
        q = q.filter(_queue_models.AdmissionQueue.department == department)
    if doctor_id:
        q = q.filter(_queue_models.AdmissionQueue.doctor_user_id == doctor_id)
    if search:
        # Search by patient name or queue number
        patient_ids = [p.id for p in db.query(models.Patient.id).filter(
            models.Patient.name.ilike(f"%{search}%")
        ).all()]
        q = q.filter(
            (_queue_models.AdmissionQueue.patient_id.in_(patient_ids)) |
            (_queue_models.AdmissionQueue.queue_number.ilike(f"%{search}%"))
        )
    total = q.count()

    # Sort
    sort_col = getattr(_queue_models.AdmissionQueue, sort, _queue_models.AdmissionQueue.queue_number)
    if order == "desc":
        q = q.order_by(sort_col.desc())
    else:        q = q.order_by(sort_col.asc())

    items = q.offset((page - 1) * page_size).limit(page_size).all()
    return schemas.AdmissionQueueListOut(
        items=[_queue_to_out(i, db) for i in items],
        total_count=total,
        page=page,
        page_size=page_size,
    )


@app.get("/admission-queue/stats", response_model=schemas.AdmissionQueueStats)
async def admission_queue_stats(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """KPI statistics for the admission queue dashboard."""
    profile = db.query(models.HospitalProfile).filter(
        models.HospitalProfile.user_id == current_user.id
    ).first()
    if not profile or not profile.hospital_id:
        raise HTTPException(403, "No hospital linked to your account")
    hosp_id = profile.hospital_id
    today_start = _queue_dt.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)

    waiting = db.query(_queue_func.count(_queue_models.AdmissionQueue.id)).filter(
        _queue_models.AdmissionQueue.hospital_id == hosp_id,
        _queue_models.AdmissionQueue.status.in_(["waiting", "on_hold"]),
    ).scalar() or 0

    emergency = db.query(_queue_func.count(_queue_models.AdmissionQueue.id)).filter(
        _queue_models.AdmissionQueue.hospital_id == hosp_id,
        _queue_models.AdmissionQueue.status.in_(["waiting", "called", "in_process"]),
        _queue_models.AdmissionQueue.priority == "emergency",
    ).scalar() or 0

    processing = db.query(_queue_func.count(_queue_models.AdmissionQueue.id)).filter(
        _queue_models.AdmissionQueue.hospital_id == hosp_id,
        _queue_models.AdmissionQueue.status.in_(["called", "in_process"]),
    ).scalar() or 0

    admitted_today = db.query(_queue_func.count(_queue_models.AdmissionQueue.id)).filter(
        _queue_models.AdmissionQueue.hospital_id == hosp_id,
        _queue_models.AdmissionQueue.status == "admitted",
        _queue_models.AdmissionQueue.admitted_at >= today_start,
    ).scalar() or 0

    # Available beds = beds in this hospital's wards that are not occupied
    ward_ids = [w.id for w in db.query(models.Ward.id).filter(
        models.Ward.hospital_id == hosp_id
    ).all()]
    total_beds = 0
    occupied = 0
    if ward_ids:
        total_beds = db.query(_queue_func.count(models.Bed.id)).filter(
            models.Bed.ward_id.in_(ward_ids)
        ).scalar() or 0
        occupied = db.query(_queue_func.count(models.Admission.id)).filter(
            models.Admission.bed_id.in_(
                db.query(models.Bed.id).filter(models.Bed.ward_id.in_(ward_ids))
            ),
            models.Admission.discharged_at.is_(None),
        ).scalar() or 0

    # Average waiting time (minutes) for entries admitted today
    avg_wait = 0.0
    recent = db.query(_queue_models.AdmissionQueue).filter(
        _queue_models.AdmissionQueue.hospital_id == hosp_id,
        _queue_models.AdmissionQueue.status == "admitted",
        _queue_models.AdmissionQueue.admitted_at >= today_start,
    ).all()
    if recent:
        waits = []
        for r in recent:
            if r.admitted_at and r.waiting_since:
                delta = (r.admitted_at - r.waiting_since).total_seconds() / 60.0
                waits.append(delta)
        if waits:
            avg_wait = round(sum(waits) / len(waits), 1)

    return schemas.AdmissionQueueStats(
        patients_waiting=waiting,
        emergency_admissions=emergency,
        currently_processing=processing,
        admitted_today=admitted_today,
        available_beds=total_beds - occupied,
        total_beds=total_beds,
        average_waiting_time_min=avg_wait,
    )


@app.post("/admission-queue", response_model=schemas.AdmissionQueueOut)
async def admission_queue_add(
    body: schemas.AdmissionQueueCreate,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Add a patient to the admission queue."""
    profile = db.query(models.HospitalProfile).filter(
        models.HospitalProfile.user_id == current_user.id
    ).first()
    if not profile or not profile.hospital_id:
        raise HTTPException(403, "No hospital linked to your account")
    hosp_id = profile.hospital_id

    # Validate priority and admission_type
    if body.priority not in ("normal", "high", "emergency"):
        raise HTTPException(400, "Priority must be normal, high, or emergency")
    if body.admission_type not in ("normal", "emergency", "surgery"):
        raise HTTPException(400, "Admission type must be normal, emergency, or surgery")

    queue_num = _next_queue_number(db, hosp_id)
    entry = _queue_models.AdmissionQueue(
        hospital_id=hosp_id,
        patient_id=body.patient_id,
        doctor_user_id=body.doctor_user_id,
        department=body.department,
        admission_type=body.admission_type,
        priority=body.priority,
        status="waiting",
        queue_number=queue_num,
        reason=body.reason,
        notes=body.notes,
        waiting_since=_queue_dt.utcnow(),
    )
    db.add(entry)
    db.commit()
    db.refresh(entry)
    out = _queue_to_out(entry, db)
    await _queue_broadcast(hosp_id, {"type": "queue_updated", "action": "added", "item": out})
    return out


@app.post("/admission-queue/{entry_id}/call")
async def admission_queue_call(
    entry_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Call next patient — sets status to 'called'."""
    entry = db.query(_queue_models.AdmissionQueue).get(entry_id)
    if not entry:
        raise HTTPException(404, "Queue entry not found")
    if entry.status not in ("waiting", "on_hold"):
        raise HTTPException(400, f"Cannot call patient with status '{entry.status}'")
    entry.status = "called"
    entry.called_at = _queue_dt.utcnow()
    entry.on_hold_since = None
    db.commit()
    db.refresh(entry)
    out = _queue_to_out(entry, db)
    await _queue_broadcast(entry.hospital_id, {"type": "queue_updated", "action": "called", "item": out})
    return out


