# ===========================================================================
# ML INTELLIGENCE LAYER (2026-09)
# ---------------------------------------------------------------------------
# Role-scoped endpoints exposing the smart/ package. Every endpoint re-uses
# the existing auth + resource authorization; ML processing never bypasses
# access control. All values are computed from real database rows.
# ===========================================================================


def _ml_patient_access(db: Session, current_user: models.User, patient_id: int) -> models.Patient:
    """Resource authorization for ML endpoints that read a patient's data.

    Patient  -> own record only
    Doctor   -> linked via PatientDoctorLink (404 to avoid leaking existence)
    Nurse    -> active NurseAssignment (404 likewise)
    Hospital -> patient with an admission under the caller's hospital
    """
    patient = db.query(models.Patient).filter(models.Patient.id == patient_id).first()
    if not patient:
        raise HTTPException(status_code=404, detail="Patient not found")
    if current_user.role == "patient":
        if current_user.patient_id != patient_id:
            raise HTTPException(status_code=403, detail="You can only access your own patient record")
        return patient
    if current_user.role == "doctor":
        if not _doctor_has_patient_link(db, current_user.id, patient_id):
            raise HTTPException(status_code=404, detail="Patient not found")
        return patient
    if current_user.role == "nurse":
        assigned = (
            db.query(models.NurseAssignment)
            .filter(
                models.NurseAssignment.nurse_user_id == current_user.id,
                models.NurseAssignment.patient_id == patient_id,
                models.NurseAssignment.is_active == True,  # noqa: E712
            )
            .first()
        )
        if not assigned:
            raise HTTPException(status_code=404, detail="Patient not found")
        return patient
    if current_user.role == "hospital":
        profile = _ensure_hospital_admin(db, current_user)
        adm = (
            db.query(models.Admission)
            .filter(
                models.Admission.patient_id == patient_id,
                models.Admission.hospital_id == profile.hospital_id,
            )
            .first()
        )
        if not adm:
            raise HTTPException(status_code=404, detail="Patient not found")
        return patient
    raise HTTPException(status_code=403, detail="Role not authorized for ML patient access.")


