@app.post("/api/ml/normalize")
def ml_terminology_normalize(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Non-destructive medical terminology normalization.

    Body: {"text": "...", "entity_type": "medicine"} -> {original, normalized,
    confidence, alias_applied}. Never alters the original text.
    """
    text = (payload or {}).get("text", "")
    entity_type = (payload or {}).get("entity_type", "general")
    if not text:
        raise HTTPException(status_code=400, detail="Provide 'text'.")
    try:
        result = ml_search.normalize_entity(text, entity_type)
        return {"query": text, "normalized": result["normalized"],
                "confidence": result["confidence"],
                "alias_applied": result["alias_applied"]}
    except Exception:
        logging.exception("Terminology normalization failed")
        raise HTTPException(status_code=500, detail="Normalization unavailable.")


