class SymptomAnalyzeIn(BaseModel):
    symptoms: str
    age: Optional[int] = None
    gender: Optional[str] = None
    duration: Optional[str] = None


@app.post("/api/ml/symptoms/analyze")
def ml_symptoms_analyze(
    request: SymptomAnalyzeIn,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Structured symptom pipeline: normalize -> extract -> score -> triage.

    Runs locally (no LLM) and returns decision-support results with safety
    guidance. Any authenticated user may analyze their own symptoms.
    """
    symptoms = (request.symptoms or "").strip()
    if not symptoms:
        raise HTTPException(status_code=400, detail="Please describe your symptoms.")
    if ml_symptoms is None:
        raise HTTPException(status_code=503, detail="Symptom intelligence unavailable.")
    try:
        result = ml_symptoms.analyze_symptoms(
            symptoms,
            age=request.age,
            gender=request.gender,
            duration=request.duration,
        )
        # Persist into the patient's AI report history (patient callers only)
        # so every analysis stays on record — with a per-feature cap so the
        # history can't grow unboundedly.
        if (current_user.role == "patient" and current_user.patient_id
                and result.get("sufficient")):
            top = result.get("top_pattern") or {}
            _save_ai_report(
                db,
                patient_id=current_user.patient_id,
                feature_type="symptom_checker",
                report_type="Symptom Intelligence Analysis",
                title=f"Symptom analysis — {symptoms[:60]}",
                generated_result=json.dumps(result, default=str)[:10000],
                findings=top.get("condition") or "No strong pattern matched.",
                recommendations="; ".join(result.get("guidance", []))[:1000],
                input_summary=symptoms[:300],
                ai_model="smart.symptoms v1.0 (rule-based)",
            )
            _prune_ai_reports(db, current_user.patient_id, "symptom_checker")
        return result
    except HTTPException:
        raise
    except Exception:
        logging.exception("Symptom intelligence failed")
        raise HTTPException(status_code=500, detail="Symptom intelligence unavailable.")


