@app.get("/api/ml/nurse/assignments")
def ml_nurse_assignments(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Nurse's open care tasks ranked by an explicit priority score."""
    _ensure_nurse(current_user)
    if ml_nurse is None:
        raise HTTPException(status_code=503, detail="Nurse intelligence unavailable.")
    try:
        tasks = (
            db.query(models.NurseTask)
            .filter(models.NurseTask.nurse_user_id == current_user.id,
                    models.NurseTask.status.in_(_TASK_OPEN_STATUSES))
            .all()
        )
        rows, scored = [], []
        for t in tasks:
            patient = db.query(models.Patient).filter(models.Patient.id == t.patient_id).first()
            row = {"id": t.id, "title": t.title, "priority": t.priority,
                   "status": t.status, "due_at": t.due_at, "progress": t.progress or 0,
                   "created_at": t.created_at,
                   "patient_name": patient.name if patient else f"Patient #{t.patient_id}"}
            rows.append(row)
            pr = ml_nurse.assignment_priority(
                priority=t.priority, status=t.status, due_at=t.due_at,
                progress=t.progress or 0, created_at=t.created_at)
            scored.append({**row, "priority_score": pr["score"],
                           "priority_level": pr["level"],
                           "priority_components": pr["components"],
                           "priority_reasons": pr["reasons"]})
        scored.sort(key=lambda r: r["priority_score"], reverse=True)
        return {"items": scored, "method": "rule-based priority scoring",
                "is_decision_support": True}
    except HTTPException:
        raise
    except Exception:
        logging.exception("Nurse assignment intelligence failed")
        raise HTTPException(status_code=500, detail="Nurse assignment intelligence unavailable.")


