# ---------------------------------------------------------------------------
# LLM explanation of structured ML results (optional polish layer)
# ---------------------------------------------------------------------------


class MLExplainIn(BaseModel):
    role: str = "general"
    intelligence: dict
    question: Optional[str] = None


@app.post("/api/ml/explain")
def ml_explain(
    payload: MLExplainIn,
    current_user: models.User = Depends(auth.get_current_user),
):
    """Phrase structured ML intelligence into natural, concise language.

    The intelligence payload is whatever the authorized caller already has
    (insights / risk / forecast). The LLM only *phrases* it — it never
    generates the numbers. On failure we return the deterministic message so
    the UI never hangs.
    """
    try:
        import json as _json
        snippet = _json.dumps(payload.intelligence, default=str)[:3500]
        prompt = (
            "You are the explanation voice of a healthcare software system. "
            "Rewrite the structured analytics below into 1-3 short, natural, "
            "professional sentences for a dashboard. Do not invent numbers, "
            "do not give medical advice, do not mention 'AI' or 'model'. "
            "Keep it concise.\n\n"
            f"ROLE: {payload.role}\n"
            f"QUESTION (optional): {payload.question or 'Summarize the key signals'}\n\n"
            f"STRUCTURED ANALYTICS:\n{snippet}"
        )
        text = gemini_client._nemotron_chat(prompt, temperature=0.2, max_tokens=600)
        text = (text or "").strip()
        if len(text) < 8:
            raise ValueError("Empty LLM explanation")
        return {"explanation": text, "fallback": False}
    except Exception:
        logging.exception("ML explain failed")
        # Deterministic fallback: reuse the human-readable messages that
        # already exist on the structured result, if any.
        messages = []
        ins = payload.intelligence.get("insights") or []
        for i in ins:
            if isinstance(i, dict) and i.get("message"):
                messages.append(i["message"])
        return {"explanation": messages or None, "fallback": True}


# ============================================================================
# 2026-09 — PATIENT MY BILLINGS + PAYMENT MANAGEMENT
# ----------------------------------------------------------------------------
# Unified patient billing center over the two real bill sources:
#   source "hospital"  -> models.HospitalInvoice (patient_id NOT NULL)
#   source "pharmacy"  -> models.Bill (patient_id optional, added 2026-09)
# Payments live only in models.BillingPayment + the append-only
# BillingPaymentEvent ledger. Bills themselves are never copied — the patient
# page reads the real rows and joins payments at request time.
# ============================================================================

# ---- Payment provider abstraction (sandbox until a real gateway is wired) ----
# When PAYMENT_GATEWAY is configured the hook goes here; until then every
# "charge" runs through the sandbox below. The sandbox is deterministic
# (reference values prefixed with "fail" simulate a declined charge) and is
# labelled "sandbox" in every transaction so nobody mistakes it for a real
# bank charge.

def _gateway_initiate(method: str, amount: float, reference: Optional[str]):
    """Returns (success: bool, transaction_reference: Optional[str])."""
    if reference and str(reference).strip().lower().startswith("fail"):
        return False, None
    return True, "SBX-" + uuid.uuid4().hex[:12].upper()


_PAYMENT_ORDER = ["initiated", "processing", "submitted", "awaiting_approval",
                  "approved", "rejected", "failed", "cancelled",
                  "refund_requested", "refunded"]


def _payment_event(
    db: Session,
    payment: models.BillingPayment,
    actor_user_id: Optional[int],
    actor_kind: str,
    previous: Optional[str],
    new_status: str,
    note: Optional[str] = None,
) -> None:
    db.add(models.BillingPaymentEvent(
        payment_id=payment.id,
        actor_user_id=actor_user_id,
        actor_kind=actor_kind,
        previous_status=previous,
        new_status=new_status,
        note=note,
    ))


def _bill_paid_approved(db: Session, source: str, bill_id: int) -> float:
    """Sum of approved (non-refunded) payments against a bill."""
    rows = (
        db.query(models.BillingPayment.amount)
        .filter(
            models.BillingPayment.bill_source == source,
            models.BillingPayment.bill_id == bill_id,
            models.BillingPayment.status == "approved",
        )
        .all()
    )
    return round(sum(r[0] or 0 for r in rows), 2)


def _resolve_source_bill(db: Session, source: str, bill_id: int):
    if source == "hospital":
        return db.query(models.HospitalInvoice).filter(models.HospitalInvoice.id == bill_id).first()
    return db.query(models.Bill).filter(models.Bill.id == bill_id).first()


def _bill_source_org(db: Session, source: str, row) -> tuple:
    """Return (org_id, org_name) for a bill row."""
    if source == "hospital":
        org_id = row.hospital_id
        org = db.query(models.Hospital).filter(models.Hospital.id == org_id).first()
        return org_id, (org.name if org else f"Hospital #{org_id}")
    org_id = row.shopkeeper_id
    shop = db.query(models.User).filter(models.User.id == org_id).first()
    return org_id, (shop.full_name or shop.username) if shop else f"Pharmacy #{org_id}"


def _bill_state(db: Session, source: str, row) -> dict:
    """Derived patient-facing bill state (unpaid/partial/paid/cancelled) from
    the underlying bill + approved payments."""
    total = round(row.total or 0.0, 2)
    cancelled = (row.payment_status == "cancelled") if source == "hospital" else (row.status == "cancelled")
    paid = _bill_paid_approved(db, source, row.id)
    if cancelled:
        return {"bill_state": "cancelled", "total": total, "paid": 0.0, "due": 0.0}
    # Bills already settled at the counter (before the online payment ledger)
    # count as paid when the source row says so and no online payment exists.
    counter_paid = False
    if source == "hospital" and row.payment_status == "paid" and paid <= 0:
        counter_paid = True
    elif source == "pharmacy" and row.status == "paid" and paid <= 0:
        counter_paid = True
    if counter_paid or paid >= total - 0.005:
        return {"bill_state": "paid", "total": total, "paid": round(total, 2) if counter_paid else paid, "due": 0.0}
    if paid > 0:
        return {"bill_state": "partial", "total": total, "paid": paid, "due": round(total - paid, 2)}
    return {"bill_state": "unpaid", "total": total, "paid": 0.0, "due": round(total, 2)}


def _bill_items(db: Session, source: str, row) -> list:
    if source == "hospital":
        rows = db.query(models.HospitalInvoiceItem).filter(
            models.HospitalInvoiceItem.invoice_id == row.id
        ).order_by(models.HospitalInvoiceItem.id.asc()).all()
        return [{
            "name": i.medicine_name, "batch": None, "quantity": i.quantity,
            "unit_price": i.unit_price, "mrp": i.mrp, "line_total": i.line_total,
        } for i in rows]
    rows = db.query(models.BillLineItem).filter(
        models.BillLineItem.bill_id == row.id
    ).order_by(models.BillLineItem.id.asc()).all()
    return [{
        "name": i.medicine_name, "batch": i.batch_no, "quantity": i.quantity,
        "unit_price": i.unit_price, "mrp": i.mrp, "line_total": i.line_total,
    } for i in rows]


def _bill_dict(db: Session, source: str, row, with_items: bool = False) -> dict:
    org_id, org_name = _bill_source_org(db, source, row)
    st = _bill_state(db, source, row)
    out = {
        "source": source,
        "bill_id": row.id,
        "bill_number": row.invoice_number if source == "hospital" else row.bill_number,
        "org_id": org_id,
        "org_name": org_name,
        "patient_id": row.patient_id,
        "date": _iso(row.created_at),
        "subtotal": round(row.subtotal or 0.0, 2),
        "discount": round(row.discount or 0.0, 2),
        "tax": round(getattr(row, "tax", None) or getattr(row, "tax_amount", None) or 0.0, 2),
        "total": st["total"],
        "paid": st["paid"],
        "due": st["due"],
        "bill_state": st["bill_state"],
        "notes": getattr(row, "notes", None),
    }
    payments = (
        db.query(models.BillingPayment)
        .filter(models.BillingPayment.bill_source == source,
                models.BillingPayment.bill_id == row.id)
        .order_by(models.BillingPayment.id.desc())
        .all()
    )
    out["payments"] = [{
        "id": p.id, "amount": p.amount, "method": p.method,
        "transaction_reference": p.transaction_reference, "status": p.status,
        "created_at": _iso(p.created_at),
    } for p in payments]
    if with_items:
        out["items"] = _bill_items(db, source, row)
    return out


def _apply_bill_payment_marker(db: Session, source: str, row, due: float) -> None:
    """Keep the underlying source row's payment status consistent with the
    ledger after an approved payment / refund."""
    if source == "hospital":
        row.payment_status = "partial" if due > 0 else "paid"
    else:
        row.status = "pending" if due > 0 else "paid"


