# ---------------------------------------------------------------------------
# Patient read APIs
# ---------------------------------------------------------------------------

def _patient_bill_query_filters(db: Session, patient_id: int, q: Optional[str], status_f: Optional[str],
                                from_d: Optional[str], to_d: Optional[str]):
    """Return (hospital rows, pharmacy rows) matching filters."""
    hosp_rows = (
        db.query(models.HospitalInvoice)
        .filter(models.HospitalInvoice.patient_id == patient_id,
                sa_or_(models.HospitalInvoice.status.is_(None),
                       models.HospitalInvoice.status != "draft"))
        .order_by(models.HospitalInvoice.created_at.desc())
        .limit(2000)
        .all()
    )
    pharm_rows = (
        db.query(models.Bill)
        .filter(models.Bill.patient_id == patient_id)
        .order_by(models.Bill.created_at.desc())
        .limit(2000)
        .all()
    )
    items = []
    for source, rows in (("hospital", hosp_rows), ("pharmacy", pharm_rows)):
        for row in rows:
            items.append(_bill_dict(db, source, row))
    if q:
        ql = q.lower()
        items = [i for i in items if ql in (i["bill_number"] or "").lower()
                 or ql in (i["org_name"] or "").lower()]
    if status_f:
        items = [i for i in items if i["bill_state"] == status_f]
    if from_d or to_d:
        def _dt(x):
            try:
                return datetime.fromisoformat(str(x))
            except Exception:
                return None
        fd, td = _dt(from_d), _dt(to_d)
        if td:
            td = td + timedelta(days=1)
        items = [i for i in items if (not fd or (_dt(i["date"]) or datetime.min) >= fd)
                 and (not td or (_dt(i["date"]) or datetime.min) < td)]
    return items


@app.get("/billing/me/summary")
def patient_billing_summary(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    pid = current_user.patient_id
    items = _patient_bill_query_filters(db, pid, None, None, None, None)
    total_bills = len(items)
    unpaid = [i for i in items if i["bill_state"] == "unpaid"]
    paid = [i for i in items if i["bill_state"] == "paid"]
    partial = [i for i in items if i["bill_state"] == "partial"]
    total_amount = round(sum(i["total"] for i in items if i["bill_state"] != "cancelled"), 2)
    amount_paid = round(sum(i["paid"] for i in items), 2)
    amount_due = round(sum(i["due"] for i in items), 2)
    pending_approvals = (
        db.query(models.BillingPayment)
        .filter(models.BillingPayment.patient_id == pid,
                models.BillingPayment.status == "awaiting_approval")
        .count()
    )
    return {
        "total_bills": total_bills,
        "unpaid": len(unpaid),
        "partial": len(partial),
        "paid": len(paid),
        "pending_approvals": pending_approvals,
        "total_amount": total_amount,
        "amount_paid": amount_paid,
        "amount_due": amount_due,
    }


@app.get("/billing/me/bills")
def list_patient_bills(
    source: Optional[str] = None,
    status: Optional[str] = None,
    q: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    sort: str = "newest",
    page: int = 1,
    page_size: int = 12,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    pid = current_user.patient_id
    items = _patient_bill_query_filters(db, pid, q, status, date_from, date_to)
    if source in ("hospital", "pharmacy"):
        items = [i for i in items if i["source"] == source]
    keyf = {"newest": lambda i: i["date"] or "", "oldest": lambda i: i["date"] or "",
            "amount_hi": lambda i: i["total"], "amount_lo": lambda i: -i["total"]}
    if sort == "oldest":
        items.sort(key=lambda i: i["date"] or "")
    elif sort == "amount_hi":
        items.sort(key=lambda i: i["total"], reverse=True)
    elif sort == "amount_lo":
        items.sort(key=lambda i: i["total"])
    else:
        items.sort(key=lambda i: i["date"] or "", reverse=True)
    page = max(1, page); page_size = min(max(1, page_size), 50)
    total = len(items)
    start = (page - 1) * page_size
    return {"items": items[start:start + page_size], "total": total, "page": page}


