@app.get("/billing/me/analytics")
def patient_billing_analytics(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    items = _patient_bill_query_filters(db, current_user.patient_id, None, None, None, None)
    by_source = {"hospital": {"bills": 0, "total": 0.0, "due": 0.0},
                 "pharmacy": {"bills": 0, "total": 0.0, "due": 0.0}}
    for i in items:
        s = by_source[i["source"]]
        s["bills"] += 1
        if i["bill_state"] != "cancelled":
            s["total"] += i["total"]; s["due"] += i["due"]
    now = datetime.utcnow()
    months = []
    for k in range(5, -1, -1):
        d = now - timedelta(days=30 * k)
        key = d.strftime("%Y-%m")
        tot = round(sum(i["total"] for i in items if (i["date"] or "")[:7] == key and i["bill_state"] != "cancelled"), 2)
        months.append({"month": d.strftime("%b %Y"), "total": tot})
    return {"by_source": by_source, "monthly": months, "total_billed": by_source["hospital"]["total"] + by_source["pharmacy"]["total"]}


# ---------------------------------------------------------------------------
# Patient payment APIs
# ---------------------------------------------------------------------------

@app.post("/billing/me/pay")
def patient_initiate_payment(
    payload: dict,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Initiate payment for an eligible own bill. Amount is re-validated
    server-side against the live bill's outstanding balance — the frontend is
    never trusted. Duplicate submissions with the same idempotency_key return
    the original transaction."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    source = str(payload.get("source") or "").strip().lower()
    bill_id = int(payload.get("bill_id") or 0)
    method = str(payload.get("method") or "").strip().lower()
    idem = str(payload.get("idempotency_key") or "").strip()
    if source not in ("hospital", "pharmacy") or not bill_id:
        raise HTTPException(status_code=400, detail="source and bill_id are required.")
    if method not in ("bank", "card", "upi"):
        raise HTTPException(status_code=400, detail="method must be bank, card or upi.")
    if not idem or len(idem) < 8 or len(idem) > 120:
        raise HTTPException(status_code=400, detail="A unique idempotency_key (8-120 chars) is required.")
    row = _resolve_source_bill(db, source, bill_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Bill not found.")
    if (row.patient_id or 0) != current_user.patient_id:
        raise HTTPException(status_code=403, detail="You can only pay your own bills.")
    # Idempotency: same key -> same payment (or conflict on mismatched target).
    dup = db.query(models.BillingPayment).filter(
        models.BillingPayment.idempotency_key == idem).first()
    if dup:
        if dup.bill_source == source and dup.bill_id == bill_id and dup.patient_id == current_user.patient_id:
            return _payment_dict(db, dup, with_events=True)
        raise HTTPException(status_code=409, detail="idempotency_key already used for a different payment.")

    st = _bill_state(db, source, row)
    if st["bill_state"] == "cancelled":
        raise HTTPException(status_code=400, detail="This bill was cancelled and cannot be paid.")
    if st["bill_state"] == "paid":
        raise HTTPException(status_code=400, detail="This bill is already fully paid.")
    if source == "hospital" and (row.status or "issued") == "draft":
        raise HTTPException(status_code=400, detail="This bill has not been issued yet.")
    due = st["due"]
    amount = round(float(payload.get("amount") or 0.0), 2)
    if amount <= 0 or amount > due + 0.005:
        raise HTTPException(status_code=400,
                            detail=f"Payment amount must be between 0 and the outstanding balance of ₹{due:,.2f}.")
    method_detail = str(payload.get("method_detail") or "").strip()
    if len(method_detail) > 120 or any(k in method_detail.lower() for k in ("cvv", "pin", "password", "otp")):
        raise HTTPException(status_code=400, detail="Only a masked reference is accepted (no credentials).")
    org_id, org_name = _bill_source_org(db, source, row)
    bill_no = row.invoice_number if source == "hospital" else row.bill_number
    needs_approval = source == "hospital"
    pay = models.BillingPayment(
        bill_source=source, bill_id=bill_id, patient_id=current_user.patient_id,
        hospital_id=(row.hospital_id if source == "hospital" else None),
        bill_number=bill_no, bill_total=st["total"], amount=amount,
        outstanding_before=due, method=method, method_detail=method_detail[:120] or None,
        transaction_reference="PENDING", idempotency_key=idem,
        status="initiated", needs_approval=needs_approval,
    )
    db.add(pay); db.flush()
    _payment_event(db, pay, current_user.id, "patient", None, "initiated", "Payment initiated by patient.")
    pay.status = "processing"
    _payment_event(db, pay, None, "gateway", "initiated", "processing", "Sent to payment gateway.")
    ok, txn = _gateway_initiate(method, amount, method_detail)
    pay.transaction_reference = txn or f"FAILED-{uuid.uuid4().hex[:10].upper()}"
    if not ok:
        pay.status = "failed"
        _payment_event(db, pay, None, "gateway", "processing", "failed", "Gateway declined the charge (sandbox).")
        db.commit()
        _notify_billing_patient(db, current_user.id, "payment_failed",
                                f"Payment failed for {org_name} bill {bill_no}", "The payment could not be processed. Please try again.")
        _activity_billing(db, actor_user_id=current_user.id, actor_role="patient",
                          event_type="payment_failed", patient_id=current_user.patient_id,
                          hospital_id=pay.hospital_id, detail=f"Payment on bill {bill_no} failed.")
        return _payment_dict(db, pay, with_events=True)
    pay.status = "submitted"
    _payment_event(db, pay, None, "gateway", "processing", "submitted", f"Charge captured (sandbox txn {txn}).")
    db.commit()

    if needs_approval:
        pay.status = "awaiting_approval"
        _payment_event(db, pay, current_user.id, "patient", "submitted", "awaiting_approval",
                       "Payment received — awaiting hospital confirmation.")
        db.commit()
        _notify_billing_patient(db, current_user.id, "payment_awaiting_approval",
                                f"Payment awaiting approval: {bill_no}",
                                f"₹{amount:,.2f} by {method} on {org_name} bill {bill_no} — waiting for the hospital to confirm.")
        _notify_hospital_admins(db, row.hospital_id, "payment_awaiting_hospital",
                                f"Payment approval needed: {bill_no}",
                                f"{current_user.full_name or current_user.username} paid ₹{amount:,.2f} ({method}) — review and approve.",
                                "hospital-pharmacy.html#payments")
        _activity_billing(db, actor_user_id=current_user.id, actor_role="patient",
                          event_type="payment_submitted", patient_id=current_user.patient_id,
                          hospital_id=row.hospital_id,
                          detail=f"Payment of ₹{amount:,.2f} on {org_name} bill {bill_no} awaits hospital approval.")
        return _payment_dict(db, pay, with_events=True)

    # Pharmacy bills have no approval step: the sandbox charge settles the bill.
    pay.status = "approved"
    pay.approved_at = datetime.utcnow()
    _payment_event(db, pay, None, "gateway", "submitted", "approved", "Sandbox payment settled.")
    new_due = round(max(0.0, due - amount), 2)
    _apply_bill_payment_marker(db, source, row, new_due)
    db.commit()
    _notify_billing_patient(db, current_user.id, "payment_approved",
                            f"Payment received: {org_name} bill {bill_no}",
                            f"₹{amount:,.2f} ({method}) recorded. Remaining due: ₹{new_due:,.2f}.")
    _activity_billing(db, actor_user_id=current_user.id, actor_role="patient",
                      event_type="payment_completed", patient_id=current_user.patient_id,
                      hospital_id=pay.hospital_id,
                      detail=f"Bill {bill_no} paid ₹{amount:,.2f} by {method}.")
    return _payment_dict(db, pay, with_events=True)


def _payment_dict(db: Session, p: models.BillingPayment, with_events: bool = False) -> dict:
    out = {
        "id": p.id, "bill_source": p.bill_source, "bill_id": p.bill_id,
        "bill_number": p.bill_number, "patient_id": p.patient_id,
        "bill_total": p.bill_total, "amount": p.amount,
        "outstanding_before": p.outstanding_before,
        "method": p.method, "method_detail": p.method_detail,
        "transaction_reference": p.transaction_reference,
        "status": p.status, "needs_approval": p.needs_approval,
        "approved_at": _iso(p.approved_at),
        "rejection_reason": p.rejection_reason,
        "refund_reason": p.refund_reason,
        "refunded_at": _iso(p.refunded_at),
        "created_at": _iso(p.created_at),
        "updated_at": _iso(p.updated_at),
    }
    if with_events:
        events = (
            db.query(models.BillingPaymentEvent)
            .filter(models.BillingPaymentEvent.payment_id == p.id)
            .order_by(models.BillingPaymentEvent.id.asc())
            .all()
        )
        out["events"] = [{
            "actor_kind": e.actor_kind, "previous_status": e.previous_status,
            "new_status": e.new_status, "note": e.note, "created_at": _iso(e.created_at),
        } for e in events]
    return out


@app.get("/billing/me/payments")
def list_patient_payments(
    page: int = 1,
    page_size: int = 15,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    page = max(1, page); page_size = min(max(1, page_size), 50)
    q = db.query(models.BillingPayment).filter(
        models.BillingPayment.patient_id == current_user.patient_id)
    total = q.count()
    rows = q.order_by(models.BillingPayment.id.desc()).offset((page - 1) * page_size).limit(page_size).all()
    items = []
    for p in rows:
        row = _resolve_source_bill(db, p.bill_source, p.bill_id)
        org = ""
        if row:
            org = _bill_source_org(db, p.bill_source, row)[1]
        d = _payment_dict(db, p)
        d["org_name"] = org
        items.append(d)
    return {"items": items, "total": total, "page": page}


