def _task_status_activity(db: Session, task: models.NurseTask, user: models.User, kind: str, note: Optional[str]) -> None:
    labels = {
        "acknowledged": "Acknowledged care task",
        "started": "Started care task",
        "completed": "Completed care task",
        "paused": "Paused care task",
        "resumed": "Resumed care task",
        "escalated": "Escalated care task",
        "cancelled": "Cancelled care task",
        "progress": "Updated care task progress",
    }
    patient = _patient_row(db, task.patient_id)
    pname = patient.name if patient else f"Patient #{task.patient_id}"
    _record_activity(
        db,
        actor_user_id=user.id,
        actor_role=user.role,
        event_type=f"task_{kind}",
        entity_type="nurse_task",
        entity_id=task.id,
        detail=f"{labels.get(kind, kind)} '{task.title}' · {pname}.",
        patient_id=task.patient_id,
        hospital_id=task.hospital_id,
        nurse_user_id=task.nurse_user_id,
    )


