@app.post("/nurse-tasks/{task_id}/progress")
def progress_nurse_task(
    task_id: int,
    payload: Optional[dict] = None,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    payload = payload or {}
    task, level = _task_access(db, task_id, current_user)
    if level != "nurse":
        raise HTTPException(status_code=403, detail="Only the assigned nurse can update this task.")
    if task.status not in ("in_progress", "on_hold"):
        raise HTTPException(status_code=400, detail="Only an active task can be updated.")
    pct = int(payload.get("progress") or 0)
    pct = max(0, min(100, pct))
    task.progress = pct
    if task.status == "on_hold" and pct > 0:
        task.status = "in_progress"
    note = str(payload.get("note") or "").strip() or None
    _record_task_event(db, task, "progress", current_user.id, note=note, progress=pct)
    if pct == 100:
        task.status = "completed"
        task.completed_at = datetime.utcnow()
        _record_task_event(db, task, "completed", current_user.id, note=note or "Marked complete at 100%.", progress=100)
        db.commit()
        _task_status_activity(db, task, current_user, "completed", note)
        # Tell the assigner their task is done.
        _enqueue_notification(
            db,
            recipient_user_id=task.created_by_user_id,
            kind="nurse_report_sent",
            title=f"Care task completed: {task.title}",
            detail=f"Marked complete by {current_user.full_name or current_user.username}.",
            link="nurse-tasks" if task.created_by_role == "doctor" else "hospital-dashboard.html",
        )
        db.commit()
        return _task_to_dict(db, task)
    db.commit()
    _task_status_activity(db, task, current_user, "progress", note)
    return _task_to_dict(db, task)


