# ====================================================================
# 2026-09 — AI REPORT HISTORY (auto-saved from AI features)
# ====================================================================

def _save_ai_report(
    db: Session,
    *,
    patient_id: int,
    feature_type: str,
    report_type: str,
    title: str,
    generated_result: str = None,
    findings: str = None,
    recommendations: str = None,
    input_summary: str = None,
    status: str = "completed",
    ai_model: str = None,
    ai_model_version: str = None,
    source_entity_type: str = None,
    source_entity_id: int = None,
) -> models.AiReport:
    """Persist an AI-generated report under the given patient.  Called from
    the backend right after a successful AI analysis completes."""
    report = models.AiReport(
        patient_id=patient_id,
        feature_type=feature_type,
        report_type=report_type,
        title=title,
        generated_result=generated_result,
        findings=findings,
        recommendations=recommendations,
        input_summary=input_summary,
        status=status,
        ai_model=ai_model,
        ai_model_version=ai_model_version,
        source_entity_type=source_entity_type,
        source_entity_id=source_entity_id,
    )
    db.add(report)
    db.commit()
    db.refresh(report)
    return report


def _prune_ai_reports(db: Session, patient_id: int, feature_type: str, keep: int = 50) -> None:
    """Keep the newest `keep` AI reports per (patient, feature_type); drop
    the older rows so auto-saved analyses can't grow the table unboundedly."""
    stale = (
        db.query(models.AiReport.id)
        .filter(models.AiReport.patient_id == patient_id,
                models.AiReport.feature_type == feature_type)
        .order_by(models.AiReport.created_at.desc())
        .offset(keep)
        .all()
    )
    if stale:
        ids = [r[0] for r in stale]
        db.query(models.AiReport).filter(models.AiReport.id.in_(ids)).delete(
            synchronize_session=False)
        db.commit()


@app.get("/ai-reports", response_model=schemas.AiReportListOut)
def list_ai_reports(
    feature_type: Optional[str] = None,
    q: Optional[str] = None,
    page: int = 1,
    page_size: int = 20,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """List AI reports for the authenticated patient.  Supports search and
    feature-type filter."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    pid = current_user.patient_id
    page = max(1, page)
    page_size = min(max(1, page_size), 50)
    q_base = db.query(models.AiReport).filter(models.AiReport.patient_id == pid)
    if feature_type:
        q_base = q_base.filter(models.AiReport.feature_type == feature_type)
    if q:
        ql = f"%{q.lower()}%"
        q_base = q_base.filter(
            models.AiReport.title.ilike(ql) |
            models.AiReport.report_type.ilike(ql) |
            models.AiReport.feature_type.ilike(ql) |
            models.AiReport.findings.ilike(ql)
        )
    total = q_base.count()
    items = (
        q_base
        .order_by(models.AiReport.created_at.desc())
        .offset((page - 1) * page_size)
        .limit(page_size)
        .all()
    )
    return schemas.AiReportListOut(
        items=[schemas.AiReportOut.model_validate(r) for r in items],
        total=total,
        page=page,
    )


@app.get("/ai-reports/summary")
def ai_reports_summary(
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Quick stats for the patient's AI report dashboard."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    pid = current_user.patient_id
    total = db.query(models.AiReport).filter(models.AiReport.patient_id == pid).count()
    features_rows = (
        db.query(models.AiReport.feature_type)
        .filter(models.AiReport.patient_id == pid)
        .group_by(models.AiReport.feature_type)
        .all()
    )
    by_feature = {row[0]: 0 for row in features_rows}
    for row in features_rows:
        by_feature[row[0]] = db.query(models.AiReport).filter(
            models.AiReport.patient_id == pid, models.AiReport.feature_type == row[0]
        ).count()
    return {"total": total, "by_feature": by_feature}


@app.get("/ai-reports/{report_id}", response_model=schemas.AiReportOut)
def get_ai_report(
    report_id: int,
    db: Session = Depends(get_db),
    current_user: models.User = Depends(auth.get_current_user),
):
    """Get a single AI report.  Patient can only view their own."""
    if current_user.role != "patient" or not current_user.patient_id:
        raise HTTPException(status_code=403, detail="Patient access required.")
    report = db.query(models.AiReport).filter(models.AiReport.id == report_id).first()
    if not report or report.patient_id != current_user.patient_id:
        raise HTTPException(status_code=404, detail="Report not found.")
    return schemas.AiReportOut.model_validate(report)


# ---------- Hook helper: called from existing AI endpoints after success ----------

def _hook_save_ai_report(
    db: Session,
    *,
    patient_id: Optional[int],
    feature_type: str,
    report_type: str,
    title: str,
    generated_result: str = None,
    findings: str = None,
    recommendations: str = None,
    input_summary: str = None,
    ai_model: str = None,
    source_entity_type: str = None,
    source_entity_id: int = None,
) -> None:
    """Fire-and-forget helper used inside existing AI endpoints.  Never raises
    so it can't break the original AI response flow."""
    if not patient_id:
        return
    try:
        _save_ai_report(
            db,
            patient_id=patient_id,
            feature_type=feature_type,
            report_type=report_type,
            title=title,
            generated_result=generated_result,
            findings=findings,
            recommendations=recommendations,
            input_summary=input_summary,
            ai_model=ai_model,
            source_entity_type=source_entity_type,
            source_entity_id=source_entity_id,
        )
    except Exception as e:
        # Best-effort: log but never fail the AI response because of history saving.
        print(f"[ai-report save] failed for patient {patient_id}: {e}")
